	@Override
	public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
		EvidenceStateRef state = leafEvidenceState(relationId);
		boolean authoritativeFrontierLeaf = mode == FrontierEstimatorMode.AUTHORITATIVE
				&& isComposableState(state)
				&& query.isStatementPattern(relationId)
				&& state.summary().guarantee() == EvidenceGuarantee.MEASURE_UNBIASED
				&& state.summary().zeroStatus() != EvidenceZeroStatus.ESTIMATED_ZERO;
		if (!authoritativeFrontierLeaf
				|| !lmdbCostModel.estimateFrontierLeafAccess(
						query, relationId, state.summary().pointRows(), output)) {
			scalar.estimateLeaf(relationId, context, output);
		}
		String scalarSource = output.estimateSource();
		String scalarFusion = output.estimateFusion();
		if (state == null) {
			state = materializeReplayableLeafState(relationId, output.outputRows());
		}
		if (state == null) {
			annotateMissingLeafState(relationId, output);
			return;
		}

		EvidenceStateSummary summary = state.summary();
		output.setEvidenceStateId(state.stateId());
		annotateReady(output, state);
		LeafState statementLeaf = leafState(relationId);
		if (statementLeaf != null && statementLeaf.materialization != null) {
			output.putPlannedStringMetric("plannedFrontierLeafMaterialization", statementLeaf.materialization);
		}
		output.putPlannedDoubleMetric("plannedFrontierFactorCount", 1.0d);
		if (mode != FrontierEstimatorMode.AUTHORITATIVE) {
			return;
		}
		if (!isComposableState(state)) {
			output.setEvidenceGuarantee(summary.guarantee());
			output.putPlannedStringMetric("plannedFrontierFallbackReason", summary.degradationReason());
			annotateQueryIndex(output);
			return;
		}
		if (summary.guarantee() == EvidenceGuarantee.MEASURE_UNBIASED
				&& summary.zeroStatus() == EvidenceZeroStatus.ESTIMATED_ZERO) {
			publishSampledZeroFallback(relationId, output, state);
			return;
		}
		double scalarWork = output.workRows();
		double frontierWork = Double.isFinite(scalarWork) && scalarWork >= 0.0d
				? Math.max(summary.pointRows(), scalarWork)
				: summary.pointRows();
		if (output.evidenceGuarantee() != EvidenceGuarantee.DATABASE_EXACT) {
			output.setRows(summary.pointRows(), frontierWork);
			output.setEvidenceGuarantee(summary.guarantee());
		}
		if (preserveScalarLeafProvenance(scalarSource)) {
			output.setEstimateProvenance(scalarSource, scalarFusion);
		} else {
			output.setEstimateProvenance(FRONTIER_SOURCE, "frontier_authoritative");
		}
		setFrontierFactorPhysicalCost(relationId, output, summary.pointRows());
	}

	private static boolean exactFiniteLeafSource(String source) {
		return "finite-values".equals(source)
				|| "lmdb-binding-set-assignment-filter".equals(source);
	}

	private static boolean preserveScalarLeafProvenance(String source) {
		return exactFiniteLeafSource(source)
				|| "lmdb-finite-binding-lookup".equals(source);
	}

	@Override
	public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
		EvidenceStateRef input = stateReference(context.evidenceStateId());
		LeafState factor = leafState(relationId);
		FiniteLeafState finiteFactor = finiteLeafState(relationId);
		if (input == null) {
			scalar.appendFactor(relationId, context, output);
			return;
		}
		if (factor == null && finiteFactor == null) {
			scalar.appendFactor(relationId, context, output);
			if (appendBoundedLocalPath(relationId, context, input, output)) {
				return;
			}
			degradeOperator(relationId, output, input, "unsupported_append_factor");
			return;
		}
		if (factor != null && factor.state == null) {
			factor.state = materializeReplayableLeafState(relationId, 1.0d);
		}
		if (factor != null && statementSource == null) {
			scalar.appendFactor(relationId, context, output);
			degradeOperator(relationId, output, input, "exact_snapshot_probe_unavailable");
			return;
		}
		FrontierStateKey factorKey = factor != null ? factor.key : finiteFactor.key;
		EvidenceStateRef factorState = factor != null ? factor.state : finiteFactor.state;
		if (!isComposableState(input)) {
			scalar.appendFactor(relationId, context, output);
			publishNonComposableAppend(relationId, output, input, factorState,
					unionLayout(arena.layout(input), factorKey.frontier()),
					input.summary().degradationReason());
			return;
		}
		FrontierStateKey outputKey = joinedStateKey(arena.key(input), factorKey);
		arena.declareCanonicalState(outputKey);
		boolean invokingScalar = false;
		try {
			boolean lineageSpecific = arena.nearestCalibration(input) != null;
			EvidenceStateRef state = lineageSpecific ? null : arena.find(outputKey);
			if (state == null) {
				state = factor != null
						? extendInner(input, factor, outputKey, relationId)
						: extendFinite(input, finiteFactor, outputKey, relationId);
				rememberState(state);
			}
			boolean sampledBypass = mode == FrontierEstimatorMode.AUTHORITATIVE
					&& factor != null
					&& state.summary().guarantee() != EvidenceGuarantee.DATABASE_EXACT
					&& isComposableState(state)
					&& state.summary().zeroStatus() != EvidenceZeroStatus.ESTIMATED_ZERO
					&& lmdbCostModel.estimateFrontierAppendAccess(
							query, relationId, context, state.summary().pointRows(), output);
			if (!sampledBypass) {
				invokingScalar = true;
				scalar.appendFactor(relationId, context, output);
				invokingScalar = false;
			}
			FrontierFactorSurfaceRefinement factorSurface = refineFactorAccessSurface(input, state, outputKey,
					relationId, context, output);
			output.putPlannedStringMetric("plannedFrontierFactorSurfaceRefinement", factorSurface.status());
			if (!factorSurface.detail().isEmpty()) {
				output.putPlannedStringMetric("plannedFrontierFactorSurfaceRefinementDetail", factorSurface.detail());
			}
			if (factorSurface.retainedState() != null) {
				state = factorSurface.retainedState();
			}
			String scalarSource = output.estimateSource();
			String scalarFusion = output.estimateFusion();
			double scalarRows = output.outputRows();
			boolean scalarExact = output.evidenceGuarantee() == EvidenceGuarantee.DATABASE_EXACT;
			if (scalarExact && !isComposableState(state)) {
				EvidenceStateRef recovered = recoverExactDerivedSurface(
						input, outputKey, relationId, context, output);
				if (recovered != null) {
					state = recovered;
				}
			}
			EvidenceStateSummary summary = state.summary();
			if (!isComposableState(state)) {
				output.setEvidenceStateId(state.stateId());
				annotateState(output, state, "degraded");
				output.putPlannedStringMetric("plannedFrontierFallbackReason", summary.degradationReason());
				return;
			}
			output.setEvidenceStateId(state.stateId());
			annotateReady(output, state);
			annotateFactorCount(output, state);
			if (mode != FrontierEstimatorMode.AUTHORITATIVE) {
				return;
			}
			if (summary.guarantee() == EvidenceGuarantee.MEASURE_UNBIASED
					&& summary.zeroStatus() == EvidenceZeroStatus.ESTIMATED_ZERO) {
				publishSampledZeroFallback(relationId, output, state);
				return;
			}
			double scalarWork = output.workRows();
			double frontierWork = Double.isFinite(scalarWork) && scalarWork >= 0.0d
					? Math.max(summary.pointRows(), scalarWork)
					: summary.pointRows();
			if (scalarExact) {
				/*
				 * Exact scalar access describes the appended physical component under the available bindings. The
				 * retained Frontier state is the object whose canonical key contains the complete prefix, including
				 * unrelated Cartesian components. Preserve the exact access rows diagnostically; the physical vector is
				 * installed below before restoring the complete-prefix logical cardinality.
				 */
				output.putPlannedDoubleMetric("plannedFrontierExactAccessComponentRows", scalarRows);
			} else {
				/*
				 * The state was produced by extending the input payload and its canonical key contains the entire
				 * prefix, including Cartesian factors. Its point estimate is therefore contextual output, not the
				 * appended factor's isolated connected-component contribution.
				 */
				output.setContextualRows(summary.pointRows(), frontierWork);
			}
			output.setEvidenceGuarantee(summary.guarantee());
			boolean learned = !scalarExact && arena.nearestCalibration(state) != null;
			if (scalarExact || preserveScalarLeafProvenance(scalarSource)) {
				output.setEstimateProvenance(scalarSource, scalarFusion);
			} else {
				output.setEstimateProvenance(learned ? FRONTIER_LEO_SOURCE : FRONTIER_SOURCE,
						learned ? "frontier_learned_calibration" : "frontier_authoritative");
			}
			setFrontierFactorPhysicalCost(relationId, output, scalarExact ? scalarRows : summary.pointRows());
			if (scalarExact) {
				/* setLocalAccessPhysicalCost writes component result work; logical rows belong to the full prefix. */
				output.setContextualOutputRowsPreservingPhysicalCost(summary.pointRows());
			}
		} catch (RuntimeException failure) {
			if (invokingScalar) {
				throw failure;
			}
			throw new PackedCostSessionFailure("exact_append_failed", failure);
		}
	}

	/**
	 * Retains tuple-aware Frontier evidence across a locally evaluable property-path factor.
	 *
	 * <p>
	 * A path with an endpoint bound in every retained input stratum is a deterministic expansion of the outer measure.
	 * Evaluating that expansion against the planning snapshot therefore has the same linear semantics as an ordinary
	 * bound statement probe: emitted tuples inherit the complete outer weight and retain all correlations.
	 * {@link FrontierLinearTransforms#expandOuterMappings} applies the ordinary Frontier work and payload budgets,
	 * preserving an exact result when it fits and a design-valid weighted sample otherwise. The scalar property-path
	 * estimator remains the source of physical work; only its contextual result cardinality is replaced by the state
	 * produced by this transform.
	 * </p>
	 */
	private boolean appendBoundedLocalPath(int relationId, PackedCostContext context, EvidenceStateRef input,
			PackedCostEstimate output) {
		TupleExpr expression = query.materializeRelation(relationId);
		if (!(expression instanceof ArbitraryLengthPath) && !(expression instanceof ZeroLengthPath)) {
			return false;
		}
		if (evaluationStrategy == null || !isComposableState(input) || !exactLocalEvaluation(expression)
				|| !everyStratumBindsPathEndpoint(arena.key(input).maskStrata(), expression)) {
			return false;
		}
		FrontierMaskStrata outputMasks = optionalMaskStrata(arena.key(input).maskStrata(), expression);
		if (outputMasks == null) {
			return false;
		}
		FrontierStateKey outputKey = operatorStateKeyWithRelationFactors(arena.key(input), relationId, outputMasks);
		arena.declareCanonicalState(outputKey);
		double invocations = output.plannedDoubleMetric(
				"plannedRepeatedInvocations", Math.max(1.0d, context.prefixRows()));
		double workPerInvocation = finiteNonNegative(output.workRows()) && finiteNonNegative(invocations)
				&& invocations > 0.0d
						? output.workRows() / invocations
						: Double.NaN;
		int maximumMappings = maximumExactProbeMappings(
				settings.refinementWorkUnits(), workPerInvocation, 0.0d);
		output.putPlannedDoubleMetric("plannedFrontierPathWorkPerMapping", workPerInvocation);
		output.putPlannedDoubleMetric("plannedFrontierPathMaximumMappings", maximumMappings);
		FrontierLayout inputLayout = arena.key(input).frontier();
		FrontierLayout outputLayout = outputKey.frontier();
		long scratchBytes = Math.addExact(FILTER_BINDING_SCRATCH_BASE_BYTES,
				Math.multiplyExact(FILTER_BINDING_SCRATCH_SLOT_BYTES,
						Math.addExact(inputLayout.size(), outputLayout.size())));
		try (FrontierMemoryReservation ignored = arena.reserveTemporary(
				scratchBytes, FrontierMemoryPurpose.TARGET_COALESCING)) {
			String[] inputNames = layoutVariables(inputLayout);
			String[] outputNames = layoutVariables(outputLayout);
			ArrayBindingSet outerBindings = new ArrayBindingSet(inputNames);
			ArrayBindingSet mergedBindings = new ArrayBindingSet(outputNames);
			boolean lineageSpecific = arena.nearestCalibration(input) != null;
			EvidenceStateRef state = lineageSpecific ? null : arena.find(outputKey);
			if (state == null) {
				QueryEvaluationStep pathStep = preparedTupleStep(relationId, expression);
				long started = System.nanoTime();
				try {
					state = FrontierLinearTransforms.expandOuterMappings(
							arena,
							input,
							outputKey,
							relationId,
							(payload, exact, stratum, index, emitter) -> expandPathMapping(
									pathStep, payload, exact, stratum, index, inputNames, outputNames,
									outerBindings, mergedBindings, outputMasks, emitter),
							maximumMappings);
				} finally {
					pathExpansionPlanningNanos = Math.addExact(
							pathExpansionPlanningNanos, System.nanoTime() - started);
				}
				pathExpansionStates = Math.incrementExact(pathExpansionStates);
				rememberState(state);
			}
			if (!isComposableState(state)) {
				publishDegradedState(output, state);
				output.putPlannedStringMetric("plannedFrontierPathExpansion", "budget-bound");
				return true;
			}
			EvidenceStateSummary summary = state.summary();
			output.setEvidenceStateId(state.stateId());
			annotateReady(output, state);
			annotateFactorCount(output, state);
			output.putPlannedStringMetric("plannedPhysicalImplementation", "frontier-bounded-path");
			output.putPlannedStringMetric("plannedFrontierPathExpansion", "bounded-local-expansion");
			if (mode != FrontierEstimatorMode.AUTHORITATIVE) {
				return true;
			}
			if (summary.guarantee() == EvidenceGuarantee.MEASURE_UNBIASED
					&& summary.zeroStatus() == EvidenceZeroStatus.ESTIMATED_ZERO) {
				publishSampledZeroFallback(relationId, output, state);
				return true;
			}
			output.setContextualOutputRowsPreservingPhysicalCost(summary.pointRows());
			output.setEvidenceGuarantee(summary.guarantee());
			setFrontierProvenance(output, state);
			return true;
		} catch (OuterProbeFailure failure) {
			throw new PackedCostSessionFailure("path_state_materialization_failed", failure);
		} catch (RuntimeException failure) {
			throw new PackedCostSessionFailure("path_state_materialization_failed", failure);
		}
	}

	private QueryEvaluationStep preparedTupleStep(int relationId, TupleExpr expression) {
		if (preparedTupleSteps == null) {
			preparedTupleSteps = new QueryEvaluationStep[query.relationCount() + 1];
		}
		QueryEvaluationStep prepared = preparedTupleSteps[relationId];
		if (prepared == null) {
			prepared = evaluationStrategy.precompile(expression);
			preparedTupleSteps[relationId] = prepared;
		}
		return prepared;
	}

	private void expandPathMapping(QueryEvaluationStep pathStep, FrontierPayloadLease payload, boolean exact,
			int stratum,
			int index, String[] inputNames, String[] outputNames, ArrayBindingSet outerBindings,
			ArrayBindingSet mergedBindings, FrontierMaskStrata outputMasks, FrontierTupleEmitter emitter) {
		try {
			pathExpansionMappingProbes = Math.incrementExact(pathExpansionMappingProbes);
			populateBindings(payload, exact, stratum, index, inputNames, outerBindings);
			try (CloseableIteration<BindingSet> matches = pathStep.evaluate(outerBindings)) {
				while (matches.hasNext()) {
					populateMergedBindings(outputNames, outerBindings, matches.next(), mergedBindings);
					emitter.emit(maskStratum(outputMasks, mergedBindings),
							bindingTuple(outputNames, mergedBindings));
				}
			}
		} catch (IOException | QueryEvaluationException failure) {
			throw new OuterProbeFailure("Frontier property-path exact probe failed", failure);
		}
	}

	private static boolean everyStratumBindsPathEndpoint(FrontierMaskStrata inputMasks, TupleExpr expression) {
		Var subject;
		Var object;
		if (expression instanceof ArbitraryLengthPath path) {
			subject = path.getSubjectVar();
			object = path.getObjectVar();
		} else if (expression instanceof ZeroLengthPath path) {
			subject = path.getSubjectVar();
			object = path.getObjectVar();
		} else {
			return false;
		}
		for (int stratum = 0; stratum < inputMasks.stratumCount(); stratum++) {
			if (!endpointBound(inputMasks, stratum, subject) && !endpointBound(inputMasks, stratum, object)) {
				return false;
			}
		}
		return true;
	}

	private static boolean endpointBound(FrontierMaskStrata inputMasks, int stratum, Var endpoint) {
		if (endpoint == null) {
			return false;
		}
		if (endpoint.hasValue()) {
			return true;
		}
		int slot = endpoint.getName() == null ? -1 : inputMasks.layout().indexOf(endpoint.getName());
		return slot >= 0 && inputMasks.isBound(stratum, slot);
	}

	@Override
	public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
		boolean finiteFilterFallback = TelemetryMetricNames.ESTIMATE_FUSION_FINITE_FILTER_SEMANTIC_FALLBACK
				.equals(output.estimateFusion());
		scalar.refineOperator(relationId, context, output);
		boolean scalarExactJoin = output.evidenceGuarantee() == EvidenceGuarantee.DATABASE_EXACT
				&& query.materializeRelation(relationId) instanceof Join;
		double rawWorkRows = finiteFilterFallback
				&& TelemetryMetricNames.ESTIMATE_FUSION_FINITE_FILTER_SEMANTIC_FALLBACK
						.equals(output.estimateFusion())
								? Double.NaN
								: output.workRows();
		TupleExpr expression = query.materializeRelation(relationId);
		EvidenceStateRef candidate = stateReference(context.evidenceStateId());
		if (expression instanceof Join) {
			EvidenceStateRef left = stateReference(context.leftInputEvidenceStateId());
			EvidenceStateRef right = stateReference(context.rightInputEvidenceStateId());
			try {
				EvidenceStateRef rawState = resolveRawJoinState(relationId, candidate, left, right);
				if (rawState == null) {
					degradeOperator(relationId, output, null, "join_child_state_unavailable");
					return;
				}
				if (scalarExactJoin) {
					attachExactJoinState(output, rawState);
				} else {
					refineJoin(rawState, output);
				}
			} catch (RuntimeException failure) {
				throw new PackedCostSessionFailure("join_state_materialization_failed", failure);
			}
			return;
		}
		if (expression instanceof LeftJoin) {
			EvidenceStateRef left = stateReference(context.leftInputEvidenceStateId());
			if (candidate != null && !isComposableState(candidate)) {
				publishOperatorState(relationId, output, candidate);
				return;
			}
			if (left == null) {
				degradeOperator(relationId, output, null, "optional_left_state_unavailable");
				return;
			}
			if (!isComposableState(left)) {
				degradeOperator(relationId, output, left, left.summary().degradationReason());
				return;
			}
			refineOptional(relationId, context, (LeftJoin) expression, left, rawWorkRows, output);
			return;
		}
		if (expression instanceof Difference) {
			EvidenceStateRef left = stateReference(context.leftInputEvidenceStateId());
			if (candidate != null && !isComposableState(candidate)) {
				publishOperatorState(relationId, output, candidate);
				applyScalarDifferencePhysicalCost(context, rawWorkRows, output);
				return;
			}
			if (left == null) {
				degradeOperator(relationId, output, null, "minus_left_state_unavailable");
				applyScalarDifferencePhysicalCost(context, rawWorkRows, output);
				return;
			}
			if (!isComposableState(left)) {
				degradeOperator(relationId, output, left, left.summary().degradationReason());
				applyScalarDifferencePhysicalCost(context, rawWorkRows, output);
				return;
			}
			refineMinus(relationId, context, (Difference) expression, left, rawWorkRows, output);
			return;
		}
		if (expression instanceof Intersection) {
			EvidenceStateRef left = stateReference(context.leftInputEvidenceStateId());
			EvidenceStateRef right = stateReference(context.rightInputEvidenceStateId());
			if (left == null || right == null) {
				degradeOperator(relationId, output, left != null ? left : right,
						"intersection_child_state_unavailable");
				return;
			}
			refineIntersection(relationId, left, right, output);
			return;
		}
		if (expression instanceof Union) {
			if (candidate != null && !isComposableState(candidate)) {
				publishOperatorState(relationId, output, candidate);
				return;
			}
			EvidenceStateRef exactSurface = exactAlternativeState(relationId, expression);
			if (exactSurface != null) {
				publishOperatorState(relationId, output, exactSurface);
				return;
			}
			EvidenceStateRef left = stateReference(context.leftInputEvidenceStateId());
			EvidenceStateRef right = stateReference(context.rightInputEvidenceStateId());
			if (left == null || right == null) {
				degradeOperator(relationId, output, left != null ? left : right, "union_child_state_unavailable");
				return;
			}
			if (!isComposableState(left) || !isComposableState(right)) {
				publishUnionBoundary(relationId, output, left, right, "union_child_state_non_composable");
				return;
			}
			refineUnion(relationId, (Union) expression, left, right, rawWorkRows, output);
			return;
		}
		/*
		 * A contextual unary winner can be costed under an inherited prefix whose state is intentionally different from
		 * the state produced by the winner's child. Unary transforms consume that child state. Callers that do not
		 * publish explicit operator inputs retain the original prefix-state compatibility path.
		 */
		int inputStateId = context.leftInputEvidenceStateId() != 0
				? context.leftInputEvidenceStateId()
				: context.evidenceStateId();
		EvidenceStateRef input = stateReference(inputStateId);
		if (input == null) {
			if (expression instanceof Filter filter) {
				applyScalarFilterPhysicalCost(relationId, filter, context, rawWorkRows, output);
			}
			return;
		}
		if (!isComposableState(input)) {
			if (FrontierOperatorCapabilities.isIdentity(expression)) {
				publishOperatorState(relationId, output, input);
			} else if (expression instanceof Filter filter && pureExistsCondition(filter) != null) {
				refineBoundedSemiAntiFilter(relationId, context, filter, input, output);
			} else if (expression instanceof Projection) {
				publishCardinalityPreservingBoundary(
						relationId, output, input, "projection_input_payload_unavailable", 0.0d);
			} else if (expression instanceof Extension extension) {
				publishCardinalityPreservingBoundary(
						relationId,
						output,
						input,
						"extension_input_payload_unavailable",
						saturatedMultiply(input.summary().pointRows(), extension.getElements().size()));
			} else if (expression instanceof MultiProjection multiProjection) {
				refineBoundedMultiProjection(relationId, multiProjection, input, output);
			} else if (expression instanceof Distinct) {
				refineBoundedDistinct(relationId, input, output);
			} else if (expression instanceof Group group) {
				refineBoundedGroup(relationId, group, input, output);
			} else if (expression instanceof Reduced) {
				refineReduced(relationId, input, output);
			} else if (expression instanceof Slice slice) {
				refineSlice(relationId, slice, input, output);
			} else {
				degradeOperator(relationId, output, input, input.summary().degradationReason());
			}
			if (expression instanceof Filter filter && !output.dependentSubqueriesCosted()) {
				applyScalarFilterPhysicalCost(relationId, filter, context, rawWorkRows, output);
			}
			return;
		}
		if (expression instanceof Filter filter) {
			refineFilter(relationId, context, filter, input, rawWorkRows, output);
			if (!output.dependentSubqueriesCosted()) {
				applyScalarFilterPhysicalCost(relationId, filter, context, rawWorkRows, output);
			}
		} else if (expression instanceof Projection) {
			refineProjection(relationId, input, output);
		} else if (expression instanceof Extension) {
			refineExtension(relationId, (Extension) expression, input, rawWorkRows, output);
		} else if (expression instanceof MultiProjection) {
			refineMultiProjection(relationId, (MultiProjection) expression, input, rawWorkRows, output);
		} else if (expression instanceof Distinct) {
			refineDistinct(relationId, input, output);
		} else if (expression instanceof Group group) {
			refineGroup(relationId, group, input, output);
		} else if (expression instanceof Reduced) {
			refineReduced(relationId, input, output);
		} else if (expression instanceof Slice slice) {
			refineSlice(relationId, slice, input, output);
		} else if (FrontierOperatorCapabilities.isIdentity(expression)) {
			publishOperatorState(relationId, output, input);
		} else {
			degradeOperator(relationId, output, input, FrontierOperatorCapabilities.boundaryReason(expression));
		}
	}

	@Override
	public void refineIntermediateJoin(PackedCostContext context, PackedCostEstimate output) {
		boolean physicalEvent = output.plannedStringMetric("optimizer.physicalJoinImplementation") != null;
		EvidenceStateRef candidate = stateReference(context.evidenceStateId());
		EvidenceStateRef left = stateReference(context.leftInputEvidenceStateId());
		EvidenceStateRef right = stateReference(context.rightInputEvidenceStateId());
		String eventRole = physicalEvent ? "Physical" : "Logical";
		annotateIntermediateJoinState(output, eventRole + "Candidate", candidate);
		annotateIntermediateJoinState(output, eventRole + "Left", left);
		annotateIntermediateJoinState(output, eventRole + "Right", right);
		boolean candidateMatchesChildLineage = !physicalEvent
				&& candidate != null
				&& intermediateCandidateMatchesChildLineage(candidate, left, right);
		if (!physicalEvent) {
			output.putPlannedDoubleMetric("optimizer.frontierJoinLogicalCandidateMatchesChildLineage",
					candidateMatchesChildLineage ? 1.0d : 0.0d);
		}
		if (physicalEvent
				&& "independent-hash".equals(output.plannedStringMetric("optimizer.physicalJoinImplementation"))) {
			refineIndependentHashPhysicalCost(context, output, left, right);
		}
		if (physicalEvent && candidate != null) {
			/*
			 * A physical implementation event refines the already-costed logical candidate. Preserve that exact state,
			 * including calibration lineage, instead of invoking the join transform a second time after the decision.
			 */
			attachJoinState(output, candidate, true);
			return;
		}
		if (candidateMatchesChildLineage) {
			/*
			 * A dependent factor is costed against the complete inherited prefix. Its resulting candidate is therefore
			 * the logical join state, while the standalone memo winner supplied as the physical right child can
			 * legitimately be bound-only. Verify the candidate against the transitive logical factors of both child
			 * lineages before accepting it. Requiring both children themselves to be composable would discard the exact
			 * contextual event and rebuild an opaque boundary even though the provider already measured the complete
			 * join.
			 */
			attachJoinState(output, candidate, false);
			return;
		}
		if (left == null || right == null) {
			/*
			 * A selected hash-join subtree can retain the query-local state chosen during enumeration even when its
			 * physical children no longer expose an execution-order prefix from which to reconstruct that state. The
			 * candidate is the memo winner's state, so publish its complete summary instead of retaining only its
			 * numeric ID. Without this, relation metadata can still say "ready" while the selected physical JOIN loses
			 * the corresponding guarantee and interval.
			 */
			if (physicalEvent) {
				retainPhysicalJoinBoundary(output, left != null ? left : right,
						"intermediate_join_child_state_unavailable");
			} else {
				degradeOperator(output, null, "intermediate_join_child_state_unavailable");
			}
			return;
		}
		if (!isComposableState(left)
				|| !isComposableState(right)
				|| !arena.hasCanonicalKey(left)
				|| !arena.hasCanonicalKey(right)) {
			retainIntermediateJoinBoundary(output, left, right,
					"intermediate_join_child_state_non_composable");
			return;
		}
		try {
			long[] factors = unionFactorWords(arena.key(left), arena.key(right));
			EvidenceStateRef state = resolveRawJoinState(0, factors, candidate, left, right);
			if (state != null) {
				attachJoinState(output, state, physicalEvent);
			}
		} catch (RuntimeException failure) {
			throw new PackedCostSessionFailure("intermediate_join_state_materialization_failed", failure);
		}
	}

	private void refineIndependentHashPhysicalCost(PackedCostContext context, PackedCostEstimate output,
			EvidenceStateRef leftState, EvidenceStateRef rightState) {
		double leftRows = context.leftInputRows();
		double rightRows = context.rightInputRows();
		double executionPartitions = finiteNonNegative(output.invocations()) && output.invocations() > 0.0d
				? output.invocations()
				: 1.0d;
		FrontierCorrelationDomain leftDomain = null;
		FrontierCorrelationDomain rightDomain = null;
		if (context.hashLookupMaskId() != 0 && leftState != null && rightState != null) {
			List<String> lookupBindings = query.bindingNames(context.hashLookupMaskId());
			leftDomain = correlationDomain(leftState, lookupBindings);
			rightDomain = correlationDomain(rightState, lookupBindings);
		}
		LmdbHashJoinCosting.CandidateEstimate candidates = LmdbHashJoinCosting.estimateCandidates(
				leftRows, rightRows, executionPartitions, output.outputRows(), context.hashLookupMaskId(), leftDomain,
				rightDomain);
		LmdbHashJoinCosting.Orientation orientation = LmdbHashJoinCosting.chooseOrientation(
				leftRows, rightRows, executionPartitions, candidates.candidateRows(), output.outputRows(),
				MinusQueryEvaluationStep.maxMaterializedRightRows());
		double probeRows = saturatedAdd(orientation.probeInputRows(), candidates.candidateRows());
		output.setLocalPhysicalCost(
				0.0d, 0.0d, 0.0d, 0.0d, orientation.buildRows(), probeRows, 0.0d, output.outputRows(), 0.0d,
				orientation.peakMemoryRows());
		output.putPlannedStringMetric("optimizer.hashJoinBuildSide", orientation.buildFromLeft() ? "left" : "right");
		output.putPlannedStringMetric("optimizer.hashJoinCandidateEstimateSource", candidates.source());
		output.putPlannedDoubleMetric("optimizer.hashJoinBuildRows", orientation.buildRows());
		output.putPlannedDoubleMetric("optimizer.hashJoinProbeInputRows", orientation.probeInputRows());
		output.putPlannedDoubleMetric("optimizer.hashJoinCandidateRows", candidates.candidateRows());
		output.putPlannedDoubleMetric("optimizer.hashJoinPeakMemoryRows", orientation.peakMemoryRows());
		output.putPlannedDoubleMetric("optimizer.hashJoinExecutionPartitions", executionPartitions);
		if (finiteNonNegative(candidates.leftJointNdv())) {
			output.putPlannedDoubleMetric("optimizer.hashJoinLeftJointNdv", candidates.leftJointNdv());
		}
		if (finiteNonNegative(candidates.rightJointNdv())) {
			output.putPlannedDoubleMetric("optimizer.hashJoinRightJointNdv", candidates.rightJointNdv());
		}
		if (orientation.buildFromLeft()) {
			publishHashOrientationNdv(output, candidates.leftJointNdv(), candidates.rightJointNdv());
		} else {
			publishHashOrientationNdv(output, candidates.rightJointNdv(), candidates.leftJointNdv());
		}
	}

	private static void publishHashOrientationNdv(PackedCostEstimate output, double buildJointNdv,
			double probeJointNdv) {
		if (finiteNonNegative(buildJointNdv)) {
			output.putPlannedDoubleMetric("optimizer.hashJoinBuildJointNdv", buildJointNdv);
		}
		if (finiteNonNegative(probeJointNdv)) {
			output.putPlannedDoubleMetric("optimizer.hashJoinProbeJointNdv", probeJointNdv);
		}
	}

	private void annotateIntermediateJoinState(PackedCostEstimate output, String role, EvidenceStateRef state) {
		output.putPlannedDoubleMetric("optimizer.frontierJoin" + role + "StateId",
				state == null ? 0.0d : state.stateId());
		output.putPlannedStringMetric("optimizer.frontierJoin" + role + "Disposition",
				state == null ? "unavailable" : arena.disposition(state).name().toLowerCase(Locale.ROOT));
		if (state != null) {
			output.putPlannedDoubleMetric("optimizer.frontierJoin" + role + "FactorCount", factorCount(state));
			output.putPlannedStringMetric("optimizer.frontierJoin" + role + "Guarantee",
					state.summary().guarantee().name().toLowerCase(Locale.ROOT));
		}
	}

	private boolean intermediateCandidateMatchesChildLineage(EvidenceStateRef candidate, EvidenceStateRef left,
			EvidenceStateRef right) {
		if (left == null || right == null) {
			return false;
		}
		int factorWordCount = (query.relationCount() + 63) >>> 6;
		if (factorCountWords == null || factorCountWords.length < factorWordCount) {
			factorCountWords = new long[factorWordCount];
		} else {
			Arrays.fill(factorCountWords, 0, factorWordCount, 0L);
		}
		if (candidateFactorWords == null || candidateFactorWords.length < factorWordCount) {
			candidateFactorWords = new long[factorWordCount];
		} else {
			Arrays.fill(candidateFactorWords, 0, factorWordCount, 0L);
		}
		int requiredVisitCapacity = stateReferences == null
				? Math.max(candidate.stateId(), Math.max(left.stateId(), right.stateId())) + 1
				: stateReferences.length;
		if (factorCountVisitEpochs == null || factorCountVisitEpochs.length < requiredVisitCapacity) {
			factorCountVisitEpochs = new int[requiredVisitCapacity];
			factorCountVisitEpoch = 0;
		}
		int visitEpoch = nextFactorCountVisitEpoch();
		collectLineageFactors(left, factorCountWords, factorCountVisitEpochs, visitEpoch);
		collectLineageFactors(right, factorCountWords, factorCountVisitEpochs, visitEpoch);
		visitEpoch = nextFactorCountVisitEpoch();
		collectLineageFactors(candidate, candidateFactorWords, factorCountVisitEpochs, visitEpoch);
		for (int word = 0; word < factorWordCount; word++) {
			if (candidateFactorWords[word] != factorCountWords[word]) {
				return false;
			}
		}
		return true;
	}

	private void retainIntermediateJoinBoundary(PackedCostEstimate output, EvidenceStateRef left,
			EvidenceStateRef right, String reason) {
		double pointRows = finiteNonNegative(output.outputRows())
				? output.outputRows()
				: saturatedMultiply(left.summary().pointRows(), right.summary().pointRows());
		EvidenceStateRef boundary = arena.deriveOpaqueBoundary(
				left,
				right,
				unionLayout(arena.layout(left), arena.layout(right)),
				EvidenceStateSummary.unresolved(pointRows, Double.POSITIVE_INFINITY,
						Double.POSITIVE_INFINITY, reason),
				0);
		rememberState(boundary);
		output.setEvidenceStateId(boundary.stateId());
		annotateState(output, boundary, "degraded");
		output.putPlannedStringMetric("plannedFrontierFallbackReason", reason);
	}

	private void attachJoinState(PackedCostEstimate output, EvidenceStateRef state, boolean physicalEvent) {
		if (physicalEvent && !isComposableState(state)) {
			retainPhysicalJoinBoundary(output, state, state.summary().degradationReason());
			return;
		}
		if (!physicalEvent && isComposableState(state)) {
			/*
			 * An intermediate logical join can be introduced solely by the physical enumerator, so its scalar fallback
			 * need not have passed through appendFactor. Publish the Frontier point estimate on that originating event;
			 * the subsequent physical event then consumes the immutable state and rows without reconstructing either.
			 */
			output.setContextualOutputRowsPreservingPhysicalCost(state.summary().pointRows());
		}
		attachExactJoinState(output, state);
	}

	/**
	 * Retains typed Frontier lineage on an already-costed physical join without replacing its implementation vector.
	 * Evidence disposition and physical work are independent axes: an opaque or bound-only state must not turn a hash
	 * build/probe event back into scalar result-row work.
	 */
	private void retainPhysicalJoinBoundary(PackedCostEstimate output, EvidenceStateRef input, String reason) {
		double pointRows = finiteNonNegative(output.outputRows()) ? output.outputRows() : 1.0d;
		EvidenceStateSummary summary = EvidenceStateSummary.unresolved(pointRows, Double.POSITIVE_INFINITY,
				Double.POSITIVE_INFINITY, reason);
		EvidenceStateRef boundary;
		if (input != null) {
			boundary = arena.deriveOpaqueBoundary(input, summary, 0);
		} else if (arena != null) {
			boundary = arena.append(FrontierLayout.empty(), summary);
		} else {
			output.setEvidenceStateId(0);
			output.putPlannedStringMetric("plannedFrontierStatus", "degraded");
			output.putPlannedStringMetric("plannedFrontierMode", mode.getConfigValue());
			output.putPlannedStringMetric("plannedFrontierFallbackReason", reason);
			return;
		}
		rememberState(boundary);
		output.setEvidenceStateId(boundary.stateId());
		annotateState(output, boundary, "degraded");
		annotateFactorCount(output, boundary);
		output.putPlannedStringMetric("plannedFrontierFallbackReason", reason);
	}

	@Override
	public double objectiveScore(PackedCostEstimate estimate) {
		double normalized = normalizedObjectiveScore(estimate, MinusQueryEvaluationStep.maxMaterializedRightRows());
		return normalized == Double.MAX_VALUE ? normalized : physicalCostObjective.score(estimate);
	}

	static double normalizedObjectiveScore(PackedCostEstimate estimate, long maxMaterializedRows) {
		double peakMemoryRows = estimate.peakMemoryRows();
		if (Double.isFinite(peakMemoryRows)
				&& peakMemoryRows > Math.max(0L, maxMaterializedRows)) {
			return Double.MAX_VALUE;
		}
		return estimate.workRows();
	}

	private void attachExactJoinState(PackedCostEstimate output, EvidenceStateRef state) {
		EvidenceStateSummary summary = state.summary();
		if (!isComposableState(state)) {
			publishDegradedState(output, state);
			return;
		}
		output.setEvidenceStateId(state.stateId());
		annotateReady(output, state);
		annotateFactorCount(output, state);
	}

	private void refineJoin(EvidenceStateRef rawState, PackedCostEstimate output) {
		publishJoinState(output, rawState);
	}

	private EvidenceStateRef resolveRawJoinState(int relationId, EvidenceStateRef candidate,
			EvidenceStateRef left, EvidenceStateRef right) {
		return resolveRawJoinState(relationId, relationFactorWords(relationId), candidate, left, right);
	}

	private EvidenceStateRef resolveRawJoinState(int relationId, long[] relationFactors, EvidenceStateRef candidate,
			EvidenceStateRef left, EvidenceStateRef right) {
		boolean candidateComposable = isComposableState(candidate);
		FrontierStateKey candidateKey = candidateComposable ? arena.key(candidate) : null;
		boolean candidateCoversRelation = candidateComposable
				&& candidateKey != null
				&& factorWordsEqual(candidateKey, relationFactors);
		EvidenceStateRef fallbackCandidate = candidate != null && (!candidateComposable || candidateCoversRelation)
				? candidate
				: null;
		if (left == null || right == null) {
			return fallbackCandidate;
		}
		if (!isComposableState(left) || !isComposableState(right)) {
			return fallbackCandidate;
		}
		FrontierStateKey leftKey = arena.key(left);
		FrontierStateKey rightKey = arena.key(right);
		if (leftKey == null || rightKey == null) {
			return fallbackCandidate;
		}
		long[] childFactors = unionFactorWords(leftKey, rightKey);
		if (!Arrays.equals(childFactors, relationFactors)) {
			return fallbackCandidate;
		}
		FrontierStateKey outputKey = joinedStateKey(leftKey, rightKey);
		EvidenceStateRef independentCartesian = resolveIndependentCartesian(
				relationId, candidateCoversRelation ? candidate : null, outputKey);
		if (independentCartesian != null) {
			return independentCartesian;
		}
		if (candidateCoversRelation) {
			return candidate;
		}
		/*
		 * A dependent child is costed in its inherited binding context, so its Frontier state can already contain the
		 * complete prefix while its physical sibling denotes an earlier subset of that same prefix. Such states are not
		 * independent join inputs. Reusing the child that already covers the complete logical factor set preserves the
		 * exact costing event and avoids composing the inherited prefix twice.
		 */
		if (factorWordsEqual(leftKey, relationFactors)) {
			return left;
		}
		if (factorWordsEqual(rightKey, relationFactors)) {
			return right;
		}
		arena.declareCanonicalState(outputKey);
		boolean lineageSpecific = arena.nearestCalibration(left) != null
				|| arena.nearestCalibration(right) != null;
		EvidenceStateRef state = lineageSpecific ? null : arena.find(outputKey);
		if (state == null) {
			state = resolveConditionalStatementJoin(left, right, outputKey);
			if (state == null) {
				state = resolveConditionalTopologyJoin(left, right, outputKey);
			}
			if (state == null) {
				state = FrontierLinearTransforms.join(
						arena,
						left,
						right,
						outputKey,
						relationId,
						settings.refinementWorkUnits());
			}
			rememberState(state);
		}
		return state;
	}

	private EvidenceStateRef resolveConditionalStatementJoin(EvidenceStateRef left, EvidenceStateRef right,
			FrontierStateKey outputKey) {
		if (statementSource == null
				|| left.summary().guarantee() == EvidenceGuarantee.DATABASE_EXACT
				|| right.summary().guarantee() == EvidenceGuarantee.DATABASE_EXACT) {
			return null;
		}
		LeafState rightFactor = singleStatementFactor(right);
		if (rightFactor != null) {
			return extendInner(left, rightFactor, outputKey, rightFactor.relationId);
		}
		LeafState leftFactor = singleStatementFactor(left);
		return leftFactor == null ? null : extendInner(right, leftFactor, outputKey, leftFactor.relationId);
	}

	/**
	 * Replays a composable factor topology as bound transforms over the other input.
	 *
	 * <p>
	 * Two sampled Frontier relations generally cannot be multiplied as independent reservoirs: they may share a
	 * coordinated inclusion design, and their pair surface can also exceed the finite join budget. The RHS lineage
	 * already records how its factors were constructed. When that lineage consists solely of replayable statement and
	 * finite-relation additions, applying those same kernels to the left payload is the conditional join estimator that
	 * matches dependent execution. This retains tuple covariance and avoids the scalar product fallback without
	 * inventing an independence assumption.
	 */
	private EvidenceStateRef resolveConditionalTopologyJoin(EvidenceStateRef left, EvidenceStateRef right,
			FrontierStateKey outputKey) {
		if (statementSource == null
				|| !disjointFactors(arena.key(left), arena.key(right))) {
			return null;
		}
		EvidenceStateRef replayed = replayFactorTopology(left, right, outputKey);
		if (replayed != null) {
			return replayed;
		}
		return replayFactorTopology(right, left, outputKey);
	}

	private EvidenceStateRef replayFactorTopology(EvidenceStateRef input, EvidenceStateRef topology,
			FrontierStateKey outputKey) {
		int topologyFactorCount = factorCount(topology);
		if (topologyFactorCount <= 1) {
			return null;
		}
		int[] replayRelations = new int[topologyFactorCount];
		boolean[] seenRelations = new boolean[query.relationCount() + 1];
		int replayCount = collectReplayRelations(topology, replayRelations, 0, seenRelations);
		if (replayCount != topologyFactorCount
				|| !replayRelationsMatchState(topology, seenRelations)) {
			return null;
		}

		EvidenceStateRef current = input;
		for (int ordinal = 0; ordinal < replayCount; ordinal++) {
			FrontierStateKey finalKey = ordinal + 1 == replayCount ? outputKey : null;
			current = appendReplayFactor(current, replayRelations[ordinal], finalKey);
			if (!isComposableState(current)) {
				return null;
			}
		}
		return factorWordsEqual(arena.key(current), logicalFactorWords(outputKey)) ? current : null;
	}

	private int collectReplayRelations(EvidenceStateRef state, int[] destination, int offset,
			boolean[] seenRelations) {
		return switch (arena.operation(state)) {
		case EXACT_LEAF, COORDINATED_STAR -> appendReplayRelation(
				arena.operationRecipeId(state), destination, offset, seenRelations);
		case BRIDGE_TRANSFER, BRIDGE_MUTATION, PROBE_FACTOR -> {
			if (arena.parentCount(state) != 1) {
				yield -1;
			}
			int next = collectReplayRelations(arena.parent(state, 0), destination, offset, seenRelations);
			yield next < 0 ? -1
					: appendReplayRelation(
							arena.operationRecipeId(state), destination, next, seenRelations);
		}
		case JOIN, CARTESIAN -> {
			if (arena.parentCount(state) != 2) {
				yield -1;
			}
			int next = collectReplayRelations(arena.parent(state, 0), destination, offset, seenRelations);
			yield next < 0
					? -1
					: collectReplayRelations(arena.parent(state, 1), destination, next, seenRelations);
		}
		case AVERAGE_DESIGN_LANES -> arena.parentCount(state) == 2
				? collectReplayRelations(arena.parent(state, 0), destination, offset, seenRelations)
				: -1;
		default -> -1;
		};
	}

	private int appendReplayRelation(int relationId, int[] destination, int offset, boolean[] seenRelations) {
		if (relationId <= 0 || relationId >= seenRelations.length
				|| seenRelations[relationId] || offset >= destination.length
				|| leafState(relationId) == null && finiteLeafState(relationId) == null) {
			return -1;
		}
		seenRelations[relationId] = true;
		destination[offset] = relationId;
		return offset + 1;
	}

	private boolean replayRelationsMatchState(EvidenceStateRef state, boolean[] seenRelations) {
		FrontierStateKey key = arena.key(state);
		for (int relationId = 1; relationId < seenRelations.length; relationId++) {
			if (seenRelations[relationId] != containsFactor(key, relationId)) {
				return false;
			}
		}
		return true;
	}

	private EvidenceStateRef appendReplayFactor(EvidenceStateRef input, int relationId,
			FrontierStateKey requestedOutputKey) {
		LeafState leaf = leafState(relationId);
		FiniteLeafState finite = finiteLeafState(relationId);
		FrontierStateKey factorKey = leaf != null ? leaf.key : finite != null ? finite.key : null;
		if (factorKey == null
				|| containsFactor(arena.key(input), relationId)
				|| !sameSamplingIdentity(arena.key(input), factorKey)) {
			return null;
		}
		FrontierStateKey naturalOutputKey = joinedStateKey(arena.key(input), factorKey);
		FrontierStateKey outputKey = requestedOutputKey == null ? naturalOutputKey : requestedOutputKey;
		if (!factorWordsEqual(outputKey, logicalFactorWords(naturalOutputKey))
				|| !outputKey.maskStrata().equals(naturalOutputKey.maskStrata())
				|| !sameSamplingIdentity(outputKey, naturalOutputKey)) {
			return null;
		}
		arena.declareCanonicalState(outputKey);
		boolean lineageSpecific = arena.nearestCalibration(input) != null;
		EvidenceStateRef state = lineageSpecific ? null : arena.find(outputKey);
		if (state == null) {
			state = leaf != null
					? extendInner(input, leaf, outputKey, relationId)
					: extendFinite(input, finite, outputKey, relationId);
			rememberState(state);
		}
		return state;
	}

	private LeafState singleStatementFactor(EvidenceStateRef state) {
		if (leafStates == null || !arena.hasCanonicalKey(state) || factorCount(state) != 1) {
			return null;
		}
		FrontierStateKey key = arena.key(state);
		for (int relationId = 1; relationId < leafStates.length; relationId++) {
			LeafState leaf = leafState(relationId);
			if (leaf != null && containsFactor(key, relationId)) {
				return leaf;
			}
		}
		return null;
	}

	private EvidenceStateRef resolveIndependentCartesian(int relationId, EvidenceStateRef candidate,
			FrontierStateKey joinedKey) {
		if (candidate != null
				&& arena.operation(candidate) != FrontierStateOperation.BRIDGE_MUTATION
				&& !exactProbeBudgetExceeded(candidate)) {
			return null;
		}
		LeafState leftLeaf = null;
		LeafState rightLeaf = null;
		for (int leafRelationId = 1; leafRelationId < leafStates.length; leafRelationId++) {
			LeafState leaf = leafState(leafRelationId);
			if (leaf == null || !containsFactor(joinedKey, leafRelationId)) {
				continue;
			}
			if (leftLeaf == null) {
				leftLeaf = leaf;
			} else if (rightLeaf == null) {
				rightLeaf = leaf;
			} else {
				return null;
			}
		}
		if (leftLeaf == null || rightLeaf == null
				|| leftLeaf.state.summary().guarantee() != EvidenceGuarantee.MEASURE_UNBIASED
				|| rightLeaf.state.summary().guarantee() != EvidenceGuarantee.MEASURE_UNBIASED
				|| !disjointLayouts(leftLeaf.key.frontier(), rightLeaf.key.frontier())) {
			return null;
		}
		FrontierStateKey productKey = joinedStateKey(leftLeaf.key, rightLeaf.key);
		if (!productKey.maskStrata().equals(joinedKey.maskStrata())
				|| !factorWordsEqual(productKey, logicalFactorWords(joinedKey))) {
			return null;
		}
		FrontierStateKey outputKey = operatorStateKey(
				productKey, logicalFactorWords(productKey), relationId, productKey.maskStrata());
		EvidenceStateRef rightIndependent = materializeIndependentLeaf(rightLeaf);
		EvidenceStateRef leftIndependent = rightIndependent == null
				? materializeIndependentLeaf(leftLeaf)
				: null;
		arena.declareCanonicalState(outputKey);
		EvidenceStateRef state = arena.find(outputKey);
		if (state == null) {
			EvidenceStateRef firstParent;
			EvidenceStateRef independentParent;
			if (rightIndependent != null) {
				firstParent = leftLeaf.state;
				independentParent = rightIndependent;
			} else if (leftIndependent != null) {
				firstParent = rightLeaf.state;
				independentParent = leftIndependent;
			} else {
				return null;
			}
			state = FrontierLinearTransforms.independentCartesian(
					arena,
					firstParent,
					independentParent,
					outputKey,
					relationId,
					settings.refinementWorkUnits());
			rememberState(state);
		}
		return state;
	}

	private EvidenceStateRef materializeIndependentLeaf(LeafState leaf) {
		if (leaf == null || leaf.independentKey == null || queryIndexLease == null) {
			return null;
		}
		if (leaf.independentState != null) {
			return leaf.independentState;
		}
		long candidateRows = queryIndexLease.designLaneCandidateRows(
				leaf.selector(), INDEPENDENT_DESIGN_LANE_INDEX);
		if (candidateRows > independentMaterializationWorkRemaining
				|| candidateRows > MAXIMUM_LEAF_BUFFER_ROWS) {
			return null;
		}
		try (EmissionBuffer rows = new EmissionBuffer(arena, 4, Math.toIntExact(candidateRows))) {
			long matchedRows = queryIndexLease.visitDesignLaneMatches(
					leaf.selector(),
					INDEPENDENT_DESIGN_LANE_INDEX,
					(subjectId, predicateId, objectId, contextId, weight) -> rows.addRow(
							subjectId, predicateId, objectId, contextId, weight));
			independentMaterializationWorkRemaining -= candidateRows;
			queryIndexVisitedRows = Math.addExact(queryIndexVisitedRows, candidateRows);
			queryIndexScanPasses = Math.incrementExact(queryIndexScanPasses);
			if (matchedRows != rows.size()) {
				throw new IllegalStateException("Frontier independent-lane scan misreported matches");
			}
			leaf.independentState = materializeLeafBuffer(
					arena,
					leaf,
					leaf.independentKey,
					rows,
					false,
					leaf.relationId);
			rememberState(leaf.independentState);
			queryIndexMatchedRows = Math.addExact(queryIndexMatchedRows, matchedRows);
			queryIndexIndependentMaterializedLeaves = Math.incrementExact(
					queryIndexIndependentMaterializedLeaves);
			queryIndexIndependentMaterializedRows = Math.addExact(
					queryIndexIndependentMaterializedRows, matchedRows);
			return leaf.independentState;
		}
	}

	private static boolean containsFactor(FrontierStateKey key, int relationId) {
		int factorIndex = relationId - 1;
		int word = factorIndex >>> 6;
		return word < key.logicalFactorWordCount()
				&& (key.logicalFactorWord(word) & 1L << (factorIndex & 63)) != 0L;
	}

	private static boolean disjointFactors(FrontierStateKey left, FrontierStateKey right) {
		int wordCount = Math.min(left.logicalFactorWordCount(), right.logicalFactorWordCount());
		for (int word = 0; word < wordCount; word++) {
			if ((left.logicalFactorWord(word) & right.logicalFactorWord(word)) != 0L) {
				return false;
			}
		}
		return true;
	}

	private static boolean disjointLayouts(FrontierLayout left, FrontierLayout right) {
		for (int slot = 0; slot < left.size(); slot++) {
			if (right.indexOf(left.variable(slot)) >= 0) {
				return false;
			}
		}
		return true;
	}

	private long[] relationFactorWords(int relationId) {
		long[] factors = new long[(query.relationCount() + 63) >>> 6];
		addRelationFactors(relationId, factors, new boolean[query.relationCount() + 1]);
		int length = factors.length;
		while (length > 0 && factors[length - 1] == 0L) {
			length--;
		}
		return length == factors.length ? factors : Arrays.copyOf(factors, length);
	}

	private static boolean factorWordsEqual(FrontierStateKey key, long[] factors) {
		int wordCount = Math.max(key.logicalFactorWordCount(), factors.length);
		for (int word = 0; word < wordCount; word++) {
			long keyWord = word < key.logicalFactorWordCount() ? key.logicalFactorWord(word) : 0L;
			long factorWord = word < factors.length ? factors[word] : 0L;
			if (keyWord != factorWord) {
				return false;
			}
		}
		return true;
	}

	private boolean logicalOutputMatchesLearningIdentity(int relationId, FrontierStateKey stateKey,
			ProductionLearningIdentity identity) {
		if (relationId <= 0 || stateKey == null) {
			return true;
		}
		LmdbRuntimeFeedbackDescriptor.LogicalGroupOrigin relationOrigin = identity.logicalGroupOrigin();
		LmdbRuntimeFeedbackDescriptor.LogicalGroupOrigin stateOrigin = logicalGroupOrigin(0, stateKey);
		return relationOrigin.certified() && relationOrigin.equals(stateOrigin);
	}

	void applyFrontierLearning(int relationId, PackedCostContext context, PackedCostEstimate output) {
		if (closed || arena == null || output == null || output.evidenceStateId() == 0) {
			return;
		}
		EvidenceStateRef predictedState = stateReference(output.evidenceStateId());
		if (predictedState == null) {
			return;
		}
		EvidenceStateRef transformState = rawTransformState(predictedState);
		FrontierStateKey stateKey = arena.hasCanonicalKey(transformState) ? arena.key(transformState) : null;
		FrontierLearningKey learningKey = FrontierLearningKey.of(
				learningOperatorFamily(relationId),
				learningRawTransform(relationId, transformState, context),
				learningLayoutFingerprint(stateKey, transformState, context),
				stateKey == null ? context.correlationMaskId() : stateKey.correlationScope(),
				learningAccessKernel(output),
				output.indexName(),
				output.accessMode());
		ProductionLearningIdentity productionIdentity = productionLearningIdentity(
				relationId, transformState, stateKey, context, output);
		boolean logicalOutputMatchesIdentity = logicalOutputMatchesLearningIdentity(
				relationId, stateKey, productionIdentity);
		String rawStateDigest = learningStateDigest(predictedState);
		output.putPlannedStringMetric("optimizer.frontierLearningKey", learningKey.externalForm());
		stampProductionLearningIdentity(output, productionIdentity, learningKey);
		output.putPlannedStringMetric("optimizer.frontierRawStateDigest", rawStateDigest);
		output.putPlannedStringMetric("optimizer.frontierStateDigest", rawStateDigest);
		output.putPlannedDoubleMetric("optimizer.frontierLeoRevision", runtime.leoRevision());

		LmdbOperatorFeedbackStats feedbackStats = runtime.feedback();
		if (feedbackStats == null) {
			return;
		}
		EvidenceStateSummary predictedSummary = predictedState.summary();
		boolean databaseExact = predictedSummary.guarantee() == EvidenceGuarantee.DATABASE_EXACT;
		if (!logicalOutputMatchesIdentity) {
			/*
			 * appendFactor costs one physical relation while its Frontier state and scalar output describe the complete
			 * joined prefix. The relation's conditional posterior remains valid for the pre-bound runtime recorder, but
			 * it is not commensurate with the contextual join cardinality. Applying it here would calibrate a join
			 * state with a child-expression key and let the child correction leak into every later implementation of
			 * the join.
			 */
			output.putPlannedStringMetric("optimizer.frontierLeo.output_rows.admission",
					"rejected-logical-origin-mismatch");
		}
		String groupFactKey = null;
		double exactFactRows = Double.NaN;
		if (frontierExactCardinalityFactsEnabled()
				&& logicalOutputMatchesIdentity
				&& (stateKey == null ? context.correlationMaskId() : stateKey.correlationScope()) == 0
				&& prefixCoversRelationInput(relationId, context)) {
			groupFactKey = productionIdentity.logicalKey().externalForm();
			if (groupFactKey != null) {
				output.putPlannedStringMetric("optimizer.frontierLogicalGroupKey", groupFactKey);
				exactFactRows = feedbackStats.exactCardinalityFact(
						productionIdentity.logicalKey(), productionIdentity.applicability());
			}
		}
		double eventPredictionRows = finiteNonNegative(output.outputRows())
				? output.outputRows()
				: predictedSummary.pointRows();
		double learningPredictionRows = isComposableState(predictedState)
				? predictedSummary.pointRows()
				: eventPredictionRows;
		if (!databaseExact && finiteNonNegative(exactFactRows)) {
			// Same-stamp observed cardinality: the fact replaces both the raw estimate and any learned correction.
			if (!isComposableState(predictedState)) {
				predictedState = alignNonComposableCostingState(relationId, predictedState, output);
				predictedSummary = predictedState.summary();
			}
			String evidenceKey = groupFactKey + ':' + productionIdentity.applicability().digest() + ":exact_fact";
			if (!arena.containsCalibrationEvidence(predictedState, evidenceKey)) {
				double factor = predictedSummary.pointRows() == 0.0d
						? exactFactRows == 0.0d ? 0.0d : Double.POSITIVE_INFINITY
						: exactFactRows / predictedSummary.pointRows();
				EvidenceCalibrationSummary calibration = new EvidenceCalibrationSummary(
						predictedSummary.pointRows(),
						exactFactRows,
						factor,
						FRONTIER_EXACT_FACT_CALIBRATION_SOURCE,
						1L,
						1.0d,
						evidenceKey,
						runtime.learnedEvidenceRevision());
				EvidenceStateRef factState = arena.calibrate(predictedState, calibration, relationId);
				rememberState(factState);
				output.setEvidenceStateId(factState.stateId());
				output.setEvidenceGuarantee(factState.summary().guarantee());
				if (output.hasComponentOutputRows()) {
					output.setComponentOutputRowsPreservingPhysicalCost(factState.summary().pointRows());
				} else if (output.hasContextualOutputRows()) {
					output.setContextualOutputRowsPreservingPhysicalCost(factState.summary().pointRows());
				} else {
					output.setOutputRowsPreservingPhysicalCost(factState.summary().pointRows());
				}
				synchronizeSemiAntiCorrelationRows(output, factState.summary(), factState.summary().pointRows());
				annotateReady(output, factState);
				output.setEstimateProvenance(FRONTIER_LEO_SOURCE, "frontier_exact_fact");
				output.putPlannedStringMetric("optimizer.frontierLeo.output_rows.source", "exact-fact");
				output.putPlannedDoubleMetric("optimizer.frontierLeo.output_rows.raw",
						predictedSummary.pointRows());
				output.putPlannedDoubleMetric("optimizer.frontierLeo.output_rows.corrected", exactFactRows);
				int factPhysicalCorrections = applyFrontierPhysicalLearning(productionIdentity, output, feedbackStats);
				output.putPlannedDoubleMetric(
						"optimizer.frontierLeoPhysicalDimensionCount", factPhysicalCorrections);
				output.putPlannedStringMetric("optimizer.frontierStateDigest", learningStateDigest(factState));
				applyObjectiveRiskAndLifecycle(productionIdentity, output, feedbackStats);
				return;
			}
			/*
			 * The fact already sits in this state's calibration lineage: an earlier costing event of the same search
			 * applied it. The learned row correction must STILL be skipped — running it here would stack a posterior on
			 * top of the measured cardinality and re-introduce exactly the drift the fact disproved (observed as a
			 * frontier-hierarchical-nig calibration multiplying a fact-pinned estimate back up, 2026-08-05). Pin the
			 * event's own row estimate to the fact as well: every alternative pricing this logical relation at this
			 * data stamp must see the same measured output.
			 */
			if (output.hasComponentOutputRows()) {
				output.setComponentOutputRowsPreservingPhysicalCost(exactFactRows);
			} else if (output.hasContextualOutputRows()) {
				output.setContextualOutputRowsPreservingPhysicalCost(exactFactRows);
			} else {
				output.setOutputRowsPreservingPhysicalCost(exactFactRows);
			}
			synchronizeSemiAntiCorrelationRows(output, predictedSummary, exactFactRows);
			output.setEstimateProvenance(FRONTIER_LEO_SOURCE, "frontier_exact_fact");
			output.putPlannedStringMetric("optimizer.frontierLeo.output_rows.source", "exact-fact");
			output.putPlannedDoubleMetric("optimizer.frontierLeo.output_rows.raw", predictedSummary.pointRows());
			output.putPlannedDoubleMetric("optimizer.frontierLeo.output_rows.corrected", exactFactRows);
			int factPhysicalCorrections = applyFrontierPhysicalLearning(productionIdentity, output, feedbackStats);
			output.putPlannedDoubleMetric(
					"optimizer.frontierLeoPhysicalDimensionCount", factPhysicalCorrections);
			output.putPlannedStringMetric("optimizer.frontierStateDigest", learningStateDigest(predictedState));
			applyObjectiveRiskAndLifecycle(productionIdentity, output, feedbackStats);
			return;
		}
		FrontierLearningModel.DimensionEstimate rowCorrection = logicalOutputMatchesIdentity
				? pinnedLogicalDimensionEstimate(
						feedbackStats, productionIdentity, FrontierCostDimension.OUTPUT_ROWS, learningPredictionRows)
				: null;
		if (rowCorrection != null
				&& !logicalCorrectionIntersectsStructuralBounds(predictedSummary, rowCorrection, output)) {
			rowCorrection = null;
		}
		EvidenceStateRef correctedState = predictedState;
		if (!databaseExact && rowCorrection != null) {
			if (!isComposableState(predictedState)) {
				predictedState = alignNonComposableCostingState(relationId, predictedState, output);
				predictedSummary = predictedState.summary();
			}
			double correctedRows = rowCorrection.correctedValue();
			/*
			 * A calibration may move a point estimate freely only inside the state's certified interval. A state with a
			 * vacuous interval and no composable payload has announced it knows nothing about its cardinality — a
			 * learned posterior applied to it is not "correcting" anything, it is inventing the estimate outright.
			 * Bound that authority to 4^exactEvidence of the raw structural value (mirroring the ln(4)-per-observation
			 * clamp): with zero exact observations the raw estimate stands, and each same-key observation earns a
			 * factor of four. Family- or legacy-pooled evidence alone earns nothing here — pooled corrections applied
			 * to degraded states are exactly how an unrelated query's inflation crushed the q9 anti-join input to ~1
			 * row (2026-08-04). Vacuity is judged like the semi-anti authority test: a HEURISTIC interval still
			 * carrying [0, inf) constrains nothing and earns no more authority than intervalKind NONE.
			 */
			boolean vacuousInterval = predictedSummary.intervalKind() == EvidenceIntervalKind.NONE
					|| !(predictedSummary.lowerRows() > 0.0d || Double.isFinite(predictedSummary.upperRows()));
			if (degradedCalibrationClampEnabled()
					&& !isComposableState(predictedState)
					&& vacuousInterval
					&& predictedSummary.pointRows() > 0.0d
					&& finiteNonNegative(correctedRows)) {
				double band = Math.pow(4.0d, Math.min(rowCorrection.exactEvidenceCount(), 8.0d));
				double clamped = Math.min(
						Math.max(correctedRows, predictedSummary.pointRows() / band),
						predictedSummary.pointRows() * band);
				if (clamped != correctedRows) {
					correctedRows = clamped;
					output.putPlannedDoubleMetric("optimizer.frontierLeo.output_rows.clamped", 1.0d);
					output.putPlannedDoubleMetric("optimizer.frontierLeo.output_rows.clampBand", band);
				}
			}
			String evidenceKey = productionIdentity.logicalKey().externalForm() + ':'
					+ productionIdentity.applicability().externalForm() + ":output_rows";
			if (!arena.containsCalibrationEvidence(predictedState, evidenceKey)) {
				double confidence = posteriorConfidence(rowCorrection.posteriorPrecision());
				double factor = predictedSummary.pointRows() == 0.0d
						? correctedRows == 0.0d ? 0.0d : Double.POSITIVE_INFINITY
						: correctedRows / predictedSummary.pointRows();
				EvidenceCalibrationSummary calibration = new EvidenceCalibrationSummary(
						predictedSummary.pointRows(),
						correctedRows,
						factor,
						"frontier-hierarchical-nig",
						learningEvidenceCount(rowCorrection),
						confidence,
						evidenceKey,
						runtime.learnedEvidenceRevision());
				correctedState = arena.calibrate(predictedState, calibration, relationId);
				rememberState(correctedState);
				output.setEvidenceStateId(correctedState.stateId());
				output.setEvidenceGuarantee(correctedState.summary().guarantee());
				if (output.hasComponentOutputRows()) {
					output.setComponentOutputRowsPreservingPhysicalCost(correctedState.summary().pointRows());
				} else if (output.hasContextualOutputRows()) {
					output.setContextualOutputRowsPreservingPhysicalCost(correctedState.summary().pointRows());
				} else {
					output.setOutputRowsPreservingPhysicalCost(correctedState.summary().pointRows());
				}
				synchronizeSemiAntiCorrelationRows(output, correctedState.summary(),
						correctedState.summary().pointRows());
				annotateReady(output, correctedState);
				String currentSource = output.estimateSource();
				String learnedSource = currentSource != null && currentSource.contains("learned-filter")
						? FRONTIER_LEARNED_FILTER_LEO_SOURCE
						: FRONTIER_LEO_SOURCE;
				output.setEstimateProvenance(learnedSource, "frontier_event_leo");
				annotateDimensionCorrection(output, FrontierCostDimension.OUTPUT_ROWS,
						predictedSummary.pointRows(), rowCorrection);
			}
		}

		int physicalCorrections = applyFrontierPhysicalLearning(productionIdentity, output, feedbackStats);
		if (rowCorrection != null || physicalCorrections > 0) {
			output.putPlannedStringMetric("optimizer.frontierLeoModel", "hierarchical-nig");
			output.putPlannedDoubleMetric("optimizer.frontierLeoPhysicalDimensionCount", physicalCorrections);
		}
		output.putPlannedStringMetric("optimizer.frontierStateDigest", learningStateDigest(correctedState));
		applyObjectiveRiskAndLifecycle(productionIdentity, output, feedbackStats);
	}

	private static boolean logicalCorrectionIntersectsStructuralBounds(EvidenceStateSummary structural,
			FrontierLearningModel.DimensionEstimate correction, PackedCostEstimate output) {
		double center = Math.log1p(correction.correctedValue());
		double variance = correction.posteriorLogMeanVariance();
		double spread = finiteNonNegative(variance)
				? PREDICTIVE_UPPER_Z_999 * Math.sqrt(variance)
				: 0.0d;
		double lower = inverseLog1pBound(Math.max(0.0d, center - spread));
		double upper = inverseLog1pBound(center + spread);
		output.putPlannedDoubleMetric("optimizer.frontierLeo.output_rows.credibleLower", lower);
		output.putPlannedDoubleMetric("optimizer.frontierLeo.output_rows.credibleUpper", upper);
		double structuralLower = Math.max(0.0d, structural.lowerRows());
		double structuralUpper = structural.upperRows();
		boolean intersects = upper >= structuralLower
				&& (!Double.isFinite(structuralUpper) || lower <= structuralUpper);
		output.putPlannedStringMetric("optimizer.frontierLeo.output_rows.admission",
				intersects ? "admitted" : "rejected-structural-bounds");
		return intersects;
	}

	/**
	 * Makes a non-composable state's scalar compatibility mirror explicit in Frontier lineage before the costing event
	 * is recorded. The resulting boundary is still unresolved and non-composable; it merely ensures that LEO observes
	 * the same immutable prediction that candidate ranking consumed. Composable payloads remain untouched.
	 */
	private EvidenceStateRef alignNonComposableCostingState(int relationId, EvidenceStateRef state,
			PackedCostEstimate output) {
		FrontierStateDisposition disposition = arena.disposition(state);
		double eventRows = output.outputRows();
		EvidenceStateSummary summary = state.summary();
		if (disposition == FrontierStateDisposition.COMPOSABLE_PAYLOAD
				|| !finiteNonNegative(eventRows)
				|| Double.doubleToLongBits(eventRows) == Double.doubleToLongBits(summary.pointRows())) {
			return state;
		}
		double upperRows = Math.max(eventRows, summary.upperRows());
		double certifiedUpperBound = Math.max(eventRows, summary.certifiedUpperBound());
		EvidenceStateSummary eventSummary = EvidenceStateSummary.unresolved(
				eventRows, upperRows, certifiedUpperBound, summary.degradationReason());
		EvidenceStateRef eventState = disposition == FrontierStateDisposition.OPAQUE_BOUNDARY
				? arena.deriveOpaqueBoundary(state, eventSummary, Math.max(0, relationId))
				: arena.deriveBoundBoundary(
						state, arena.layout(state), eventSummary, Math.max(0, relationId));
		rememberState(eventState);
		publishDegradedState(output, eventState);
		output.putPlannedStringMetric("plannedFrontierBoundaryRowsSource", "originating-cost-event");
		return eventState;
	}

	void applyFrontierPhysicalEventLearning(PackedCostContext context, PackedCostEstimate output) {
		if (closed || arena == null || output == null || output.evidenceStateId() == 0) {
			return;
		}
		EvidenceStateRef predictedState = stateReference(output.evidenceStateId());
		if (predictedState == null) {
			return;
		}
		EvidenceStateRef transformState = rawTransformState(predictedState);
		FrontierStateKey stateKey = arena.hasCanonicalKey(transformState) ? arena.key(transformState) : null;
		FrontierLearningKey learningKey = FrontierLearningKey.of(
				"join",
				arena.operation(transformState).name(),
				learningLayoutFingerprint(stateKey, transformState, context),
				stateKey == null ? context.correlationMaskId() : stateKey.correlationScope(),
				learningAccessKernel(output),
				output.indexName(),
				output.accessMode());
		ProductionLearningIdentity eventIdentity = productionLearningIdentity(
				0, transformState, stateKey, context, output);
		String stateDigest = learningStateDigest(predictedState);
		output.putPlannedStringMetric("optimizer.frontierPhysicalLearningKey", learningKey.externalForm());
		output.putPlannedStringMetric("optimizer.frontierRawStateDigest", stateDigest);
		output.putPlannedStringMetric("optimizer.frontierStateDigest", stateDigest);
		output.putPlannedDoubleMetric("optimizer.frontierLeoRevision", runtime.leoRevision());
		ProductionLearningIdentity productionIdentity = stampPhysicalProductionLearningIdentity(
				output, eventIdentity, learningKey);
		if (productionIdentity == null) {
			output.putPlannedStringMetric("optimizer.physicalLearningAdmission", "rejected-missing-logical-contract");
			return;
		}

		LmdbOperatorFeedbackStats feedbackStats = runtime.feedback();
		if (feedbackStats == null) {
			return;
		}
		int physicalCorrections = applyFrontierPhysicalLearning(productionIdentity, output, feedbackStats);
		if (physicalCorrections > 0) {
			output.putPlannedStringMetric("optimizer.frontierLeoModel", "hierarchical-nig");
			output.putPlannedDoubleMetric("optimizer.frontierLeoPhysicalDimensionCount", physicalCorrections);
		}
		applyObjectiveRiskAndLifecycle(productionIdentity, output, feedbackStats);
	}

	private ProductionLearningIdentity stampPhysicalProductionLearningIdentity(PackedCostEstimate output,
			ProductionLearningIdentity eventIdentity, FrontierLearningKey physicalLearningKey) {
		RuntimeFeedbackContract inheritedContract = output.runtimeFeedbackContract();
		if (inheritedContract == null
				|| !(inheritedContract.descriptor()instanceof LmdbRuntimeFeedbackDescriptor inherited)) {
			return null;
		}
		/*
		 * The physical event must retain the canonical logical contract produced immediately before it, because the
		 * physical Frontier state can use a different enumeration-route expression for the same memo group. A copied
		 * filter or a smaller/differently-conditioned join is not equivalent. Certify equivalence from typed factor and
		 * applicability fields; explanation strings remain diagnostics only.
		 */
		boolean sameLogicalGroup = "join".equals(inherited.logicalKey().logicalOperator())
				&& inherited.logicalKey().sameSemanticContractIgnoringExpression(eventIdentity.logicalKey())
				&& inherited.logicalGroupOrigin().certified()
				&& inherited.logicalGroupOrigin().equals(eventIdentity.logicalGroupOrigin())
				&& sameConditionalApplicability(inherited.applicability(), eventIdentity.applicability());
		ProductionLearningIdentity identity = sameLogicalGroup
				? new ProductionLearningIdentity(inherited.logicalKey(), inherited.applicability(),
						eventIdentity.physicalKey(), eventIdentity.logicalGroupOrigin())
				: eventIdentity;
		output.putPlannedStringMetric("optimizer.logicalLearningKey", identity.logicalKey().externalForm());
		output.putPlannedStringMetric("optimizer.logicalLearningKeyDigest", identity.logicalKey().digest());
		output.putPlannedStringMetric("optimizer.learningApplicability", identity.applicability().externalForm());
		output.putPlannedStringMetric("optimizer.learningApplicabilityDigest", identity.applicability().digest());
		output.putPlannedStringMetric("optimizer.physicalResidualKey", identity.physicalKey().externalForm());
		output.putPlannedStringMetric("optimizer.physicalResidualKeyDigest", identity.physicalKey().digest());
		LmdbRuntimeFeedbackDescriptor descriptor = new LmdbRuntimeFeedbackDescriptor(
				sameLogicalGroup ? inherited.legacyLogicalKey() : null, physicalLearningKey, identity.logicalKey(),
				identity.applicability(), identity.physicalKey(), identity.logicalGroupOrigin());
		output.setRuntimeFeedbackContract(runtimeFeedbackContract(descriptor, output));
		return identity;
	}

	private static boolean sameConditionalApplicability(LearningApplicability left, LearningApplicability right) {
		return left.correlationContractFingerprint() == right.correlationContractFingerprint()
				&& left.conditionalFeatureBucket().equals(right.conditionalFeatureBucket())
				&& left.dataEpoch() == right.dataEpoch()
				&& left.catalogEpoch() == right.catalogEpoch()
				&& left.modelEpoch() == right.modelEpoch();
	}

	private void applyObjectiveRiskAndLifecycle(ProductionLearningIdentity identity, PackedCostEstimate output,
			LmdbOperatorFeedbackStats feedbackStats) {
		double point = physicalCostObjective.score(output);
		if (!finiteNonNegative(point)) {
			return;
		}
		double maximumLogMeanVariance = Double.NaN;
		for (FrontierCostDimension dimension : FrontierCostDimension.values()) {
			double variance = output.plannedDoubleMetric(
					"optimizer.frontierLeo." + dimension.name().toLowerCase(Locale.ROOT)
							+ ".posteriorLogMeanVariance",
					Double.NaN);
			if (finiteNonNegative(variance)) {
				maximumLogMeanVariance = Double.isNaN(maximumLogMeanVariance)
						? variance
						: Math.max(maximumLogMeanVariance, variance);
			}
		}
		double lower = point;
		double upper = point;
		if (finiteNonNegative(maximumLogMeanVariance) && maximumLogMeanVariance > 0.0d) {
			double spread = PREDICTIVE_UPPER_Z_999 * Math.sqrt(maximumLogMeanVariance);
			double center = Math.log1p(point);
			lower = inverseLog1pBound(Math.max(0.0d, center - spread));
			upper = inverseLog1pBound(center + spread);
		}
		double structuralLower = structuralObjectiveBound(output, point, false);
		if (finiteNonNegative(structuralLower)) {
			lower = Math.min(lower, structuralLower);
		}
		double structuralUpper = structuralObjectiveBound(output, point, true);
		if (finiteNonNegative(structuralUpper)) {
			upper = Math.max(upper, structuralUpper);
		}
		output.setObjectiveInterval(lower, point, upper);
		PlanLifecycleStore.ObjectiveEnvelope envelope = new PlanLifecycleStore.ObjectiveEnvelope(lower, point, upper);
		PlanLifecycleStore.Decision decision = feedbackStats.planLifecycleDecision(
				identity.logicalKey(), identity.physicalKey(), identity.applicability(), envelope);
		output.putPlannedStringMetric("optimizer.lifecycleState",
				decision.state().name().toLowerCase(Locale.ROOT));
		output.putPlannedStringMetric("optimizer.lifecycleReason", decision.reason());
		output.putPlannedStringMetric("optimizer.lifecycleLastGoodPhysicalDigest",
				decision.lastGoodPhysicalDigest());
		output.putPlannedStringMetric("optimizer.lifecycleAdmissionReason",
				decision.eligible() ? "eligible" : "excluded-" + decision.state().name().toLowerCase(Locale.ROOT));
		output.putPlannedStringMetric("optimizer.lifecycleSwitchReason",
				decision.state() == PlanLifecycleStore.State.APPLYING ? decision.reason() : "none");
		output.putPlannedStringMetric("optimizer.lifecycleRollbackReason",
				decision.state() == PlanLifecycleStore.State.BLOCKED
						|| decision.state() == PlanLifecycleStore.State.QUARANTINED
								? decision.reason()
								: "none");
		output.putPlannedDoubleMetric("optimizer.lifecycleEnforced",
				feedbackStats.planLifecycleEnforced() ? 1.0d : 0.0d);
		output.putPlannedDoubleMetric("optimizer.lifecycleEligible", decision.eligible() ? 1.0d : 0.0d);
		output.putPlannedDoubleMetric("optimizer.lifecycleLastGood", decision.lastGood() ? 1.0d : 0.0d);
		output.putPlannedDoubleMetric("optimizer.lifecycleComparisonCost", decision.comparisonCost());
		output.putPlannedDoubleMetric("optimizer.lifecycleRegressionLimit",
				Double.isFinite(decision.regressionLimit()) ? decision.regressionLimit() : Double.MAX_VALUE);
	}

	private static double structuralObjectiveBound(PackedCostEstimate output, double point, boolean upper) {
		String metric = upper ? "plannedFrontierUpperRows" : "plannedFrontierLowerRows";
		double boundRows = output.plannedDoubleMetric(metric, Double.NaN);
		if (upper && boundRows == Double.POSITIVE_INFINITY) {
			return Double.MAX_VALUE;
		}
		if (!finiteNonNegative(boundRows)) {
			return Double.NaN;
		}
		double pointRows = output.outputRows();
		if (!finiteNonNegative(pointRows)) {
			return Double.NaN;
		}
		if (Double.doubleToLongBits(boundRows) == Double.doubleToLongBits(pointRows)) {
			return point;
		}
		if (!(pointRows > 0.0d)) {
			return upper && boundRows > 0.0d ? Double.MAX_VALUE : 0.0d;
		}
		double scaled = saturatedMultiply(point, boundRows / pointRows);
		return upper ? Math.max(point, scaled) : Math.min(point, scaled);
	}

	private static double inverseLog1pBound(double logarithm) {
		if (!(logarithm > 0.0d)) {
			return 0.0d;
		}
		if (!Double.isFinite(logarithm) || logarithm >= Math.log(Double.MAX_VALUE)) {
			return Double.MAX_VALUE;
		}
		double value = Math.expm1(logarithm);
		return finiteNonNegative(value) ? value : Double.MAX_VALUE;
	}

	private int applyFrontierPhysicalLearning(ProductionLearningIdentity identity, PackedCostEstimate output,
			LmdbOperatorFeedbackStats feedbackStats) {
		DependentComponentCorrection dependentCorrection = correctedDependentComponents(
				identity, output, feedbackStats);
		double sequentialRows = dependentCorrection.corrected()
				? Math.max(0.0d, saturatedAdd(output.sequentialRows(), dependentCorrection.objectiveDelta()))
				: correctedPhysicalDimension(identity, FrontierCostDimension.SOURCE_ROWS_SCANNED,
						output.sequentialRows(), output, feedbackStats);
		double randomSeeks = correctedPhysicalDimension(identity, FrontierCostDimension.INDEX_SEEKS,
				output.randomSeeks(), output, feedbackStats);
		double iteratorOpens = correctedPhysicalDimension(identity, FrontierCostDimension.ITERATOR_OPENS,
				output.iteratorOpens(), output, feedbackStats);
		double expressionEvaluations = correctedPhysicalDimension(identity,
				FrontierCostDimension.EXPRESSION_EVALUATIONS,
				output.expressionEvaluations(), output, feedbackStats);
		double hashBuildRows = correctedPhysicalDimension(identity, FrontierCostDimension.HASH_BUILD_ROWS,
				output.hashBuildRows(), output, feedbackStats);
		double hashProbeRows = correctedPhysicalDimension(identity, FrontierCostDimension.HASH_PROBE_ROWS,
				output.hashProbeRows(), output, feedbackStats);
		double pathExpansions = correctedPhysicalDimension(identity, FrontierCostDimension.PATH_EXPANSIONS,
				output.pathExpansions(), output, feedbackStats);
		double resultRows = correctedPhysicalDimension(identity, FrontierCostDimension.RESULT_ROWS,
				output.resultRows(), output, feedbackStats);
		double remoteCalls = correctedPhysicalDimension(identity, FrontierCostDimension.REMOTE_CALLS,
				output.remoteCalls(), output, feedbackStats);
		int corrected = dependentCorrection.correctionCount()
				+ changed(output.sequentialRows(), sequentialRows)
				+ changed(output.randomSeeks(), randomSeeks)
				+ changed(output.iteratorOpens(), iteratorOpens)
				+ changed(output.expressionEvaluations(), expressionEvaluations)
				+ changed(output.hashBuildRows(), hashBuildRows)
				+ changed(output.hashProbeRows(), hashProbeRows)
				+ changed(output.pathExpansions(), pathExpansions)
				+ changed(output.resultRows(), resultRows)
				+ changed(output.remoteCalls(), remoteCalls);
		if (corrected == 0 || !finiteNonNegative(sequentialRows) || !finiteNonNegative(randomSeeks)
				|| !finiteNonNegative(iteratorOpens) || !finiteNonNegative(expressionEvaluations)
				|| !finiteNonNegative(hashBuildRows) || !finiteNonNegative(hashProbeRows)
				|| !finiteNonNegative(pathExpansions) || !finiteNonNegative(resultRows)
				|| !finiteNonNegative(remoteCalls)
				|| !finiteNonNegative(output.peakMemoryRows())) {
			return 0;
		}
		if (output.costScope() == PackedCostEstimate.CostScope.INCLUSIVE) {
			output.setInclusivePhysicalCost(sequentialRows, randomSeeks, iteratorOpens, expressionEvaluations,
					hashBuildRows, hashProbeRows, pathExpansions, resultRows, remoteCalls, output.peakMemoryRows());
		} else {
			output.setLocalPhysicalCost(sequentialRows, randomSeeks, iteratorOpens, expressionEvaluations,
					hashBuildRows, hashProbeRows, pathExpansions, resultRows, remoteCalls, output.peakMemoryRows());
		}
		return corrected;
	}

	private DependentComponentCorrection correctedDependentComponents(ProductionLearningIdentity identity,
			PackedCostEstimate output, LmdbOperatorFeedbackStats feedbackStats) {
		if (!output.hasDependentCostComponents()
				|| !finiteNonNegative(output.hitProbability())
				|| !finiteNonNegative(output.firstMatchWork())
				|| !finiteNonNegative(output.exhaustionWork())) {
			return DependentComponentCorrection.NONE;
		}
		double rawHitProbability = output.hitProbability();
		double correctedHitProbability = rawHitProbability;
		double correctedFirstMatchWork = output.firstMatchWork();
		double correctedExhaustionWork = output.exhaustionWork();
		int correctionCount = 0;

		FrontierLearningModel.DimensionEstimate hitRate = pinnedLogicalDimensionEstimate(
				feedbackStats, identity, FrontierCostDimension.SEMI_ANTI_HIT_RATE, rawHitProbability);
		if (hitRate != null) {
			correctedHitProbability = Math.clamp(hitRate.correctedValue(), 0.0d, 1.0d);
			annotateDimensionCorrection(output, FrontierCostDimension.SEMI_ANTI_HIT_RATE,
					rawHitProbability, hitRate);
			correctionCount += changed(rawHitProbability, correctedHitProbability);
		}
		FrontierLearningModel.DimensionEstimate firstMatch = pinnedPhysicalDimensionEstimate(
				feedbackStats, identity, FrontierCostDimension.FIRST_MATCH_WORK, output.firstMatchWork());
		if (firstMatch != null) {
			correctedFirstMatchWork = firstMatch.correctedValue();
			annotateDimensionCorrection(output, FrontierCostDimension.FIRST_MATCH_WORK,
					output.firstMatchWork(), firstMatch);
			correctionCount += changed(output.firstMatchWork(), correctedFirstMatchWork);
		}
		FrontierLearningModel.DimensionEstimate exhaustion = pinnedPhysicalDimensionEstimate(
				feedbackStats, identity, FrontierCostDimension.EXHAUSTION_WORK, output.exhaustionWork());
		if (exhaustion != null) {
			correctedExhaustionWork = exhaustion.correctedValue();
			annotateDimensionCorrection(output, FrontierCostDimension.EXHAUSTION_WORK,
					output.exhaustionWork(), exhaustion);
			correctionCount += changed(output.exhaustionWork(), correctedExhaustionWork);
		}
		if (correctionCount == 0) {
			return DependentComponentCorrection.NONE;
		}

		double probeExecutions = finiteNonNegative(output.cacheMisses()) && output.cacheMisses() > 0.0d
				? output.cacheMisses()
				: Math.max(0.0d, output.dependentInvocationCount());
		double rawFirstMatchSum = saturatedMultiply(
				saturatedMultiply(probeExecutions, rawHitProbability), output.firstMatchWork());
		double rawExhaustionSum = saturatedMultiply(
				saturatedMultiply(probeExecutions, 1.0d - rawHitProbability), output.exhaustionWork());
		double appliedFirstMatchSum = saturatedMultiply(
				saturatedMultiply(probeExecutions, correctedHitProbability), correctedFirstMatchWork);
		double appliedExhaustionSum = saturatedMultiply(
				saturatedMultiply(probeExecutions, 1.0d - correctedHitProbability), correctedExhaustionWork);
		double rawTotal = saturatedAdd(rawFirstMatchSum, rawExhaustionSum);
		double appliedTotal = saturatedAdd(appliedFirstMatchSum, appliedExhaustionSum);
		double objectiveDelta = appliedTotal - rawTotal;
		if (!Double.isFinite(objectiveDelta)) {
			objectiveDelta = appliedTotal >= rawTotal ? Double.MAX_VALUE : -rawTotal;
		}

		output.setDependentCostComponents(output.startupOnceWork(), output.dependentInvocationCount(),
				correctedHitProbability, correctedFirstMatchWork, correctedExhaustionWork,
				output.rebindWork(), output.closeWork(), output.outputWork(), output.distinctKeyMisses(),
				output.cacheHits(), output.cacheMisses(), output.cacheEvictions(), output.materializationBuilds(),
				output.materializationLookups(), output.memorySpillWork());
		output.putPlannedDoubleMetric("optimizer.dependentFirstMatchAppliedSum", appliedFirstMatchSum);
		output.putPlannedDoubleMetric("optimizer.dependentExhaustionAppliedSum", appliedExhaustionSum);
		return new DependentComponentCorrection(true, objectiveDelta, correctionCount);
	}

	private record DependentComponentCorrection(boolean corrected, double objectiveDelta, int correctionCount) {
		private static final DependentComponentCorrection NONE = new DependentComponentCorrection(false, 0.0d, 0);
	}

	private double correctedPhysicalDimension(ProductionLearningIdentity identity, FrontierCostDimension dimension,
			double rawValue, PackedCostEstimate output, LmdbOperatorFeedbackStats feedbackStats) {
		if (!finiteNonNegative(rawValue)) {
			return rawValue;
		}
		FrontierLearningModel.DimensionEstimate estimate = pinnedPhysicalDimensionEstimate(
				feedbackStats, identity, dimension, rawValue);
		if (estimate == null) {
			return rawValue;
		}
		annotateDimensionCorrection(output, dimension, rawValue, estimate);
		return estimate.correctedValue();
	}

	static final String PLANNING_CALIBRATION_PINNING_PROPERTY = "rdf4j.optimizer.lmdb.planningCalibrationPinning";
	private static final Object NO_POSTERIOR = new Object();
	private java.util.HashMap<String, Object> pinnedPosteriors;

	private static boolean planningCalibrationPinningEnabled() {
		return !"false".equalsIgnoreCase(System.getProperty(PLANNING_CALIBRATION_PINNING_PROPERTY, "true"));
	}

	/*
	 * Observations from concurrently executing queries land in the shared learning model while this session is still
	 * comparing plan alternatives; a live read per costing event would price some alternatives with old calibration and
	 * some with new. Pinning each (key, dimension) posterior on first read keeps every alternative in one Cascades
	 * search on identical calibration.
	 */
	private FrontierLearningModel.DimensionEstimate pinnedLogicalDimensionEstimate(
			LmdbOperatorFeedbackStats feedbackStats, ProductionLearningIdentity identity,
			FrontierCostDimension dimension, double predicted) {
		if (!planningCalibrationPinningEnabled()) {
			return feedbackStats.logicalDimensionEstimate(
					identity.logicalKey(), identity.applicability(), dimension, predicted);
		}
		if (pinnedPosteriors == null) {
			pinnedPosteriors = new java.util.HashMap<>();
		}
		String memoKey = "logical|" + identity.logicalKey().externalForm() + '|'
				+ identity.applicability().externalForm() + '|' + dimension.ordinal();
		Object snapshot = pinnedPosteriors.get(memoKey);
		if (snapshot == null) {
			FrontierLearningModel.PosteriorSnapshot computed = feedbackStats.logicalPosterior(
					identity.logicalKey(), identity.applicability(), dimension);
			snapshot = computed == null ? NO_POSTERIOR : computed;
			pinnedPosteriors.put(memoKey, snapshot);
		}
		return snapshot == NO_POSTERIOR ? null
				: FrontierLearningModel.estimateLogical(
						(FrontierLearningModel.PosteriorSnapshot) snapshot, dimension, predicted);
	}

	private FrontierLearningModel.DimensionEstimate pinnedPhysicalDimensionEstimate(
			LmdbOperatorFeedbackStats feedbackStats, ProductionLearningIdentity identity,
			FrontierCostDimension dimension, double predicted) {
		if (!planningCalibrationPinningEnabled()) {
			return feedbackStats.physicalDimensionEstimate(identity.logicalKey(), identity.physicalKey(),
					identity.applicability(), dimension, predicted);
		}
		if (pinnedPosteriors == null) {
			pinnedPosteriors = new java.util.HashMap<>();
		}
		String memoKey = "physical|" + identity.logicalKey().externalForm() + '|'
				+ identity.physicalKey().externalForm() + '|' + identity.applicability().externalForm() + '|'
				+ dimension.ordinal();
		Object snapshot = pinnedPosteriors.get(memoKey);
		if (snapshot == null) {
			FrontierLearningModel.PosteriorSnapshot computed = feedbackStats.physicalPosterior(
					identity.logicalKey(), identity.physicalKey(), identity.applicability(), dimension);
			snapshot = computed == null ? NO_POSTERIOR : computed;
			pinnedPosteriors.put(memoKey, snapshot);
		}
		return snapshot == NO_POSTERIOR ? null
				: FrontierLearningModel.estimate((FrontierLearningModel.PosteriorSnapshot) snapshot, predicted);
	}

	private static void annotateDimensionCorrection(PackedCostEstimate output, FrontierCostDimension dimension,
			double rawValue, FrontierLearningModel.DimensionEstimate estimate) {
		String prefix = "optimizer.frontierLeo." + dimension.name().toLowerCase(Locale.ROOT);
		output.putPlannedDoubleMetric(prefix + ".raw", rawValue);
		output.putPlannedDoubleMetric(prefix + ".corrected", estimate.correctedValue());
		output.putPlannedDoubleMetric(prefix + ".posteriorLogMean", estimate.posteriorLogMean());
		output.putPlannedDoubleMetric(prefix + ".posteriorLogMeanVariance", estimate.posteriorLogMeanVariance());
		output.putPlannedDoubleMetric(prefix + ".posteriorPrecision", estimate.posteriorPrecision());
		output.putPlannedDoubleMetric(prefix + ".exactEvidence", estimate.exactEvidenceCount());
		output.putPlannedDoubleMetric(prefix + ".familyEvidence", estimate.familyEvidenceCount());
		output.putPlannedDoubleMetric(prefix + ".legacyEvidence", estimate.legacyEvidenceCount());
	}

	private EvidenceStateRef rawTransformState(EvidenceStateRef state) {
		EvidenceStateRef current = state;
		while (arena.operation(current) == FrontierStateOperation.CALIBRATE && arena.parentCount(current) == 1) {
			current = arena.parent(current, 0);
		}
		return current;
	}

	/*
	 * Learning identity of a relation: the canonical member of its logical memo group. Rule-program alternatives
	 * (Difference vs correlated NOT-EXISTS filter vs typed anti-join over the same MINUS) share a group, and output
	 * cardinality is a property of that logical relation, not of the physical framing that happened to execute. Keying
	 * OUTPUT_ROWS learning by the alternative's own algebra let the executed framing accumulate corrections while its
	 * never-executed siblings kept raw estimates — flipping near-tied choices toward whichever plan had not run yet
	 * (MEDICAL q9 oscillation, 2026-08-04). Physical-dimension families keep the alternative's access identity (kernel,
	 * index, mode, operation prefix), so scan/seek/hash evidence still does not pool across kernels. Unlike
	 * canonicalContextualOperatorRelationIds this never routes a costing event through the canonical member's
	 * expression — it only derives a fingerprint string from it.
	 */
	static final String GROUP_CANONICAL_OUTPUT_ROWS_LEARNING_PROPERTY = "rdf4j.optimizer.lmdb.groupCanonicalOutputRowsLearning";

	private static boolean groupCanonicalOutputRowsLearningEnabled() {
		return !"false".equalsIgnoreCase(
				System.getProperty(GROUP_CANONICAL_OUTPUT_ROWS_LEARNING_PROPERTY, "true"));
	}

	static final String DEGRADED_CALIBRATION_CLAMP_PROPERTY = "rdf4j.optimizer.lmdb.degradedCalibrationClamp";

	private static boolean degradedCalibrationClampEnabled() {
		return !"false".equalsIgnoreCase(
				System.getProperty(DEGRADED_CALIBRATION_CLAMP_PROPERTY, "true"));
	}

	/*
	 * An observed cardinality of a top-level, uncorrelated logical relation at the current data stamp is a fact, not an
	 * estimate: at this exact data version that relation produced exactly N rows. Keyed by the logical group's
	 * canonical fingerprint, one execution's measurement overrides both raw estimates and learned corrections for EVERY
	 * physical alternative over the same relation — which is what makes near-tie ranking symmetric again after one run.
	 * Facts are minted and validated inside LmdbOperatorFeedbackStats against its LMDB write-txn data stamp; any store
	 * mutation silently demotes them back to priors. Correlated or prefix-conditioned evaluations observe a different
	 * conditional relation and never mint or consume facts.
	 */
	static final String FRONTIER_EXACT_CARDINALITY_FACTS_PROPERTY = "rdf4j.optimizer.lmdb.frontierExactCardinalityFacts";

	private static boolean frontierExactCardinalityFactsEnabled() {
		return !"false".equalsIgnoreCase(
				System.getProperty(FRONTIER_EXACT_CARDINALITY_FACTS_PROPERTY, "true"));
	}

	/**
	 * Operation-independent logical identity of the relation's memo group: canonical member's operator family plus its
	 * structural-topology hex. Group-canonical regardless of the A1 learning-key flag — facts are meaningless under
	 * per-alternative identities. Empty-string cache slots encode "no key".
	 */
	private String logicalGroupFactKey(int relationId) {
		if (relationId <= 0 || relationId > query.relationCount()) {
			return null;
		}
		if (logicalGroupFactKeys == null) {
			logicalGroupFactKeys = new String[query.relationCount() + 1];
		}
		String cached = logicalGroupFactKeys[relationId];
		if (cached != null) {
			return cached.isEmpty() ? null : cached;
		}
		int identity = contextualCanonicalGroupId(relationId);
		TupleExpr expression = query.materializeRelation(identity);
		String simpleName = expression.getClass().getSimpleName();
		String family = simpleName.isBlank() ? "tuple-expr" : camelToKebab(simpleName);
		String topology = LeoOperatorKey.from(expression, "", LeoOperatorKey.ConstantMode.EXACT)
				.structuralFingerprint();
		String key = family + '@' + fixedHex(avalancheLearningFingerprint(fnvFingerprint(topology)));
		logicalGroupFactKeys[relationId] = key;
		return key;
	}

	private ProductionLearningIdentity productionLearningIdentity(int relationId, EvidenceStateRef transformState,
			FrontierStateKey stateKey, PackedCostContext context, PackedCostEstimate output) {
		TupleExpr expression = null;
		String operator;
		String canonicalExpression;
		String childGroups;
		String visibleVariables;
		if (relationId > 0 && relationId <= query.relationCount()) {
			int identityId = contextualCanonicalGroupId(relationId);
			expression = query.materializeRelation(identityId);
			LeoOperatorKey leoKey = LeoOperatorKey.from(expression, "", LeoOperatorKey.ConstantMode.EXACT);
			operator = learningOperatorFamily(identityId);
			canonicalExpression = leoKey.structuralFingerprint();
			visibleVariables = alphaMask(leoKey.outputMask());
			StringBuilder children = new StringBuilder();
			for (int child = 0; child < query.childCount(identityId); child++) {
				if (child > 0) {
					children.append('|');
				}
				int childId = query.childRelationId(identityId, child);
				TupleExpr childExpression = query.materializeRelation(contextualCanonicalGroupId(childId));
				children.append(LeoOperatorKey.from(childExpression, "", LeoOperatorKey.ConstantMode.EXACT)
						.structuralFingerprint());
			}
			childGroups = children.toString();
		} else {
			operator = "join";
			String factorTopology = stateKey == null ? null : canonicalJoinFactorTopology(stateKey);
			canonicalExpression = factorTopology == null
					? learningRawTransform(relationId, transformState, context)
					: "inner-join|" + factorTopology;
			childGroups = factorTopology == null ? "none" : factorTopology;
			visibleVariables = stateKey == null ? "unknown" : alphaLayout(arena.layout(transformState));
		}
		long correlationFingerprint = stateKey == null
				? context == null ? 0L : context.correlationMaskId()
				: stateKey.correlationScope();
		/*
		 * A scheduled unary or semi/anti operator may be costed with a prefix that is exactly its own logical input.
		 * That prefix is planner topology, not an outer invocation condition: treating its bindings as applicability
		 * changes the key when the same implementation is reached through a different enumeration route. Only a
		 * genuinely partial or inherited prefix contributes a conditional binding shape. The same applies to an
		 * uncorrelated intermediate join: its prefix is one child of the canonical join group, not an outer binding.
		 */
		boolean ownInputPrefix = context != null && (prefixCoversRelationInput(relationId, context)
				|| relationId == 0 && stateKey != null && correlationFingerprint == 0L);
		Collection<String> inputBindingNames = ownInputPrefix
				? List.of()
				: learningInputBindingNames(context);
		String inputBindingShape = expression == null
				? inputBindingNames.isEmpty() ? "unbound" : "bound-prefix"
				: LeoOperatorKey.alphaNormalizedInputBindingShape(expression, inputBindingNames);
		if (ownInputPrefix) {
			correlationFingerprint = 0L;
		}
		String requiredOuter = correlationFingerprint == 0L
				? "none"
				: "alpha-correlation:" + LearningKeyCodec.digest(inputBindingShape);
		String semantics = logicalSemantics(expression);
		String datasetScope = (datasetUsesStoreDefaults ? "store-defaults" : "explicit-dataset") + '|'
				+ (expression instanceof StatementPattern pattern ? pattern.getScope().name() : "mixed-scope");
		LogicalLearningKey logicalKey = LogicalLearningKey.of(operator,
				LearningKeyCodec.digest(canonicalExpression), LearningKeyCodec.digest(childGroups),
				LearningKeyCodec.digest(canonicalExpression), visibleVariables, requiredOuter, semantics, datasetScope);

		long physicalLayout = learningLayoutFingerprint(stateKey, transformState, context);
		long bindingShape = logicalBindingShapeFingerprint(
				logicalKey, visibleVariables, requiredOuter, semantics, datasetScope, inputBindingShape);
		long semanticScopeContract = ownInputPrefix || context == null ? 0L : context.semanticScopeMaskId();
		long correlationContract = avalancheLearningFingerprint(mixLearningFingerprint(
				fnvFingerprint(requiredOuter), semanticScopeContract));
		String conditionalBucket = "input:" + LearningKeyCodec.digest(inputBindingShape);
		if (correlationFingerprint != 0L) {
			conditionalBucket += "|correlated:" + LearningKeyCodec.digest(requiredOuter);
		}
		LearningApplicability applicability = new LearningApplicability(bindingShape, correlationContract,
				conditionalBucket, runtime.snapshotVersion(), runtime.frontierPlanningRevision(), 1L);

		String algorithm = firstNonBlank(output.plannedStringMetric("optimizer.semiAntiAlgorithm"),
				output.plannedStringMetric("optimizer.physicalJoinImplementation"),
				output.plannedStringMetric("plannedPhysicalImplementation"), operator);
		String normalizedAlgorithm = algorithm.toLowerCase(Locale.ROOT);
		String reopenMode = output.invocations() > 1.0d || correlationFingerprint != 0L
				? "dependent-reopen"
				: "single-open";
		String cacheMode = normalizedAlgorithm.contains("memo") ? "memoized"
				: normalizedAlgorithm.contains("material") ? "materialized" : "none";
		double cacheCapacity = output.plannedDoubleMetric("optimizer.semiAntiCacheCapacity", Double.NaN);
		String cacheCapacityClass = !Double.isFinite(cacheCapacity) ? "none"
				: cacheCapacity <= 64.0d ? "small" : cacheCapacity <= 4096.0d ? "medium" : "large";
		String parameterDomain = normalizedAlgorithm.contains("material")
				? conditionalBucket
				: "none";
		PhysicalResidualKey physicalKey = PhysicalResidualKey.of(algorithm, learningAccessKernel(output),
				firstNonBlank(output.indexName(), "none") + ':' + firstNonBlank(output.accessMode(), "none"),
				reopenMode, cacheMode, cacheCapacityClass, parameterDomain,
				"layout:" + Long.toUnsignedString(physicalLayout, 16));
		return new ProductionLearningIdentity(logicalKey, applicability, physicalKey,
				logicalGroupOrigin(relationId, stateKey));
	}

	private LmdbRuntimeFeedbackDescriptor.LogicalGroupOrigin logicalGroupOrigin(int relationId,
			FrontierStateKey stateKey) {
		/*
		 * A nonzero relation identifies a canonical memo group. Its certificate must therefore come from that group's
		 * transitive logical factors, even when the costing event is reached with a larger contextual Frontier state.
		 * Intermediate joins have no relation id and are certified directly by their canonical state key.
		 */
		if (relationId > 0 && relationId <= query.relationCount()) {
			return logicalGroupOrigin(relationFactorWords(relationId));
		}
		if (stateKey != null) {
			int wordCount = stateKey.logicalFactorWordCount();
			while (wordCount > 0 && stateKey.logicalFactorWord(wordCount - 1) == 0L) {
				wordCount--;
			}
			long high = 0x6a09e667f3bcc909L;
			long low = 0xbb67ae8584caa73bL;
			int factorCount = 0;
			for (int word = 0; word < wordCount; word++) {
				long factors = stateKey.logicalFactorWord(word);
				factorCount += Long.bitCount(factors);
				high = mixLearningFingerprint(high, factors ^ word);
				low = mixLearningFingerprint(low, Long.reverse(factors) ^ Integer.toUnsignedLong(word));
			}
			return logicalGroupOrigin(high, low, wordCount, factorCount);
		}
		return LmdbRuntimeFeedbackDescriptor.LogicalGroupOrigin.UNKNOWN;
	}

	private static LmdbRuntimeFeedbackDescriptor.LogicalGroupOrigin logicalGroupOrigin(long[] factorWords) {
		long high = 0x6a09e667f3bcc909L;
		long low = 0xbb67ae8584caa73bL;
		int factorCount = 0;
		for (int word = 0; word < factorWords.length; word++) {
			long factors = factorWords[word];
			factorCount += Long.bitCount(factors);
			high = mixLearningFingerprint(high, factors ^ word);
			low = mixLearningFingerprint(low, Long.reverse(factors) ^ Integer.toUnsignedLong(word));
		}
		return logicalGroupOrigin(high, low, factorWords.length, factorCount);
	}

	private static LmdbRuntimeFeedbackDescriptor.LogicalGroupOrigin logicalGroupOrigin(long high, long low,
			int wordCount, int factorCount) {
		if (factorCount == 0) {
			return LmdbRuntimeFeedbackDescriptor.LogicalGroupOrigin.UNKNOWN;
		}
		high = avalancheLearningFingerprint(mixLearningFingerprint(high, wordCount));
		low = avalancheLearningFingerprint(mixLearningFingerprint(low, factorCount));
		return new LmdbRuntimeFeedbackDescriptor.LogicalGroupOrigin(high, low, factorCount);
	}

	private String canonicalJoinFactorTopology(FrontierStateKey stateKey) {
		List<String> factors = new ArrayList<>();
		for (int relationId = 1; relationId <= query.relationCount(); relationId++) {
			if (!containsFactor(stateKey, relationId)) {
				continue;
			}
			TupleExpr factor = query.materializeRelation(contextualCanonicalGroupId(relationId));
			factors.add(LeoOperatorKey.from(factor, "", LeoOperatorKey.ConstantMode.EXACT)
					.structuralFingerprint());
		}
		if (factors.isEmpty()) {
			return null;
		}
		Collections.sort(factors);
		return String.join("|", factors);
	}

	private static String alphaLayout(FrontierLayout layout) {
		if (layout == null || layout.size() == 0) {
			return "none";
		}
		StringBuilder result = new StringBuilder(layout.size() * 3);
		for (int slot = 0; slot < layout.size(); slot++) {
			if (!result.isEmpty()) {
				result.append(',');
			}
			result.append('v').append(slot);
		}
		return result.toString();
	}

	private static long logicalBindingShapeFingerprint(LogicalLearningKey logicalKey, String visibleVariables,
			String requiredOuterVariables, String semantics, String datasetScope, String inputBindingShape) {
		long hash = fnvFingerprint(logicalKey.logicalOperator());
		hash = mixLearningFingerprint(hash, fnvFingerprint(visibleVariables));
		hash = mixLearningFingerprint(hash, fnvFingerprint(requiredOuterVariables));
		hash = mixLearningFingerprint(hash, fnvFingerprint(semantics));
		hash = mixLearningFingerprint(hash, fnvFingerprint(datasetScope));
		hash = mixLearningFingerprint(hash, fnvFingerprint(inputBindingShape));
		return avalancheLearningFingerprint(hash);
	}

	private Collection<String> learningInputBindingNames(PackedCostContext context) {
		if (context == null) {
			return List.of();
		}
		LinkedHashSet<String> names = new LinkedHashSet<>();
		for (int ordinal = 0; ordinal < context.prefixRelationCount(); ordinal++) {
			addLearningRelationBindingNames(names, context.prefixRelationId(ordinal));
		}
		addLearningRelationBindingNames(names, context.assuredBindingRelationId());
		return names.isEmpty() ? List.of() : names;
	}

	private void addLearningRelationBindingNames(Collection<String> target, int relationId) {
		if (relationId <= 0 || relationId > query.relationCount()) {
			return;
		}
		if (learningRelationBindingNames == null) {
			learningRelationBindingNames = new String[query.relationCount() + 1][];
		}
		String[] names = learningRelationBindingNames[relationId];
		if (names == null) {
			names = query.materializeRelation(relationId).getBindingNames().toArray(String[]::new);
			learningRelationBindingNames[relationId] = names;
		}
		Collections.addAll(target, names);
	}

	private LogicalLearningKey uncorrelatedLogicalLearningKey(int relationId) {
		if (relationId <= 0 || relationId > query.relationCount()) {
			return null;
		}
		int identityId = contextualCanonicalGroupId(relationId);
		TupleExpr expression = query.materializeRelation(identityId);
		LeoOperatorKey leoKey = LeoOperatorKey.from(expression, "", LeoOperatorKey.ConstantMode.EXACT);
		StringBuilder children = new StringBuilder();
		for (int child = 0; child < query.childCount(identityId); child++) {
			if (child > 0) {
				children.append('|');
			}
			TupleExpr childExpression = query.materializeRelation(
					contextualCanonicalGroupId(query.childRelationId(identityId, child)));
			children.append(LeoOperatorKey.from(childExpression, "", LeoOperatorKey.ConstantMode.EXACT)
					.structuralFingerprint());
		}
		String canonicalExpression = leoKey.structuralFingerprint();
		String datasetScope = (datasetUsesStoreDefaults ? "store-defaults" : "explicit-dataset") + '|'
				+ (expression instanceof StatementPattern pattern ? pattern.getScope().name() : "mixed-scope");
		return LogicalLearningKey.of(learningOperatorFamily(identityId),
				LearningKeyCodec.digest(canonicalExpression), LearningKeyCodec.digest(children.toString()),
				LearningKeyCodec.digest(canonicalExpression), alphaMask(leoKey.outputMask()), "none",
				logicalSemantics(expression), datasetScope);
	}

	private void stampProductionLearningIdentity(PackedCostEstimate output,
			ProductionLearningIdentity identity, FrontierLearningKey learningKey) {
		output.putPlannedStringMetric("optimizer.logicalLearningKey", identity.logicalKey().externalForm());
		output.putPlannedStringMetric("optimizer.logicalLearningKeyDigest", identity.logicalKey().digest());
		output.putPlannedStringMetric("optimizer.learningApplicability", identity.applicability().externalForm());
		output.putPlannedStringMetric("optimizer.learningApplicabilityDigest", identity.applicability().digest());
		output.putPlannedStringMetric("optimizer.physicalResidualKey", identity.physicalKey().externalForm());
		output.putPlannedStringMetric("optimizer.physicalResidualKeyDigest", identity.physicalKey().digest());
		FrontierLearningKey physicalLearningKey = FrontierLearningKey.parse(
				output.plannedStringMetric("optimizer.frontierPhysicalLearningKey"));
		if (physicalLearningKey == null) {
			physicalLearningKey = learningKey;
		}
		output.setRuntimeFeedbackContract(runtimeFeedbackContract(
				new LmdbRuntimeFeedbackDescriptor(learningKey, physicalLearningKey, identity.logicalKey(),
						identity.applicability(), identity.physicalKey(), identity.logicalGroupOrigin()),
				output));
	}

	void refreshRuntimeFeedbackContract(PackedCostEstimate output) {
		if (output == null) {
			return;
		}
		RuntimeFeedbackContract contract = output.runtimeFeedbackContract();
		if (contract == null || !(contract.descriptor()instanceof LmdbRuntimeFeedbackDescriptor descriptor)) {
			return;
		}
		output.setRuntimeFeedbackContract(runtimeFeedbackContract(descriptor, output));
	}

	private RuntimeFeedbackContract runtimeFeedbackContract(LmdbRuntimeFeedbackDescriptor descriptor,
			PackedCostEstimate output) {
		double rawLogicalCardinality = predictionDimension(
				output, FrontierCostDimension.OUTPUT_ROWS, output.outputRows(), true);
		double appliedLogicalCardinality = predictionDimension(
				output, FrontierCostDimension.OUTPUT_ROWS, output.outputRows(), false);
		RuntimeFeedbackContract.PredictionVector applied = predictionVector(descriptor, output, false);
		RuntimeFeedbackContract.PredictionVector raw = predictionVector(descriptor, output, true);
		RuntimeFeedbackContract.DependentPredictionVector appliedDependent = dependentPredictionVector(output, false);
		RuntimeFeedbackContract.DependentPredictionVector rawDependent = dependentPredictionVector(output, true);
		double point = finiteNonNegative(output.objectivePoint()) ? output.objectivePoint()
				: finiteNonNegative(output.workRows()) ? output.workRows() : 0.0d;
		double lower = finiteNonNegative(output.objectiveLower()) ? Math.min(output.objectiveLower(), point) : point;
		double upper = finiteNonNegative(output.objectiveUpper()) ? Math.max(output.objectiveUpper(), point) : point;
		double regressionLimit = output.plannedDoubleMetric("optimizer.lifecycleRegressionLimit",
				Double.POSITIVE_INFINITY);
		if (!(finiteNonNegative(regressionLimit) || regressionLimit == Double.POSITIVE_INFINITY)) {
			regressionLimit = Double.POSITIVE_INFINITY;
		}
		RuntimeFeedbackContract.SemanticKind semanticKind = runtimeSemanticKind(descriptor, output);
		RuntimeFeedbackContract.Algorithm algorithm = runtimeAlgorithm(output);
		int flags = RuntimeFeedbackContract.ADMIT_LOGICAL | RuntimeFeedbackContract.ADMIT_PHYSICAL
				| RuntimeFeedbackContract.ADMIT_LIFECYCLE | RuntimeFeedbackContract.ORIGIN_CERTIFIED;
		if (semanticKind == RuntimeFeedbackContract.SemanticKind.FILTER) {
			flags |= RuntimeFeedbackContract.ADMIT_FILTER;
		} else if (semanticKind == RuntimeFeedbackContract.SemanticKind.EXISTS
				|| semanticKind == RuntimeFeedbackContract.SemanticKind.NOT_EXISTS) {
			flags |= RuntimeFeedbackContract.ADMIT_FILTER | RuntimeFeedbackContract.ADMIT_SEMI_ANTI;
		}
		if (output.evidenceGuarantee() == EvidenceGuarantee.DATABASE_EXACT) {
			flags |= RuntimeFeedbackContract.DATABASE_EXACT;
		}
		if (output.plannedStringMetric("optimizer.frontierLogicalGroupKey") != null) {
			flags |= RuntimeFeedbackContract.EXACT_FACT_ELIGIBLE;
		}
		long dataEpoch = Math.max(0L, runtime.snapshotVersion());
		long modelEpoch = Math.max(0L, runtime.leoRevision());
		return new RuntimeFeedbackContract(descriptor, raw, applied,
				rawLogicalCardinality, appliedLogicalCardinality, rawDependent, appliedDependent,
				lower, point, upper, regressionLimit, semanticKind, algorithm, runtimeAccess(output),
				descriptor.physicalKey().hashCode(),
				dataEpoch, dataEpoch, modelEpoch, flags);
	}

	private static RuntimeFeedbackContract.PredictionVector predictionVector(
			LmdbRuntimeFeedbackDescriptor descriptor, PackedCostEstimate output, boolean raw) {
		double totalRows = predictionDimension(output, FrontierCostDimension.OUTPUT_ROWS, output.outputRows(), raw);
		double exposure = immutableOpenPredictionExposure(descriptor, output);
		boolean perOpen = exposure > 0.0d;
		double rows = perOpen ? perOpenRowsPrediction(output, totalRows, raw, exposure) : totalRows;
		double sourceRows = perOpenAdditivePrediction(predictionDimension(output,
				FrontierCostDimension.SOURCE_ROWS_SCANNED, output.sequentialRows(), raw), exposure, perOpen);
		double seeks = perOpenAdditivePrediction(
				predictionDimension(output, FrontierCostDimension.INDEX_SEEKS, output.randomSeeks(), raw),
				exposure, perOpen);
		double opens = perOpenAdditivePrediction(
				predictionDimension(output, FrontierCostDimension.ITERATOR_OPENS, output.iteratorOpens(), raw),
				exposure, perOpen);
		double expressions = perOpenAdditivePrediction(predictionDimension(output,
				FrontierCostDimension.EXPRESSION_EVALUATIONS, output.expressionEvaluations(), raw), exposure, perOpen);
		double hashBuild = perOpenAdditivePrediction(predictionDimension(output,
				FrontierCostDimension.HASH_BUILD_ROWS, output.hashBuildRows(), raw), exposure, perOpen);
		double hashProbe = perOpenAdditivePrediction(predictionDimension(output,
				FrontierCostDimension.HASH_PROBE_ROWS, output.hashProbeRows(), raw), exposure, perOpen);
		double paths = perOpenAdditivePrediction(predictionDimension(output,
				FrontierCostDimension.PATH_EXPANSIONS, output.pathExpansions(), raw), exposure, perOpen);
		double results = perOpen ? rows
				: predictionDimension(output,
						FrontierCostDimension.RESULT_ROWS, output.resultRows(), raw);
		double remote = perOpenAdditivePrediction(predictionDimension(output,
				FrontierCostDimension.REMOTE_CALLS, output.remoteCalls(), raw), exposure, perOpen);
		double memory = predictionDimension(output, FrontierCostDimension.MEMORY_SPILL_WORK,
				output.peakMemoryRows(), raw);
		double work = raw
				? sumKnown(sourceRows, seeks, opens, expressions, hashBuild, hashProbe, paths, results, remote)
				: perOpenAdditivePrediction(output.workRows(), exposure, perOpen);
		return new RuntimeFeedbackContract.PredictionVector(rows, work, results, sourceRows, seeks, opens,
				expressions, hashBuild, hashProbe, paths, remote, memory);
	}

	/**
	 * Returns the costing event's explicit immutable-open exposure, or zero when the event describes one complete node
	 * evaluation. Only logical access leaves currently publish an authoritative {@code plannedRowsPerInvocation};
	 * higher operators can inherit that explanatory metric from a child and must not use it as their own prediction.
	 */
	private static double immutableOpenPredictionExposure(LmdbRuntimeFeedbackDescriptor descriptor,
			PackedCostEstimate output) {
		String operator = descriptor.logicalKey().logicalOperator();
		boolean accessLeaf = "statement-pattern".equals(operator)
				|| "binding-set-assignment".equals(operator)
				|| operator.endsWith("path");
		double perOpenRows = output.plannedDoubleMetric("plannedRowsPerInvocation", Double.NaN);
		if (!accessLeaf || !finiteNonNegative(perOpenRows)) {
			return 0.0d;
		}
		double exposure = output.invocations();
		return finiteNonNegative(exposure) && exposure > 0.0d ? exposure : 1.0d;
	}

	private static double perOpenRowsPrediction(PackedCostEstimate output, double totalRows, boolean raw,
			double exposure) {
		double rawPerOpen = output.plannedDoubleMetric("plannedRowsPerInvocation", Double.NaN);
		if (raw || !finiteNonNegative(rawPerOpen)) {
			return rawPerOpen;
		}
		double rawTotal = predictionDimension(
				output, FrontierCostDimension.OUTPUT_ROWS, output.outputRows(), true);
		if (finiteNonNegative(rawTotal) && rawTotal > 0.0d && finiteNonNegative(totalRows)) {
			return finiteProduct(rawPerOpen, totalRows / rawTotal);
		}
		if (rawTotal == 0.0d && totalRows == 0.0d) {
			return rawPerOpen;
		}
		return perOpenAdditivePrediction(totalRows, exposure, true);
	}

	private static double perOpenAdditivePrediction(double total, double exposure, boolean perOpen) {
		if (!perOpen || !finiteNonNegative(total)) {
			return total;
		}
		double prediction = total / exposure;
		return finiteNonNegative(prediction) ? prediction : Double.NaN;
	}

	private static double finiteProduct(double left, double right) {
		double product = left * right;
		return finiteNonNegative(product) ? product : Double.NaN;
	}

	private static RuntimeFeedbackContract.DependentPredictionVector dependentPredictionVector(
			PackedCostEstimate output, boolean raw) {
		if (!output.hasDependentCostComponents()) {
			return RuntimeFeedbackContract.DependentPredictionVector.UNKNOWN;
		}
		double invocations = output.dependentInvocationCount();
		double firstMatchPerHit = predictionDimension(output, FrontierCostDimension.FIRST_MATCH_WORK,
				output.firstMatchWork(), raw);
		double exhaustionPerMiss = predictionDimension(output, FrontierCostDimension.EXHAUSTION_WORK,
				output.exhaustionWork(), raw);
		double reopenPerInvocation = addKnown(Double.NaN, output.rebindWork());
		reopenPerInvocation = addKnown(reopenPerInvocation, output.closeWork());
		double reopen = multiplyKnown(invocations, reopenPerInvocation);
		double materializationBuild = predictionDimension(output,
				FrontierCostDimension.MATERIALIZATION_BUILD_WORK, output.hashBuildRows(), raw);
		double materializationLookup = predictionDimension(output,
				FrontierCostDimension.MATERIALIZATION_LOOKUP_WORK, output.hashProbeRows(), raw);
		double memorySpill = predictionDimension(output, FrontierCostDimension.MEMORY_SPILL_WORK,
				output.memorySpillWork(), raw);
		return new RuntimeFeedbackContract.DependentPredictionVector(
				predictionDimension(output, FrontierCostDimension.STARTUP_ONCE, output.startupOnceWork(), raw),
				reopen, firstMatchPerHit, exhaustionPerMiss,
				predictionDimension(output, FrontierCostDimension.CACHE_HIT_WORK, output.cacheHits(), raw),
				predictionDimension(output, FrontierCostDimension.CACHE_MISS_WORK, output.cacheMisses(), raw),
				predictionDimension(output, FrontierCostDimension.CACHE_EVICTION_WORK, output.cacheEvictions(), raw),
				materializationBuild, materializationLookup, memorySpill);
	}

	private static double multiplyKnown(double first, double second) {
		return finiteNonNegative(first) && finiteNonNegative(second)
				? saturatedMultiply(first, second)
				: Double.NaN;
	}

	private static double multiplyKnown(double first, double second, double third) {
		return finiteNonNegative(first) && finiteNonNegative(second) && finiteNonNegative(third)
				? saturatedMultiply(saturatedMultiply(first, second), third)
				: Double.NaN;
	}

	private static double predictionDimension(PackedCostEstimate output, FrontierCostDimension dimension,
			double applied, boolean raw) {
		if (!raw) {
			return applied;
		}
		return output.plannedDoubleMetric(
				"optimizer.frontierLeo." + dimension.name().toLowerCase(Locale.ROOT) + ".raw", applied);
	}

	private static double sumKnown(double first, double second, double third, double fourth, double fifth,
			double sixth, double seventh, double eighth, double ninth) {
		double sum = addKnown(Double.NaN, first);
		sum = addKnown(sum, second);
		sum = addKnown(sum, third);
		sum = addKnown(sum, fourth);
		sum = addKnown(sum, fifth);
		sum = addKnown(sum, sixth);
		sum = addKnown(sum, seventh);
		sum = addKnown(sum, eighth);
		return addKnown(sum, ninth);
	}

	private static double addKnown(double sum, double value) {
		if (!finiteNonNegative(value)) {
			return sum;
		}
		return Double.isNaN(sum) ? value : saturatedAdd(sum, value);
	}

	private static RuntimeFeedbackContract.SemanticKind runtimeSemanticKind(
			LmdbRuntimeFeedbackDescriptor descriptor, PackedCostEstimate output) {
		String semiAntiKind = output.plannedStringMetric("optimizer.semiAntiKind");
		if ("exists".equals(semiAntiKind)) {
			return RuntimeFeedbackContract.SemanticKind.EXISTS;
		}
		if ("not-exists".equals(semiAntiKind) || "minus-assured-shared".equals(semiAntiKind)) {
			return RuntimeFeedbackContract.SemanticKind.NOT_EXISTS;
		}
		if ("filter".equals(descriptor.logicalKey().logicalOperator())) {
			return RuntimeFeedbackContract.SemanticKind.FILTER;
		}
		return RuntimeFeedbackContract.SemanticKind.ORDINARY;
	}

	private static RuntimeFeedbackContract.Algorithm runtimeAlgorithm(PackedCostEstimate output) {
		String algorithm = firstNonBlank(output.plannedStringMetric("optimizer.semiAntiAlgorithm"),
				output.plannedStringMetric("optimizer.physicalJoinImplementation"),
				output.plannedStringMetric("plannedPhysicalImplementation"), "").toLowerCase(Locale.ROOT);
		if (algorithm.contains("material")) {
			return RuntimeFeedbackContract.Algorithm.MATERIALIZED_HASH;
		}
		if (algorithm.contains("memo")) {
			return RuntimeFeedbackContract.Algorithm.MEMOIZED_CORRELATED;
		}
		if (algorithm.contains("stream")) {
			return RuntimeFeedbackContract.Algorithm.STREAMING_CORRELATED;
		}
		if (algorithm.contains("hash")) {
			return RuntimeFeedbackContract.Algorithm.HASH_JOIN;
		}
		if (algorithm.contains("path")) {
			return RuntimeFeedbackContract.Algorithm.PATH;
		}
		if (algorithm.contains("remote") || algorithm.contains("service")) {
			return RuntimeFeedbackContract.Algorithm.REMOTE;
		}
		if (output.invocations() > 1.0d) {
			return RuntimeFeedbackContract.Algorithm.DEPENDENT_ITERATION;
		}
		return algorithm.isEmpty()
				? RuntimeFeedbackContract.Algorithm.UNKNOWN
				: RuntimeFeedbackContract.Algorithm.SCAN;
	}

	private static RuntimeFeedbackContract.Access runtimeAccess(PackedCostEstimate output) {
		String accessMode = firstNonBlank(output.accessMode(), "").toLowerCase(Locale.ROOT);
		if (accessMode.contains("direct") || accessMode.contains("exact")) {
			return RuntimeFeedbackContract.Access.EXACT_LOOKUP;
		}
		if (accessMode.contains("range")) {
			return RuntimeFeedbackContract.Access.RANGE_LOOKUP;
		}
		if (accessMode.contains("prefix")) {
			return RuntimeFeedbackContract.Access.PREFIX_SCAN;
		}
		if (accessMode.contains("scan")) {
			return RuntimeFeedbackContract.Access.FULL_SCAN;
		}
		if (output.indexName() != null && !output.indexName().isBlank()) {
			return RuntimeFeedbackContract.Access.PREFIX_SCAN;
		}
		return RuntimeFeedbackContract.Access.NONE;
	}

	private static String alphaMask(BindingMask mask) {
		if (mask == null || mask.isEmpty()) {
			return "none";
		}
		StringBuilder result = new StringBuilder();
		for (int bit = mask.nextSetBit(0); bit >= 0; bit = mask.nextSetBit(bit + 1)) {
			if (!result.isEmpty()) {
				result.append(',');
			}
			result.append('v').append(bit);
		}
		return result.toString();
	}

	private static String logicalSemantics(TupleExpr expression) {
		String bagMode = expression instanceof Distinct ? "set" : expression instanceof Reduced ? "reduced" : "bag";
		String duplicateMode = expression instanceof Distinct
				? "duplicate-insensitive"
				: "duplicate-sensitive";
		String unboundMode = expression instanceof Difference
				? "minus-compatible-domain"
				: expression instanceof LeftJoin ? "optional-unbound" : "sparql-unbound";
		return bagMode + '|' + duplicateMode + '|' + unboundMode;
	}

	private static String firstNonBlank(String... values) {
		for (String value : values) {
			if (value != null && !value.isBlank()) {
				return value;
			}
		}
		return "unknown";
	}

	private record ProductionLearningIdentity(LogicalLearningKey logicalKey, LearningApplicability applicability,
			PhysicalResidualKey physicalKey,
			LmdbRuntimeFeedbackDescriptor.LogicalGroupOrigin logicalGroupOrigin) {
	}

	private int learningIdentityRelationId(int relationId) {
		if (!groupCanonicalOutputRowsLearningEnabled()
				|| relationId <= 0 || relationId > query.relationCount()) {
			return relationId;
		}
		return contextualCanonicalGroupId(relationId);
	}

	/*
	 * Fact and learning identities are keyed by memo group, but one scheduled predicate can span several groups: a
	 * rule-derived framing (e.g. the duplicate-insensitive unused-optional rewrite of a MINUS) re-interns the operator
	 * and its scheduled FILTER copies under a fresh group. Those copies share one contextual operator cost identity
	 * with the source framing's copies, and the outer costing wrapper already routes their events through the earliest
	 * copy — so an executed DIFFERENCE framing and its scheduled-FILTER framing would otherwise mint and consume group
	 * facts under different keys (MEDICAL q9 run-2 plan flip, 2026-08-05). Union the groups bridged by that mapping and
	 * key every member by the earliest group in its union.
	 */
	private int contextualCanonicalGroupId(int relationId) {
		int[] canonicalGroups = contextualCanonicalGroupIds;
		if (canonicalGroups == null) {
			canonicalGroups = buildContextualCanonicalGroupIds();
			contextualCanonicalGroupIds = canonicalGroups;
		}
		return canonicalGroups[memberGroupId(relationId)];
	}

	private int[] buildContextualCanonicalGroupIds() {
		int[] roots = new int[query.relationCount() + 1];
		for (int id = 0; id < roots.length; id++) {
			roots[id] = id;
		}
		for (int relationId = 1; relationId <= query.relationCount(); relationId++) {
			int canonicalId = query.canonicalContextualOperatorRelationId(relationId);
			if (canonicalId == relationId || canonicalId <= 0 || canonicalId > query.relationCount()) {
				continue;
			}
			int left = rootGroupId(roots, memberGroupId(relationId));
			int right = rootGroupId(roots, memberGroupId(canonicalId));
			if (left != right) {
				roots[Math.max(left, right)] = Math.min(left, right);
			}
		}
		for (int id = 1; id < roots.length; id++) {
			roots[id] = rootGroupId(roots, id);
		}
		return roots;
	}

	private static int rootGroupId(int[] roots, int groupId) {
		int current = groupId;
		while (roots[current] != current) {
			current = roots[current];
		}
		return current;
	}

	private int memberGroupId(int relationId) {
		int groupId = query.relGroup(relationId);
		return groupId > 0 && groupId <= query.relationCount() ? groupId : relationId;
	}

	/*
	 * A group cardinality fact describes the standalone logical relation. A costing event may still mint or consume one
	 * with a non-empty prefix in exactly one shape: a unary operator (a contextually interned scheduled FILTER copy),
	 * or a typed semi/anti operator, whose prefix is precisely its own encoded input. That event is the same
	 * top-of-stream application a prefix-free operator refinement describes, merely reached through the join
	 * enumerator's contextual route. Partial prefixes observe a different conditional relation, and per-outer-row
	 * probes are already excluded by the correlation-scope gate; both stay barred from facts.
	 */
	/*
	 * An exact same-stamp cardinality fact for a semi/anti relation bounds its probe invocation count from below:
	 * retained rows are a subset of the outer input, so outer rows can never be smaller than an observed output. Unlike
	 * the structural floor this also overrules a composable input whose learned interval authoritatively vouches for a
	 * crushed row count — the fact is a measurement at the current data stamp. Correlated probes and partial-prefix
	 * schedules observe conditional relations and take no floor.
	 */
	private double semiAntiFactOuterRowsFloor(int relationId, PackedCostContext context,
			EvidenceStateRef predictedState, PackedCostEstimate output) {
		if (!frontierExactCardinalityFactsEnabled()
				|| context == null || context.correlationMaskId() != 0
				|| !prefixCoversRelationInput(relationId, context) || predictedState == null || output == null) {
			return Double.NaN;
		}
		LmdbOperatorFeedbackStats feedbackStats = runtime.feedback();
		if (feedbackStats == null) {
			return Double.NaN;
		}
		EvidenceStateRef transformState = rawTransformState(predictedState);
		FrontierStateKey stateKey = arena.hasCanonicalKey(transformState) ? arena.key(transformState) : null;
		ProductionLearningIdentity identity = productionLearningIdentity(
				relationId, transformState, stateKey, context, output);
		double factRows = feedbackStats.exactCardinalityFact(identity.logicalKey(), identity.applicability());
		return finiteNonNegative(factRows) ? factRows : Double.NaN;
	}

	private boolean prefixCoversRelationInput(int relationId, PackedCostContext context) {
		int prefixCount = context.prefixRelationCount();
		if (prefixCount == 0) {
			return true;
		}
		if (relationId <= 0 || relationId > query.relationCount()) {
			return false;
		}
		int childCount = query.childCount(relationId);
		boolean typedSemiAnti = query.isSemiJoin(relationId) || query.isAntiJoin(relationId);
		boolean logicalDifference = query.materializeRelation(relationId) instanceof Difference;
		if (childCount != 1 && !((typedSemiAnti || logicalDifference) && childCount == 2)) {
			return false;
		}
		long[] inputFactors = relationFactorWords(query.childRelationId(relationId, 0));
		long[] prefixFactors = new long[(query.relationCount() + 63) >>> 6];
		boolean[] visited = new boolean[query.relationCount() + 1];
		for (int ordinal = 0; ordinal < prefixCount; ordinal++) {
			addRelationFactors(context.prefixRelationId(ordinal), prefixFactors, visited);
		}
		int wordCount = Math.max(inputFactors.length, prefixFactors.length);
		for (int word = 0; word < wordCount; word++) {
			long inputWord = word < inputFactors.length ? inputFactors[word] : 0L;
			long prefixWord = word < prefixFactors.length ? prefixFactors[word] : 0L;
			if (inputWord != prefixWord) {
				return false;
			}
		}
		return true;
	}

	private String learningOperatorFamily(int relationId) {
		if (relationId == 0) {
			return "join";
		}
		if (learningOperatorFamilies == null) {
			learningOperatorFamilies = new String[query.relationCount() + 1];
		}
		String cached = learningOperatorFamilies[relationId];
		if (cached != null) {
			return cached;
		}
		TupleExpr expression = query.materializeRelation(learningIdentityRelationId(relationId));
		String simpleName = expression.getClass().getSimpleName();
		String family = simpleName.isBlank() ? "tuple-expr" : camelToKebab(simpleName);
		learningOperatorFamilies[relationId] = family;
		return family;
	}

	private String learningRawTransform(int relationId, EvidenceStateRef state, PackedCostContext context) {
		String operation = arena.operation(state).name();
		if (relationId <= 0 || relationId > query.relationCount()) {
			/*
			 * Without a topology suffix every intermediate join in the store shares one OUTPUT_ROWS learning family
			 * ("joinJOIN"), letting workload A's join corrections calibrate unrelated queries. The prefix relation set
			 * gives the join a stable topology identity: same-topology pooling across binding layouts and access
			 * kernels (the useful generalization) survives; cross-topology pooling does not. The joined factor is not
			 * part of the prefix, so joins extending the same prefix still pool — that residual is bounded by the
			 * family clamp credit in FrontierLearningModel.
			 */
			if (relationId <= 0 && frontierJoinFamilyTopologyEnabled() && context != null
					&& context.prefixRelationCount() > 0) {
				long fingerprint = prefixTopologyFingerprint(context);
				if (fingerprint != 0L) {
					return operation + '@' + fixedHex(fingerprint);
				}
			}
			return operation;
		}
		if (learningRawTransforms == null) {
			learningRawTransforms = new String[query.relationCount() + 1];
		}
		String cached = learningRawTransforms[relationId];
		if (cached != null && cached.startsWith(operation + '@')) {
			return cached;
		}
		TupleExpr expression = query.materializeRelation(learningIdentityRelationId(relationId));
		String topology = LeoOperatorKey.from(expression, "", LeoOperatorKey.ConstantMode.EXACT)
				.structuralFingerprint();
		String transform = operation + '@' + fixedHex(avalancheLearningFingerprint(fnvFingerprint(topology)));
		learningRawTransforms[relationId] = transform;
		return transform;
	}

	static final String FRONTIER_JOIN_FAMILY_TOPOLOGY_PROPERTY = "rdf4j.optimizer.lmdb.frontierJoinFamilyTopology";

	private static boolean frontierJoinFamilyTopologyEnabled() {
		return !"false".equalsIgnoreCase(System.getProperty(FRONTIER_JOIN_FAMILY_TOPOLOGY_PROPERTY, "true"));
	}

	private long prefixTopologyFingerprint(PackedCostContext context) {
		int count = context.prefixRelationCount();
		long[] fingerprints = new long[count];
		for (int ordinal = 0; ordinal < count; ordinal++) {
			int prefixRelationId = context.prefixRelationId(ordinal);
			if (prefixRelationId <= 0 || prefixRelationId > query.relationCount()) {
				return 0L;
			}
			fingerprints[ordinal] = relationTopologyFingerprint(prefixRelationId);
		}
		java.util.Arrays.sort(fingerprints);
		long hash = 0x9e3779b97f4a7c15L;
		for (long fingerprint : fingerprints) {
			hash ^= fingerprint;
			hash *= 0x100000001b3L;
		}
		long avalanched = avalancheLearningFingerprint(hash);
		return avalanched == 0L ? 1L : avalanched;
	}

	private long relationTopologyFingerprint(int relationId) {
		if (relationTopologyFingerprints == null) {
			relationTopologyFingerprints = new long[query.relationCount() + 1];
		}
		long cached = relationTopologyFingerprints[relationId];
		if (cached != 0L) {
			return cached;
		}
		TupleExpr expression = query.materializeRelation(relationId);
		String topology = LeoOperatorKey.from(expression, "", LeoOperatorKey.ConstantMode.EXACT)
				.structuralFingerprint();
		long fingerprint = fnvFingerprint(topology);
		fingerprint = fingerprint == 0L ? 1L : fingerprint;
		relationTopologyFingerprints[relationId] = fingerprint;
		return fingerprint;
	}

	private static long fnvFingerprint(String value) {
		long fingerprint = 0xcbf29ce484222325L;
		for (int index = 0; index < value.length(); index++) {
			fingerprint ^= value.charAt(index);
			fingerprint *= 0x100000001b3L;
		}
		return fingerprint;
	}

	private static String camelToKebab(String value) {
		StringBuilder result = new StringBuilder(value.length() + 4);
		for (int index = 0; index < value.length(); index++) {
			char character = value.charAt(index);
			if (Character.isUpperCase(character) && index > 0) {
				result.append('-');
			}
			result.append(Character.toLowerCase(character));
		}
		return result.toString();
	}

	private long learningLayoutFingerprint(FrontierStateKey key, EvidenceStateRef state, PackedCostContext context) {
		long hash = mixLearningFingerprint(0x243f6a8885a308d3L, arena.layout(state).hashCode());
		/*
		 * A physical binding-layout class describes the ordered variables and their semantic scope. Mask strata are
		 * sampled evidence and query-local layout IDs are interning details; either can change after feedback without
		 * changing the implementation that will execute. Including them makes a verified LastGood alternative
		 * unreachable on the next planning pass.
		 */
		if (key != null) {
			hash = mixLearningFingerprint(hash, key.semanticScope());
		} else if (context != null) {
			hash = mixLearningFingerprint(hash, context.semanticScopeMaskId());
		}
		return avalancheLearningFingerprint(hash);
	}

	static String learningAccessKernel(PackedCostEstimate output) {
		String implementation = output.plannedStringMetric("plannedPhysicalImplementation");
		if (implementation == null || implementation.isBlank()) {
			implementation = "unspecified";
		}
		String kernel = "lookup=" + output.lookupComponentMask() + ":missing="
				+ output.missingLookupComponentMask() + ":prefix=" + output.indexPrefixLength()
				+ ":implementation=" + implementation;
		String physicalJoin = output.plannedStringMetric("optimizer.physicalJoinImplementation");
		return physicalJoin == null || physicalJoin.isBlank() ? kernel : kernel + ":physical-join=" + physicalJoin;
	}

	private String learningStateDigest(EvidenceStateRef state) {
		FrontierStateKey key = arena.hasCanonicalKey(state) ? arena.key(state) : null;
		EvidenceStateSummary summary = state.summary();
		long keyHash = key == null ? arena.layout(state).hashCode() : key.stableHash();
		long high = mixLearningFingerprint(0x6a09e667f3bcc909L, keyHash);
		high = mixLearningFingerprint(high, summary.hashCode());
		high = mixLearningFingerprint(high, arena.operation(state).ordinal());
		high = mixLearningFingerprint(high, arena.disposition(state).ordinal());
		long low = mixLearningFingerprint(0xbb67ae8584caa73bL, Long.rotateLeft(keyHash, 29));
		low = mixLearningFingerprint(low, summary.guarantee().ordinal());
		low = mixLearningFingerprint(low, Double.doubleToLongBits(summary.pointRows()));
		EvidenceCalibrationSummary calibration = arena.nearestCalibration(state);
		if (calibration != null) {
			high = mixLearningFingerprint(high, calibration.hashCode());
			low = mixLearningFingerprint(low, calibration.evidenceRevision());
		}
		return fixedHex(avalancheLearningFingerprint(high)) + fixedHex(avalancheLearningFingerprint(low));
	}

	private static long learningEvidenceCount(FrontierLearningModel.DimensionEstimate estimate) {
		return Math.max(1L, estimate.exactEvidenceCount() + estimate.familyEvidenceCount()
				+ estimate.legacyEvidenceCount());
	}

	private static double posteriorConfidence(double precision) {
		return finiteNonNegative(precision) ? Math.clamp(precision / (precision + 1.0d), 0.0d, 1.0d) : 0.0d;
	}

	private static int changed(double raw, double corrected) {
		return Double.doubleToLongBits(raw) == Double.doubleToLongBits(corrected) ? 0 : 1;
	}

	private static long mixLearningFingerprint(long hash, long value) {
		long mixed = value + 0x9e3779b97f4a7c15L + (hash << 6) + (hash >>> 2);
		return hash ^ mixed;
	}

	private static long avalancheLearningFingerprint(long value) {
		value ^= value >>> 33;
		value *= 0xff51afd7ed558ccdL;
		value ^= value >>> 33;
		value *= 0xc4ceb9fe1a85ec53L;
		return value ^ value >>> 33;
	}

	private static String fixedHex(long value) {
		String hex = Long.toUnsignedString(value, 16);
		return "0".repeat(16 - hex.length()) + hex;
	}

	private void publishJoinState(PackedCostEstimate output, EvidenceStateRef state) {
		EvidenceStateSummary summary = state.summary();
		if (!isComposableState(state)) {
			publishDegradedState(output, state);
			output.putPlannedStringMetric("plannedPhysicalImplementation", FRONTIER_EXECUTION_MODE);
			return;
		}
		output.setEvidenceStateId(state.stateId());
		annotateReady(output, state);
		annotateFactorCount(output, state);
		output.putPlannedStringMetric("plannedPhysicalImplementation", FRONTIER_EXECUTION_MODE);
		if (mode != FrontierEstimatorMode.AUTHORITATIVE) {
			return;
		}
		if (summary.guarantee() == EvidenceGuarantee.MEASURE_UNBIASED
				&& summary.zeroStatus() == EvidenceZeroStatus.ESTIMATED_ZERO) {
			publishSampledZeroFallback(0, output, state);
			return;
		}
		setLocalOperatorPhysicalCost(output, summary.pointRows(), 0.0d, 0.0d, 0.0d, 0.0d);
		output.setEvidenceGuarantee(summary.guarantee());
		boolean learned = arena.nearestCalibration(state) != null;
		output.setEstimateProvenance(learned ? FRONTIER_LEO_SOURCE : FRONTIER_SOURCE,
				learned ? "frontier_learned_calibration" : "frontier_authoritative");
	}

	private static boolean qualifiedLeoCorrection(LmdbOperatorFeedbackStats.OperatorEstimate feedback) {
		return feedback != null
				&& feedback.evidenceCount() >= MINIMUM_LEO_EVIDENCE_COUNT
				&& feedback.correctionConfidence() >= MINIMUM_LEO_CORRECTION_CONFIDENCE
				&& finiteNonNegative(feedback.rows())
				&& finiteNonNegative(feedback.workRows())
				&& feedback.feedbackKey() != null
				&& !feedback.feedbackKey().isBlank();
	}

	private double evidenceRows(int stateId, double fallback) {
		EvidenceStateRef state = stateReference(stateId);
		return state == null ? fallback : state.summary().pointRows();
	}

	@Override
	public FrontierEvidenceBundle detachEvidence(int[] evidenceStateIds) {
		if (closed || arena == null) {
			return FrontierEvidenceBundle.empty(evidenceStateIds.length);
		}
		return arena.exportEvidence(evidenceStateIds);
	}

	PackedStalePlanValidation validateStalePlan(PackedPlanValidationRequest request) {
		Objects.requireNonNull(request, "request");
		if (arena == null || closed) {
			return PackedStalePlanValidation.replan(0.0d, 1.0d, queryIndexVisitedRows,
					"current-frontier-generation-unavailable");
		}
		if (request.cachedContext().predicateRangeVersion() != request.currentContext().predicateRangeVersion()) {
			return PackedStalePlanValidation.replan(0.0d, 1.0d, queryIndexVisitedRows,
					"predicate-range-semantics-changed");
		}

		PackedCostingReplay.Result replay = PackedCostingReplay.replay(request,
				new LmdbFrontierLearningCostSession(this));
		if (request.decisionCount() == 0) {
			return PackedStalePlanValidation.replan(0.0d, 1.0d, replay.workUnits(),
					"selected-cost-event-missing-from-certificate");
		}
		int[] selectedCandidates = new int[request.decisionCount()];
		int comparisonCount = 0;
		for (int decision = 0; decision < request.decisionCount(); decision++) {
			int selected = selectedCandidate(request, decision);
			if (selected < 0) {
				return PackedStalePlanValidation.replan(0.0d, 1.0d, replay.workUnits(),
						"selected-cost-event-missing-from-certificate");
			}
			selectedCandidates[decision] = selected;
			int selectedTier = request.candidateTier(selected);
			double selectedCost = replay.candidateCost(selected);
			for (int candidate = request.decisionStart(decision); candidate < request
					.decisionEnd(decision); candidate++) {
				if (candidate == selected) {
					continue;
				}
				comparisonCount++;
				int tier = request.candidateTier(candidate);
				double cost = replay.candidateCost(candidate);
				if (tier < selectedTier || tier == selectedTier && cost < selectedCost) {
					return PackedStalePlanValidation.replan(1.0d, relativeRegret(selectedCost, cost),
							replay.workUnits(), request.acceptedWhenCosted(candidate)
									? "current-cost-event-changed-winner"
									: "current-cost-event-invalidated-pruning-proof");
				}
			}
		}
		double selectedCost = replay.candidateCost(selectedCandidates[0]);
		boolean candidateStatesExact = allCandidateStatesExact(request, replay);
		FrontierDecisionRiskController.Decision riskDecision = null;
		if (!candidateStatesExact) {
			riskDecision = settings.validationDecision(
					request.decisionFamilyFingerprint(), Math.max(selectedCost, Double.MIN_NORMAL), replay.workUnits(),
					Math.max(1, comparisonCount));
			if (!riskDecision.certified()) {
				return PackedStalePlanValidation.replan(riskDecision.confidence(), riskDecision.expectedRegret(),
						replay.workUnits(), riskDecision.reason());
			}
		}
		if (allCandidateEvidenceUnchanged(request, replay)) {
			double[] candidateCosts = replayedCandidateCosts(replay);
			return PackedStalePlanValidation.certified(replay, candidateCosts,
					candidateStatesExact ? 1.0d : riskDecision.confidence(),
					candidateStatesExact ? 0.0d : riskDecision.expectedRegret(), replay.workUnits(),
					candidateStatesExact ? "current-cost-events-certified" : "paired-cost-events-certified");
		}
		if (!candidateStatesExact) {
			long observations = 0L;
			String reason = "paired-cost-events-certified";
			for (int decision = 0; decision < request.decisionCount(); decision++) {
				PackedFrontierDecisionValidator.Result paired = PackedFrontierDecisionValidator.validate(
						request, replay, decision, selectedCandidates[decision], Math.max(1, comparisonCount),
						riskDecision.confidence(), riskDecision.expectedRegret(),
						settings.maximumExpectedRegret());
				observations = Math.addExact(observations, paired.observations());
				if (!paired.certified()) {
					return PackedStalePlanValidation.replan(paired.confidence(), paired.expectedRegret(),
							Math.addExact(replay.workUnits(), observations), paired.reason());
				}
				reason = paired.reason();
			}
			return PackedStalePlanValidation.certified(replay, replayedCandidateCosts(replay),
					riskDecision.confidence(), riskDecision.expectedRegret(),
					Math.addExact(replay.workUnits(), observations), reason);
		}
		double[] candidateCosts = replayedCandidateCosts(replay);
		return PackedStalePlanValidation.certified(replay, candidateCosts, 1.0d, 0.0d,
				replay.workUnits(), "current-cost-events-certified");
	}

	private static boolean allCandidateEvidenceUnchanged(PackedPlanValidationRequest request,
			PackedCostingReplay.Result replay) {
		FrontierEvidenceBundle cached = request.evidenceBundle();
		FrontierEvidenceBundle current = replay.currentEvidence();
		for (int candidate = 0; candidate < request.candidateCount(); candidate++) {
			int cachedOrdinal = request.candidateStateOrdinal(candidate);
			int currentOrdinal = replay.currentStateOrdinal(cachedOrdinal);
			if (cachedOrdinal == 0 || currentOrdinal == 0
					|| cached.guarantee(cachedOrdinal) != current.guarantee(currentOrdinal)
					|| cached.disposition(cachedOrdinal) != current.disposition(currentOrdinal)
					|| !cached.layout(cachedOrdinal).equals(current.layout(currentOrdinal))
					|| !cached.summary(cachedOrdinal).equals(current.summary(currentOrdinal))
					|| cached.payloadKind(cachedOrdinal) != current.payloadKind(currentOrdinal)
					|| cached.contentDigestHigh(cachedOrdinal) != current.contentDigestHigh(currentOrdinal)
					|| cached.contentDigestLow(cachedOrdinal) != current.contentDigestLow(currentOrdinal)) {
				return false;
			}
		}
		return true;
	}

	private static double[] replayedCandidateCosts(PackedCostingReplay.Result replay) {
		double[] candidateCosts = new double[replay.candidateCount()];
		for (int candidate = 0; candidate < candidateCosts.length; candidate++) {
			candidateCosts[candidate] = replay.candidateCost(candidate);
		}
		return candidateCosts;
	}

	private static int selectedCandidate(PackedPlanValidationRequest request, int decision) {
		for (int candidate = request.decisionStart(decision); candidate < request.decisionEnd(decision); candidate++) {
			if (request.candidateEventId(candidate) == request.selectedEventId(decision)) {
				return candidate;
			}
		}
		return -1;
	}

	private static boolean allCandidateStatesExact(PackedPlanValidationRequest request,
			PackedCostingReplay.Result replay) {
		FrontierEvidenceBundle current = replay.currentEvidence();
		for (int candidate = 0; candidate < request.candidateCount(); candidate++) {
			int cachedOrdinal = request.candidateStateOrdinal(candidate);
			int currentOrdinal = replay.currentStateOrdinal(cachedOrdinal);
			if (currentOrdinal == 0
					|| current.guarantee(currentOrdinal) != EvidenceGuarantee.DATABASE_EXACT
					|| current.disposition(currentOrdinal) != FrontierStateDisposition.COMPOSABLE_PAYLOAD) {
				return false;
			}
		}
		return true;
	}

	private static double relativeRegret(double selectedCost, double betterCost) {
		if (!(selectedCost > 0.0d) || !Double.isFinite(selectedCost) || !Double.isFinite(betterCost)) {
			return 1.0d;
		}
		return Math.max(0.0d, Math.min(1.0d, (selectedCost - betterCost) / selectedCost));
	}

	private boolean sameExactSourceContent(FrontierEvidenceBundle cached, int cachedOrdinal,
			EvidenceStateRef currentState) {
		if (currentState == null || currentState.summary().guarantee() != EvidenceGuarantee.DATABASE_EXACT) {
			return false;
		}
		FrontierEvidenceBundle current = arena.exportEvidence(new int[] { currentState.stateId() });
		int currentOrdinal = current.requestedStateOrdinal(0);
		return currentOrdinal > 0
				&& cached.layout(cachedOrdinal).equals(current.layout(currentOrdinal))
				&& cached.contentDigestHigh(cachedOrdinal) == current.contentDigestHigh(currentOrdinal)
				&& cached.contentDigestLow(cachedOrdinal) == current.contentDigestLow(currentOrdinal);
	}

	@Override
	public void close() {
		if (closed) {
			return;
		}
		closed = true;
		scalar.close();
		closePrimitiveMemo(storedFrontierValues);
		storedFrontierValues = null;
		closePrimitiveMemo(subjectCenterCompleteness);
		subjectCenterCompleteness = null;
		closePrimitiveMemo(objectCenterCompleteness);
		objectCenterCompleteness = null;
		if (statementProbeMemo != null) {
			statementProbeMemo.close();
			statementProbeMemo = null;
		}
		if (sessionReservation != null) {
			sessionReservation.close();
			sessionReservation = null;
		}
		if (arena != null) {
			arena.close();
			arena = null;
		}
		if (queryIndexLease != null) {
			queryIndexLease.close();
			queryIndexLease = null;
		}
		leafStates = null;
		finiteLeafStates = null;
		stateReferences = null;
		factorCountWords = null;
		candidateFactorWords = null;
		factorCountVisitEpochs = null;
		queryLocalValueIds.clear();
		queryLocalValues.clear();
		alternateReplayStates.clear();
		alternateReplayFailures.clear();
		exactDerivedStates.clear();
	}

	private static void closePrimitiveMemo(LmdbFrontierLongObjectMemo<?> memo) {
		if (memo != null) {
			memo.close();
		}
	}

	private void prepare() {
		LmdbFrontierSynopsisService synopsis = runtime.frontierSynopsis();
		if (mode == FrontierEstimatorMode.OFF || synopsis == null) {
			return;
		}
		FrontierSynopsisStatus currentStatus = synopsis.status();
		exposeFallback = currentStatus != FrontierSynopsisStatus.DISABLED_MODE;
		if (currentStatus == FrontierSynopsisStatus.DISABLED_ZERO_BUDGET) {
			unavailable("persistent_" + statusName(currentStatus));
			return;
		}
		if (settings.queryMemoryBudgetBytes() <= 0L) {
			unavailable("query_memory_budget_disabled");
			return;
		}
		if (!datasetUsesStoreDefaults) {
			unavailable("dataset_restricted");
			return;
		}
		if (runtime.mayHaveInferred()) {
			unavailable("inferred_plane_present");
			return;
		}
		if (executionSnapshotEpoch.isEmpty()) {
			unavailable("snapshot_epoch_unavailable");
			return;
		}
		LeafState[] candidates = collectLeafStates();
		FiniteLeafState[] finiteCandidates = collectFiniteLeafStates();
		int finiteCount = supportedFiniteLeafCount(finiteCandidates);
		int supported = Math.addExact(supportedLeafCount(candidates), finiteCount);
		if (supported == 0) {
			unavailable("no_supported_frontier_leaf");
			return;
		}

		long requiredEpoch = executionSnapshotEpoch.getAsLong();
		FrontierQueryIndexLease lease = synopsis.acquireQueryIndex(requiredEpoch);
		queryIndexStatus = lease.ready() ? "ready" : lease.fallbackReason();
		if (!lease.ready()) {
			availabilityStatus = statusName(lease.status());
			fallbackReason = lease.fallbackReason();
			FrontierSynopsisStatus unavailableStatus = lease.status();
			lease.close();
			prepareReplayableSources(candidates, finiteCandidates, unavailableStatus, requiredEpoch);
			return;
		}
		queryIndexLease = lease;
		queryIndexBytes = lease.byteLength();
		FrontierSynopsisReadResult counted = lease.readResult();
		generationDatabaseExact = counted.databaseExact();
		long workBudget = settings.initialMaterializationWorkUnits();
		independentMaterializationWorkRemaining = workBudget;
		boolean materializeIndependentLane = !generationDatabaseExact
				&& lease.designLaneCount() > INDEPENDENT_DESIGN_LANE_INDEX;
		int statementLeafCount = supportedLeafCount(candidates);
		int independentCount = materializeIndependentLane ? statementLeafCount : 0;
		int declaredLeafCount = Math.addExact(Math.addExact(statementLeafCount, independentCount), finiteCount);
		FrontierStateArena candidateArena = null;
		FrontierMemoryReservation candidateReservation = null;
		EvidenceStateRef[] candidateReferences = null;
		try {
			candidateArena = new FrontierStateArena(settings.queryMemoryBudgetBytes());
			long sessionBytes = Math.addExact(SESSION_BASE_BYTES,
					Math.addExact(Math.multiplyExact(SESSION_RELATION_BYTES, candidates.length),
							Math.multiplyExact(SESSION_LEAF_BYTES, declaredLeafCount)));
			sessionBytes = Math.addExact(sessionBytes,
					Math.addExact(retainedArrayBytes(candidates.length, Long.BYTES),
							retainedArrayBytes(Math.addExact(declaredLeafCount, 1), Long.BYTES)));
			candidateReservation = candidateArena.reserveTemporary(sessionBytes, FrontierMemoryPurpose.ARRAY_GROWTH);

			FrontierStateKey[] declaredKeys = new FrontierStateKey[declaredLeafCount];
			int declaredKeyCount = 0;
			for (int relationId = 1; relationId < candidates.length; relationId++) {
				LeafState candidate = candidates[relationId];
				if (candidate != null) {
					candidate.key = leafStateKey(candidate, counted, candidates.length);
					declaredKeys[declaredKeyCount++] = candidate.key;
					if (materializeIndependentLane) {
						candidate.independentKey = leafStateKey(
								candidate, counted, candidates.length, INDEPENDENT_DESIGN_LANE_INDEX);
						declaredKeys[declaredKeyCount++] = candidate.independentKey;
					}
				}
			}
			for (FiniteLeafState candidate : finiteCandidates) {
				if (candidate != null) {
					candidate.key = finiteStateKey(candidate, counted, candidates.length);
					declaredKeys[declaredKeyCount++] = candidate.key;
				}
			}
			try (FrontierMemoryReservation declarationInput = candidateArena.reserveTemporary(
					retainedArrayBytes(declaredKeyCount, Long.BYTES), FrontierMemoryPurpose.ARRAY_GROWTH)) {
				candidateArena.declareCanonicalStates(declaredKeys);
			}
			candidateReferences = new EvidenceStateRef[declaredKeyCount + 1];

			long[] candidateRangeRows = new long[candidates.length];
			for (int relationId = 1; relationId < candidates.length; relationId++) {
				LeafState candidate = candidates[relationId];
				if (candidate == null) {
					continue;
				}
				candidateRangeRows[relationId] = lease.candidateRangeRows(candidate.selector());
				queryIndexCandidateRows = Math.addExact(
						queryIndexCandidateRows, candidateRangeRows[relationId]);
			}
			int[] scanOrder = leafScanOrder(candidates, candidateRangeRows);
			long remainingWork = workBudget;
			for (int relationId : scanOrder) {
				LeafState candidate = candidates[relationId];
				long candidateRows = candidateRangeRows[relationId];
				if (candidateRows > remainingWork || candidateRows > MAXIMUM_LEAF_BUFFER_ROWS) {
					/*
					 * The mapped synopsis could not materialize this leaf within the preparation budget, but the
					 * descriptor remains a replayable snapshot source. Retaining it lets estimateLeaf publish a typed
					 * bound-only state and lets a later append refine the actual correlated prefix directly. Removing
					 * the descriptor here incorrectly turned ordinary statement patterns into unsupported opaque
					 * boundaries.
					 */
					queryIndexExcludedLeaves = Math.incrementExact(queryIndexExcludedLeaves);
					candidate.replayFallbackReason = candidateRows > MAXIMUM_LEAF_BUFFER_ROWS
							? "query_index_leaf_buffer_limit_exceeded"
							: "query_index_work_budget_exhausted";
					continue;
				}
				long primaryCandidateRows = lease.designLaneCandidateRows(candidate.selector(), DESIGN_LANE_INDEX);
				int maximumMatches = Math.toIntExact(primaryCandidateRows);
				EmissionBuffer primaryRows = new EmissionBuffer(candidateArena, 4, maximumMatches);
				try (primaryRows) {
					FrontierQueryIndexLeafScan scan = lease.visitPrimaryLeafWithDiagnostics(
							candidate.selector(),
							remainingWork,
							(subjectId, predicateId, objectId, contextId, weight) -> primaryRows.addRow(
									subjectId, predicateId, objectId, contextId, weight));
					queryIndexScanPasses = 1;
					long scannedRows = scan.diagnostics().scannedRows();
					queryIndexVisitedRows = Math.addExact(queryIndexVisitedRows, scannedRows);
					remainingWork -= scannedRows;
					if (!scan.complete()) {
						/* Retain the descriptor for the same replayable-source path as an up-front budget exclusion. */
						queryIndexExcludedLeaves = Math.incrementExact(queryIndexExcludedLeaves);
						candidate.replayFallbackReason = "query_index_work_budget_exhausted";
						continue;
					}
					if (!generationDatabaseExact) {
						recordLaneDiagnostics(scan.diagnostics());
					}
					if (scan.diagnostics().designMatchedRows(DESIGN_LANE_INDEX) != primaryRows.size()) {
						throw new IllegalStateException("Frontier single-pass leaf scan misreported matches");
					}
					queryIndexMatchedRows = Math.addExact(queryIndexMatchedRows, primaryRows.size());
					candidate.state = materializeLeafBuffer(
							candidateArena,
							candidate,
							candidate.key,
							primaryRows,
							generationDatabaseExact,
							relationId);
					candidateReferences[candidate.state.stateId()] = candidate.state;
				}
			}
			supported = Math.addExact(supportedLeafCount(candidates), finiteCount);
			if (supported == 0) {
				unavailableQueryIndex("query_index_work_budget_exhausted");
				return;
			}
			for (int relationId = 1; relationId < finiteCandidates.length; relationId++) {
				FiniteLeafState candidate = finiteCandidates[relationId];
				if (candidate == null) {
					continue;
				}
				candidate.state = materializeFiniteLeaf(candidateArena, candidate);
				candidateReferences[candidate.state.stateId()] = candidate.state;
			}

			arena = candidateArena;
			sessionReservation = candidateReservation;
			leafStates = candidates;
			finiteLeafStates = finiteCandidates;
			stateReferences = candidateReferences;
			availabilityStatus = "ready";
			fallbackReason = "";
			candidateArena = null;
			candidateReservation = null;
		} catch (RuntimeException failure) {
			throw new PackedCostSessionFailure("query_state_materialization_failed", failure);
		} finally {
			if (candidateReservation != null) {
				candidateReservation.close();
			}
			if (candidateArena != null) {
				candidateArena.close();
			}
		}
	}

	private void prepareReplayableSources(LeafState[] candidates, FiniteLeafState[] finiteCandidates,
			FrontierSynopsisStatus sourceStatus, long snapshotEpoch) {
		int statementLeafCount = supportedLeafCount(candidates);
		int finiteCount = supportedFiniteLeafCount(finiteCandidates);
		int declaredLeafCount = Math.addExact(statementLeafCount, finiteCount);
		if (declaredLeafCount == 0) {
			return;
		}
		FrontierStateArena candidateArena = null;
		FrontierMemoryReservation candidateReservation = null;
		try {
			candidateArena = new FrontierStateArena(settings.queryMemoryBudgetBytes());
			long sessionBytes = Math.addExact(SESSION_BASE_BYTES,
					Math.addExact(Math.multiplyExact(SESSION_RELATION_BYTES, candidates.length),
							Math.multiplyExact(SESSION_LEAF_BYTES, declaredLeafCount)));
			sessionBytes = Math.addExact(sessionBytes,
					Math.addExact(retainedArrayBytes(candidates.length, Long.BYTES),
							retainedArrayBytes(Math.addExact(declaredLeafCount, 1), Long.BYTES)));
			candidateReservation = candidateArena.reserveTemporary(sessionBytes, FrontierMemoryPurpose.ARRAY_GROWTH);

			FrontierSynopsisReadResult generation = new FrontierSynopsisReadResult(sourceStatus, 0L, 0L,
					snapshotEpoch, 0L, Double.NaN, false);
			FrontierStateKey[] declaredKeys = new FrontierStateKey[declaredLeafCount];
			int declaredKeyCount = 0;
			for (int relationId = 1; relationId < candidates.length; relationId++) {
				LeafState candidate = candidates[relationId];
				if (candidate != null) {
					candidate.key = leafStateKey(candidate, generation, candidates.length);
					declaredKeys[declaredKeyCount++] = candidate.key;
				}
			}
			for (FiniteLeafState candidate : finiteCandidates) {
				if (candidate != null) {
					candidate.key = finiteStateKey(candidate, generation, candidates.length);
					declaredKeys[declaredKeyCount++] = candidate.key;
				}
			}
			candidateArena.declareCanonicalStates(declaredKeys);
			EvidenceStateRef[] candidateReferences = new EvidenceStateRef[declaredLeafCount + 1];
			long[] candidateRangeRows = snapshotCandidateRangeRows(candidates);
			int[] scanOrder = leafScanOrder(candidates, candidateRangeRows);
			long remainingWork = settings.initialMaterializationWorkUnits();
			for (int relationId : scanOrder) {
				LeafState candidate = candidates[relationId];
				long candidateRows = candidateRangeRows[relationId];
				if (statementSource == null || candidateRows > remainingWork
						|| candidateRows > MAXIMUM_LEAF_BUFFER_ROWS) {
					candidate.replayFallbackReason = statementSource == null
							? "exact_snapshot_source_unavailable"
							: candidateRows > MAXIMUM_LEAF_BUFFER_ROWS
									? "snapshot_leaf_buffer_limit_exceeded"
									: "snapshot_leaf_work_budget_exhausted";
					continue;
				}
				candidate.state = materializeSnapshotExactLeaf(candidateArena, candidate, candidateRows);
				candidate.materialization = "snapshot_exact";
				candidateReferences[candidate.state.stateId()] = candidate.state;
				remainingWork -= candidateRows;
			}
			for (FiniteLeafState candidate : finiteCandidates) {
				if (candidate == null) {
					continue;
				}
				candidate.state = materializeFiniteLeaf(candidateArena, candidate);
				candidateReferences[candidate.state.stateId()] = candidate.state;
			}

			arena = candidateArena;
			sessionReservation = candidateReservation;
			leafStates = candidates;
			finiteLeafStates = finiteCandidates;
			stateReferences = candidateReferences;
			generationDatabaseExact = true;
			candidateArena = null;
			candidateReservation = null;
		} catch (RuntimeException failure) {
			throw new PackedCostSessionFailure("replayable_source_materialization_failed", failure);
		} finally {
			if (candidateReservation != null) {
				candidateReservation.close();
			}
			if (candidateArena != null) {
				candidateArena.close();
			}
		}
	}

	private long[] snapshotCandidateRangeRows(LeafState[] candidates) {
		long[] rows = new long[candidates.length];
		if (statementSource == null) {
			return rows;
		}
		try {
			for (int relationId = 1; relationId < candidates.length; relationId++) {
				LeafState candidate = candidates[relationId];
				if (candidate == null) {
					continue;
				}
				Resource context = (Resource) candidate.constantValues[3];
				Resource[] contexts = context == null ? new Resource[0] : new Resource[] { context };
				rows[relationId] = statementSource.getStatementCount(
						(Resource) candidate.constantValues[0],
						(IRI) candidate.constantValues[1],
						candidate.constantValues[2],
						contexts);
			}
			return rows;
		} catch (QueryEvaluationException failure) {
			throw new PackedCostSessionFailure("snapshot_leaf_count_failed", failure);
		}
	}

	private EvidenceStateRef materializeSnapshotExactLeaf(FrontierStateArena targetArena, LeafState candidate,
			long candidateRows) {
		int maximumEntries = Math.toIntExact(candidateRows);
		ExactLeafAccumulator accumulator = null;
		FrontierPayloadWriter writer = null;
		try {
			accumulator = new ExactLeafAccumulator(targetArena, maximumEntries, candidate.masks.layout().size());
			long[] tuple = new long[candidate.masks.layout().size()];
			Resource context = (Resource) candidate.constantValues[3];
			Resource[] contexts = context == null ? new Resource[0] : new Resource[] { context };
			long visitedRows = 0L;
			try (CloseableIteration<? extends Statement> statements = statementSource.getStatements(
					(Resource) candidate.constantValues[0],
					(IRI) candidate.constantValues[1],
					candidate.constantValues[2],
					contexts)) {
				while (statements.hasNext()) {
					Statement statement = statements.next();
					visitedRows = Math.incrementExact(visitedRows);
					if (visitedRows > candidateRows) {
						throw new IllegalStateException("snapshot leaf count underreported its candidate range");
					}
					if (!candidate.matches(statement, candidate.constantValues)) {
						continue;
					}
					Arrays.fill(tuple, 0L);
					for (int component = 0; component < candidate.componentToSlot.length; component++) {
						int slot = candidate.componentToSlot[component];
						if (slot < 0) {
							continue;
						}
						Value value = statementValue(statement, component);
						long termId = value == null ? 0L : runtime.valueStore().getId(value);
						if (termId <= 0L) {
							throw new IllegalStateException("snapshot-exact Frontier leaf returned an unstored term");
						}
						tuple[slot] = termId;
					}
					accumulator.add(tuple, 1.0d);
				}
			}
			if (visitedRows != candidateRows) {
				throw new IllegalStateException("snapshot leaf count changed within one LMDB read transaction");
			}
			writer = targetArena.newPayloadWriter(
					candidate.key, new int[] { accumulator.size() }, new int[] { 0 });
			accumulator.writeTo(writer);
			double pointRows = writer.pointRows();
			EvidenceStateRef state = targetArena.internPayload(
					candidate.key,
					EvidenceStateSummary.exact(pointRows),
					FrontierStateOperation.EXACT_LEAF,
					null,
					null,
					candidate.relationId,
					writer);
			writer = null;
			return state;
		} catch (IOException | QueryEvaluationException failure) {
			throw new PackedCostSessionFailure("snapshot_leaf_materialization_failed", failure);
		} finally {
			if (writer != null) {
				writer.close();
			}
			if (accumulator != null) {
				accumulator.close();
			}
		}
	}

	private LeafState[] collectLeafStates() {
		LeafState[] candidates = new LeafState[query.relationCount() + 1];
		HashSet<String> sharedStatementVariables = sharedStatementVariables();
		for (int relationId = 1; relationId <= query.relationCount(); relationId++) {
			if (!query.isStatementPattern(relationId)) {
				continue;
			}
			StatementPattern pattern = (StatementPattern) query.materializeRelation(relationId);
			LeafState candidate = LeafState.create(
					query, runtime, relationId, pattern, sharedStatementVariables);
			if (candidate != null) {
				candidates[relationId] = candidate;
			}
		}
		return candidates;
	}

	private HashSet<String> sharedStatementVariables() {
		HashSet<String> seen = new HashSet<>();
		HashSet<String> shared = new HashSet<>();
		for (int relationId = 1; relationId <= query.relationCount(); relationId++) {
			if (!query.isStatementPattern(relationId)) {
				continue;
			}
			for (int component = 0; component < 4; component++) {
				if (query.statementPatternValue(relationId, component) != null) {
					continue;
				}
				String name = query.statementPatternName(relationId, component);
				if (name != null && !seen.add(name)) {
					shared.add(name);
				}
			}
		}
		return shared;
	}

	private FiniteLeafState[] collectFiniteLeafStates() {
		FiniteLeafState[] candidates = new FiniteLeafState[query.relationCount() + 1];
		for (int relationId = 1; relationId <= query.relationCount(); relationId++) {
			TupleExpr expression = query.materializeRelation(relationId);
			if (expression instanceof BindingSetAssignment
					|| expression instanceof SingletonSet
					|| expression instanceof EmptySet) {
				candidates[relationId] = FiniteLeafState.create(relationId, expression);
			} else if (expression instanceof ZeroLengthPath path) {
				candidates[relationId] = FiniteLeafState.createBoundedZeroLengthPath(relationId, path);
			}
		}
		return candidates;
	}

	private EvidenceStateRef materializeFiniteLeaf(FrontierStateArena targetArena, FiniteLeafState candidate) {
		return materializeFiniteState(
				targetArena, candidate, FrontierStateOperation.EXACT_LEAF, null, null);
	}

	private EvidenceStateRef materializeFiniteState(FrontierStateArena targetArena, FiniteLeafState candidate,
			FrontierStateOperation operation, EvidenceStateRef firstParent, EvidenceStateRef secondParent) {
		int stratumCount = candidate.masks.stratumCount();
		int[] maximumCounts = new int[stratumCount];
		for (int stratum : candidate.rowStrata) {
			maximumCounts[stratum] = Math.incrementExact(maximumCounts[stratum]);
		}
		ExactLeafAccumulator[] accumulators = new ExactLeafAccumulator[stratumCount];
		FrontierPayloadWriter writer = null;
		try {
			for (int stratum = 0; stratum < stratumCount; stratum++) {
				accumulators[stratum] = new ExactLeafAccumulator(
						targetArena, maximumCounts[stratum], candidate.layout.size());
			}
			long[] tuple = new long[candidate.layout.size()];
			for (int row = 0; row < candidate.values.length; row++) {
				Arrays.fill(tuple, 0L);
				for (int slot = 0; slot < tuple.length; slot++) {
					Value value = candidate.values[row][slot];
					if (value != null) {
						tuple[slot] = encodeFrontierValue(value);
					}
				}
				accumulators[candidate.rowStrata[row]].add(tuple, 1.0d);
			}
			int[] exactCounts = new int[stratumCount];
			for (int stratum = 0; stratum < stratumCount; stratum++) {
				exactCounts[stratum] = accumulators[stratum].size();
			}
			writer = targetArena.newPayloadWriter(candidate.key, exactCounts, new int[stratumCount]);
			for (int stratum = 0; stratum < stratumCount; stratum++) {
				accumulators[stratum].writeTo(writer, stratum);
			}
			EvidenceStateRef state = targetArena.internPayload(
					candidate.key,
					EvidenceStateSummary.exact(writer.pointRows()),
					operation,
					firstParent,
					secondParent,
					candidate.relationId,
					writer);
			writer = null;
			return state;
		} finally {
			if (writer != null) {
				writer.close();
			}
			for (ExactLeafAccumulator accumulator : accumulators) {
				if (accumulator != null) {
					accumulator.close();
				}
			}
		}
	}

	private EvidenceStateRef exactAlternativeState(int relationId, TupleExpr expression) {
		LmdbFiniteJoinSurfaceEstimator.SurfaceEstimate surface = runtime
				.exactAlternativeSurface(expression)
				.orElse(null);
		if (surface == null || !surface.exact() || surface.relation() == null
				|| surface.relation().rows() != surface.surfaceRows()) {
			return null;
		}
		FrontierStateKey samplingKey = samplingIdentityKey();
		if (samplingKey == null) {
			return null;
		}
		FiniteLeafState finite = FiniteLeafState.create(relationId, surface.relation());
		long[] factors = new long[(query.relationCount() + 63) >>> 6];
		addRelationFactors(relationId, factors, new boolean[query.relationCount() + 1]);
		finite.key = operatorStateKey(samplingKey, factors, relationId, finite.masks);
		arena.declareCanonicalState(finite.key);
		EvidenceStateRef state = arena.find(finite.key);
		if (state == null) {
			state = materializeFiniteLeaf(arena, finite);
			rememberState(state);
		}
		return state;
	}

	private FrontierStateKey samplingIdentityKey() {
		if (leafStates != null) {
			for (LeafState leaf : leafStates) {
				if (leaf != null && leaf.key != null) {
					return leaf.key;
				}
			}
		}
		if (finiteLeafStates != null) {
			for (FiniteLeafState leaf : finiteLeafStates) {
				if (leaf != null && leaf.key != null) {
					return leaf.key;
				}
			}
		}
		return null;
	}

	private long encodeFrontierValue(Value value) {
		try {
			long storedId = runtime.valueStore().getId(value);
			if (storedId > 0L) {
				return storedId;
			}
		} catch (IOException failure) {
			throw new IllegalStateException("Frontier finite leaf could not resolve an LMDB value ID", failure);
		}
		Long existing = queryLocalValueIds.get(value);
		if (existing != null) {
			return existing;
		}
		long ordinal = Math.addExact(queryLocalValues.size(), 1);
		if (ordinal > Long.MAX_VALUE >>> 7) {
			throw new IllegalStateException("Frontier query-local value dictionary exhausted");
		}
		long encoded = ValueIds.createId(63, ordinal);
		queryLocalValueIds.put(value, encoded);
		queryLocalValues.add(value);
		return encoded;
	}

	private Value frontierValue(long termId) throws IOException {
		if (!ValueIds.isDouble(termId) && ValueIds.getIdType(termId) == 63) {
			long ordinal = ValueIds.getValue(termId);
			if (ordinal <= 0L || ordinal > queryLocalValues.size()) {
				throw new IOException("Frontier query-local value ID is outside the session dictionary");
			}
			return queryLocalValues.get(Math.toIntExact(ordinal - 1L));
		}
		if (storedFrontierValues == null && arena != null) {
			storedFrontierValues = LmdbFrontierLongObjectMemo.createIfCapacity(arena);
		}
		if (storedFrontierValues != null) {
			Value cached = storedFrontierValues.get(termId);
			if (cached != null) {
				return cached;
			}
		}
		Value value = runtime.valueStore().getValue(termId);
		if (storedFrontierValues != null) {
			storedFrontierValues.put(termId, value);
		}
		return value;
	}

	private void refineFilter(int relationId, PackedCostContext context, Filter filter, EvidenceStateRef input,
			double rawWorkRows, PackedCostEstimate output) {
		ExistsCondition existsCondition = pureExistsCondition(filter);
		EvidenceStateRef kernelInput = existsCondition == null
				? input
				: averageIndependentDesignState(input, relationId);
		FrontierStateKey outputKey = filterOperatorKey(relationId, kernelInput);
		if (outputKey == null || evaluationStrategy == null) {
			degradeOperator(output, input,
					outputKey == null ? "filter_state_unavailable" : "filter_evaluator_unavailable");
			return;
		}
		FrontierStateKey inputKey = arena.key(kernelInput);
		if (!filterCanInspectRetainedState(filter, inputKey.frontier())) {
			degradeOperator(output, input, "filter_condition_not_retained_or_nondeterministic");
			return;
		}

		try {
			boolean lineageSpecific = arena.nearestCalibration(kernelInput) != null;
			EvidenceStateRef state = lineageSpecific ? null : arena.find(outputKey);
			ExactProbeBudget exactProbeBudget = existsCondition == null
					? null
					: exactProbeBudget(relationId, filter, kernelInput,
							existsCondition.exists().getSubQuery(), output);
			if (exactProbeBudget != null) {
				output.putPlannedDoubleMetric("plannedFrontierExactProbeBoundWorkPerKey",
						exactProbeBudget.boundWorkPerKey());
				output.putPlannedDoubleMetric("plannedFrontierExactProbeDependentPlanWorkPerKey",
						exactProbeBudget.dependentPlanWorkPerKey());
				output.putPlannedDoubleMetric("plannedFrontierExactProbeEstimatedWorkPerKey",
						exactProbeBudget.estimatedWorkPerKey());
				output.putPlannedDoubleMetric("plannedFrontierExactProbeMaximumMappings",
						exactProbeBudget.maximumMappings());
				output.putPlannedDoubleMetric("plannedFrontierExactProbeWorkBudget",
						settings.refinementWorkUnits());
			}
			if (state == null) {
				state = existsCondition != null
						? restrictExistsFilter(kernelInput, outputKey, relationId, filter,
								exactProbeBudget.maximumMappings())
						: restrictFilter(kernelInput, outputKey, relationId, filter);
				rememberState(state);
			}
			EvidenceStateRef rawState = state;
			state = existsCondition == null
					? applyLearnedFilterCalibration(relationId, filter, input, rawState, output)
					: rawState;
			if (kernelInput.stateId() != input.stateId()) {
				output.putPlannedStringMetric(
						"plannedFrontierVarianceReduction", "independent_design_lane_average");
			}
			state = publishOperatorState(relationId, output, state);
			EvidenceStateSummary summary = state.summary();
			if (mode == FrontierEstimatorMode.AUTHORITATIVE
					&& isComposableState(state)
					&& !(summary.guarantee() == EvidenceGuarantee.MEASURE_UNBIASED
							&& summary.zeroStatus() == EvidenceZeroStatus.ESTIMATED_ZERO)
					&& existsCondition == null) {
				setLocalOperatorPhysicalCost(
						output,
						summary.pointRows(),
						input.summary().pointRows(),
						0.0d,
						0.0d,
						0.0d);
			}
			/*
			 * Candidate costs must consume the same immutable evidence state that was published for this candidate. In
			 * particular, a semi/anti outcome calibration changes the matched and unmatched row masses even though the
			 * underlying correlated key tuples remain attached through the CALIBRATE overlay. Passing rawState here
			 * delayed that correction until after physical alternatives had already been priced.
			 */
			applySemiAntiPhysicalCost(relationId, context, filter, input, state, output);
		} catch (FilterEvaluationFailure failure) {
			degradeOperator(output, input, "filter_evaluation_failed");
		} catch (RuntimeException failure) {
			throw new PackedCostSessionFailure("filter_state_materialization_failed", failure);
		}
	}

	private void applySemiAntiPhysicalCost(int relationId, PackedCostContext context, Filter filter,
			EvidenceStateRef input, EvidenceStateRef outputEvidence, PackedCostEstimate output) {
		ExistsCondition existsCondition = pureExistsCondition(filter);
		if (existsCondition == null) {
			return;
		}
		boolean typed = query.isSemiJoin(relationId) || query.isAntiJoin(relationId);
		SemiAntiPlanIdentity planIdentity = semiAntiPlanIdentity(relationId, existsCondition, output);
		int semanticKind = planIdentity.semanticKind();
		int rhsRelationId = typed ? query.semiAntiRightRelationId(relationId) : relationId;
		TupleExpr rhs = typed
				? query.materializeRelation(rhsRelationId)
				: existsCondition.exists().getSubQuery();
		Collection<String> structuralCorrelationNames = typed
				? Arrays.asList(semiAntiCorrelationNames(relationId))
				: filter.getArg().getBindingNames();
		SemiAntiBindingDomains bindingDomains = semiAntiBindingDomains(
				arena.layout(input).variables(), structuralCorrelationNames, rhs);
		double rhsRows = typed
				? estimatedRelationRows(rhsRelationId)
				: estimatedTupleRows(rhs);
		/*
		 * The structural cross-check for the probe invocation count: the costing context's input rows when the caller
		 * published them, else the annotator's standalone estimate of the filter's own argument. The context value wins
		 * when finite — a prefix-conditioned invocation legitimately sees fewer rows — but several costing routes never
		 * publish inputs, and without the fallback a degraded frontier input state was the sole authority for the
		 * invocation count.
		 */
		double structuralOuterRows = context != null && finiteNonNegative(context.leftInputRows())
				? context.leftInputRows()
				: typed && query.childCount(relationId) > 0
						? estimatedRelationRows(query.childRelationId(relationId, 0))
						: estimatedTupleRows(filter.getArg());
		FrontierSemiAntiProfile profile = correlationProfile(
				input, outputEvidence, bindingDomains, rhsRelationId, semanticKind,
				structuralOuterRows, semiAntiFactOuterRowsFloor(relationId, context, outputEvidence, output));
		annotateCorrelationProfile(output, profile);
		if (!arena.layout(input).variables().containsAll(bindingDomains.probeNames())) {
			output.putPlannedStringMetric(
					"plannedCorrelationDomainDisposition", "bound-only-missing-layout");
		}

		applyFrontierSemiAntiPhysicalCost(
				filter, semanticKind, planIdentity.algorithm(), rhs, rhsRows, profile, output);
	}

	private void refineBoundedSemiAntiFilter(int relationId, PackedCostContext context, Filter filter,
			EvidenceStateRef input, PackedCostEstimate output) {
		EvidenceStateSummary inputSummary = input.summary();
		double pointRows = finiteNonNegative(output.outputRows())
				? output.outputRows()
				: inputSummary.pointRows();
		double certifiedUpperBound = inputSummary.certifiedUpperBound();
		if (Double.isFinite(certifiedUpperBound)) {
			pointRows = Math.min(pointRows, certifiedUpperBound);
		}
		double intervalUpperRows = inputSummary.upperRows();
		if (Double.isFinite(intervalUpperRows)) {
			pointRows = Math.min(pointRows, intervalUpperRows);
		}
		String reason = inputSummary.degradationReason().isBlank()
				? "semi_anti_input_payload_unavailable"
				: inputSummary.degradationReason();
		EvidenceStateSummary outputSummary = EvidenceStateSummary.unresolved(
				pointRows, intervalUpperRows, certifiedUpperBound, reason);
		EvidenceStateRef state = arena.disposition(input) == FrontierStateDisposition.OPAQUE_BOUNDARY
				? arena.deriveOpaqueBoundary(input, outputSummary, relationId)
				: arena.deriveBoundBoundary(input, arena.layout(input), outputSummary, relationId);
		rememberState(state);
		publishOperatorState(relationId, output, state);
		applySemiAntiPhysicalCost(relationId, context, filter, input, state, output);
	}

	private void applyFrontierSemiAntiPhysicalCost(Filter feedbackFilter, int semanticKind, int algorithm,
			TupleExpr rhs, double rhsRows, FrontierSemiAntiProfile profile, PackedCostEstimate output) {
		double outerRows = profile.outerRows();
		double distinctProbeKeys = profile.probeDomain().planningDistinctKeys();
		double matchedDistinctProbeKeys = profile.planningMatchedDistinctProbeKeys();
		double unmatchedDistinctProbeKeys = profile.planningUnmatchedDistinctProbeKeys();
		if (profile.structuralFloorApplied()
				&& distinctProbeKeys < outerRows * DISTRUSTED_DISTINCT_KEY_FRACTION) {
			// The probe-key domain shares lineage with the overridden input estimate; scale the key masses to the
			// corrected invocation count instead of granting the memoized algorithm a near-total cache-hit rate.
			double matchedShare = outerRows > 0.0d ? profile.matchedRows() / outerRows : 0.0d;
			distinctProbeKeys = outerRows;
			matchedDistinctProbeKeys = outerRows * matchedShare;
			unmatchedDistinctProbeKeys = outerRows - matchedDistinctProbeKeys;
			output.putPlannedDoubleMetric("plannedCorrelationDistinctKeysOverride", distinctProbeKeys);
		}
		double materializationPartitions = profile.materializationParameterDomain().planningDistinctKeys();
		String[] probeNames = profile.probeDomain().bindingNames().toArray(String[]::new);
		String[] materializationNames = profile.materializationParameterDomain()
				.bindingNames()
				.toArray(String[]::new);
		JoinFactorCostModel.FactorCostEstimate probeFactor = candidateFactor(
				rhs, probeNames, rhsRows)
						.filter(JoinFactorCostModel.FactorCostEstimate::hasPhysicalAccessPath)
						.orElse(null);
		JoinFactorCostModel.FactorCostEstimate materializationFactor = candidateFactor(
				rhs, materializationNames, rhsRows)
						.filter(JoinFactorCostModel.FactorCostEstimate::hasPhysicalAccessPath)
						.orElse(null);
		double probeWorkRows = factorWorkRows(probeFactor, rhsRows);
		double materializationWorkRows = factorWorkRows(materializationFactor, rhsRows);
		DependentReopenCost dependentReopenCost = DependentReopenCost.from(output);
		double effectiveProbeWorkRows = dependentReopenCost.required()
				? Math.max(probeWorkRows, dependentReopenCost.workRows())
				: probeWorkRows;
		double hitProbability = outerRows > 0.0d
				? Math.max(0.0d, Math.min(1.0d, profile.matchedRows() / outerRows))
				: 0.0d;
		double firstMatchWorkRows = firstMatchWorkRows(
				effectiveProbeWorkRows, factorOutputRows(probeFactor, rhsRows));
		double exhaustionWorkRows = effectiveProbeWorkRows;
		double streamingFirstMatchWorkRows = firstMatchWorkRows;
		double streamingExhaustionWorkRows = exhaustionWorkRows;
		double memoizedFirstMatchWorkRows = firstMatchWorkRows;
		double memoizedExhaustionWorkRows = exhaustionWorkRows;
		MemoizedProbeCounts memoizedProbeCounts = memoizedProbeCounts(
				outerRows,
				distinctProbeKeys,
				matchedDistinctProbeKeys,
				unmatchedDistinctProbeKeys,
				hitProbability,
				semiAntiMemoCapacity());
		double materializationOutputRows = Math.max(0.0d, rhsRows);
		double streamingMatchedRowsExamined = saturatedMultiply(
				profile.matchedRows(), streamingFirstMatchWorkRows);
		double streamingUnmatchedRowsExamined = saturatedMultiply(
				profile.unmatchedRows(), streamingExhaustionWorkRows);
		double streamingRowsExamined = saturatedAdd(
				streamingMatchedRowsExamined, streamingUnmatchedRowsExamined);
		double memoizedMatchedRowsExamined = saturatedMultiply(
				memoizedProbeCounts.matchedMisses(), memoizedFirstMatchWorkRows);
		double memoizedUnmatchedRowsExamined = saturatedMultiply(
				memoizedProbeCounts.unmatchedMisses(), memoizedExhaustionWorkRows);
		double memoizedRowsExamined = saturatedAdd(
				memoizedMatchedRowsExamined, memoizedUnmatchedRowsExamined);
		double materializationAccessRows = saturatedMultiply(materializationPartitions, materializationWorkRows);
		double materializationBuildRows = saturatedMultiply(materializationPartitions, materializationOutputRows);
		double streamingObjective = semiAntiStreamingObjective(
				probeFactor, streamingRowsExamined, outerRows, hitProbability, streamingFirstMatchWorkRows,
				streamingExhaustionWorkRows, output.outputRows(), dependentReopenCost);
		double memoizedObjective = semiAntiMemoizedObjective(
				probeFactor, memoizedRowsExamined, memoizedProbeCounts, memoizedFirstMatchWorkRows,
				memoizedExhaustionWorkRows, output.outputRows(), dependentReopenCost);
		double materializedObjective = semiAntiMaterializedObjective(
				materializationFactor,
				materializationAccessRows,
				materializationPartitions,
				materializationBuildRows,
				outerRows,
				output.outputRows());
		ExactSemiAntiRefinement refinement = exactSemiAntiRefinement(
				rhs,
				profile,
				streamingObjective,
				memoizedObjective,
				materializedObjective,
				streamingRowsExamined,
				memoizedRowsExamined,
				materializationAccessRows,
				materializationBuildRows);
		if (refinement.applied()) {
			double streamingScale = streamingRowsExamined > 0.0d
					? refinement.streamingAccessRows() / streamingRowsExamined
					: 1.0d;
			double memoizedScale = memoizedRowsExamined > 0.0d
					? refinement.memoizedAccessRows() / memoizedRowsExamined
					: 1.0d;
			streamingRowsExamined = refinement.streamingAccessRows();
			memoizedRowsExamined = refinement.memoizedAccessRows();
			materializationAccessRows = refinement.materializationAccessRows();
			materializationBuildRows = refinement.materializationBuildRows();
			probeWorkRows = outerRows == 0.0d ? 0.0d : streamingRowsExamined / outerRows;
			materializationWorkRows = materializationPartitions == 0.0d
					? 0.0d
					: materializationAccessRows / materializationPartitions;
			materializationOutputRows = materializationPartitions == 0.0d
					? 0.0d
					: materializationBuildRows / materializationPartitions;
			streamingFirstMatchWorkRows = saturatedMultiply(streamingFirstMatchWorkRows, streamingScale);
			streamingExhaustionWorkRows = saturatedMultiply(streamingExhaustionWorkRows, streamingScale);
			memoizedFirstMatchWorkRows = saturatedMultiply(memoizedFirstMatchWorkRows, memoizedScale);
			memoizedExhaustionWorkRows = saturatedMultiply(memoizedExhaustionWorkRows, memoizedScale);
			streamingMatchedRowsExamined = saturatedMultiply(
					profile.matchedRows(), streamingFirstMatchWorkRows);
			streamingUnmatchedRowsExamined = saturatedMultiply(
					profile.unmatchedRows(), streamingExhaustionWorkRows);
			memoizedMatchedRowsExamined = saturatedMultiply(
					memoizedProbeCounts.matchedMisses(), memoizedFirstMatchWorkRows);
			memoizedUnmatchedRowsExamined = saturatedMultiply(
					memoizedProbeCounts.unmatchedMisses(), memoizedExhaustionWorkRows);
			streamingObjective = semiAntiStreamingObjective(
					probeFactor, streamingRowsExamined, outerRows, hitProbability,
					streamingFirstMatchWorkRows, streamingExhaustionWorkRows,
					output.outputRows(), dependentReopenCost);
			memoizedObjective = semiAntiMemoizedObjective(
					probeFactor, memoizedRowsExamined, memoizedProbeCounts, memoizedFirstMatchWorkRows,
					memoizedExhaustionWorkRows, output.outputRows(), dependentReopenCost);
			materializedObjective = semiAntiMaterializedObjective(
					materializationFactor,
					materializationAccessRows,
					materializationPartitions,
					materializationBuildRows,
					outerRows,
					output.outputRows());
		}
		int cheapestAlgorithm = bestSemiAntiAlgorithm(
				streamingObjective,
				memoizedObjective,
				distinctProbeKeys,
				materializedObjective,
				materializationBuildRows);
		int selectedAlgorithm = algorithm;
		double breakEvenKeys = semiAntiBreakEvenDistinctKeys(
				materializationAccessRows + materializationBuildRows, effectiveProbeWorkRows, distinctProbeKeys);

		output.putPlannedDoubleMetric("plannedCorrelationRhsRowsExamined", streamingRowsExamined);
		output.putPlannedDoubleMetric("plannedSemiAntiBoundAccessWorkRows", probeWorkRows);
		output.putPlannedDoubleMetric("plannedSemiAntiProbeWorkRows", effectiveProbeWorkRows);
		output.putPlannedDoubleMetric("plannedSemiAntiHitProbability", hitProbability);
		output.putPlannedDoubleMetric("plannedSemiAntiStreamingFirstMatchWork",
				streamingFirstMatchWorkRows);
		output.putPlannedDoubleMetric("plannedSemiAntiStreamingExhaustionWork",
				streamingExhaustionWorkRows);
		output.putPlannedDoubleMetric("plannedSemiAntiMemoizedFirstMatchWork",
				memoizedFirstMatchWorkRows);
		output.putPlannedDoubleMetric("plannedSemiAntiMemoizedExhaustionWork",
				memoizedExhaustionWorkRows);
		output.putPlannedDoubleMetric("plannedSemiAntiProbeOutputRows", factorOutputRows(probeFactor, rhsRows));
		output.putPlannedDoubleMetric("plannedSemiAntiStreamingMatchedProbeRows",
				streamingMatchedRowsExamined);
		output.putPlannedDoubleMetric("plannedSemiAntiStreamingUnmatchedProbeRows",
				streamingUnmatchedRowsExamined);
		output.putPlannedDoubleMetric("plannedSemiAntiMemoizedMatchedProbeKeys", matchedDistinctProbeKeys);
		output.putPlannedDoubleMetric("plannedSemiAntiMemoizedUnmatchedProbeKeys", unmatchedDistinctProbeKeys);
		output.putPlannedDoubleMetric("plannedSemiAntiMemoizedCacheMisses", memoizedProbeCounts.cacheMisses());
		output.putPlannedDoubleMetric("plannedSemiAntiMemoizedCacheHits", memoizedProbeCounts.cacheHits());
		output.putPlannedDoubleMetric("plannedSemiAntiMemoizedCacheEvictions",
				memoizedProbeCounts.cacheEvictions());
		output.putPlannedDoubleMetric("plannedSemiAntiMemoizedCacheRows", memoizedProbeCounts.cacheRows());
		output.putPlannedDoubleMetric("plannedSemiAntiMaterializationWorkRows", materializationAccessRows);
		output.putPlannedDoubleMetric("plannedSemiAntiMaterializationOutputRows", materializationBuildRows);
		output.putPlannedDoubleMetric("plannedSemiAntiMaterializationPartitions", materializationPartitions);
		output.putPlannedDoubleMetric("plannedSemiAntiBreakEvenDistinctKeys", breakEvenKeys);
		output.putPlannedDoubleMetric("plannedSemiAntiStreamingObjectiveCost", streamingObjective);
		output.putPlannedDoubleMetric("plannedSemiAntiMemoizedObjectiveCost", memoizedObjective);
		output.putPlannedDoubleMetric("plannedSemiAntiMaterializedObjectiveCost", materializedObjective);
		output.putPlannedStringMetric("plannedSemiAntiPackedCandidateAlgorithm", semiAntiAlgorithmName(algorithm));
		output.putPlannedStringMetric("plannedSemiAntiCheapestRawAlgorithm", semiAntiAlgorithmName(cheapestAlgorithm));
		output.putPlannedStringMetric("plannedSemiAntiProbeBindingDomain",
				String.join(",", profile.probeDomain().bindingNames()));
		output.putPlannedStringMetric("plannedSemiAntiHashBindingDomain",
				String.join(",", profile.sharedHashDomain().bindingNames()));
		output.putPlannedStringMetric("plannedSemiAntiMaterializationParameterDomain",
				String.join(",", profile.materializationParameterDomain().bindingNames()));
		if (dependentReopenCost.required()) {
			output.putPlannedStringMetric("plannedSemiAntiDependentPlanDisposition",
					dependentReopenCost.outerIndependentWork()
							? "reopened-outer-independent-plan"
							: "reopened-independent-hash");
			output.putPlannedDoubleMetric("plannedSemiAntiDependentPlanObjectivePerInvocation",
					dependentReopenCost.objectiveCost());
		}
		annotateCandidateAccess(output, "Probe", probeFactor);
		annotateCandidateAccess(output, "Materialization", materializationFactor);
		annotateExactRefinement(output, refinement);

		switch (selectedAlgorithm) {
		case PackedQueryView.SEMI_ANTI_STREAMING -> {
			if (dependentReopenCost.required()) {
				setReopenedDependentPhysicalCost(output, dependentReopenCost,
						equivalentExhaustionInvocations(profile.matchedRows(), profile.unmatchedRows(),
								streamingFirstMatchWorkRows, streamingExhaustionWorkRows),
						0.0d, 0.0d);
			} else {
				output.setLocalPhysicalCost(
						streamingRowsExamined, outerRows, outerRows, 0.0d, 0.0d, 0.0d, 0.0d,
						output.outputRows(), 0.0d, 0.0d);
			}
		}
		case PackedQueryView.SEMI_ANTI_MEMOIZED -> {
			if (dependentReopenCost.required()) {
				setReopenedDependentPhysicalCost(
						output, dependentReopenCost,
						equivalentExhaustionInvocations(
								memoizedProbeCounts.matchedMisses(), memoizedProbeCounts.unmatchedMisses(),
								memoizedFirstMatchWorkRows, memoizedExhaustionWorkRows),
						outerRows, memoizedProbeCounts.cacheRows());
			} else {
				output.setLocalPhysicalCost(
						memoizedRowsExamined, memoizedProbeCounts.cacheMisses(),
						memoizedProbeCounts.cacheMisses(), 0.0d, 0.0d, outerRows, 0.0d,
						output.outputRows(), 0.0d, memoizedProbeCounts.cacheRows());
			}
		}
		case PackedQueryView.SEMI_ANTI_MATERIALIZED -> output.setLocalPhysicalCost(
				materializationAccessRows,
				0.0d,
				materializationAccessRows == 0.0d ? 0.0d : materializationPartitions,
				0.0d,
				materializationBuildRows,
				outerRows,
				0.0d,
				output.outputRows(),
				0.0d,
				materializationBuildRows);
		default -> throw new IllegalStateException("unknown packed semi/anti algorithm " + algorithm);
		}
		stampDependentCostComponents(output, selectedAlgorithm, dependentReopenCost, outerRows, hitProbability,
				streamingFirstMatchWorkRows, streamingExhaustionWorkRows, memoizedFirstMatchWorkRows,
				memoizedExhaustionWorkRows, memoizedProbeCounts, materializationPartitions,
				materializationAccessRows + materializationBuildRows, materializationBuildRows,
				streamingObjective, memoizedObjective, materializedObjective);
		stampSelectedSemiAntiAccess(
				output,
				selectedAlgorithm,
				probeFactor,
				materializationFactor,
				streamingRowsExamined,
				memoizedRowsExamined,
				materializationAccessRows,
				outerRows,
				memoizedProbeCounts.cacheMisses(),
				materializationPartitions);
		output.putPlannedDoubleMetric("optimizer.semiAntiCacheCapacity",
				selectedAlgorithm == PackedQueryView.SEMI_ANTI_MEMOIZED ? semiAntiMemoCapacity() : 0.0d);
		String algorithmName = semiAntiAlgorithmName(selectedAlgorithm);
		output.putPlannedStringMetric("optimizer.filterAlgorithmHint", algorithmName);
		output.putPlannedStringMetric("optimizer.semiAntiAlgorithm", algorithmName);
		output.putPlannedStringMetric("optimizer.semiAntiKind", semiAntiPlanSemanticName(semanticKind));
		output.putPlannedStringMetric("plannedPhysicalImplementation",
				semanticKind == PackedQueryView.SEMI_ANTI_MINUS_ASSURED_SHARED
						&& selectedAlgorithm == PackedQueryView.SEMI_ANTI_MATERIALIZED
								? "materialized-minus-compatibility"
								: algorithmName);
		applySemiAntiPhysicalFeedback(feedbackFilter, semanticKind, selectedAlgorithm, outerRows, output);
		applySemiAntiLeoPhysicalResidual(feedbackFilter, selectedAlgorithm, output);
		output.setDependentSubqueriesCosted(true);
	}

	private Optional<JoinFactorCostModel.FactorCostEstimate> candidateFactor(
			TupleExpr rhs, String[] boundNames, double unboundOutputRows) {
		return boundNames == null || boundNames.length == 0
				? lmdbCostModel.estimateFactor(rhs, boundNames)
				: lmdbCostModel.estimateCorrelatedFactor(rhs, boundNames, unboundOutputRows);
	}

	private static double factorWorkRows(JoinFactorCostModel.FactorCostEstimate factor, double fallbackRows) {
		if (factor != null && finiteNonNegative(factor.getWorkRows())) {
			/*
			 * A composite factor's access metric may describe only its leaf-most index scan. The factor work is the
			 * provider's inclusive per-invocation estimate and is therefore the only valid quantity for probe budgeting
			 * and correlated candidate costing. Retain the access metric solely as a compatibility fallback for older
			 * providers that did not publish finite total work.
			 */
			return Math.max(1.0d, factor.getWorkRows());
		}
		Double accessWorkRows = factor == null
				? null
				: factor.getDoubleMetrics().get(TelemetryMetricNames.PLANNED_ACCESS_WORK_ROWS);
		double rows = accessWorkRows != null && finiteNonNegative(accessWorkRows)
				? accessWorkRows
				: factor == null ? fallbackRows : factor.getWorkRows();
		return finiteNonNegative(rows) ? Math.max(1.0d, rows) : Math.max(1.0d, fallbackRows);
	}

	private static double factorOutputRows(JoinFactorCostModel.FactorCostEstimate factor, double fallbackRows) {
		double rows = factor == null ? fallbackRows : factor.getOutputRows();
		return finiteNonNegative(rows) ? rows : Math.max(0.0d, fallbackRows);
	}

	private static void annotateCandidateAccess(PackedCostEstimate output, String candidate,
			JoinFactorCostModel.FactorCostEstimate factor) {
		if (factor == null) {
			output.putPlannedStringMetric("plannedSemiAnti" + candidate + "AccessMode", "unavailable");
			return;
		}
		String indexName = factor.getStringMetrics().get(TelemetryMetricNames.PLANNED_INDEX_NAME);
		if (indexName != null) {
			output.putPlannedStringMetric("plannedSemiAnti" + candidate + "IndexName", indexName);
		}
		String accessMode = factor.getStringMetrics().get(TelemetryMetricNames.PLANNED_INDEX_ACCESS_MODE);
		if (accessMode == null) {
			accessMode = factor.isDirectLookup() ? "directLookup" : "prefixScan";
		}
		output.putPlannedStringMetric("plannedSemiAnti" + candidate + "AccessMode", accessMode);
	}

	private static void stampSelectedSemiAntiAccess(PackedCostEstimate output, int algorithm,
			JoinFactorCostModel.FactorCostEstimate probeFactor,
			JoinFactorCostModel.FactorCostEstimate materializationFactor,
			double streamingAccessRows, double memoizedAccessRows, double materializationAccessRows,
			double outerRows, double distinctProbeKeys, double materializationPartitions) {
		JoinFactorCostModel.FactorCostEstimate selectedFactor = algorithm == PackedQueryView.SEMI_ANTI_MATERIALIZED
				? materializationFactor
				: probeFactor;
		if (selectedFactor == null) {
			return;
		}
		double invocations;
		double totalAccessRows;
		switch (algorithm) {
		case PackedQueryView.SEMI_ANTI_STREAMING -> {
			invocations = outerRows;
			totalAccessRows = streamingAccessRows;
		}
		case PackedQueryView.SEMI_ANTI_MEMOIZED -> {
			invocations = distinctProbeKeys;
			totalAccessRows = memoizedAccessRows;
		}
		case PackedQueryView.SEMI_ANTI_MATERIALIZED -> {
			invocations = materializationPartitions;
			totalAccessRows = materializationAccessRows;
		}
		default -> throw new IllegalStateException("unknown packed semi/anti algorithm " + algorithm);
		}
		double accessRows = invocations == 0.0d ? 0.0d : totalAccessRows / invocations;
		if (!finiteNonNegative(accessRows)) {
			accessRows = selectedFactor.getAccessRowsBeforeFilter();
		}
		if (!finiteNonNegative(accessRows)) {
			accessRows = 0.0d;
		}
		Map<String, String> strings = selectedFactor.getStringMetrics();
		String operatorEstimateSource = output.estimateSource();
		String operatorEstimateFusion = output.estimateFusion();
		String accessEstimateSource = strings.getOrDefault(
				TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE, "lmdb-semi-anti");
		String accessMode = strings.get(TelemetryMetricNames.PLANNED_INDEX_ACCESS_MODE);
		if (accessMode == null) {
			accessMode = selectedFactor.isDirectLookup() ? "directLookup" : "prefixScan";
		}
		output.setAccess(
				selectedFactor.getLookupComponentMask(),
				selectedFactor.getMissingLookupComponentMask(),
				factorIndexPrefixLength(selectedFactor),
				accessRows,
				invocations,
				factorIndexName(selectedFactor),
				accessEstimateSource,
				accessMode);
		output.putPlannedStringMetric("plannedSemiAntiSelectedAccessEstimateSource", accessEstimateSource);
		if (operatorEstimateSource != null || operatorEstimateFusion != null) {
			/*
			 * setAccess retains the legacy single-source mirror used by leaf estimates. A semi/anti FILTER has two
			 * independently measured facts: its output cardinality comes from the Frontier transform, while its probe
			 * work comes from the selected RHS access event. Preserve both instead of letting the child access source
			 * overwrite the originating operator estimate.
			 */
			output.setEstimateProvenance(operatorEstimateSource, operatorEstimateFusion);
		}
	}

	private static int factorIndexPrefixLength(JoinFactorCostModel.FactorCostEstimate factor) {
		Double prefixLength = factor.getDoubleMetrics().get(TelemetryMetricNames.PLANNED_INDEX_PREFIX_LENGTH);
		if (prefixLength != null && finiteNonNegative(prefixLength)) {
			return (int) Math.min(Integer.MAX_VALUE, prefixLength);
		}
		return Integer.bitCount(factor.getLookupComponentMask());
	}

	private static String factorIndexName(JoinFactorCostModel.FactorCostEstimate factor) {
		return factor == null ? null : factor.getStringMetrics().get(TelemetryMetricNames.PLANNED_INDEX_NAME);
	}

	private ExactSemiAntiRefinement exactSemiAntiRefinement(TupleExpr rhs, FrontierSemiAntiProfile profile,
			double streamingObjective, double memoizedObjective, double materializedObjective,
			double streamingAccessRows, double memoizedAccessRows, double materializationAccessRows,
			double materializationBuildRows) {
		double[] objectives = { streamingObjective, memoizedObjective, materializedObjective };
		Arrays.sort(objectives);
		boolean decisionClose = objectives[0] == 0.0d
				? objectives[1] == 0.0d
				: objectives[1] <= objectives[0] * SEMI_ANTI_EXACT_REFINEMENT_RATIO;
		if (!decisionClose) {
			return ExactSemiAntiRefinement.declined(
					"not-needed", "decisive", streamingAccessRows, memoizedAccessRows,
					materializationAccessRows, materializationBuildRows);
		}
		if (profile.guarantee() != EvidenceGuarantee.DATABASE_EXACT
				|| profile.probeDomain().guarantee() != EvidenceGuarantee.DATABASE_EXACT) {
			return ExactSemiAntiRefinement.declined(
					"declined", "inexact-domain", streamingAccessRows, memoizedAccessRows,
					materializationAccessRows, materializationBuildRows);
		}
		if (!(rhs instanceof StatementPattern)) {
			return ExactSemiAntiRefinement.declined(
					"declined", "unsupported-access-kernel", streamingAccessRows, memoizedAccessRows,
					materializationAccessRows, materializationBuildRows);
		}
		ExactRelationResult probeRelation = exactCorrelationRelation(profile.probeDomain());
		if (probeRelation.relation() == null) {
			return ExactSemiAntiRefinement.declined(
					"declined", probeRelation.declineReason(), streamingAccessRows, memoizedAccessRows,
					materializationAccessRows, materializationBuildRows);
		}
		FiniteRelationEstimate distinctProbeRelation = distinctRelation(probeRelation.relation());
		CorrelationSurfaceCacheIdentity probeIdentity = new CorrelationSurfaceCacheIdentity(
				profile.probeDomain().stateId(),
				String.join("\u0000", profile.probeDomain().bindingNames()),
				"probe");
		var streamingSurface = runtime.exactCorrelatedSurface(
				probeIdentity,
				probeRelation.relation(),
				rhs,
				JoinFactorCostModel.EstimationTier.DECISION_EXACT);
		var memoizedSurface = runtime.exactCorrelatedSurface(
				probeIdentity,
				distinctProbeRelation,
				rhs,
				JoinFactorCostModel.EstimationTier.DECISION_EXACT);
		if (streamingSurface.isEmpty() || memoizedSurface.isEmpty()) {
			return ExactSemiAntiRefinement.declined(
					"declined", "surface-budget-or-shape", streamingAccessRows, memoizedAccessRows,
					materializationAccessRows, materializationBuildRows);
		}

		double exactStreamingAccessRows = exactSurfaceWork(streamingSurface.orElseThrow());
		double exactMemoizedAccessRows = exactSurfaceWork(memoizedSurface.orElseThrow());
		double exactMaterializationAccessRows = materializationAccessRows;
		double exactMaterializationBuildRows = materializationBuildRows;
		long materializationScannedRows = -1L;
		String appliedScope = "probe";
		ExactRelationResult parameterRelation = exactCorrelationRelation(
				profile.materializationParameterDomain());
		if (parameterRelation.relation() != null) {
			FiniteRelationEstimate distinctParameters = distinctRelation(parameterRelation.relation());
			CorrelationSurfaceCacheIdentity parameterIdentity = new CorrelationSurfaceCacheIdentity(
					profile.materializationParameterDomain().stateId(),
					String.join("\u0000", profile.materializationParameterDomain().bindingNames()),
					"materialization");
			var materializationSurface = runtime.exactCorrelatedSurface(
					parameterIdentity,
					distinctParameters,
					rhs,
					JoinFactorCostModel.EstimationTier.DECISION_EXACT);
			if (materializationSurface.isPresent()) {
				var surface = materializationSurface.orElseThrow();
				exactMaterializationAccessRows = exactSurfaceWork(surface);
				exactMaterializationBuildRows = surface.surfaceRows();
				materializationScannedRows = surface.scannedRows();
				appliedScope = "probe+materialization";
			}
		}
		return new ExactSemiAntiRefinement(
				true,
				"applied",
				appliedScope,
				exactStreamingAccessRows,
				exactMemoizedAccessRows,
				exactMaterializationAccessRows,
				exactMaterializationBuildRows,
				streamingSurface.orElseThrow().scannedRows(),
				memoizedSurface.orElseThrow().scannedRows(),
				materializationScannedRows);
	}

	private ExactRelationResult exactCorrelationRelation(FrontierCorrelationDomain domain) {
		if (domain.exactRelation() != null) {
			return new ExactRelationResult(domain.exactRelation(), "");
		}
		FrontierPrimitiveCorrelationRelation primitive = domain.primitiveRelation();
		if (primitive == null || primitive.size() > MAX_EXACT_CORRELATION_ROWS) {
			return new ExactRelationResult(null, "row-budget");
		}
		double rows = 0.0d;
		Map<List<Value>, Double> frequencies = new LinkedHashMap<>();
		try {
			for (int row = 0; row < primitive.size(); row++) {
				double multiplicity = primitive.multiplicity(row);
				if (!Double.isFinite(multiplicity) || multiplicity <= 0.0d
						|| multiplicity != Math.rint(multiplicity)
						|| rows + multiplicity > MAX_EXACT_CORRELATION_ROWS) {
					return new ExactRelationResult(null, "row-budget");
				}
				List<Value> tuple = new ArrayList<>(primitive.width());
				for (int column = 0; column < primitive.width(); column++) {
					long termId = primitive.termId(row, column);
					Value value = termId == 0L ? null : frontierValue(termId);
					if (termId != 0L && value == null) {
						return new ExactRelationResult(null, "unresolved-term");
					}
					tuple.add(value);
				}
				frequencies.merge(Collections.unmodifiableList(tuple), multiplicity, Double::sum);
				rows += multiplicity;
			}
		} catch (IOException failure) {
			return new ExactRelationResult(null, "value-resolution-failed");
		}
		return new ExactRelationResult(
				FiniteRelationEstimate.fromFrequencies(
						domain.bindingNames(), frequencies, "lmdb-frontier-correlation"),
				"");
	}

	private static FiniteRelationEstimate distinctRelation(FiniteRelationEstimate relation) {
		Map<List<Value>, Double> frequencies = new LinkedHashMap<>();
		for (List<Value> tuple : relation.frequencies().keySet()) {
			frequencies.put(tuple, 1.0d);
		}
		return FiniteRelationEstimate.fromFrequencies(
				relation.variables(), frequencies, relation.source() + "-distinct");
	}

	private static double exactSurfaceWork(LmdbFiniteJoinSurfaceEstimator.SurfaceEstimate surface) {
		return Math.max(surface.prefixRows(), surface.scannedRows());
	}

	private static double firstMatchWorkRows(double exhaustionWorkRows, double expectedOutputRows) {
		if (!(exhaustionWorkRows > 0.0d)) {
			return 0.0d;
		}
		if (!(expectedOutputRows > 0.0d)) {
			return exhaustionWorkRows;
		}
		return Math.min(exhaustionWorkRows,
				Math.max(Math.min(1.0d, exhaustionWorkRows), exhaustionWorkRows / Math.max(1.0d, expectedOutputRows)));
	}

	private static double scaledFirstMatchObjective(double exhaustionObjective, double firstMatchWork,
			double exhaustionWork) {
		if (!(exhaustionObjective > 0.0d) || !(exhaustionWork > 0.0d)) {
			return 0.0d;
		}
		return saturatedMultiply(exhaustionObjective,
				Math.max(0.0d, Math.min(1.0d, firstMatchWork / exhaustionWork)));
	}

	private static double equivalentExhaustionInvocations(double matchedInvocations, double unmatchedInvocations,
			double firstMatchWork, double exhaustionWork) {
		if (!(exhaustionWork > 0.0d)) {
			return saturatedAdd(matchedInvocations, unmatchedInvocations);
		}
		return saturatedAdd(unmatchedInvocations,
				saturatedMultiply(matchedInvocations,
						Math.max(0.0d, Math.min(1.0d, firstMatchWork / exhaustionWork))));
	}

	private static int semiAntiMemoCapacity() {
		String configured = System.getProperty(SEMI_ANTI_MEMO_CAPACITY_PROPERTY);
		if (configured != null) {
			try {
				return Math.max(1, Integer.parseInt(configured));
			} catch (NumberFormatException ignored) {
				// Retain the bounded default for malformed optional tuning input.
			}
		}
		return DEFAULT_SEMI_ANTI_MEMO_CAPACITY;
	}

	private static MemoizedProbeCounts memoizedProbeCounts(double outerRows, double distinctProbeKeys,
			double matchedDistinctProbeKeys, double unmatchedDistinctProbeKeys, double hitProbability,
			int capacity) {
		double boundedOuterRows = Math.max(0.0d, outerRows);
		double distinctKeys = Math.min(boundedOuterRows, Math.max(0.0d, distinctProbeKeys));
		double cacheRows = Math.min(distinctKeys, Math.max(1, capacity));
		double repeatedRows = Math.max(0.0d, boundedOuterRows - distinctKeys);
		double retainedFraction = distinctKeys > 0.0d ? cacheRows / distinctKeys : 0.0d;
		double cacheHits = saturatedMultiply(repeatedRows, retainedFraction);
		double repeatedMisses = Math.max(0.0d, repeatedRows - cacheHits);
		double cacheMisses = saturatedAdd(distinctKeys, repeatedMisses);
		double cacheEvictions = Math.max(0.0d, cacheMisses - cacheRows);
		double initialMatchedMisses = Math.min(distinctKeys, Math.max(0.0d, matchedDistinctProbeKeys));
		double initialUnmatchedMisses = Math.min(
				Math.max(0.0d, distinctKeys - initialMatchedMisses),
				Math.max(0.0d, unmatchedDistinctProbeKeys));
		double unclassifiedInitial = Math.max(0.0d,
				distinctKeys - initialMatchedMisses - initialUnmatchedMisses);
		double matchedMisses = saturatedAdd(initialMatchedMisses,
				saturatedMultiply(saturatedAdd(unclassifiedInitial, repeatedMisses), hitProbability));
		matchedMisses = Math.min(cacheMisses, matchedMisses);
		double unmatchedMisses = Math.max(0.0d, cacheMisses - matchedMisses);
		return new MemoizedProbeCounts(boundedOuterRows, distinctKeys, matchedMisses, unmatchedMisses,
				cacheHits, cacheMisses, cacheEvictions, cacheRows);
	}

	private static void stampDependentCostComponents(PackedCostEstimate output, int selectedAlgorithm,
			DependentReopenCost dependent, double outerRows, double hitProbability,
			double streamingFirstMatchWork, double streamingExhaustionWork,
			double memoizedFirstMatchWork, double memoizedExhaustionWork,
			MemoizedProbeCounts memoizedCounts, double materializationPartitions,
			double materializationBuildWork, double materializationMemoryRows,
			double streamingObjective, double memoizedObjective, double materializedObjective) {
		double outputWork = finiteNonNegative(output.outputRows()) ? output.outputRows() : 0.0d;
		double startupOnce = dependent.required() ? dependent.startupOnceObjectiveCost() : 0.0d;
		double objective;
		switch (selectedAlgorithm) {
		case PackedQueryView.SEMI_ANTI_STREAMING -> {
			output.setDependentCostComponents(startupOnce, outerRows, hitProbability,
					streamingFirstMatchWork, streamingExhaustionWork,
					dependent.required() ? 0.0d : 1.0d, dependent.required() ? 0.0d : 1.0d,
					outputWork, outerRows, 0.0d, outerRows, 0.0d, 0.0d, 0.0d, 0.0d);
			objective = streamingObjective;
		}
		case PackedQueryView.SEMI_ANTI_MEMOIZED -> {
			output.setDependentCostComponents(startupOnce, outerRows, hitProbability,
					memoizedFirstMatchWork, memoizedExhaustionWork,
					dependent.required() ? 0.0d : 1.0d, 1.0d, outputWork,
					memoizedCounts.distinctKeyMisses(), memoizedCounts.cacheHits(),
					memoizedCounts.cacheMisses(), memoizedCounts.cacheEvictions(),
					0.0d, 0.0d, 0.0d);
			objective = memoizedObjective;
		}
		case PackedQueryView.SEMI_ANTI_MATERIALIZED -> {
			output.setDependentCostComponents(startupOnce, outerRows, hitProbability,
					0.0d, 0.0d, 0.0d, 0.0d, outputWork,
					0.0d, 0.0d, 0.0d, 0.0d, materializationPartitions, outerRows, 0.0d);
			output.putPlannedDoubleMetric("optimizer.dependentMaterializationBuildWork",
					materializationBuildWork);
			output.putPlannedDoubleMetric("optimizer.dependentMaterializationMemoryRows",
					materializationMemoryRows);
			objective = materializedObjective;
		}
		default -> throw new IllegalStateException("unknown packed semi/anti algorithm " + selectedAlgorithm);
		}
		double probeExecutions = selectedAlgorithm == PackedQueryView.SEMI_ANTI_MATERIALIZED
				? 0.0d
				: selectedAlgorithm == PackedQueryView.SEMI_ANTI_MEMOIZED
						? memoizedCounts.cacheMisses()
						: outerRows;
		double predictedFirstMatchSum = saturatedMultiply(
				saturatedMultiply(probeExecutions, hitProbability), output.firstMatchWork());
		double predictedExhaustionSum = saturatedMultiply(
				saturatedMultiply(probeExecutions, 1.0d - hitProbability), output.exhaustionWork());
		output.putPlannedDoubleMetric("optimizer.dependentFirstMatchPredictedSum", predictedFirstMatchSum);
		output.putPlannedDoubleMetric("optimizer.dependentExhaustionPredictedSum", predictedExhaustionSum);
		output.putPlannedDoubleMetric("optimizer.dependentFirstMatchAppliedSum", predictedFirstMatchSum);
		output.putPlannedDoubleMetric("optimizer.dependentExhaustionAppliedSum", predictedExhaustionSum);
		output.setObjectiveInterval(objective, objective, objective);
	}

	private double semiAntiStreamingObjective(JoinFactorCostModel.FactorCostEstimate probeFactor,
			double accessRows, double outerRows, double hitProbability, double firstMatchWork,
			double exhaustionWork, double resultRows, DependentReopenCost dependentReopenCost) {
		if (dependentReopenCost.required()) {
			double firstMatchObjective = scaledFirstMatchObjective(
					dependentReopenCost.nonStartupObjectiveCost(), firstMatchWork, exhaustionWork);
			double outputObjective = physicalCostObjective.score(
					null, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, resultRows, 0.0d);
			return PackedCostEstimate.streamingDependentCost(
					dependentReopenCost.startupOnceObjectiveCost(), outerRows, hitProbability,
					firstMatchObjective, dependentReopenCost.nonStartupObjectiveCost(),
					0.0d, 0.0d, outputObjective);
		}
		return physicalCostObjective.score(
				factorIndexName(probeFactor),
				accessRows,
				outerRows,
				outerRows,
				0.0d,
				0.0d,
				0.0d,
				0.0d,
				resultRows,
				0.0d);
	}

	private double semiAntiMemoizedObjective(JoinFactorCostModel.FactorCostEstimate probeFactor,
			double accessRows, MemoizedProbeCounts counts, double firstMatchWork, double exhaustionWork,
			double resultRows, DependentReopenCost dependentReopenCost) {
		if (dependentReopenCost.required()) {
			double firstMatchObjective = scaledFirstMatchObjective(
					dependentReopenCost.nonStartupObjectiveCost(), firstMatchWork, exhaustionWork);
			double outputObjective = physicalCostObjective.score(
					null, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, resultRows, 0.0d);
			return PackedCostEstimate.memoizedDependentCost(
					dependentReopenCost.startupOnceObjectiveCost(), counts.matchedMisses(),
					counts.unmatchedMisses(), firstMatchObjective,
					dependentReopenCost.nonStartupObjectiveCost(), counts.cacheHits(), 1.0d,
					counts.cacheEvictions(), 0.0d, 0.0d, 1.0d, outputObjective);
		}
		return physicalCostObjective.score(
				factorIndexName(probeFactor),
				accessRows,
				counts.cacheMisses(),
				counts.cacheMisses(),
				0.0d,
				0.0d,
				counts.outerRows(),
				0.0d,
				resultRows,
				0.0d);
	}

	private static void setReopenedDependentPhysicalCost(PackedCostEstimate output,
			DependentReopenCost dependent, double invocations, double cacheProbeRows, double cacheRows) {
		double startupFraction = dependent.objectiveCost() <= 0.0d
				? 0.0d
				: Math.max(0.0d, Math.min(1.0d,
						dependent.startupOnceObjectiveCost() / dependent.objectiveCost()));
		double physicalMultiplier = saturatedAdd(
				startupFraction, saturatedMultiply(1.0d - startupFraction, invocations));
		output.setLocalPhysicalCost(
				saturatedMultiply(dependent.sequentialRows(), physicalMultiplier),
				saturatedMultiply(dependent.randomSeeks(), physicalMultiplier),
				saturatedMultiply(dependent.iteratorOpens(), physicalMultiplier),
				saturatedMultiply(dependent.expressionEvaluations(), physicalMultiplier),
				saturatedMultiply(dependent.hashBuildRows(), physicalMultiplier),
				saturatedAdd(saturatedMultiply(dependent.hashProbeRows(), physicalMultiplier), cacheProbeRows),
				saturatedMultiply(dependent.pathExpansions(), physicalMultiplier),
				saturatedAdd(saturatedMultiply(dependent.resultRows(), physicalMultiplier), output.outputRows()),
				saturatedMultiply(dependent.remoteCalls(), physicalMultiplier),
				saturatedMaximum(dependent.peakMemoryRows(), cacheRows));
	}

	private double semiAntiMaterializedObjective(JoinFactorCostModel.FactorCostEstimate materializationFactor,
			double accessRows, double partitions, double buildRows, double outerRows, double resultRows) {
		return physicalCostObjective.score(
				factorIndexName(materializationFactor),
				accessRows,
				0.0d,
				accessRows == 0.0d ? 0.0d : partitions,
				0.0d,
				buildRows,
				outerRows,
				0.0d,
				resultRows,
				0.0d);
	}

	private static void annotateExactRefinement(PackedCostEstimate output, ExactSemiAntiRefinement refinement) {
		output.putPlannedStringMetric("plannedSemiAntiExactRefinementStatus", refinement.status());
		output.putPlannedStringMetric("plannedSemiAntiExactRefinement",
				refinement.status() + ":" + refinement.detail());
		if (!refinement.applied()) {
			output.putPlannedStringMetric("plannedSemiAntiExactRefinementDeclineReason", refinement.detail());
			return;
		}
		output.putPlannedDoubleMetric("plannedSemiAntiExactStreamingScannedRows",
				refinement.streamingScannedRows());
		output.putPlannedDoubleMetric("plannedSemiAntiExactMemoizedScannedRows",
				refinement.memoizedScannedRows());
		if (refinement.materializationScannedRows() >= 0L) {
			output.putPlannedDoubleMetric("plannedSemiAntiExactMaterializationScannedRows",
					refinement.materializationScannedRows());
		}
	}

	private static int bestSemiAntiAlgorithm(double streamingObjective, double memoizedObjective,
			double memoizedPeakRows, double materializedObjective, double materializedPeakRows) {
		long maximumMaterializedRows = MinusQueryEvaluationStep.maxMaterializedRightRows();
		double bestObjective = streamingObjective;
		int bestAlgorithm = PackedQueryView.SEMI_ANTI_STREAMING;
		if (memoizedPeakRows <= maximumMaterializedRows && memoizedObjective < bestObjective) {
			bestObjective = memoizedObjective;
			bestAlgorithm = PackedQueryView.SEMI_ANTI_MEMOIZED;
		}
		if (materializedPeakRows <= maximumMaterializedRows && materializedObjective < bestObjective) {
			bestAlgorithm = PackedQueryView.SEMI_ANTI_MATERIALIZED;
		}
		return bestAlgorithm;
	}

	private void applyScalarDifferencePhysicalCost(PackedCostContext context, double rawWorkRows,
			PackedCostEstimate output) {
		double leftRows = finiteNonNegative(context.leftInputRows())
				? context.leftInputRows()
				: Math.max(1.0d, output.outputRows());
		double rightRows = finiteNonNegative(context.rightInputRows())
				? context.rightInputRows()
				: 1.0d;
		output.setLocalPhysicalCost(
				0.0d,
				0.0d,
				rightRows == 0.0d ? 0.0d : 1.0d,
				leftRows,
				rightRows,
				leftRows,
				0.0d,
				output.outputRows(),
				0.0d,
				rightRows);
		output.putPlannedStringMetric("optimizer.filterAlgorithmHint", "materialized-hash");
		output.putPlannedStringMetric("optimizer.semiAntiAlgorithm", "materialized-hash");
		output.putPlannedStringMetric("optimizer.semiAntiKind", "minus-assured-shared");
		output.putPlannedStringMetric("plannedPhysicalImplementation", "materialized-minus-compatibility");
	}

	private void applyScalarSemiAntiPhysicalCost(int relationId, Filter filter, PackedCostContext context,
			double rawWorkRows, PackedCostEstimate output) {
		ExistsCondition existsCondition = pureExistsCondition(filter);
		boolean typed = query.isSemiJoin(relationId) || query.isAntiJoin(relationId);
		SemiAntiPlanIdentity planIdentity = semiAntiPlanIdentity(relationId, existsCondition, output);
		int semanticKind = planIdentity.semanticKind();
		int algorithm = planIdentity.algorithm();
		int rhsRelationId = typed ? query.semiAntiRightRelationId(relationId) : 0;
		TupleExpr rhs = typed
				? query.materializeRelation(rhsRelationId)
				: existsCondition.exists().getSubQuery();
		String[] correlationNames = typed
				? semiAntiCorrelationNames(relationId)
				: sharedCorrelationNames(filter.getArg().getBindingNames(), existsCondition.exists().getSubQuery());
		double rhsRows = typed
				? estimatedRelationRows(rhsRelationId)
				: estimatedTupleRows(existsCondition.exists().getSubQuery());
		rhsRows = Math.max(0.0d, rhsRows);
		SemiAntiBindingDomains bindingDomains = semiAntiBindingDomains(filter.getArg().getBindingNames(), rhs);
		JoinFactorCostModel.FactorCostEstimate probeFactor = candidateFactor(
				rhs, correlationNames, rhsRows)
						.filter(JoinFactorCostModel.FactorCostEstimate::hasPhysicalAccessPath)
						.orElse(null);
		JoinFactorCostModel.FactorCostEstimate materializationFactor = candidateFactor(
				rhs,
				bindingDomains.materializationParameterNames().toArray(String[]::new),
				rhsRows)
						.filter(JoinFactorCostModel.FactorCostEstimate::hasPhysicalAccessPath)
						.orElse(null);
		double probeWorkRows = factorWorkRows(probeFactor, rhsRows);
		double materializationWorkRows = factorWorkRows(materializationFactor, rhsRows);
		double materializationOutputRows = rhsRows;
		/*
		 * Without published context inputs the previous fallback was the filter's own output estimate — for an
		 * anti-join that is the post-filter cardinality, which a poisoned calibration can crush to ~1 and thereby
		 * charge the probe almost nothing. The filter's argument estimate is the honest invocation count.
		 */
		double outerRows = finiteNonNegative(context.leftInputRows())
				? context.leftInputRows()
				: semiAntiStructuralOuterRowsFloorEnabled()
						? Math.max(
								finiteNonNegative(output.outputRows()) ? output.outputRows() : 0.0d,
								Math.max(0.0d, typed && query.childCount(relationId) > 0
										? estimatedRelationRows(query.childRelationId(relationId, 0))
										: estimatedTupleRows(filter.getArg())))
						: finiteNonNegative(output.outputRows()) ? output.outputRows() : 1.0d;
		double conservativeOuterRows = Math.max(0.0d, outerRows);
		Optional<LmdbPackedCostModel.ExactSemiAntiOutcome> exactOutcome = lmdbCostModel.exactSemiAntiOutcome(
				query, context, rhs, semanticKind != PackedQueryView.SEMI_ANTI_EXISTS);
		if (exactOutcome.isPresent()) {
			LmdbPackedCostModel.ExactSemiAntiOutcome exact = exactOutcome.orElseThrow();
			output.setContextualOutputRowsPreservingPhysicalCost(exact.outputRows());
			output.setEvidenceGuarantee(EvidenceGuarantee.DATABASE_EXACT);
			output.putPlannedDoubleMetric("plannedCorrelationMatchedRows", exact.matchedRows());
			output.putPlannedDoubleMetric("plannedCorrelationUnmatchedRows",
					exact.outerRows() - exact.matchedRows());
			output.putPlannedDoubleMetric("plannedSemiAntiExactRhsResultRows", exact.rhsResultRows());
			output.putPlannedDoubleMetric("plannedSemiAntiExactScannedRows", exact.scannedRows());
		}
		double distinctLowerBound = conservativeOuterRows == 0.0d ? 0.0d : 1.0d;
		double distinctUpperBound = conservativeOuterRows;
		double materializationPartitions = bindingDomains.materializationParameterNames().isEmpty()
				? conservativeOuterRows == 0.0d ? 0.0d : 1.0d
				: distinctUpperBound;
		double materializationAccessRows = saturatedMultiply(
				materializationPartitions, materializationWorkRows);
		double materializationBuildRows = saturatedMultiply(
				materializationPartitions, materializationOutputRows);
		double breakEvenKeys = semiAntiBreakEvenDistinctKeys(
				materializationAccessRows + materializationBuildRows, probeWorkRows, distinctUpperBound);

		output.putPlannedDoubleMetric("plannedCorrelationOuterRows", conservativeOuterRows);
		output.putPlannedDoubleMetric("plannedCorrelationDistinctKeysLowerBound", distinctLowerBound);
		output.putPlannedDoubleMetric("plannedCorrelationDistinctKeysUpperBound", distinctUpperBound);
		output.putPlannedDoubleMetric("plannedCorrelationProbeWorkRows", probeWorkRows);
		output.putPlannedDoubleMetric("plannedSemiAntiProbeWorkRows", probeWorkRows);
		output.putPlannedDoubleMetric("plannedSemiAntiProbeOutputRows",
				factorOutputRows(probeFactor, rhsRows));
		output.putPlannedDoubleMetric("plannedSemiAntiMaterializationWorkRows", materializationAccessRows);
		output.putPlannedDoubleMetric("plannedSemiAntiMaterializationOutputRows", materializationBuildRows);
		output.putPlannedDoubleMetric("plannedSemiAntiMaterializationPartitions", materializationPartitions);
		output.putPlannedDoubleMetric("plannedSemiAntiBreakEvenDistinctKeys", breakEvenKeys);
		output.putPlannedStringMetric("plannedSemiAntiProbeBindingDomain",
				String.join(",", bindingDomains.probeNames()));
		output.putPlannedStringMetric("plannedSemiAntiHashBindingDomain",
				String.join(",", bindingDomains.sharedHashNames()));
		output.putPlannedStringMetric("plannedSemiAntiMaterializationParameterDomain",
				String.join(",", bindingDomains.materializationParameterNames()));
		annotateCandidateAccess(output, "Probe", probeFactor);
		annotateCandidateAccess(output, "Materialization", materializationFactor);
		if (exactOutcome.isPresent()) {
			output.putPlannedStringMetric("plannedSemiAntiExactRefinementStatus", "applied");
			output.putPlannedStringMetric("plannedSemiAntiExactRefinement", "applied:bounded-prefix-surface");
			output.putPlannedStringMetric("plannedCorrelationGuarantee", "database_exact");
			output.putPlannedStringMetric("plannedCorrelationConfidence", "1.0");
		} else {
			output.putPlannedStringMetric("plannedSemiAntiExactRefinementStatus", "declined");
			output.putPlannedStringMetric("plannedSemiAntiExactRefinement", "declined:no-frontier-domain");
			output.putPlannedStringMetric("plannedSemiAntiExactRefinementDeclineReason", "no-frontier-domain");
			output.putPlannedStringMetric("plannedCorrelationGuarantee", "scalar_fallback");
			output.putPlannedStringMetric("plannedCorrelationConfidence", "unknown");
		}
		switch (algorithm) {
		case PackedQueryView.SEMI_ANTI_STREAMING -> output.setLocalPhysicalCost(
				saturatedMultiply(conservativeOuterRows, probeWorkRows),
				conservativeOuterRows,
				conservativeOuterRows,
				0.0d,
				0.0d,
				0.0d,
				0.0d,
				output.outputRows(),
				0.0d,
				0.0d);
		case PackedQueryView.SEMI_ANTI_MEMOIZED -> output.setLocalPhysicalCost(
				saturatedMultiply(distinctUpperBound, probeWorkRows),
				distinctUpperBound,
				distinctUpperBound,
				0.0d,
				0.0d,
				conservativeOuterRows,
				0.0d,
				output.outputRows(),
				0.0d,
				distinctUpperBound);
		case PackedQueryView.SEMI_ANTI_MATERIALIZED -> output.setLocalPhysicalCost(
				materializationAccessRows,
				0.0d,
				materializationAccessRows == 0.0d ? 0.0d : materializationPartitions,
				0.0d,
				materializationBuildRows,
				conservativeOuterRows,
				0.0d,
				output.outputRows(),
				0.0d,
				materializationBuildRows);
		default -> throw new IllegalStateException("unknown packed semi/anti algorithm");
		}
		String algorithmName = semiAntiAlgorithmName(algorithm);
		output.putPlannedStringMetric("optimizer.filterAlgorithmHint", algorithmName);
		output.putPlannedStringMetric("optimizer.semiAntiAlgorithm", algorithmName);
		output.putPlannedStringMetric("optimizer.semiAntiKind", semiAntiPlanSemanticName(semanticKind));
		output.putPlannedStringMetric("plannedPhysicalImplementation",
				semanticKind == PackedQueryView.SEMI_ANTI_MINUS_ASSURED_SHARED
						&& algorithm == PackedQueryView.SEMI_ANTI_MATERIALIZED
								? "materialized-minus-compatibility"
								: algorithmName);
		applySemiAntiPhysicalFeedback(filter, semanticKind, algorithm, outerRows, output);
		applySemiAntiLeoPhysicalResidual(filter, algorithm, output);
		output.setDependentSubqueriesCosted(true);
	}

	private void applyScalarFilterPhysicalCost(int relationId, Filter filter, PackedCostContext context,
			double rawWorkRows, PackedCostEstimate output) {
		if (pureExistsCondition(filter) != null) {
			applyScalarSemiAntiPhysicalCost(relationId, filter, context, rawWorkRows, output);
		} else if (!applyScalarDependentExpressionPhysicalCost(filter, context, output)
				&& finiteNonNegative(context.leftInputRows())) {
			/*
			 * The scalar estimator reports FILTER result rows, but condition evaluation is performed over the complete
			 * input. Keep those two physical dimensions separate so a broad scan followed by a selective predicate is
			 * not priced as though only the surviving rows were inspected.
			 */
			setLocalOperatorPhysicalCost(
					output,
					finiteNonNegative(output.outputRows()) ? output.outputRows() : 0.0d,
					context.leftInputRows(),
					0.0d,
					0.0d,
					0.0d);
		}
	}

	private boolean applyScalarDependentExpressionPhysicalCost(Filter filter, PackedCostContext context,
			PackedCostEstimate output) {
		dependentExistsScratch.clear();
		filter.getCondition().visit(new AbstractQueryModelVisitor<RuntimeException>() {

			@Override
			public void meet(Exists exists) {
				dependentExistsScratch.add(exists);
			}
		});
		if (dependentExistsScratch.isEmpty()) {
			return false;
		}

		double outerRows = finiteNonNegative(context.leftInputRows())
				? context.leftInputRows()
				: finiteNonNegative(output.outputRows()) ? output.outputRows() : 1.0d;
		outerRows = Math.max(0.0d, outerRows);
		double sequentialRows = 0.0d;
		double randomSeeks = 0.0d;
		double iteratorOpens = 0.0d;
		double expressionEvaluations = outerRows;
		double resultRows = finiteNonNegative(output.outputRows()) ? output.outputRows() : 0.0d;
		double totalProbeWorkRows = 0.0d;
		for (Exists exists : dependentExistsScratch) {
			TupleExpr rhs = exists.getSubQuery();
			String[] correlationNames = sharedCorrelationNames(filter.getArg().getBindingNames(), rhs);
			if (correlationNames.length == 0) {
				return false;
			}
			var factor = lmdbCostModel.estimateCorrelatedFactor(rhs, correlationNames);
			if (factor.isEmpty() || !factor.orElseThrow().hasPhysicalAccessPath()) {
				return false;
			}
			double probeWorkRows = factor.orElseThrow().getWorkRows();
			if (!finiteNonNegative(probeWorkRows)) {
				return false;
			}
			probeWorkRows = Math.max(1.0d, probeWorkRows);
			totalProbeWorkRows = saturatedAdd(totalProbeWorkRows, probeWorkRows);
			sequentialRows = saturatedAdd(sequentialRows, saturatedMultiply(outerRows, probeWorkRows));
			randomSeeks = saturatedAdd(randomSeeks, outerRows);
			iteratorOpens = saturatedAdd(iteratorOpens, outerRows);
			expressionEvaluations = saturatedAdd(
					expressionEvaluations, saturatedMultiply(outerRows, probeWorkRows));
		}

		output.setLocalPhysicalCost(
				sequentialRows,
				randomSeeks,
				iteratorOpens,
				expressionEvaluations,
				0.0d,
				0.0d,
				0.0d,
				resultRows,
				0.0d,
				0.0d);
		output.putPlannedDoubleMetric("plannedDependentSubqueryCount", dependentExistsScratch.size());
		output.putPlannedDoubleMetric("plannedDependentSubqueryOuterRows", outerRows);
		output.putPlannedDoubleMetric("plannedDependentSubqueryProbeWorkRows", totalProbeWorkRows);
		output.putPlannedStringMetric("plannedPhysicalImplementation", "correlated-dependent-expressions");
		output.setDependentSubqueriesCosted(true);
		return true;
	}

	private double correlatedProbeWorkRows(TupleExpr rhs, String[] correlationNames, double fallbackRows) {
		return lmdbCostModel.estimateCorrelatedFactor(rhs, correlationNames)
				.filter(JoinFactorCostModel.FactorCostEstimate::hasPhysicalAccessPath)
				.map(JoinFactorCostModel.FactorCostEstimate::getWorkRows)
				.filter(LmdbFrontierPackedCostSession::finiteNonNegative)
				.map(workRows -> Math.max(1.0d, workRows))
				.orElse(fallbackRows);
	}

	private void applySemiAntiPhysicalFeedback(Filter filter, int semanticKind, int algorithm, double plannedOuterRows,
			PackedCostEstimate output) {
		if (output.evidenceStateId() != 0) {
			/*
			 * Frontier candidates consume the event-keyed, per-dimension posterior in LmdbFrontierLearningCostSession.
			 * Surface aggregates are retained for scalar failover and persistence compatibility, but must never
			 * overwrite an originating Frontier event with an unkeyed point estimate.
			 */
			return;
		}
		String semanticName = semiAntiFeedbackSemanticName(semanticKind);
		String algorithmName = semiAntiAlgorithmName(algorithm);
		LmdbOperatorFeedbackStats.SemiAntiEstimate feedback = runtime.semiAntiFeedback(
				filter, semanticName, algorithmName);
		if (feedback == null || feedback.observationCount() <= 0L
				|| feedback.physicalObservationCount() <= 0L || feedback.outerRows() <= 0L) {
			return;
		}
		boolean failoverGates = semiAntiFailoverGatesEnabled();
		if (failoverGates && (feedback.observationCount() < MINIMUM_LEO_EVIDENCE_COUNT
				|| feedback.physicalObservationCount() < MINIMUM_LEO_EVIDENCE_COUNT)) {
			// A surface replacement rewrites every physical dimension; a single aliased observation must not be
			// allowed to do that — mirror the ≥3-observation gate of the residual path below.
			return;
		}
		double outerScale = Math.max(0.0d, plannedOuterRows) / feedback.outerRows();
		double executionScale = 1.0d / feedback.observationCount();
		double physicalExecutionScale = 1.0d / feedback.physicalObservationCount();
		double physicalOuterRows = feedback.outerRows()
				* ((double) feedback.physicalObservationCount() / feedback.observationCount());
		boolean perExecutionBuild = algorithm == PackedQueryView.SEMI_ANTI_MATERIALIZED;
		double sourceScanScale = perExecutionBuild
				? physicalExecutionScale
				: Math.max(0.0d, plannedOuterRows) / physicalOuterRows;
		double sequentialRows = feedback.rhsSourceRowsScanned() * sourceScanScale;
		double scanScale = perExecutionBuild ? executionScale : outerScale;
		double iteratorOpens = feedback.iteratorOpens() * scanScale;
		double randomSeeks = algorithm == PackedQueryView.SEMI_ANTI_MATERIALIZED ? 0.0d : iteratorOpens;
		double hashBuildRows = feedback.hashBuildRows() * executionScale;
		double hashProbeRows = (feedback.hashProbeRows() + feedback.cacheLookups()) * outerScale;
		double peakMemoryRows = switch (algorithm) {
		case PackedQueryView.SEMI_ANTI_STREAMING -> 0.0d;
		case PackedQueryView.SEMI_ANTI_MEMOIZED -> Math.max(
				feedback.distinctKeys() * executionScale, hashBuildRows);
		case PackedQueryView.SEMI_ANTI_MATERIALIZED -> hashBuildRows;
		default -> throw new IllegalStateException("unknown packed semi/anti algorithm " + algorithm);
		};
		boolean[] clamped = { false };
		if (failoverGates) {
			// Bound each replacement to within 4^physicalObservations of the raw model value (mirroring the
			// frontier ln(4)-per-observation clamp); a raw value of 0 accepts the learned value outright since
			// streaming paths legitimately introduce dimensions from zero.
			double maxFactor = Math.pow(4.0d, Math.min(feedback.physicalObservationCount(), 8L));
			sequentialRows = clampToRawFactor(sequentialRows, output.sequentialRows(), maxFactor, clamped);
			randomSeeks = clampToRawFactor(randomSeeks, output.randomSeeks(), maxFactor, clamped);
			iteratorOpens = clampToRawFactor(iteratorOpens, output.iteratorOpens(), maxFactor, clamped);
			hashBuildRows = clampToRawFactor(hashBuildRows, output.hashBuildRows(), maxFactor, clamped);
			hashProbeRows = clampToRawFactor(hashProbeRows, output.hashProbeRows(), maxFactor, clamped);
			peakMemoryRows = clampToRawFactor(peakMemoryRows, output.peakMemoryRows(), maxFactor, clamped);
		}
		output.setLocalPhysicalCost(
				sequentialRows,
				randomSeeks,
				iteratorOpens,
				Math.max(0.0d, plannedOuterRows),
				hashBuildRows,
				hashProbeRows,
				output.pathExpansions(),
				output.resultRows(),
				output.remoteCalls(),
				peakMemoryRows);
		if (clamped[0]) {
			output.putPlannedDoubleMetric("plannedSemiAntiFeedbackClamped", 1.0d);
		}
		output.putPlannedDoubleMetric("plannedSemiAntiFeedbackEvidence", feedback.observationCount());
		output.putPlannedDoubleMetric("plannedSemiAntiFeedbackOuterRows", feedback.outerRows());
		output.putPlannedDoubleMetric("plannedSemiAntiFeedbackDistinctKeys", feedback.distinctKeys());
		output.putPlannedDoubleMetric("plannedSemiAntiFeedbackRowsExamined", feedback.rhsRowsExamined());
		output.putPlannedDoubleMetric("plannedSemiAntiFeedbackPhysicalEvidence",
				feedback.physicalObservationCount());
		output.putPlannedDoubleMetric("plannedSemiAntiFeedbackSourceRowsScanned",
				feedback.rhsSourceRowsScanned());
		output.putPlannedDoubleMetric("plannedSemiAntiFeedbackExhaustedFailures", feedback.exhaustedFailures());
		output.putPlannedStringMetric("plannedSemiAntiFeedbackSource", "completed-key-outcomes+source-scans");
	}

	private void applySemiAntiLeoPhysicalResidual(Filter filter, int algorithm, PackedCostEstimate output) {
		if (output.evidenceStateId() != 0) {
			// Frontier observations are calibrated by independent event-keyed dimensions after this raw transition.
			return;
		}
		double baseWorkRows = output.workRows();
		if (!finiteNonNegative(baseWorkRows) || baseWorkRows == 0.0d) {
			return;
		}
		String algorithmName = semiAntiAlgorithmName(algorithm);
		LmdbOperatorFeedbackStats.OperatorEstimate feedback = runtime.operatorMultiplierFeedback(
				filter, output.outputRows(), baseWorkRows, algorithmName);
		if (!qualifiedLeoCorrection(feedback)) {
			return;
		}
		double factor = feedback.workRows() / baseWorkRows;
		if (!finiteNonNegative(factor)) {
			return;
		}
		output.setLocalPhysicalCost(
				saturatedMultiply(output.sequentialRows(), factor),
				saturatedMultiply(output.randomSeeks(), factor),
				saturatedMultiply(output.iteratorOpens(), factor),
				saturatedMultiply(output.expressionEvaluations(), factor),
				saturatedMultiply(output.hashBuildRows(), factor),
				saturatedMultiply(output.hashProbeRows(), factor),
				saturatedMultiply(output.pathExpansions(), factor),
				output.resultRows(),
				saturatedMultiply(output.remoteCalls(), factor),
				output.peakMemoryRows());
		output.putPlannedDoubleMetric("plannedSemiAntiLeoPhysicalFactor", factor);
		output.putPlannedDoubleMetric("plannedSemiAntiLeoPhysicalEvidence", feedback.evidenceCount());
		output.putPlannedDoubleMetric(
				"plannedSemiAntiLeoPhysicalConfidence", feedback.correctionConfidence());
		output.putPlannedStringMetric("plannedSemiAntiLeoPhysicalSource", feedback.source());
	}

	private static String semiAntiFeedbackSemanticName(int semanticKind) {
		return switch (semanticKind) {
		case PackedQueryView.SEMI_ANTI_EXISTS -> "EXISTS";
		case PackedQueryView.SEMI_ANTI_NOT_EXISTS -> "NOT_EXISTS";
		case PackedQueryView.SEMI_ANTI_MINUS_ASSURED_SHARED -> "MINUS_ASSURED_SHARED";
		default -> throw new IllegalStateException("unknown packed semi/anti semantic kind " + semanticKind);
		};
	}

	private static String semiAntiAlgorithmName(int algorithm) {
		return switch (algorithm) {
		case PackedQueryView.SEMI_ANTI_STREAMING -> "streaming-correlated";
		case PackedQueryView.SEMI_ANTI_MEMOIZED -> "memoized-correlated";
		case PackedQueryView.SEMI_ANTI_MATERIALIZED -> "materialized-hash";
		default -> throw new IllegalStateException("unknown packed semi/anti algorithm " + algorithm);
		};
	}

	private static int semiAntiAlgorithm(String algorithmName, int fallback) {
		return switch (algorithmName == null ? "" : algorithmName) {
		case "streaming-correlated" -> PackedQueryView.SEMI_ANTI_STREAMING;
		case "memoized-correlated" -> PackedQueryView.SEMI_ANTI_MEMOIZED;
		case "materialized-hash" -> PackedQueryView.SEMI_ANTI_MATERIALIZED;
		default -> fallback;
		};
	}

	private SemiAntiPlanIdentity semiAntiPlanIdentity(
			int relationId, ExistsCondition condition, PackedCostEstimate output) {
		if (query.isSemiJoin(relationId) || query.isAntiJoin(relationId)) {
			return new SemiAntiPlanIdentity(
					query.semiAntiKind(relationId), query.semiAntiAlgorithm(relationId));
		}
		boolean safeMinusAlternative = condition.negated() && query.isAssuredSharedMinusFilter(relationId);
		if (safeMinusAlternative) {
			return new SemiAntiPlanIdentity(
					PackedQueryView.SEMI_ANTI_MINUS_ASSURED_SHARED,
					semiAntiAlgorithm(
							output.plannedStringMetric("optimizer.semiAntiAlgorithm"),
							PackedQueryView.SEMI_ANTI_STREAMING));
		}
		return new SemiAntiPlanIdentity(
				condition.negated()
						? PackedQueryView.SEMI_ANTI_NOT_EXISTS
						: PackedQueryView.SEMI_ANTI_EXISTS,
				PackedQueryView.SEMI_ANTI_STREAMING);
	}

	private static String semiAntiPlanSemanticName(int semanticKind) {
		return switch (semanticKind) {
		case PackedQueryView.SEMI_ANTI_EXISTS -> "exists";
		case PackedQueryView.SEMI_ANTI_NOT_EXISTS -> "not-exists";
		case PackedQueryView.SEMI_ANTI_MINUS_ASSURED_SHARED -> "minus-assured-shared";
		default -> throw new IllegalStateException("unknown packed semi/anti semantic kind " + semanticKind);
		};
	}

	private FrontierSemiAntiProfile correlationProfile(EvidenceStateRef input, EvidenceStateRef outputEvidence,
			SemiAntiBindingDomains bindingDomains, int rhsRelationId, int semanticKind,
			double structuralOuterRows, double factOuterRowsFloor) {
		CorrelationProfileKey key = new CorrelationProfileKey(
				input.stateId(), outputEvidence.stateId(), rhsRelationId, semanticKind, bindingDomains.cacheKey(),
				structuralOuterRows, factOuterRowsFloor);
		FrontierSemiAntiProfile existing = correlationProfiles.get(key);
		if (existing != null) {
			return existing;
		}
		FrontierCorrelationDomain probeDomain = correlationDomain(input, bindingDomains.probeNames());
		FrontierCorrelationDomain outputProbeDomain = correlationDomain(outputEvidence, bindingDomains.probeNames());
		FrontierCorrelationDomain sharedHashDomain = correlationDomain(input, bindingDomains.sharedHashNames());
		FrontierCorrelationDomain materializationParameterDomain = correlationDomain(
				input, bindingDomains.materializationParameterNames());
		EvidenceStateSummary inputSummary = input.summary();
		double evidenceOuterRows = inputSummary.pointRows();
		double outerRows = evidenceOuterRows;
		String outerRowsSource = FrontierSemiAntiProfile.OUTER_ROWS_SOURCE_FRONTIER_EVIDENCE;
		if (semiAntiStructuralOuterRowsFloorEnabled()) {
			// The interval must actually constrain: a heuristic interval carries [0, inf) and vouches for nothing.
			boolean authoritativeInput = isComposableState(input)
					&& (inputSummary.lowerRows() > 0.0d || Double.isFinite(inputSummary.upperRows()));
			if (authoritativeInput) {
				outerRows = Math.min(
						Math.max(evidenceOuterRows, inputSummary.lowerRows()), inputSummary.upperRows());
			} else if (finiteNonNegative(structuralOuterRows) && structuralOuterRows > outerRows) {
				outerRows = structuralOuterRows;
				outerRowsSource = FrontierSemiAntiProfile.OUTER_ROWS_SOURCE_STRUCTURAL_FLOOR;
			}
		}
		if (finiteNonNegative(factOuterRowsFloor) && factOuterRowsFloor > outerRows) {
			outerRows = factOuterRowsFloor;
			outerRowsSource = FrontierSemiAntiProfile.OUTER_ROWS_SOURCE_EXACT_FACT_FLOOR;
		}
		double evidenceOutputRows = Math.min(evidenceOuterRows, outputEvidence.summary().pointRows());
		/*
		 * The output evidence shares lineage with the distrusted input, so when the floor rescales the invocation count
		 * the outcome masses keep the evidence's survival ratio instead of its absolute row count — otherwise a floored
		 * anti-join would claim that every added outer row is eliminated by the probe.
		 */
		double outputRows = outerRows == evidenceOuterRows || !(evidenceOuterRows > 0.0d)
				? evidenceOutputRows
				: Math.min(1.0d, evidenceOutputRows / evidenceOuterRows) * outerRows;
		boolean anti = semanticKind != PackedQueryView.SEMI_ANTI_EXISTS;
		double matchedRows = anti ? outerRows - outputRows : outputRows;
		double unmatchedRows = anti ? outputRows : outerRows - outputRows;
		double matchedDistinctKeys = Double.NaN;
		double unmatchedDistinctKeys = Double.NaN;
		if (Double.isFinite(probeDomain.distinctKeyEstimate())
				&& Double.isFinite(outputProbeDomain.distinctKeyEstimate())) {
			double retainedOutputKeys = Math.min(
					probeDomain.distinctKeyEstimate(), outputProbeDomain.distinctKeyEstimate());
			if (anti) {
				unmatchedDistinctKeys = retainedOutputKeys;
				matchedDistinctKeys = probeDomain.distinctKeyEstimate() - retainedOutputKeys;
			} else {
				matchedDistinctKeys = retainedOutputKeys;
				unmatchedDistinctKeys = probeDomain.distinctKeyEstimate() - retainedOutputKeys;
			}
		}
		FrontierSemiAntiProfile profile = new FrontierSemiAntiProfile(
				outerRows,
				evidenceOuterRows,
				outerRowsSource,
				Math.max(0.0d, matchedRows),
				Math.max(0.0d, unmatchedRows),
				Math.max(0.0d, matchedDistinctKeys),
				Math.max(0.0d, unmatchedDistinctKeys),
				probeDomain,
				sharedHashDomain,
				materializationParameterDomain,
				probeDomain.guarantee(),
				Math.min(inputSummary.confidence(), probeDomain.confidence()));
		correlationProfiles.put(key, profile);
		return profile;
	}

	private FrontierCorrelationDomain correlationDomain(EvidenceStateRef state, List<String> bindingNames) {
		String[] names = bindingNames.toArray(String[]::new);
		CorrelationDomainKey key = new CorrelationDomainKey(state.stateId(), String.join("\u0000", names));
		FrontierCorrelationDomain existing = correlationDomains.get(key);
		if (existing != null) {
			return existing;
		}
		FrontierLayout layout = arena.layout(state);
		int[] correlationSlots = correlationSlots(layout, names);
		if (correlationSlots == null) {
			FrontierCorrelationDomain domain = missingCorrelationDomain(state, bindingNames);
			correlationDomains.put(key, domain);
			return domain;
		}
		EvidenceStateSummary summary = state.summary();
		if (arena.payloadStatus(state) != FrontierPayloadStatus.RESIDENT) {
			double rows = summary.pointRows();
			boolean emptyKey = correlationSlots.length == 0;
			boolean exactEmpty = summary.guarantee() == EvidenceGuarantee.DATABASE_EXACT && rows == 0.0d;
			double distinctKeys = emptyKey
					? rows == 0.0d ? 0.0d : 1.0d
					: exactEmpty ? 0.0d : Double.NaN;
			double distinctUpperBound = Double.isFinite(distinctKeys)
					? distinctKeys
					: Math.max(0.0d, rows);
			double fanoutMean = distinctUpperBound == 0.0d ? 0.0d : rows / distinctUpperBound;
			FrontierCorrelationDomain domain = new FrontierCorrelationDomain(
					state.stateId(),
					bindingNames,
					rows,
					Double.isFinite(distinctKeys) ? distinctKeys : 0.0d,
					distinctKeys,
					distinctUpperBound,
					fanoutMean,
					rows,
					summary.guarantee(),
					summary.confidence(),
					null,
					null);
			correlationDomains.put(key, domain);
			return domain;
		}
		PrimitiveCorrelationKeyTable keys;
		double retainedRows = 0.0d;
		try (FrontierPayloadLease payload = arena.openPayload(state)) {
			keys = new PrimitiveCorrelationKeyTable(payloadEntryCount(payload), correlationSlots.length);
			long[] tuple = new long[correlationSlots.length];
			for (int stratum = 0; stratum < payload.stratumCount(); stratum++) {
				for (int index = 0; index < payload.exactCount(stratum); index++) {
					fillCorrelationTuple(payload, true, stratum, index, correlationSlots, tuple);
					double weight = payload.exactWeight(stratum, index);
					keys.add(tuple, weight);
					retainedRows += weight;
				}
				for (int index = 0; index < payload.residualCount(stratum); index++) {
					fillCorrelationTuple(payload, false, stratum, index, correlationSlots, tuple);
					double weight = payload.residualWeight(stratum, index);
					keys.add(tuple, weight);
					retainedRows += weight;
				}
			}
		}
		double retainedKeys = keys.size();
		boolean exact = summary.guarantee() == EvidenceGuarantee.DATABASE_EXACT;
		double lineageUpperBound = exact ? retainedKeys : exactCorrelationKeyUpperBound(state, names, 0);
		boolean exactRetainedDomain = Double.isFinite(lineageUpperBound) && retainedKeys == lineageUpperBound;
		/*
		 * Coalesced Frontier tuples are the query-local distinct-key estimate even when their row masses are sampled.
		 * Keep the independently certified upper bound alongside that estimate; exact refinement still requires a
		 * database-exact guarantee.
		 */
		double distinctEstimate = retainedKeys > 0.0d || summary.pointRows() == 0.0d
				? retainedKeys
				: Double.NaN;
		double distinctUpperBound = exact
				? retainedKeys
				: Double.isFinite(lineageUpperBound)
						? Math.max(retainedKeys, lineageUpperBound)
						: Math.max(retainedKeys, summary.pointRows());
		double fanoutMean = retainedKeys == 0.0d ? 0.0d : retainedRows / retainedKeys;
		FrontierCorrelationDomain domain = new FrontierCorrelationDomain(
				state.stateId(),
				bindingNames,
				summary.pointRows(),
				retainedKeys,
				distinctEstimate,
				distinctUpperBound,
				fanoutMean,
				keys.maximumMass(),
				summary.guarantee(),
				summary.confidence(),
				keys.relation(),
				null);
		correlationDomains.put(key, domain);
		return domain;
	}

	private FrontierCorrelationDomain missingCorrelationDomain(EvidenceStateRef state, List<String> bindingNames) {
		EvidenceStateSummary summary = state.summary();
		double rows = summary.pointRows();
		double distinctUpperBound = summary.certifiedUpperBound();
		EvidenceGuarantee guarantee = EvidenceGuarantee.CERTIFIED_BOUND_ONLY;
		if (!Double.isFinite(distinctUpperBound)) {
			distinctUpperBound = summary.upperRows();
		}
		if (!Double.isFinite(distinctUpperBound)) {
			distinctUpperBound = Double.POSITIVE_INFINITY;
			guarantee = EvidenceGuarantee.UNRESOLVED;
		}
		if (rows == 0.0d && summary.zeroStatus() == EvidenceZeroStatus.EXACT_ZERO) {
			distinctUpperBound = 0.0d;
			guarantee = EvidenceGuarantee.DATABASE_EXACT;
		}
		return new FrontierCorrelationDomain(
				state.stateId(),
				bindingNames,
				rows,
				0.0d,
				Double.NaN,
				distinctUpperBound,
				0.0d,
				rows,
				guarantee,
				0.0d,
				null,
				null);
	}

	private FrontierFactorSurfaceRefinement refineFactorAccessSurface(EvidenceStateRef input,
			EvidenceStateRef outputState, FrontierStateKey outputKey, int relationId, PackedCostContext context,
			PackedCostEstimate output) {
		if (!query.isStatementPattern(relationId)) {
			return FrontierFactorSurfaceRefinement.declined("unsupported-access-kernel");
		}
		if (input.summary().guarantee() != EvidenceGuarantee.DATABASE_EXACT || !isComposableState(input)) {
			return FrontierFactorSurfaceRefinement.declined("input-not-database-exact");
		}
		List<String> bindingNames = factorInputBindingNames(input, relationId);
		if (bindingNames.isEmpty()) {
			return FrontierFactorSurfaceRefinement.declined("uncorrelated-factor");
		}
		FrontierCorrelationDomain domain = correlationDomain(input, bindingNames);
		if (!domain.hasExactDistinctKeys()) {
			return FrontierFactorSurfaceRefinement.declined("distinct-domain-not-exact");
		}
		ExactRelationResult relationResult = exactCorrelationRelation(domain);
		FiniteRelationEstimate relation = relationResult.relation();
		if (relation == null) {
			return FrontierFactorSurfaceRefinement.declined(relationResult.declineReason());
		}
		if (!fullyBound(relation)) {
			return FrontierFactorSurfaceRefinement.declined("nullable-binding-domain");
		}
		List<String> inputBindingNames = List.of(layoutVariables(arena.layout(input)));
		FiniteRelationEstimate correlatedRelation = relation;
		if (!relation.containsAll(inputBindingNames)) {
			ExactRelationResult inputRelationResult = exactCorrelationRelation(
					correlationDomain(input, inputBindingNames));
			correlatedRelation = inputRelationResult.relation();
			if (correlatedRelation == null) {
				return FrontierFactorSurfaceRefinement.declined(
						"complete-input-" + inputRelationResult.declineReason());
			}
			if (Double.compare(correlatedRelation.rows(), input.summary().pointRows()) != 0) {
				throw new IllegalStateException("database-exact Frontier input relation has inconsistent row mass");
			}
		}
		CorrelationSurfaceCacheIdentity identity = new CorrelationSurfaceCacheIdentity(
				input.stateId(), String.join("\u0000", bindingNames), "factor-access:" + relationId);
		var estimated = runtime.exactCorrelatedSurface(
				identity, correlatedRelation, query.materializeRelation(relationId),
				JoinFactorCostModel.EstimationTier.DECISION_EXACT);
		if (estimated.isEmpty()) {
			return FrontierFactorSurfaceRefinement.declined("surface-budget-or-kernel");
		}
		LmdbFiniteJoinSurfaceEstimator.SurfaceEstimate surface = estimated.orElseThrow();
		if (!finiteNonNegative(surface.surfaceRows())
				|| !finiteNonNegative(surface.prefixRows())
				|| Double.compare(surface.prefixRows(), input.summary().pointRows()) != 0) {
			return FrontierFactorSurfaceRefinement.declined("surface-prefix-mismatch");
		}
		double resultRows = outputState.summary().guarantee() == EvidenceGuarantee.DATABASE_EXACT
				? outputState.summary().pointRows()
				: surface.surfaceRows();
		boolean applied = lmdbCostModel.applyFrontierCorrelatedAccess(
				query,
				relationId,
				bindingNames,
				resultRows,
				surface.prefixRows(),
				domain.distinctKeyEstimate(),
				String.join(",", bindingNames),
				surface.cardinalityProbes(),
				output);
		if (!applied) {
			return FrontierFactorSurfaceRefinement.declined("invalid-surface");
		}
		EvidenceStateRef retainedState = surface.exact()
				? retainMeasuredExactSurface(input, outputKey, relationId, surface, output)
				: outputState;
		return FrontierFactorSurfaceRefinement.applied(
				surface.exact() ? "materialized-exact" : "bounded-probe",
				retainedState == null ? outputState : retainedState);
	}

	private EvidenceStateRef recoverExactDerivedSurface(EvidenceStateRef input, FrontierStateKey outputKey,
			int relationId, PackedCostContext context, PackedCostEstimate output) {
		LmdbFiniteJoinSurfaceEstimator.SurfaceEstimate surface = lmdbCostModel
				.exactDerivedSurface(query, relationId, context)
				.orElse(null);
		if (surface == null) {
			output.putPlannedStringMetric("plannedFrontierExactSurfaceStateRecovery", "declined:surface-unavailable");
			return null;
		}
		return retainMeasuredExactSurface(input, outputKey, relationId, surface, output);
	}

	private EvidenceStateRef retainMeasuredExactSurface(EvidenceStateRef input, FrontierStateKey outputKey,
			int relationId, LmdbFiniteJoinSurfaceEstimator.SurfaceEstimate surface, PackedCostEstimate output) {
		if (!surface.exact()) {
			output.putPlannedStringMetric("plannedFrontierExactSurfaceStateRecovery", "declined:surface-not-exact");
			return null;
		}
		FiniteRelationEstimate relation = surface.relation();
		if (relation == null) {
			output.putPlannedStringMetric("plannedFrontierExactSurfaceStateRecovery", "declined:relation-unavailable");
			return null;
		}
		if (Double.compare(surface.surfaceRows(), relation.rows()) != 0) {
			output.putPlannedStringMetric("plannedFrontierExactSurfaceStateRecovery", "declined:row-mismatch");
			return null;
		}
		String missingBinding = missingOutputBinding(outputKey.frontier(), relation);
		if (missingBinding != null) {
			output.putPlannedStringMetric("plannedFrontierExactSurfaceStateRecovery",
					"declined:missing-binding:" + missingBinding);
			return null;
		}
		if (!relation.frequencies().isEmpty() && settings.refinementWorkUnits() == 0L) {
			output.putPlannedStringMetric("plannedFrontierExactSurfaceStateRecovery",
					"declined:retention-budget-exhausted");
			return null;
		}
		EvidenceStateRef recovered = materializeDerivedSurface(input, outputKey, relationId, relation);
		if (recovered != null) {
			output.putPlannedStringMetric("plannedFrontierExactSurfaceStateRecovery",
					recovered.summary().guarantee() == EvidenceGuarantee.DATABASE_EXACT
							? "inline-exact"
							: "deterministic-weighted-sample");
			output.putPlannedDoubleMetric(
					"plannedFrontierExactSurfaceStateRows", recovered.summary().pointRows());
		}
		return recovered;
	}

	private static String missingOutputBinding(FrontierLayout outputLayout, FiniteRelationEstimate relation) {
		for (int slot = 0; slot < outputLayout.size(); slot++) {
			String bindingName = outputLayout.variable(slot);
			if (!relation.variables().contains(bindingName)) {
				return bindingName;
			}
		}
		return null;
	}

	private EvidenceStateRef materializeDerivedSurface(EvidenceStateRef input, FrontierStateKey outputKey,
			int relationId, FiniteRelationEstimate relation) {
		FrontierLayout outputLayout = outputKey.frontier();
		int[] relationSlots = new int[outputLayout.size()];
		for (int slot = 0; slot < outputLayout.size(); slot++) {
			relationSlots[slot] = relation.variables().indexOf(outputLayout.variable(slot));
			if (relationSlots[slot] < 0) {
				return null;
			}
		}

		int entryCount = relation.frequencies().size();
		int particleBudget = Math.toIntExact(Math.min(settings.refinementWorkUnits(), Integer.MAX_VALUE));
		if (entryCount > 0 && particleBudget <= 0) {
			return null;
		}
		boolean exact = entryCount <= particleBudget;
		boolean learnedInput = arena.nearestCalibration(input) != null;
		EvidenceStateRef retainedExact = learnedInput ? null : exactDerivedStates.get(outputKey);
		if (retainedExact != null) {
			if (retainedExact.summary().guarantee() != EvidenceGuarantee.DATABASE_EXACT
					|| !isComposableState(retainedExact)
					|| Double.compare(retainedExact.summary().pointRows(), relation.rows()) != 0) {
				throw new IllegalStateException("retained database-exact Frontier derivation is inconsistent");
			}
			return retainedExact;
		}
		EvidenceStateRef canonicalState = learnedInput ? null : arena.find(outputKey);
		if (canonicalState != null
				&& canonicalState.summary().guarantee() == EvidenceGuarantee.DATABASE_EXACT
				&& isComposableState(canonicalState)) {
			if (Double.compare(canonicalState.summary().pointRows(), relation.rows()) != 0) {
				throw new IllegalStateException("database-exact Frontier derivations disagree for one logical state");
			}
			exactDerivedStates.put(outputKey, canonicalState);
			return canonicalState;
		}
		int target = exact ? entryCount : particleBudget;
		long scratchBytes = exact || entryCount == 0
				? 0L
				: Math.addExact(
						Math.multiplyExact(2L, retainedArrayBytes(entryCount, Double.BYTES)),
						Math.addExact(retainedArrayBytes(entryCount, Integer.BYTES),
								retainedArrayBytes(target, Double.BYTES)));
		try (FrontierMemoryReservation ignored = scratchBytes == 0L
				? null
				: arena.reserveTemporary(scratchBytes, FrontierMemoryPurpose.ARRAY_GROWTH);
				EmissionBuffer emissions = new EmissionBuffer(arena, outputLayout.size(), target)) {
			int[] drawCounts = null;
			double drawMass = 0.0d;
			if (!exact) {
				double[] weights = new double[entryCount];
				int ordinal = 0;
				double totalMass = 0.0d;
				for (double frequency : relation.frequencies().values()) {
					weights[ordinal++] = frequency;
					totalMass += frequency;
				}
				long seed = FrontierSeedSchedule.derive(
						arena.deterministicSeed(input), FrontierRandomDomain.RESAMPLE,
						Integer.toUnsignedLong(relationId), 2L);
				drawCounts = FrontierMultinomialResampler.drawCounts(weights, target, seed);
				drawMass = totalMass / target;
			}

			long[] tuple = new long[outputLayout.size()];
			int ordinal = 0;
			for (Map.Entry<List<Value>, Double> entry : relation.frequencies().entrySet()) {
				double weight = exact ? entry.getValue() : drawCounts[ordinal] * drawMass;
				ordinal++;
				if (weight <= 0.0d) {
					continue;
				}
				Arrays.fill(tuple, 0L);
				for (int slot = 0; slot < tuple.length; slot++) {
					Value value = entry.getKey().get(relationSlots[slot]);
					if (value != null) {
						tuple[slot] = encodeFrontierValue(value);
					}
				}
				emissions.add(tupleMaskStratum(outputKey.maskStrata(), tuple), tuple, 0, weight);
			}

			boolean databaseExactOutput = exact && !learnedInput;
			FrontierPayloadWriter writer = materializeEmissions(outputKey, emissions, databaseExactOutput);
			try {
				double pointRows = writer.pointRows();
				if (learnedInput && pointRows == 0.0d) {
					writer.close();
					writer = null;
					return arena.deriveSummary(
							outputKey,
							EvidenceStateSummary.unresolved(
									0.0d,
									Double.POSITIVE_INFINITY,
									Double.POSITIVE_INFINITY,
									"learned-calibrated-transform-zero-support"),
							FrontierStateOperation.UNRESOLVED,
							input,
							null,
							relationId);
				}
				EvidenceStateSummary summary = databaseExactOutput
						? EvidenceStateSummary.exact(pointRows)
						: learnedInput
								? learnedSummary(pointRows, writer.effectiveSampleSize(),
										writer.maximumWeightFraction())
								: sampledSummary(pointRows, writer.effectiveSampleSize(),
										writer.maximumWeightFraction(), Double.POSITIVE_INFINITY);
				FrontierStateOperation operation = exact
						? FrontierStateOperation.BRIDGE_TRANSFER
						: FrontierStateOperation.BRIDGE_MUTATION;
				EvidenceStateRef state = !learnedInput && canonicalState == null
						? arena.internPayload(outputKey, summary, operation, input, null, relationId, writer)
						: arena.derivePayload(outputKey, summary, operation, input, null, relationId, writer);
				writer = null;
				rememberState(state);
				if (databaseExactOutput) {
					exactDerivedStates.put(outputKey, state);
				}
				return state;
			} finally {
				if (writer != null) {
					writer.close();
				}
			}
		}
	}

	private List<String> factorInputBindingNames(EvidenceStateRef input, int relationId) {
		FrontierLayout inputLayout = arena.layout(input);
		List<String> names = new ArrayList<>(4);
		for (int component = 0; component < 4; component++) {
			if (query.statementPatternValue(relationId, component) != null) {
				continue;
			}
			String name = query.statementPatternName(relationId, component);
			if (name != null && inputLayout.indexOf(name) >= 0 && !names.contains(name)) {
				names.add(name);
			}
		}
		return names;
	}

	private static boolean fullyBound(FiniteRelationEstimate relation) {
		for (List<Value> tuple : relation.frequencies().keySet()) {
			if (tuple.contains(null)) {
				return false;
			}
		}
		return true;
	}

	private double exactCorrelationKeyUpperBound(EvidenceStateRef state, String[] correlationNames, int depth) {
		if (state == null || depth > MAX_ALTERNATE_REPLAY_DEPTH) {
			return Double.NaN;
		}
		FrontierLayout layout = arena.layout(state);
		int[] slots = correlationSlots(layout, correlationNames);
		if (slots == null) {
			return Double.NaN;
		}
		if (state.summary().guarantee() == EvidenceGuarantee.DATABASE_EXACT) {
			try (FrontierPayloadLease payload = arena.openPayload(state)) {
				PrimitiveCorrelationKeyTable keys = new PrimitiveCorrelationKeyTable(
						payloadEntryCount(payload), slots.length);
				long[] tuple = new long[slots.length];
				for (int stratum = 0; stratum < payload.stratumCount(); stratum++) {
					for (int index = 0; index < payload.exactCount(stratum); index++) {
						fillCorrelationTuple(payload, true, stratum, index, slots, tuple);
						keys.add(tuple, payload.exactWeight(stratum, index));
					}
				}
				return keys.size();
			}
		}
		FrontierStateOperation operation = arena.operation(state);
		if (operation == FrontierStateOperation.UNION) {
			double upperBound = 0.0d;
			for (int parentIndex = 0; parentIndex < arena.parentCount(state); parentIndex++) {
				EvidenceStateRef parent = arena.parent(state, parentIndex);
				if (correlationSlots(arena.key(parent).frontier(), correlationNames) == null) {
					return Double.NaN;
				}
				double parentUpperBound = exactCorrelationKeyUpperBound(parent, correlationNames, depth + 1);
				if (!Double.isFinite(parentUpperBound)) {
					return Double.NaN;
				}
				upperBound = saturatedAdd(upperBound, parentUpperBound);
			}
			return upperBound;
		}
		if (!preservesExistingCorrelationDomain(operation)) {
			return Double.NaN;
		}
		double upperBound = Double.NaN;
		for (int parentIndex = 0; parentIndex < arena.parentCount(state); parentIndex++) {
			EvidenceStateRef parent = arena.parent(state, parentIndex);
			if (correlationSlots(arena.key(parent).frontier(), correlationNames) == null) {
				continue;
			}
			double parentUpperBound = exactCorrelationKeyUpperBound(parent, correlationNames, depth + 1);
			if (Double.isFinite(parentUpperBound)) {
				upperBound = Double.isFinite(upperBound)
						? Math.min(upperBound, parentUpperBound)
						: parentUpperBound;
			}
		}
		return upperBound;
	}

	private static boolean preservesExistingCorrelationDomain(FrontierStateOperation operation) {
		return switch (operation) {
		case BRIDGE_TRANSFER, BRIDGE_MUTATION, PROBE_FACTOR, JOIN, CARTESIAN, RESOLVE_OUTER_KERNEL, RESOLVE_OUTER_EXPANSION, PROJECT, ALIGN, RESTRICT, AVERAGE_DESIGN_LANES, CALIBRATE -> true;
		default -> false;
		};
	}

	private static int[] correlationSlots(FrontierLayout layout, String[] correlationNames) {
		int[] slots = new int[correlationNames.length];
		for (int index = 0; index < correlationNames.length; index++) {
			slots[index] = layout.indexOf(correlationNames[index]);
			if (slots[index] < 0) {
				return null;
			}
		}
		return slots;
	}

	private static void fillCorrelationTuple(FrontierPayloadLease payload, boolean exact, int stratum, int index,
			int[] correlationSlots, long[] tuple) {
		for (int ordinal = 0; ordinal < correlationSlots.length; ordinal++) {
			int slot = correlationSlots[ordinal];
			tuple[ordinal] = payload.masks().isBound(stratum, slot)
					? payloadTermId(payload, exact, stratum, index, slot)
					: 0L;
		}
	}

	private static void annotateCorrelationProfile(PackedCostEstimate output, FrontierSemiAntiProfile profile) {
		FrontierCorrelationDomain probeDomain = profile.probeDomain();
		output.putPlannedDoubleMetric("plannedCorrelationOuterRows", profile.outerRows());
		output.putPlannedDoubleMetric("plannedCorrelationEvidenceOuterRows", profile.evidenceOuterRows());
		output.putPlannedStringMetric("plannedCorrelationOuterRowsSource", profile.outerRowsSource());
		output.putPlannedDoubleMetric("plannedCorrelationMatchedRows", profile.matchedRows());
		output.putPlannedDoubleMetric("plannedCorrelationUnmatchedRows", profile.unmatchedRows());
		output.putPlannedDoubleMetric("plannedCorrelationDistinctKeyLowerBound",
				probeDomain.distinctKeyLowerBound());
		if (Double.isFinite(probeDomain.distinctKeyEstimate())) {
			output.putPlannedDoubleMetric("plannedCorrelationDistinctKeys", probeDomain.distinctKeyEstimate());
		}
		output.putPlannedDoubleMetric("plannedCorrelationDistinctKeyUpperBound",
				probeDomain.distinctKeyUpperBound());
		output.putPlannedDoubleMetric("plannedCorrelationMatchedDistinctKeys",
				profile.planningMatchedDistinctProbeKeys());
		output.putPlannedDoubleMetric("plannedCorrelationUnmatchedDistinctKeys",
				profile.planningUnmatchedDistinctProbeKeys());
		output.putPlannedDoubleMetric("plannedCorrelationFanoutMean", probeDomain.fanoutMean());
		output.putPlannedDoubleMetric("plannedCorrelationFanoutMaximum", probeDomain.fanoutMaximum());
		output.putPlannedDoubleMetric("plannedCorrelationConfidence", profile.confidence());
		output.putPlannedStringMetric("plannedCorrelationGuarantee", statusName(profile.guarantee()));
	}

	private static void synchronizeSemiAntiCorrelationRows(PackedCostEstimate output,
			EvidenceStateSummary correctedSummary, double correctedRows) {
		String semanticKind = output.plannedStringMetric("optimizer.semiAntiKind");
		double outerRows = output.plannedDoubleMetric("plannedCorrelationOuterRows", Double.NaN);
		if (semanticKind == null || !finiteNonNegative(outerRows)
				|| !finiteNonNegative(correctedRows)) {
			return;
		}
		double selectedRows = Math.min(outerRows, correctedRows);
		switch (semanticKind) {
		case "exists" -> {
			output.putPlannedDoubleMetric("plannedCorrelationMatchedRows", selectedRows);
			output.putPlannedDoubleMetric("plannedCorrelationUnmatchedRows", outerRows - selectedRows);
		}
		case "not-exists", "minus-assured-shared" -> {
			output.putPlannedDoubleMetric("plannedCorrelationMatchedRows", outerRows - selectedRows);
			output.putPlannedDoubleMetric("plannedCorrelationUnmatchedRows", selectedRows);
		}
		default -> {
			return;
		}
		}
		output.putPlannedDoubleMetric("plannedCorrelationConfidence", correctedSummary.confidence());
		output.putPlannedStringMetric("plannedCorrelationGuarantee", statusName(correctedSummary.guarantee()));
		output.putPlannedStringMetric("plannedCorrelationRowsSource", "frontier-cost-event-leo");
	}

	private static SemiAntiBindingDomains semiAntiBindingDomains(Collection<String> outerNames, TupleExpr rhs) {
		return semiAntiBindingDomains(outerNames, List.of(), rhs);
	}

	private static SemiAntiBindingDomains semiAntiBindingDomains(Collection<String> frontierNames,
			Collection<String> structuralCorrelationNames, TupleExpr rhs) {
		LinkedHashSet<String> outerNames = new LinkedHashSet<>(frontierNames);
		outerNames.addAll(structuralCorrelationNames);
		LinkedHashSet<String> constantNames = new LinkedHashSet<>();
		rhs.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Var var) {
				if (var.hasValue() && var.getName() != null) {
					constantNames.add(var.getName());
				}
			}
		});
		LinkedHashSet<String> outputNames = new LinkedHashSet<>(rhs.getBindingNames());
		outputNames.removeAll(constantNames);
		LinkedHashSet<String> probeNames = new LinkedHashSet<>(outputNames);
		probeNames.addAll(VarNameCollector.process(rhs));
		probeNames.removeAll(constantNames);
		probeNames.retainAll(outerNames);
		LinkedHashSet<String> sharedHashNames = new LinkedHashSet<>(outerNames);
		sharedHashNames.retainAll(outputNames);
		LinkedHashSet<String> materializationParameterNames = new LinkedHashSet<>(probeNames);
		materializationParameterNames.removeAll(sharedHashNames);
		return new SemiAntiBindingDomains(
				sortedNames(probeNames),
				sortedNames(sharedHashNames),
				sortedNames(materializationParameterNames));
	}

	private static List<String> sortedNames(Collection<String> names) {
		ArrayList<String> result = new ArrayList<>(names);
		result.sort(String::compareTo);
		return List.copyOf(result);
	}

	private String[] semiAntiCorrelationNames(int relationId) {
		String[] names = new String[query.semiAntiCorrelationBindingCount(relationId)];
		for (int ordinal = 0; ordinal < names.length; ordinal++) {
			names[ordinal] = query.semiAntiCorrelationBindingName(relationId, ordinal);
		}
		Arrays.sort(names);
		return names;
	}

	private static String[] sharedCorrelationNames(FrontierLayout layout, TupleExpr rhs) {
		return sharedCorrelationNames(layout.variables(), rhs);
	}

	private static String[] sharedCorrelationNames(Collection<String> outerNames, TupleExpr rhs) {
		ArrayList<String> names = new ArrayList<>();
		for (String name : outerNames) {
			if (rhs.getBindingNames().contains(name)) {
				names.add(name);
			}
		}
		names.sort(String::compareTo);
		return names.toArray(String[]::new);
	}

	private double estimatedRelationRows(int relationId) {
		EvidenceStateRef leaf = leafEvidenceState(relationId);
		if (leaf != null) {
			return leaf.summary().pointRows();
		}
		double annotated = query.annotatedRows(relationId);
		if (finiteNonNegative(annotated)) {
			return annotated;
		}
		return estimatedTupleRows(query.materializeRelation(relationId));
	}

	private double estimatedTupleRows(TupleExpr expression) {
		BagEstimate estimate = runtime.estimate(expression);
		return estimate != null && finiteNonNegative(estimate.rows()) ? estimate.rows() : 1.0d;
	}

	private static double semiAntiBreakEvenDistinctKeys(double rhsRows, double memoizedRowsExamined,
			double plannedDistinctKeys) {
		double perKeyCost = plannedDistinctKeys > 0.0d
				? memoizedRowsExamined / plannedDistinctKeys + 2.0d
				: 2.0d;
		return Math.max(1.0d, Math.ceil((rhsRows * 2.0d + 1.0d) / Math.max(1.0d, perKeyCost)));
	}

	private static ExistsCondition pureExistsCondition(Filter filter) {
		if (filter.getCondition()instanceof Exists exists) {
			return new ExistsCondition(exists, false);
		}
		if (filter.getCondition()instanceof Not not && not.getArg()instanceof Exists exists) {
			return new ExistsCondition(exists, true);
		}
		return null;
	}

	private FrontierStateKey filterOperatorKey(int relationId, EvidenceStateRef input) {
		FrontierStateKey inputKey = arena.key(input);
		FrontierStateKey outputKey = operatorStateKey(inputKey, relationId, inputKey.maskStrata());
		arena.declareCanonicalState(outputKey);
		return outputKey;
	}

	private EvidenceStateRef applyLearnedFilterCalibration(int relationId, Filter filter, EvidenceStateRef input,
			EvidenceStateRef rawState, PackedCostEstimate output) {
		EvidenceStateSummary primaryRawSummary = rawState.summary();
		EvidenceStateSummary rawSummary = primaryRawSummary;
		if (rawSummary.guarantee() == EvidenceGuarantee.DATABASE_EXACT) {
			return rawState;
		}
		LmdbLearnedFilterEvidence learned = runtime.learnedFilterEvidence(filter);
		if (learned == null || arena.containsCalibrationEvidence(rawState, learned.evidenceKey())) {
			return rawState;
		}
		double inputRows = input.summary().pointRows();
		if (!finiteNonNegative(inputRows)) {
			return rawState;
		}
		double rawPassRatio = inputRows == 0.0d
				? 0.0d
				: Math.clamp(rawSummary.pointRows() / inputRows, 0.0d, 1.0d);
		double frontierPseudoCount = finiteNonNegative(rawSummary.effectiveSampleSize())
				? rawSummary.effectiveSampleSize()
				: 0.0d;
		double learnedPseudoCount = learned.evidenceCount();
		double posteriorAlpha = 0.5d
				+ frontierPseudoCount * rawPassRatio
				+ learnedPseudoCount * learned.passRatio();
		double posteriorBeta = 0.5d
				+ frontierPseudoCount * (1.0d - rawPassRatio)
				+ learnedPseudoCount * (1.0d - learned.passRatio());
		double posteriorTotal = posteriorAlpha + posteriorBeta;
		double posteriorPassRatio = posteriorAlpha / posteriorTotal;
		double posteriorVariance = posteriorAlpha * posteriorBeta
				/ (posteriorTotal * posteriorTotal * (posteriorTotal + 1.0d));
		double posteriorMargin = NORMAL_95_Z * Math.sqrt(Math.max(0.0d, posteriorVariance));
		double posteriorLower95PassRatio = Math.clamp(posteriorPassRatio - posteriorMargin, 0.0d, 1.0d);
		double posteriorUpper95PassRatio = Math.clamp(posteriorPassRatio + posteriorMargin, 0.0d, 1.0d);
		double finalRows = inputRows * posteriorPassRatio;
		EvidenceStateRef calibrationParent = rawState;
		if (primaryRawSummary.pointRows() == 0.0d && finalRows > 0.0d) {
			EvidenceStateRef replayed = replayFilterSupport(relationId, filter, input);
			if (replayed != null && replayed.summary().pointRows() > 0.0d) {
				calibrationParent = replayed;
				rawSummary = replayed.summary();
				output.putPlannedStringMetric("plannedFrontierFilterSupportReplay", "alternate_design_lane");
			} else {
				output.putPlannedStringMetric("plannedFrontierFilterSupportReplay", "exhausted");
			}
		}
		double factor = rawSummary.pointRows() == 0.0d
				? finalRows == 0.0d ? 0.0d : Double.POSITIVE_INFINITY
				: finalRows / rawSummary.pointRows();
		EvidenceCalibrationSummary calibration = new EvidenceCalibrationSummary(
				rawSummary.pointRows(),
				finalRows,
				factor,
				learned.source(),
				learned.evidenceCount(),
				learned.confidence(),
				learned.evidenceKey(),
				runtime.learnedEvidenceRevision());
		EvidenceStateRef calibrated = arena.calibrate(calibrationParent, calibration, relationId);
		rememberState(calibrated);
		output.putPlannedDoubleMetric("plannedFrontierFilterRawPassRatio", rawPassRatio);
		output.putPlannedDoubleMetric("plannedFrontierFilterLearnedPassRatio", learned.planningPassRatio());
		output.putPlannedDoubleMetric("plannedFrontierFilterBlendedPassRatio", posteriorPassRatio);
		output.putPlannedDoubleMetric("plannedFrontierFilterLower95PassRatio", learned.lower95PassRatio());
		output.putPlannedDoubleMetric("plannedFrontierFilterUpper95PassRatio", learned.upper95PassRatio());
		output.putPlannedDoubleMetric("plannedFrontierFilterPosteriorPassRatio", posteriorPassRatio);
		output.putPlannedDoubleMetric(
				"plannedFrontierFilterPosteriorLower95PassRatio", posteriorLower95PassRatio);
		output.putPlannedDoubleMetric(
				"plannedFrontierFilterPosteriorUpper95PassRatio", posteriorUpper95PassRatio);
		output.putPlannedDoubleMetric("plannedFrontierFilterFrontierPseudoCount", frontierPseudoCount);
		output.putPlannedDoubleMetric("plannedFrontierFilterLearnedPseudoCount", learnedPseudoCount);
		output.putPlannedDoubleMetric("plannedFrontierFilterModelConfidence", learned.confidence());
		output.putPlannedDoubleMetric("plannedFrontierFilterEvidenceCount", learned.evidenceCount());
		output.putPlannedStringMetric("plannedFrontierFilterEvidenceSource", learned.source());
		output.putPlannedStringMetric("plannedFrontierFilterEvidenceScope",
				learned.generalized() ? "generalized" : "exact");
		return calibrated;
	}

	private ExactProbeBudget exactProbeBudget(int relationId, Filter filter, EvidenceStateRef input,
			TupleExpr right, PackedCostEstimate output) {
		FrontierLayout layout = arena.key(input).frontier();
		boolean typed = query.isSemiJoin(relationId) || query.isAntiJoin(relationId);
		Collection<String> structuralCorrelationNames = typed
				? Arrays.asList(semiAntiCorrelationNames(relationId))
				: filter.getArg().getBindingNames();
		SemiAntiBindingDomains bindingDomains = semiAntiBindingDomains(
				layout.variables(), structuralCorrelationNames, right);
		String[] probeNames = bindingDomains.probeNames().toArray(String[]::new);
		double rhsRows = estimatedTupleRows(right);
		JoinFactorCostModel.FactorCostEstimate factor = candidateFactor(
				right, probeNames, rhsRows).orElse(null);
		double boundWorkPerKey = factorWorkRows(factor, rhsRows);
		DependentReopenCost dependentReopenCost = DependentReopenCost.from(output);
		double dependentPlanWorkPerKey = dependentReopenCost.required()
				? dependentReopenCost.workRows()
				: 0.0d;
		double estimatedWorkPerKey = Math.max(boundWorkPerKey, dependentPlanWorkPerKey);
		int maximumMappings = maximumExactProbeMappings(
				settings.refinementWorkUnits(), boundWorkPerKey, dependentPlanWorkPerKey);
		return new ExactProbeBudget(
				boundWorkPerKey, dependentPlanWorkPerKey, estimatedWorkPerKey, maximumMappings);
	}

	private ExactProbeBudget exactProbeBudget(EvidenceStateRef input, TupleExpr right) {
		FrontierLayout layout = arena.key(input).frontier();
		SemiAntiBindingDomains bindingDomains = semiAntiBindingDomains(layout.variables(), right);
		String[] probeNames = bindingDomains.probeNames().toArray(String[]::new);
		double rhsRows = estimatedTupleRows(right);
		JoinFactorCostModel.FactorCostEstimate factor = candidateFactor(
				right, probeNames, rhsRows).orElse(null);
		double boundWorkPerKey = factorWorkRows(factor, rhsRows);
		int maximumMappings = maximumExactProbeMappings(
				settings.refinementWorkUnits(), boundWorkPerKey, 0.0d);
		return new ExactProbeBudget(boundWorkPerKey, 0.0d, boundWorkPerKey, maximumMappings);
	}

	private static int maximumExactProbeMappings(long workBudget, double boundWorkPerKey,
			double dependentPlanWorkPerKey) {
		if (workBudget <= 0L) {
			return 0;
		}
		double workPerKey = Math.max(boundWorkPerKey, dependentPlanWorkPerKey);
		if (!finiteNonNegative(workPerKey)) {
			return 0;
		}
		if (workPerKey == 0.0d) {
			return Integer.MAX_VALUE;
		}
		double affordableMappings = workBudget / workPerKey;
		return affordableMappings >= Integer.MAX_VALUE
				? Integer.MAX_VALUE
				: (int) Math.floor(affordableMappings);
	}

	private EvidenceStateRef restrictExistsFilter(EvidenceStateRef input, FrontierStateKey outputKey, int relationId,
			Filter filter, int maximumProbeMappings) {
		boolean negated = filter.getCondition() instanceof Not;
		Exists exists = negated
				? (Exists) ((Not) filter.getCondition()).getArg()
				: (Exists) filter.getCondition();
		FrontierLayout layout = arena.key(input).frontier();
		long scratchBytes = Math.addExact(FILTER_BINDING_SCRATCH_BASE_BYTES,
				Math.multiplyExact(FILTER_BINDING_SCRATCH_SLOT_BYTES, layout.size()));
		try (FrontierMemoryReservation ignored = arena.reserveTemporary(
				scratchBytes, FrontierMemoryPurpose.TARGET_COALESCING)) {
			String[] names = layoutVariables(layout);
			ArrayBindingSet bindings = new ArrayBindingSet(names);
			return FrontierLinearTransforms.resolveProjectedOuterKernel(
					arena,
					input,
					outputKey,
					relationId,
					negated ? FrontierOuterKernel.NOT_EXISTS : FrontierOuterKernel.EXISTS,
					(payload, exact, stratum, index) -> existsMatchMultiplicity(
							exists, payload, exact, stratum, index, names, bindings),
					maximumProbeMappings,
					1.0d);
		}
	}

	private long existsMatchMultiplicity(Exists exists, FrontierPayloadLease payload, boolean exact, int stratum,
			int index, String[] names, ArrayBindingSet bindings) {
		try {
			populateBindings(payload, exact, stratum, index, names, bindings);
			try (CloseableIteration<BindingSet> matches = evaluationStrategy.evaluate(
					exists.getSubQuery(), bindings)) {
				return matches.hasNext() ? 1L : 0L;
			}
		} catch (IOException | QueryEvaluationException failure) {
			throw new FilterEvaluationFailure("Frontier EXISTS exact probe failed", failure);
		}
	}

	private EvidenceStateRef averageIndependentDesignState(EvidenceStateRef primary, int operationRecipeId) {
		if (primary == null || primary.summary().guarantee() != EvidenceGuarantee.MEASURE_UNBIASED) {
			return primary;
		}
		EvidenceStateRef independent = replayAlternateDesignState(primary, MAX_ALTERNATE_REPLAY_DEPTH);
		if (independent == null
				|| independent.summary().guarantee() != EvidenceGuarantee.MEASURE_UNBIASED) {
			return primary;
		}
		FrontierStateKey primaryKey = arena.key(primary);
		FrontierStateKey outputKey = averagedDesignStateKey(primaryKey);
		arena.declareCanonicalState(outputKey);
		EvidenceStateRef averaged = arena.find(outputKey);
		if (averaged == null) {
			averaged = FrontierLinearTransforms.averageIndependentMeasures(
					arena, primary, independent, outputKey, operationRecipeId);
			rememberState(averaged);
		}
		return averaged;
	}

	private static FrontierStateKey averagedDesignStateKey(FrontierStateKey inputKey) {
		long correlationScope = inputKey.correlationScope() ^ DESIGN_LANE_AVERAGE_SCOPE_DOMAIN;
		correlationScope ^= correlationScope >>> 32;
		correlationScope *= 0xd6e8feb86659fd93L;
		correlationScope ^= correlationScope >>> 32;
		if (correlationScope == inputKey.correlationScope()) {
			correlationScope ^= 0xa5a3564e27f8862fL;
		}
		return FrontierStateKey.of(
				logicalFactorWords(inputKey),
				inputKey.maskStrata(),
				inputKey.semanticScope(),
				correlationScope,
				inputKey.continuationObjective(),
				inputKey.snapshotStoreIdHigh(),
				inputKey.snapshotStoreIdLow(),
				inputKey.snapshotEpoch(),
				inputKey.laneFamily(),
				inputKey.laneIndex(),
				inputKey.seedVersion());
	}

	/**
	 * Attempts a bounded support replay in the independent design lane before learned positive mass becomes a
	 * non-composable summary. The replay changes only the particle support: the final cardinality still comes from the
	 * primary-lane raw estimate blended with the learned filter surface.
	 */
	private EvidenceStateRef replayFilterSupport(int relationId, Filter filter, EvidenceStateRef input) {
		EvidenceStateRef replayedInput = replayAlternateDesignState(input, MAX_ALTERNATE_REPLAY_DEPTH);
		if (!isComposableState(replayedInput)) {
			return null;
		}
		FrontierStateKey outputKey = filterOperatorKey(relationId, replayedInput);
		if (outputKey == null) {
			return null;
		}
		EvidenceStateRef replayed = arena.find(outputKey);
		if (replayed == null) {
			replayed = restrictFilter(replayedInput, outputKey, relationId, filter);
			rememberState(replayed);
		}
		return isComposableState(replayed)
				&& replayed.summary().pointRows() > 0.0d
						? replayed
						: null;
	}

	private EvidenceStateRef replayAlternateDesignState(EvidenceStateRef source, int remainingDepth) {
		if (remainingDepth <= 0 || !isComposableState(source)) {
			return null;
		}
		FrontierStateKey sourceKey = arena.key(source);
		if (sourceKey.laneFamily() == FrontierLaneFamily.DESIGN
				&& sourceKey.laneIndex() == INDEPENDENT_DESIGN_LANE_INDEX) {
			return source;
		}
		EvidenceStateRef cached = alternateReplayStates.get(source.stateId());
		if (cached != null) {
			return cached;
		}
		if (alternateReplayFailures.contains(source.stateId())) {
			return null;
		}

		EvidenceStateRef replayed = switch (arena.operation(source)) {
		case COORDINATED_STAR -> replayAlternateLeaf(source);
		case CALIBRATE -> replayAlternateDesignState(arena.parent(source, 0), remainingDepth - 1);
		case BRIDGE_TRANSFER, BRIDGE_MUTATION -> replayAlternateBridge(source, remainingDepth - 1);
		case PROJECT -> replayAlternateProjection(source, remainingDepth - 1);
		case ALIGN -> replayAlternateAlignment(source, remainingDepth - 1);
		case RESTRICT -> replayAlternateRestriction(source, remainingDepth - 1);
		case UNION -> replayAlternateUnion(source, remainingDepth - 1);
		default -> null;
		};
		if (!isComposableState(replayed)) {
			alternateReplayFailures.add(source.stateId());
			return null;
		}
		alternateReplayStates.put(source.stateId(), replayed);
		return replayed;
	}

	private EvidenceStateRef replayAlternateLeaf(EvidenceStateRef source) {
		LeafState leaf = leafState(arena.operationRecipeId(source));
		return leaf != null && leaf.state != null && leaf.state.stateId() == source.stateId()
				? materializeIndependentLeaf(leaf)
				: null;
	}

	private EvidenceStateRef replayAlternateBridge(EvidenceStateRef source, int remainingDepth) {
		EvidenceStateRef replayedParent = replayAlternateDesignState(arena.parent(source, 0), remainingDepth);
		LeafState factor = leafState(arena.operationRecipeId(source));
		if (replayedParent == null || factor == null) {
			return null;
		}
		FrontierStateKey outputKey = withSamplingIdentity(arena.key(source), arena.key(replayedParent));
		arena.declareCanonicalState(outputKey);
		EvidenceStateRef replayed = arena.find(outputKey);
		if (replayed == null) {
			replayed = extendInner(replayedParent, factor, outputKey, arena.operationRecipeId(source));
			rememberState(replayed);
		}
		return replayed;
	}

	private EvidenceStateRef replayAlternateProjection(EvidenceStateRef source, int remainingDepth) {
		EvidenceStateRef replayedParent = replayAlternateDesignState(arena.parent(source, 0), remainingDepth);
		int relationId = arena.operationRecipeId(source);
		TupleExpr expression = relationId > 0 && relationId <= query.relationCount()
				? query.materializeRelation(relationId)
				: null;
		if (replayedParent == null || !(expression instanceof Projection projection)) {
			return null;
		}
		FrontierStateKey outputKey = projectionStateKey(arena.key(replayedParent), relationId, projection);
		if (outputKey == null) {
			return null;
		}
		int[] sourceSlots = projectionSourceSlots(arena.key(replayedParent).frontier(), projection);
		if (sourceSlots == null) {
			return null;
		}
		arena.declareCanonicalState(outputKey);
		EvidenceStateRef replayed = arena.find(outputKey);
		if (replayed == null) {
			replayed = FrontierLinearTransforms.project(
					arena, replayedParent, outputKey, relationId, sourceSlots);
			rememberState(replayed);
		}
		return replayed;
	}

	private EvidenceStateRef replayAlternateAlignment(EvidenceStateRef source, int remainingDepth) {
		EvidenceStateRef replayedParent = replayAlternateDesignState(arena.parent(source, 0), remainingDepth);
		if (replayedParent == null) {
			return null;
		}
		int relationId = arena.operationRecipeId(source);
		FrontierMaskStrata outputMasks = arena.key(source).maskStrata();
		return alignUnionBranch(replayedParent, outputMasks, relationId);
	}

	private EvidenceStateRef replayAlternateRestriction(EvidenceStateRef source, int remainingDepth) {
		EvidenceStateRef replayedParent = replayAlternateDesignState(arena.parent(source, 0), remainingDepth);
		int relationId = arena.operationRecipeId(source);
		TupleExpr expression = relationId > 0 && relationId <= query.relationCount()
				? query.materializeRelation(relationId)
				: null;
		if (replayedParent == null || !(expression instanceof Filter filter)
				|| !filterCanInspectRetainedState(filter, arena.key(replayedParent).frontier())) {
			return null;
		}
		FrontierStateKey outputKey = filterOperatorKey(relationId, replayedParent);
		EvidenceStateRef replayed = arena.find(outputKey);
		if (replayed == null) {
			replayed = restrictFilter(replayedParent, outputKey, relationId, filter);
			rememberState(replayed);
		}
		return replayed;
	}

	private EvidenceStateRef replayAlternateUnion(EvidenceStateRef source, int remainingDepth) {
		EvidenceStateRef replayedLeft = replayAlternateDesignState(arena.parent(source, 0), remainingDepth);
		EvidenceStateRef replayedRight = replayAlternateDesignState(arena.parent(source, 1), remainingDepth);
		if (replayedLeft == null || replayedRight == null) {
			return null;
		}
		int relationId = arena.operationRecipeId(source);
		FrontierMaskStrata outputMasks = unionMaskStrata(
				arena.key(replayedLeft).maskStrata(),
				arena.key(replayedRight).maskStrata());
		replayedLeft = alignUnionBranch(replayedLeft, outputMasks, relationId);
		replayedRight = alignUnionBranch(replayedRight, outputMasks, relationId);
		FrontierStateKey outputKey = combinedOperatorStateKey(
				arena.key(replayedLeft),
				arena.key(replayedRight),
				relationId,
				outputMasks);
		if (outputKey == null) {
			return null;
		}
		arena.declareCanonicalState(outputKey);
		EvidenceStateRef replayed = arena.find(outputKey);
		if (replayed == null) {
			replayed = FrontierLinearTransforms.union(
					arena, replayedLeft, replayedRight, outputKey, relationId);
			rememberState(replayed);
		}
		return replayed;
	}

	private boolean exactProbeBudgetExceeded(EvidenceStateRef input) {
		try (FrontierPayloadLease payload = arena.openPayload(input)) {
			return payloadEntryCount(payload) > settings.refinementWorkUnits();
		}
	}

	private static boolean containsExists(Filter filter) {
		return filter.getCondition() instanceof Exists
				|| filter.getCondition()instanceof Not not && not.getArg() instanceof Exists;
	}

	private void refineProjection(int relationId, EvidenceStateRef input, PackedCostEstimate output) {
		Projection projection = (Projection) query.materializeRelation(relationId);
		int[] sourceSlots = projectionSourceSlots(arena.key(input).frontier(), projection);
		if (sourceSlots == null) {
			output.putPlannedStringMetric("plannedFrontierProjectionInputLayout",
					arena.key(input).frontier().variables().toString());
			publishCardinalityPreservingBoundary(
					relationId, output, input, "projection_source_not_retained", 0.0d);
			return;
		}
		FrontierStateKey outputKey = projectionStateKey(arena.key(input), relationId, projection);
		if (outputKey == null) {
			publishCardinalityPreservingBoundary(
					relationId, output, input, "projection_state_unavailable", 0.0d);
			return;
		}
		arena.declareCanonicalState(outputKey);
		try {
			boolean lineageSpecific = arena.nearestCalibration(input) != null;
			EvidenceStateRef state = lineageSpecific ? null : arena.find(outputKey);
			if (state == null) {
				state = FrontierLinearTransforms.project(arena, input, outputKey, relationId, sourceSlots);
				rememberState(state);
			}
			publishOperatorState(relationId, output, state);
		} catch (RuntimeException failure) {
			throw new PackedCostSessionFailure("projection_state_materialization_failed", failure);
		}
	}

	private void refineDistinct(int relationId, EvidenceStateRef input, PackedCostEstimate output) {
		FrontierStateKey inputKey = arena.key(input);
		FrontierStateKey outputKey = operatorStateKey(inputKey, relationId, inputKey.maskStrata());
		if (outputKey == null) {
			degradeOperator(relationId, output, input, "distinct_state_unavailable");
			return;
		}
		arena.declareCanonicalState(outputKey);
		if (input.summary().guarantee() != EvidenceGuarantee.DATABASE_EXACT) {
			publishBoundOperator(relationId, output, input, outputKey,
					"sampled_distinct_requires_nonlinear_estimator", input.summary().certifiedUpperBound());
			setLocalDistinctPhysicalCost(input, output);
			return;
		}
		try {
			EvidenceStateRef state = arena.find(outputKey);
			if (state == null) {
				state = FrontierLinearTransforms.distinct(arena, input, outputKey, relationId);
				rememberState(state);
			}
			publishOperatorState(relationId, output, state);
			setLocalDistinctPhysicalCost(input, output);
		} catch (RuntimeException failure) {
			throw new PackedCostSessionFailure("distinct_state_materialization_failed", failure);
		}
	}

	private void refineBoundedDistinct(int relationId, EvidenceStateRef input, PackedCostEstimate output) {
		publishBoundOperator(
				relationId,
				output,
				input,
				null,
				"distinct_input_payload_unavailable",
				input.summary().certifiedUpperBound());
		setLocalDistinctPhysicalCost(input, output);
	}

	private void refineGroup(int relationId, Group group, EvidenceStateRef input, PackedCostEstimate output) {
		FrontierStateKey inputKey = arena.key(input);
		FrontierLayout outputLayout = outputLayout(relationId);
		FrontierMaskStrata fallbackMasks = FrontierMaskStrata.of(
				outputLayout,
				1,
				new long[(outputLayout.size() + 63) >>> 6]);
		FrontierStateKey fallbackKey = operatorStateKey(inputKey, relationId, fallbackMasks);
		if (fallbackKey == null) {
			degradeOperator(relationId, output, input, "group_state_unavailable");
			return;
		}
		arena.declareCanonicalState(fallbackKey);
		double upperBound = group.getGroupBindingNames().isEmpty()
				? 1.0d
				: input.summary().certifiedUpperBound();
		if (input.summary().guarantee() != EvidenceGuarantee.DATABASE_EXACT) {
			publishBoundOperator(relationId, output, input, fallbackKey,
					"sampled_group_requires_nonlinear_estimator", upperBound);
			setLocalGroupPhysicalCost(group, input, output);
			return;
		}
		if (evaluationStrategy == null) {
			publishBoundOperator(relationId, output, input, fallbackKey,
					"group_evaluator_unavailable", upperBound);
			setLocalGroupPhysicalCost(group, input, output);
			return;
		}
		String unsupportedReason = exactGroupFailureReason(group, inputKey.frontier());
		if (unsupportedReason != null) {
			publishBoundOperator(relationId, output, input, fallbackKey, unsupportedReason, upperBound);
			setLocalGroupPhysicalCost(group, input, output);
			return;
		}
		if (!isIntegralBoundedRows(input.summary().pointRows(), settings.refinementWorkUnits())) {
			publishBoundOperator(relationId, output, input, fallbackKey,
					"group_exact_work_budget_exhausted", upperBound);
			setLocalGroupPhysicalCost(group, input, output);
			return;
		}
		try {
			EvidenceStateRef state = materializeExactGroup(relationId, group, input);
			if (state == null) {
				publishBoundOperator(relationId, output, input, fallbackKey,
						"group_exact_memory_budget_exhausted", upperBound);
				setLocalGroupPhysicalCost(group, input, output);
				return;
			}
			publishOperatorState(relationId, output, state);
			setLocalGroupPhysicalCost(group, input, output);
		} catch (GroupEvaluationFailure failure) {
			publishBoundOperator(relationId, output, input, fallbackKey,
					"group_exact_evaluation_failed", upperBound);
			setLocalGroupPhysicalCost(group, input, output);
		} catch (RuntimeException failure) {
			throw new PackedCostSessionFailure("group_state_materialization_failed", failure);
		}
	}

	private void refineBoundedGroup(int relationId, Group group, EvidenceStateRef input,
			PackedCostEstimate output) {
		double upperBound = group.getGroupBindingNames().isEmpty()
				? 1.0d
				: input.summary().certifiedUpperBound();
		publishBoundOperator(
				relationId,
				output,
				input,
				null,
				"group_input_payload_unavailable",
				upperBound);
		setLocalGroupPhysicalCost(group, input, output);
	}

	private static void setLocalDistinctPhysicalCost(EvidenceStateRef input, PackedCostEstimate output) {
		double resultRows = output.outputRows();
		setLocalOperatorPhysicalCost(
				output,
				resultRows,
				0.0d,
				resultRows,
				input.summary().pointRows(),
				resultRows);
	}

	private static void setLocalGroupPhysicalCost(Group group, EvidenceStateRef input, PackedCostEstimate output) {
		double resultRows = output.outputRows();
		setLocalOperatorPhysicalCost(
				output,
				resultRows,
				saturatedMultiply(input.summary().pointRows(), group.getGroupElements().size()),
				resultRows,
				input.summary().pointRows(),
				resultRows);
	}

	private EvidenceStateRef materializeExactGroup(int relationId, Group group, EvidenceStateRef input) {
		FrontierLayout inputLayout = arena.key(input).frontier();
		int inputRows = Math.toIntExact(Math.round(input.summary().pointRows()));
		int maximumOutputRows = Math.max(1, inputRows);
		long scratchBytes = groupScratchBytes(inputRows, maximumOutputRows,
				inputLayout.size(), group.getBindingNames().size());
		if (scratchBytes > arena.remainingBytes()) {
			return null;
		}
		try (FrontierMemoryReservation ignored = arena.reserveTemporary(
				scratchBytes, FrontierMemoryPurpose.TARGET_COALESCING);
				FrontierPayloadLease payload = arena.openPayload(input)) {
			String[] inputNames = layoutVariables(inputLayout);
			ArrayList<BindingSet> inputBindings = new ArrayList<>(inputRows);
			for (int stratum = 0; stratum < payload.stratumCount(); stratum++) {
				if (payload.residualCount(stratum) != 0) {
					throw new IllegalStateException("database-exact group input contains residual particles");
				}
				for (int index = 0; index < payload.exactCount(stratum); index++) {
					double weight = payload.exactWeight(stratum, index);
					if (!isIntegralBoundedRows(weight, settings.refinementWorkUnits())) {
						throw new IllegalStateException("database-exact group input has invalid multiplicity");
					}
					ArrayBindingSet bindings = new ArrayBindingSet(inputNames);
					populateBindings(payload, true, stratum, index, inputNames, bindings);
					int occurrences = Math.toIntExact(Math.round(weight));
					if (inputBindings.size() > inputRows - occurrences) {
						throw new IllegalStateException("database-exact group multiplicity exceeds its summary");
					}
					for (int occurrence = 0; occurrence < occurrences; occurrence++) {
						inputBindings.add(bindings);
					}
				}
			}
			if (inputBindings.size() != inputRows) {
				throw new IllegalStateException("database-exact group payload does not match its summary");
			}

			BindingSetAssignment assignment = new BindingSetAssignment();
			assignment.setBindingNames(new LinkedHashSet<>(Arrays.asList(inputNames)));
			assignment.setBindingSets(inputBindings);
			Group boundedGroup = group.clone();
			boundedGroup.setArg(assignment);
			ArrayList<BindingSet> outputBindings = new ArrayList<>(maximumOutputRows);
			try (CloseableIteration<BindingSet> evaluated = evaluationStrategy.evaluate(
					boundedGroup, EmptyBindingSet.getInstance())) {
				while (evaluated.hasNext()) {
					if (outputBindings.size() == maximumOutputRows) {
						throw new IllegalStateException("exact group output exceeded its cardinality bound");
					}
					outputBindings.add(new QueryBindingSet(evaluated.next()));
				}
			}

			BindingSetAssignment result = new BindingSetAssignment();
			result.setBindingNames(new LinkedHashSet<>(group.getBindingNames()));
			result.setBindingSets(outputBindings);
			FiniteLeafState finite = FiniteLeafState.create(relationId, result);
			finite.key = operatorStateKey(arena.key(input), relationId, finite.masks);
			arena.declareCanonicalState(finite.key);
			EvidenceStateRef state = arena.find(finite.key);
			if (state == null) {
				state = materializeFiniteState(arena, finite, FrontierStateOperation.GROUP, input, null);
				rememberState(state);
			}
			return state;
		} catch (IOException | QueryEvaluationException failure) {
			throw new GroupEvaluationFailure("Frontier GROUP exact evaluation failed", failure);
		}
	}

	private static String exactGroupFailureReason(Group group, FrontierLayout inputLayout) {
		for (String groupBinding : group.getGroupBindingNames()) {
			if (inputLayout.indexOf(groupBinding) < 0) {
				return "group_input_not_retained";
			}
		}
		for (var element : group.getGroupElements()) {
			if (!(element.getOperator()instanceof AbstractAggregateOperator aggregate)
					|| !(aggregate instanceof Count || aggregate instanceof Sum || aggregate instanceof Avg
							|| aggregate instanceof Min || aggregate instanceof Max)) {
				return "group_aggregate_not_exactly_replayable";
			}
			ValueExpr argument = aggregate.getArg();
			if (!ScalarEvaluationEffects.effectOf(argument).reorderingIsSafe()) {
				return "group_aggregate_expression_not_repeatable";
			}
			if (argument != null) {
				for (String variable : directValueExpressionVariables(argument)) {
					if (inputLayout.indexOf(variable) < 0) {
						return "group_aggregate_input_not_retained";
					}
				}
			}
		}
		return null;
	}

	private static boolean isIntegralBoundedRows(double rows, int maximumRows) {
		return Double.isFinite(rows) && rows >= 0.0d && rows == Math.rint(rows) && rows <= maximumRows;
	}

	private static long groupScratchBytes(int inputRows, int outputRows, int inputWidth, int outputWidth) {
		long input = Math.multiplyExact((long) inputRows,
				Math.addExact(64L, Math.multiplyExact((long) inputWidth, 16L)));
		long output = Math.multiplyExact((long) outputRows,
				Math.addExact(64L, Math.multiplyExact((long) outputWidth, 16L)));
		return Math.addExact(256L, Math.addExact(input, output));
	}

	private void refineReduced(int relationId, EvidenceStateRef input, PackedCostEstimate output) {
		FrontierStateKey inputKey = isComposableState(input)
				? arena.key(input)
				: null;
		FrontierStateKey outputKey = inputKey == null
				? null
				: operatorStateKey(inputKey, relationId, inputKey.maskStrata());
		if (outputKey == null && isComposableState(input)) {
			degradeOperator(relationId, output, input, "reduced_state_unavailable");
			return;
		}
		if (outputKey != null) {
			arena.declareCanonicalState(outputKey);
		}
		publishBoundOperator(relationId, output, input, outputKey,
				"reduced_preserves_support_with_unspecified_multiplicity",
				input.summary().certifiedUpperBound());
		if (mode == FrontierEstimatorMode.AUTHORITATIVE) {
			setLocalOperatorPhysicalCost(
					output,
					output.outputRows(),
					input.summary().pointRows(),
					0.0d,
					0.0d,
					Math.min(1.0d, input.summary().pointRows()));
		}
	}

	private void refineSlice(int relationId, Slice slice, EvidenceStateRef input, PackedCostEstimate output) {
		FrontierStateKey inputKey = isComposableState(input)
				? arena.key(input)
				: null;
		FrontierStateKey outputKey = inputKey == null
				? null
				: operatorStateKey(inputKey, relationId, inputKey.maskStrata());
		if (outputKey == null && isComposableState(input)) {
			degradeOperator(relationId, output, input, "slice_state_unavailable");
			return;
		}
		if (outputKey != null) {
			arena.declareCanonicalState(outputKey);
		}
		double pointRows = slicedRows(input.summary().pointRows(), slice);
		double upperBound = slicedRows(input.summary().certifiedUpperBound(), slice);
		output.setRows(pointRows, Math.max(pointRows, output.workRows()));
		publishBoundOperator(relationId, output, input, outputKey,
				"slice_retains_cardinality_bound_without_ordered_payload", upperBound);
	}

	private static double slicedRows(double rows, Slice slice) {
		if (Double.isInfinite(rows)) {
			return slice.hasLimit() ? slice.getLimit() : Double.POSITIVE_INFINITY;
		}
		double afterOffset = Math.max(0.0d, rows - (slice.hasOffset() ? slice.getOffset() : 0L));
		return slice.hasLimit() ? Math.min(afterOffset, slice.getLimit()) : afterOffset;
	}

	private void publishBoundOperator(int relationId, PackedCostEstimate output, EvidenceStateRef input,
			FrontierStateKey outputKey, String reason, double certifiedUpperBound) {
		double bound = finiteNonNegative(certifiedUpperBound) ? certifiedUpperBound : Double.POSITIVE_INFINITY;
		double pointRows = finiteNonNegative(output.outputRows()) ? Math.min(output.outputRows(), bound) : 0.0d;
		EvidenceStateSummary summary = EvidenceStateSummary.unresolved(pointRows, bound, bound, reason);
		EvidenceStateRef state;
		if (!isComposableState(input) || outputKey == null) {
			state = arena.deriveBoundBoundary(input, outputLayout(relationId), summary, relationId);
		} else {
			boolean lineageSpecific = arena.nearestCalibration(input) != null;
			state = lineageSpecific ? null : arena.find(outputKey);
			if (state == null) {
				state = arena.deriveSummary(
						outputKey,
						summary,
						FrontierStateOperation.UNRESOLVED,
						input,
						null,
						relationId);
			}
		}
		if (state.stateId() >= stateReferences.length || stateReferences[state.stateId()] == null) {
			rememberState(state);
		}
		output.setEvidenceStateId(state.stateId());
		annotateState(output, state, "degraded");
		output.putPlannedStringMetric("plannedFrontierFallbackReason", reason);
		if (mode == FrontierEstimatorMode.AUTHORITATIVE) {
			setLocalOperatorPhysicalCost(output, pointRows, 0.0d, 0.0d, 0.0d, 0.0d);
		}
	}

	private void publishBinaryBoundOperator(int relationId, PackedCostEstimate output, EvidenceStateRef left,
			EvidenceStateRef right, String reason, double certifiedUpperBound) {
		double bound = finiteNonNegative(certifiedUpperBound) ? certifiedUpperBound : Double.POSITIVE_INFINITY;
		double defaultPoint = Math.min(left.summary().pointRows(), right.summary().pointRows());
		double pointRows = finiteNonNegative(output.outputRows()) ? output.outputRows() : defaultPoint;
		pointRows = Math.min(pointRows, bound);
		EvidenceStateRef state = arena.deriveBoundBoundary(
				left,
				right,
				outputLayout(relationId),
				EvidenceStateSummary.unresolved(pointRows, bound, bound, reason),
				relationId);
		rememberState(state);
		output.setEvidenceStateId(state.stateId());
		annotateState(output, state, "degraded");
		output.putPlannedStringMetric("plannedFrontierFallbackReason", reason);
		if (mode == FrontierEstimatorMode.AUTHORITATIVE) {
			setLocalOperatorPhysicalCost(
					output,
					pointRows,
					0.0d,
					right.summary().pointRows(),
					left.summary().pointRows(),
					right.summary().pointRows());
		}
	}

	private void publishCardinalityPreservingBoundary(int relationId, PackedCostEstimate output,
			EvidenceStateRef input, String reason, double expressionEvaluations) {
		EvidenceStateRef state = arena.deriveBoundBoundary(
				input, outputLayout(relationId), input.summary(), relationId);
		rememberState(state);
		output.setEvidenceStateId(state.stateId());
		annotateState(output, state, "degraded");
		output.putPlannedStringMetric("plannedFrontierFallbackReason", reason);
		if (mode == FrontierEstimatorMode.AUTHORITATIVE) {
			setLocalOperatorPhysicalCost(
					output, input.summary().pointRows(), expressionEvaluations, 0.0d, 0.0d, 0.0d);
		}
	}

	private void refineExtension(int relationId, Extension extension, EvidenceStateRef input, double rawWorkRows,
			PackedCostEstimate output) {
		if (evaluationStrategy == null) {
			degradeOperator(output, input, "extension_evaluator_unavailable");
			return;
		}
		String extensionFailure = extensionFailureReason(extension, arena.key(input).frontier());
		if (extensionFailure != null) {
			degradeOperator(output, input, extensionFailure);
			return;
		}
		FrontierMaskStrata outputMasks = extensionMaskStrata(arena.key(input).maskStrata(), extension);
		if (outputMasks == null) {
			degradeOperator(output, input, "extension_mask_strata_exhausted");
			return;
		}
		FrontierStateKey outputKey = operatorStateKey(arena.key(input), relationId, outputMasks);
		arena.declareCanonicalState(outputKey);
		FrontierLayout inputLayout = arena.key(input).frontier();
		long scratchBytes = Math.addExact(FILTER_BINDING_SCRATCH_BASE_BYTES,
				Math.multiplyExact(FILTER_BINDING_SCRATCH_SLOT_BYTES,
						Math.addExact(inputLayout.size(), outputMasks.layout().size())));
		try (FrontierMemoryReservation ignored = arena.reserveTemporary(
				scratchBytes, FrontierMemoryPurpose.TARGET_COALESCING)) {
			String[] inputNames = layoutVariables(inputLayout);
			String[] outputNames = layoutVariables(outputMasks.layout());
			ArrayBindingSet bindings = new ArrayBindingSet(outputNames);
			boolean lineageSpecific = arena.nearestCalibration(input) != null;
			EvidenceStateRef state = lineageSpecific ? null : arena.find(outputKey);
			if (state == null) {
				state = FrontierLinearTransforms.expandOuterMappings(
						arena,
						input,
						outputKey,
						relationId,
						(payload, exact, stratum, index, emitter) -> expandExtensionMapping(
								extension, payload, exact, stratum, index, inputNames, outputNames,
								bindings, outputMasks, emitter),
						settings.refinementWorkUnits());
				rememberState(state);
			}
			if (!isComposableState(state)) {
				publishDegradedState(output, state);
				return;
			}
			publishOperatorState(relationId, output, state);
			setLocalOperatorPhysicalCost(
					output,
					state.summary().pointRows(),
					saturatedMultiply(input.summary().pointRows(), extension.getElements().size()),
					0.0d,
					0.0d,
					0.0d);
		} catch (ExtensionEvaluationFailure failure) {
			degradeOperator(output, input, "extension_evaluation_failed");
		} catch (RuntimeException failure) {
			throw new PackedCostSessionFailure("extension_state_materialization_failed", failure);
		}
	}

	private void expandExtensionMapping(Extension extension, FrontierPayloadLease payload, boolean exact, int stratum,
			int index, String[] inputNames, String[] outputNames, ArrayBindingSet bindings,
			FrontierMaskStrata outputMasks, FrontierTupleEmitter emitter) {
		try {
			for (String outputName : outputNames) {
				bindings.setBinding(outputName, null);
			}
			populateBindings(payload, exact, stratum, index, inputNames, bindings);
			for (ExtensionElem element : extension.getElements()) {
				try {
					Value value = evaluationStrategy.evaluate(element.getExpr(), bindings);
					if (value != null) {
						bindings.setBinding(element.getName(), value);
					}
				} catch (ValueExprEvaluationException ignored) {
					bindings.setBinding(element.getName(), null);
				}
			}
			emitter.emit(maskStratum(outputMasks, bindings), bindingTuple(outputNames, bindings));
		} catch (IOException | QueryEvaluationException failure) {
			throw new ExtensionEvaluationFailure("Frontier extension evaluation failed", failure);
		}
	}

	private static String extensionFailureReason(Extension extension, FrontierLayout inputLayout) {
		var available = new HashSet<String>(Arrays.asList(layoutVariables(inputLayout)));
		for (ExtensionElem element : extension.getElements()) {
			if (ScalarEvaluationEffects.effectOf(element.getExpr()) != ScalarEvaluationEffects.Effect.REPEATABLE) {
				return "extension_expression_nondeterministic_or_unknown";
			}
			for (String variable : directValueExpressionVariables(element.getExpr())) {
				if (!available.contains(variable)) {
					return "extension_input_not_retained";
				}
			}
			available.add(element.getName());
		}
		return null;
	}

	private static Iterable<String> directValueExpressionVariables(ValueExpr expression) {
		var variables = new HashSet<String>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof Var variable && !variable.hasValue()) {
					variables.add(variable.getName());
				}
				node.visitChildren(this);
			}
		});
		return variables;
	}

	private void refineMultiProjection(int relationId, MultiProjection multiProjection, EvidenceStateRef input,
			double rawWorkRows, PackedCostEstimate output) {
		MultiProjectionPlan plan = multiProjectionPlan(arena.key(input).maskStrata(), multiProjection);
		if (plan == null) {
			degradeOperator(output, input, "multi_projection_layout_unavailable");
			return;
		}
		if (!isDuplicateFreeMultiProjection(input, plan)) {
			degradeOperator(output, input, "multi_projection_duplicate_suppression_unresolved");
			return;
		}
		FrontierStateKey outputKey = operatorStateKey(arena.key(input), relationId, plan.outputMasks());
		arena.declareCanonicalState(outputKey);
		try {
			boolean lineageSpecific = arena.nearestCalibration(input) != null;
			EvidenceStateRef state = lineageSpecific ? null : arena.find(outputKey);
			if (state == null) {
				long[] tupleScratch = new long[plan.outputMasks().layout().size()];
				state = FrontierLinearTransforms.expandOuterMappings(
						arena,
						input,
						outputKey,
						relationId,
						(payload, exact, stratum, index, emitter) -> expandMultiProjectionMapping(
								plan, payload, exact, stratum, index, tupleScratch, emitter),
						settings.refinementWorkUnits());
				rememberState(state);
			}
			if (!isComposableState(state)) {
				publishDegradedState(output, state);
				return;
			}
			publishOperatorState(relationId, output, state);
		} catch (RuntimeException failure) {
			throw new PackedCostSessionFailure("multi_projection_state_materialization_failed", failure);
		}
	}

	private void refineBoundedMultiProjection(int relationId, MultiProjection multiProjection,
			EvidenceStateRef input, PackedCostEstimate output) {
		double upperBound = saturatedMultiply(
				input.summary().certifiedUpperBound(), multiProjection.getProjections().size());
		publishBoundOperator(
				relationId,
				output,
				input,
				null,
				"multi_projection_input_payload_unavailable",
				upperBound);
	}

	private boolean isDuplicateFreeMultiProjection(EvidenceStateRef input, MultiProjectionPlan plan) {
		if (input.summary().guarantee() != EvidenceGuarantee.DATABASE_EXACT) {
			return isStructurallyInjectiveMultiProjection(arena.key(input).maskStrata(), plan);
		}
		try (FrontierPayloadLease payload = arena.openPayload(input)) {
			int entryCount = payloadEntryCount(payload);
			long[] projected = new long[Math.addExact(plan.outputMasks().layout().size(), 1)];
			for (int projection = 0; projection < plan.sourceSlots().length; projection++) {
				try (ExactLeafAccumulator projectedMappings = new ExactLeafAccumulator(
						arena, entryCount, projected.length)) {
					for (int stratum = 0; stratum < payload.stratumCount(); stratum++) {
						if (payload.residualCount(stratum) != 0) {
							return false;
						}
						for (int index = 0; index < payload.exactCount(stratum); index++) {
							if (payload.exactWeight(stratum, index) != 1.0d) {
								return false;
							}
							Arrays.fill(projected, 0L);
							projected[0] = plan.targetStrata()[projection][stratum] + 1L;
							for (int element = 0; element < plan.sourceSlots()[projection].length; element++) {
								int sourceSlot = plan.sourceSlots()[projection][element];
								if (sourceSlot >= 0 && payload.masks().isBound(stratum, sourceSlot)) {
									projected[plan.targetSlots()[projection][element] + 1] = payload.exactTermId(
											stratum, index, sourceSlot);
								}
							}
							projectedMappings.add(projected, 1.0d);
						}
					}
					if (projectedMappings.size() != entryCount) {
						return false;
					}
				}
			}
			return true;
		}
	}

	private static boolean isStructurallyInjectiveMultiProjection(
			FrontierMaskStrata inputMasks, MultiProjectionPlan plan) {
		int inputWidth = inputMasks.layout().size();
		int outputWidth = plan.outputMasks().layout().size();
		boolean[] canBeBound = new boolean[inputWidth];
		for (int stratum = 0; stratum < inputMasks.stratumCount(); stratum++) {
			for (int inputSlot = 0; inputSlot < inputWidth; inputSlot++) {
				canBeBound[inputSlot] |= inputMasks.isBound(stratum, inputSlot);
			}
		}
		for (int projection = 0; projection < plan.sourceSlots().length; projection++) {
			boolean[] retainedInput = new boolean[inputWidth];
			int[] sourceByOutput = new int[outputWidth];
			Arrays.fill(sourceByOutput, -1);
			for (int element = 0; element < plan.sourceSlots()[projection].length; element++) {
				int sourceSlot = plan.sourceSlots()[projection][element];
				int targetSlot = plan.targetSlots()[projection][element];
				if (sourceSlot < 0) {
					continue;
				}
				int previousSource = sourceByOutput[targetSlot];
				if (previousSource >= 0 && previousSource != sourceSlot) {
					return false;
				}
				sourceByOutput[targetSlot] = sourceSlot;
				retainedInput[sourceSlot] = true;
			}
			for (int inputSlot = 0; inputSlot < inputWidth; inputSlot++) {
				if (canBeBound[inputSlot] && !retainedInput[inputSlot]) {
					return false;
				}
			}
		}
		return true;
	}

	private static void expandMultiProjectionMapping(MultiProjectionPlan plan, FrontierPayloadLease payload,
			boolean exact, int sourceStratum, int sourceIndex, long[] tupleScratch, FrontierTupleEmitter emitter) {
		for (int projection = 0; projection < plan.sourceSlots().length; projection++) {
			Arrays.fill(tupleScratch, 0L);
			int[] sourceSlots = plan.sourceSlots()[projection];
			int[] targetSlots = plan.targetSlots()[projection];
			for (int element = 0; element < sourceSlots.length; element++) {
				int sourceSlot = sourceSlots[element];
				if (sourceSlot >= 0 && payload.masks().isBound(sourceStratum, sourceSlot)) {
					tupleScratch[targetSlots[element]] = payloadTermId(
							payload, exact, sourceStratum, sourceIndex, sourceSlot);
				}
			}
			emitter.emit(plan.targetStrata()[projection][sourceStratum], tupleScratch);
		}
	}

	private void refineUnion(int relationId, Union union, EvidenceStateRef left, EvidenceStateRef right,
			double rawWorkRows, PackedCostEstimate output) {
		if (!isComposableState(left) || !isComposableState(right)) {
			publishUnionBoundary(relationId, output, left, right, "union_child_state_non_composable");
			return;
		}
		if (!sameSamplingIdentity(arena.key(left), arena.key(right))
				|| !sameEstimatorSemantics(arena.key(left), arena.key(right))) {
			publishUnionBoundary(relationId, output, left, right, "union_state_unavailable");
			return;
		}
		FrontierMaskStrata outputMasks = unionMaskStrata(
				arena.key(left).maskStrata(),
				arena.key(right).maskStrata());
		left = alignUnionBranch(left, outputMasks, relationId);
		right = alignUnionBranch(right, outputMasks, relationId);
		FrontierStateKey outputKey = combinedOperatorStateKey(
				arena.key(left), arena.key(right), relationId, outputMasks);
		if (outputKey == null) {
			publishUnionBoundary(relationId, output, left, right, "union_state_unavailable");
			return;
		}
		arena.declareCanonicalState(outputKey);
		try {
			boolean lineageSpecific = arena.nearestCalibration(left) != null
					|| arena.nearestCalibration(right) != null;
			EvidenceStateRef state = lineageSpecific ? null : arena.find(outputKey);
			if (state == null) {
				state = FrontierLinearTransforms.union(arena, left, right, outputKey, relationId);
				rememberState(state);
			}
			publishOperatorState(relationId, output, state);
		} catch (RuntimeException failure) {
			throw new PackedCostSessionFailure("union_state_materialization_failed", failure);
		}
	}

	private void refineIntersection(int relationId, EvidenceStateRef left, EvidenceStateRef right,
			PackedCostEstimate output) {
		double upperBound = Math.min(
				left.summary().certifiedUpperBound(), right.summary().certifiedUpperBound());
		if (!isComposableState(left)
				|| !isComposableState(right)
				|| left.summary().guarantee() != EvidenceGuarantee.DATABASE_EXACT
				|| right.summary().guarantee() != EvidenceGuarantee.DATABASE_EXACT) {
			publishBinaryBoundOperator(relationId, output, left, right,
					"intersection_requires_database_exact_support", upperBound);
			return;
		}
		if (!sameSamplingIdentity(arena.key(left), arena.key(right))
				|| !sameEstimatorSemantics(arena.key(left), arena.key(right))) {
			publishBinaryBoundOperator(relationId, output, left, right,
					"intersection_state_identity_mismatch", upperBound);
			return;
		}
		FrontierMaskStrata outputMasks = unionMaskStrata(
				arena.key(left).maskStrata(), arena.key(right).maskStrata());
		left = alignUnionBranch(left, outputMasks, relationId);
		right = alignUnionBranch(right, outputMasks, relationId);
		FrontierStateKey outputKey = combinedOperatorStateKey(
				arena.key(left), arena.key(right), relationId, outputMasks);
		if (outputKey == null) {
			publishBinaryBoundOperator(relationId, output, left, right,
					"intersection_state_unavailable", upperBound);
			return;
		}
		arena.declareCanonicalState(outputKey);
		try {
			boolean lineageSpecific = arena.nearestCalibration(left) != null
					|| arena.nearestCalibration(right) != null;
			EvidenceStateRef state = lineageSpecific ? null : arena.find(outputKey);
			if (state == null) {
				state = FrontierLinearTransforms.intersection(arena, left, right, outputKey, relationId);
				rememberState(state);
			}
			publishOperatorState(relationId, output, state);
			setLocalOperatorPhysicalCost(
					output,
					state.summary().pointRows(),
					0.0d,
					right.summary().pointRows(),
					left.summary().pointRows(),
					right.summary().pointRows());
		} catch (RuntimeException failure) {
			throw new PackedCostSessionFailure("intersection_state_materialization_failed", failure);
		}
	}

	private void refineOptional(int relationId, PackedCostContext context, LeftJoin optional, EvidenceStateRef input,
			double rawWorkRows, PackedCostEstimate output) {
		FrontierMaskStrata inputMasks = arena.key(input).maskStrata();
		FrontierMaskStrata outputMasks = optionalMaskStrata(inputMasks, optional.getRightArg());
		FrontierStateKey outputKey = outputMasks == null
				? null
				: operatorStateKeyWithRelationFactors(arena.key(input), relationId, outputMasks);
		if (outputKey == null || evaluationStrategy == null) {
			degradeOperator(output, input,
					outputKey == null ? "optional_state_unavailable" : "optional_evaluator_unavailable");
			return;
		}
		arena.declareCanonicalState(outputKey);
		if (!exactLocalEvaluation(optional.getRightArg())
				|| optional.getCondition() != null && !exactLocalEvaluation(optional.getCondition())) {
			degradeOperator(output, input, "optional_rhs_not_exactly_probeable");
			return;
		}
		if (requiresUnboundedOptionalCompatibilityScan(optional.getRightArg(), inputMasks)) {
			degradeOperator(output, input, "optional_rhs_requires_unbounded_compatibility_scan");
			return;
		}
		FrontierLayout inputLayout = arena.key(input).frontier();
		FrontierLayout outputLayout = outputKey.frontier();
		long scratchBytes = Math.addExact(FILTER_BINDING_SCRATCH_BASE_BYTES,
				Math.multiplyExact(FILTER_BINDING_SCRATCH_SLOT_BYTES,
						Math.addExact(inputLayout.size(), outputLayout.size())));
		try (FrontierMemoryReservation ignored = arena.reserveTemporary(
				scratchBytes, FrontierMemoryPurpose.TARGET_COALESCING)) {
			String[] inputNames = layoutVariables(inputLayout);
			String[] outputNames = layoutVariables(outputLayout);
			ArrayBindingSet outerBindings = new ArrayBindingSet(inputNames);
			ArrayBindingSet mergedBindings = new ArrayBindingSet(outputNames);
			boolean lineageSpecific = arena.nearestCalibration(input) != null;
			EvidenceStateRef state = lineageSpecific ? null : arena.find(outputKey);
			if (state == null) {
				state = FrontierLinearTransforms.expandOuterMappings(
						arena, input, outputKey, relationId,
						(payload, exact, stratum, index, emitter) -> expandOptionalMapping(
								optional, payload, exact, stratum, index, inputNames, outputNames,
								outerBindings, mergedBindings, outputKey.maskStrata(), emitter),
						settings.refinementWorkUnits());
				rememberState(state);
			}
			if (!isComposableState(state)) {
				publishDegradedState(output, state);
				return;
			}
			publishOperatorState(relationId, output, state);
			double conditionEvaluations = optional.getCondition() == null
					? 0.0d
					: evidenceRows(context.rightInputEvidenceStateId(), context.rightInputRows());
			output.setLocalPhysicalCost(
					0.0d,
					0.0d,
					0.0d,
					conditionEvaluations,
					0.0d,
					0.0d,
					0.0d,
					state.summary().pointRows(),
					0.0d,
					0.0d);
		} catch (OuterProbeFailure failure) {
			degradeOperator(output, input, "optional_exact_probe_failed");
		} catch (RuntimeException failure) {
			throw new PackedCostSessionFailure("optional_state_materialization_failed", failure);
		}
	}

	private void expandOptionalMapping(LeftJoin optional, FrontierPayloadLease payload, boolean exact, int stratum,
			int index, String[] inputNames, String[] outputNames, ArrayBindingSet outerBindings,
			ArrayBindingSet mergedBindings, FrontierMaskStrata outputMasks, FrontierTupleEmitter emitter) {
		try {
			populateBindings(payload, exact, stratum, index, inputNames, outerBindings);
			boolean matched = false;
			try (CloseableIteration<BindingSet> matches = evaluationStrategy.evaluate(
					optional.getRightArg(), outerBindings)) {
				while (matches.hasNext()) {
					BindingSet right = matches.next();
					populateMergedBindings(outputNames, outerBindings, right, mergedBindings);
					if (!optionalConditionAccepts(optional, mergedBindings)) {
						continue;
					}
					emitter.emit(maskStratum(outputMasks, mergedBindings),
							bindingTuple(outputNames, mergedBindings));
					matched = true;
				}
			}
			if (!matched) {
				populateMergedBindings(outputNames, outerBindings, null, mergedBindings);
				emitter.emit(maskStratum(outputMasks, mergedBindings),
						bindingTuple(outputNames, mergedBindings));
			}
		} catch (IOException | QueryEvaluationException failure) {
			throw new OuterProbeFailure("Frontier OPTIONAL exact probe failed", failure);
		}
	}

	private boolean optionalConditionAccepts(LeftJoin optional, ArrayBindingSet bindings)
			throws QueryEvaluationException {
		if (optional.getCondition() == null) {
			return true;
		}
		try {
			return evaluationStrategy.isTrue(optional.getCondition(), bindings);
		} catch (ValueExprEvaluationException ignored) {
			return false;
		}
	}

	private static void populateMergedBindings(String[] outputNames, BindingSet outer, BindingSet right,
			ArrayBindingSet merged) {
		for (String name : outputNames) {
			Value value = right == null ? null : right.getValue(name);
			if (value == null) {
				value = outer.getValue(name);
			}
			merged.setBinding(name, value);
		}
	}

	private long[] bindingTuple(String[] names, BindingSet bindings) throws IOException {
		long[] tuple = new long[names.length];
		for (int slot = 0; slot < names.length; slot++) {
			Value value = bindings.getValue(names[slot]);
			if (value == null) {
				continue;
			}
			tuple[slot] = encodeFrontierValue(value);
		}
		return tuple;
	}

	private static int maskStratum(FrontierMaskStrata masks, BindingSet bindings) {
		for (int stratum = 0; stratum < masks.stratumCount(); stratum++) {
			boolean matches = true;
			for (int slot = 0; slot < masks.layout().size(); slot++) {
				if (masks.isBound(stratum, slot) != bindings.hasBinding(masks.layout().variable(slot))) {
					matches = false;
					break;
				}
			}
			if (matches) {
				return stratum;
			}
		}
		throw new IllegalStateException("OPTIONAL produced an undeclared bound-mask stratum");
	}

	private void refineMinus(int relationId, PackedCostContext context, Difference minus, EvidenceStateRef input,
			double rawWorkRows, PackedCostEstimate output) {
		EvidenceStateRef probeInput = averageIndependentDesignState(input, relationId);
		FrontierStateKey outputKey = operatorStateKeyWithRelationFactors(
				arena.key(probeInput), relationId, arena.key(probeInput).maskStrata());
		if (outputKey == null || evaluationStrategy == null) {
			degradeOperator(output, input,
					outputKey == null ? "minus_state_unavailable" : "minus_evaluator_unavailable");
			return;
		}
		arena.declareCanonicalState(outputKey);
		if (!exactLocalEvaluation(minus.getRightArg())) {
			degradeOperator(output, input, "minus_rhs_not_exactly_probeable");
			return;
		}
		FrontierLayout layout = arena.key(probeInput).frontier();
		int[] sharedSlots = sharedSlots(layout, minus.getRightArg());
		long scratchBytes = Math.addExact(FILTER_BINDING_SCRATCH_BASE_BYTES,
				Math.multiplyExact(FILTER_BINDING_SCRATCH_SLOT_BYTES, layout.size()));
		try (FrontierMemoryReservation ignored = arena.reserveTemporary(
				scratchBytes, FrontierMemoryPurpose.TARGET_COALESCING)) {
			String[] names = layoutVariables(layout);
			ArrayBindingSet bindings = new ArrayBindingSet(names);
			boolean lineageSpecific = arena.nearestCalibration(probeInput) != null;
			EvidenceStateRef state = lineageSpecific ? null : arena.find(outputKey);
			ExactProbeBudget exactProbeBudget = exactProbeBudget(probeInput, minus.getRightArg());
			output.putPlannedDoubleMetric("plannedFrontierExactProbeBoundWorkPerKey",
					exactProbeBudget.boundWorkPerKey());
			output.putPlannedDoubleMetric("plannedFrontierExactProbeDependentPlanWorkPerKey",
					exactProbeBudget.dependentPlanWorkPerKey());
			output.putPlannedDoubleMetric("plannedFrontierExactProbeEstimatedWorkPerKey",
					exactProbeBudget.estimatedWorkPerKey());
			output.putPlannedDoubleMetric("plannedFrontierExactProbeMaximumMappings",
					exactProbeBudget.maximumMappings());
			output.putPlannedDoubleMetric("plannedFrontierExactProbeWorkBudget",
					settings.refinementWorkUnits());
			if (state == null) {
				state = FrontierLinearTransforms.resolveProjectedOuterKernel(arena, probeInput, outputKey, relationId,
						FrontierOuterKernel.MINUS,
						(payload, exact, stratum, index) -> minusMatchMultiplicity(
								minus, payload, exact, stratum, index, sharedSlots, names, bindings),
						exactProbeBudget.maximumMappings(), 1.0d);
				rememberState(state);
			}
			if (!isComposableState(state)) {
				publishDegradedState(output, state);
				return;
			}
			if (probeInput.stateId() != input.stateId()) {
				output.putPlannedStringMetric(
						"plannedFrontierVarianceReduction", "independent_design_lane_average");
			}
			publishOperatorState(relationId, output, state);
			applySelectedMinusPhysicalCost(relationId, context, minus, input, state, output);
		} catch (OuterProbeFailure failure) {
			degradeOperator(output, input, "minus_exact_probe_failed");
		} catch (RuntimeException failure) {
			throw new PackedCostSessionFailure("minus_state_materialization_failed", failure);
		}
	}

	private void applySelectedMinusPhysicalCost(int relationId, PackedCostContext context, Difference minus,
			EvidenceStateRef input, EvidenceStateRef outputState, PackedCostEstimate output) {
		int algorithm = semiAntiAlgorithm(
				output.plannedStringMetric("optimizer.semiAntiAlgorithm"), -1);
		if (algorithm < 0) {
			/*
			 * The unre-written Difference implementation is MinusQueryEvaluationStep: it materializes the complete
			 * right input and compatibility-probes that hash table for every left row. Frontier may refine the exact
			 * result cardinality without changing that physical implementation. Retain the implementation's
			 * independently measurable work dimensions instead of replacing them with result production alone;
			 * otherwise the generic Difference falsely dominates the typed correlated alternatives that were costed
			 * beside it.
			 */
			applyScalarDifferencePhysicalCost(context, Double.NaN, output);
			return;
		}
		TupleExpr rhs = minus.getRightArg();
		SemiAntiBindingDomains bindingDomains = semiAntiBindingDomains(
				arena.key(input).frontier().variables(), rhs);
		double rhsRows = estimatedTupleRows(rhs);
		FrontierSemiAntiProfile profile = correlationProfile(
				input,
				outputState,
				bindingDomains,
				relationId,
				PackedQueryView.SEMI_ANTI_MINUS_ASSURED_SHARED,
				context == null ? Double.NaN : context.leftInputRows(),
				semiAntiFactOuterRowsFloor(relationId, context, outputState, output));
		annotateCorrelationProfile(output, profile);
		Filter feedbackFilter = new Filter(
				minus.getLeftArg().clone(),
				new Not(new Exists(rhs.clone())));
		applyFrontierSemiAntiPhysicalCost(
				feedbackFilter,
				PackedQueryView.SEMI_ANTI_MINUS_ASSURED_SHARED,
				algorithm,
				rhs,
				rhsRows,
				profile,
				output);
	}

	private long minusMatchMultiplicity(Difference minus, FrontierPayloadLease payload, boolean exact, int stratum,
			int index, int[] sharedSlots, String[] names, ArrayBindingSet bindings) {
		if (!hasBoundDomainOverlap(payload, stratum, sharedSlots)) {
			return 0L;
		}
		try {
			populateBindings(payload, exact, stratum, index, names, bindings);
			try (CloseableIteration<BindingSet> matches = evaluationStrategy.evaluate(minus.getRightArg(), bindings)) {
				return matches.hasNext() ? 1L : 0L;
			}
		} catch (IOException | QueryEvaluationException failure) {
			throw new OuterProbeFailure("Frontier MINUS exact probe failed", failure);
		}
	}

	private void populateBindings(FrontierPayloadLease payload, boolean exact, int stratum, int index,
			String[] names, ArrayBindingSet bindings) throws IOException {
		for (int slot = 0; slot < names.length; slot++) {
			Value value = null;
			if (payload.masks().isBound(stratum, slot)) {
				value = frontierValue(payloadTermId(payload, exact, stratum, index, slot));
				if (value == null) {
					throw new IOException("retained Frontier term is absent from the value store");
				}
			}
			bindings.setBinding(names[slot], value);
		}
	}

	private static boolean hasBoundDomainOverlap(FrontierPayloadLease payload, int stratum, int[] sharedSlots) {
		for (int sharedSlot : sharedSlots) {
			if (payload.masks().isBound(stratum, sharedSlot)) {
				return true;
			}
		}
		return false;
	}

	private static int[] sharedSlots(FrontierLayout layout, TupleExpr right) {
		var rightBindings = right.getBindingNames();
		int count = 0;
		for (int slot = 0; slot < layout.size(); slot++) {
			count += rightBindings.contains(layout.variable(slot)) ? 1 : 0;
		}
		int[] shared = new int[count];
		int next = 0;
		for (int slot = 0; slot < layout.size(); slot++) {
			if (rightBindings.contains(layout.variable(slot))) {
				shared[next++] = slot;
			}
		}
		return shared;
	}

	private static String[] layoutVariables(FrontierLayout layout) {
		String[] names = new String[layout.size()];
		for (int slot = 0; slot < names.length; slot++) {
			names[slot] = layout.variable(slot);
		}
		return names;
	}

	private EvidenceStateRef publishOperatorState(int relationId, PackedCostEstimate output, EvidenceStateRef state) {
		EvidenceStateSummary summary = state.summary();
		output.setEvidenceStateId(state.stateId());
		annotateReady(output, state);
		annotateFactorCount(output, state);
		output.putPlannedStringMetric("plannedPhysicalImplementation", FRONTIER_EXECUTION_MODE);
		if (!isComposableState(state)) {
			output.putPlannedStringMetric("plannedFrontierStatus", "degraded");
			output.putPlannedStringMetric("plannedFrontierFallbackReason", summary.degradationReason());
			if (mode == FrontierEstimatorMode.AUTHORITATIVE) {
				setLocalOperatorPhysicalCost(output, summary.pointRows(), 0.0d, 0.0d, 0.0d, 0.0d);
			}
			return state;
		}
		if (mode != FrontierEstimatorMode.AUTHORITATIVE) {
			return state;
		}
		if (summary.guarantee() == EvidenceGuarantee.MEASURE_UNBIASED
				&& summary.zeroStatus() == EvidenceZeroStatus.ESTIMATED_ZERO) {
			return publishSampledZeroFallback(relationId, output, state);
		}
		setLocalOperatorPhysicalCost(output, summary.pointRows(), 0.0d, 0.0d, 0.0d, 0.0d);
		output.setEvidenceGuarantee(summary.guarantee());
		setFrontierProvenance(output, state);
		return state;
	}

	/**
	 * Retains a sampled-zero payload as audit lineage without letting its zero point estimate enter later composition.
	 *
	 * <p>
	 * A design-valid sample may omit every tuple for a present mapping. In authoritative mode that estimate already
	 * falls back to the scalar event rows. Keeping the sampled state composable would let the next join reinterpret
	 * omission as absence. Publish a bound-only child whose unresolved point estimate matches the conservative rows
	 * used for ranking, while its parent retains the raw sampled-zero payload for replay and LEO. This lets subsequent
	 * supported operators continue costing from the same nonzero Frontier lineage without presenting the fallback as
	 * measured tuple evidence.
	 */
	private EvidenceStateRef publishSampledZeroFallback(int relationId, PackedCostEstimate output,
			EvidenceStateRef sampledState) {
		EvidenceStateSummary sampledSummary = sampledState.summary();
		double fallbackRows = finiteNonNegative(output.outputRows()) ? output.outputRows() : 0.0d;
		double upperRows = Math.max(fallbackRows, sampledSummary.upperRows());
		double certifiedUpperBound = Math.max(fallbackRows, sampledSummary.certifiedUpperBound());
		EvidenceStateRef boundary = arena.deriveBoundBoundary(
				sampledState,
				arena.layout(sampledState),
				EvidenceStateSummary.unresolved(fallbackRows, upperRows, certifiedUpperBound,
						"sampled_zero_not_authoritative"),
				Math.max(0, relationId));
		rememberState(boundary);
		publishDegradedState(output, boundary);
		output.putPlannedDoubleMetric("plannedFrontierSampledRows", sampledSummary.pointRows());
		output.putPlannedDoubleMetric("plannedFrontierFallbackRows", fallbackRows);
		return boundary;
	}

	private static void setLocalOperatorPhysicalCost(PackedCostEstimate output, double resultRows,
			double expressionEvaluations, double hashBuildRows, double hashProbeRows, double peakMemoryRows) {
		boolean contextualRows = output.hasContextualOutputRows();
		boolean componentRows = output.hasComponentOutputRows();
		output.setLocalPhysicalCost(
				0.0d,
				0.0d,
				0.0d,
				expressionEvaluations,
				hashBuildRows,
				hashProbeRows,
				0.0d,
				resultRows,
				0.0d,
				peakMemoryRows);
		if (componentRows) {
			output.setComponentOutputRowsPreservingPhysicalCost(resultRows);
		} else if (contextualRows) {
			output.setContextualOutputRowsPreservingPhysicalCost(resultRows);
		} else {
			output.setOutputRowsPreservingPhysicalCost(resultRows);
		}
	}

	private static void setLocalAccessPhysicalCost(PackedCostEstimate output, double resultRows,
			boolean lmdbStatementAccess) {
		boolean contextualRows = output.hasContextualOutputRows();
		boolean componentRows = output.hasComponentOutputRows();
		double invocations = finiteNonNegative(output.invocations()) ? output.invocations() : 0.0d;
		boolean describedAccess = lmdbStatementAccess
				&& output.indexName() != null
				&& finiteNonNegative(output.accessRows());
		double sequentialRows = describedAccess
				? saturatedMultiply(output.accessRows(), invocations)
				: lmdbStatementAccess && finiteNonNegative(output.sequentialRows()) ? output.sequentialRows() : 0.0d;
		double randomSeeks = describedAccess ? invocations : 0.0d;
		double iteratorOpens = describedAccess ? invocations : 0.0d;
		output.setLocalPhysicalCost(
				sequentialRows,
				randomSeeks,
				iteratorOpens,
				0.0d,
				0.0d,
				0.0d,
				0.0d,
				resultRows,
				0.0d,
				0.0d);
		if (componentRows) {
			output.setComponentOutputRowsPreservingPhysicalCost(resultRows);
		} else if (contextualRows) {
			output.setContextualOutputRowsPreservingPhysicalCost(resultRows);
		} else {
			output.setOutputRowsPreservingPhysicalCost(resultRows);
		}
	}

	private void setFrontierFactorPhysicalCost(int relationId, PackedCostEstimate output, double resultRows) {
		if (query.isBindingSetAssignment(relationId)) {
			preservePhysicalCostWithRows(output, resultRows);
			return;
		}
		setLocalAccessPhysicalCost(output, resultRows, query.isStatementPattern(relationId));
	}

	private static void preservePhysicalCostWithRows(PackedCostEstimate output, double resultRows) {
		if (output.hasComponentOutputRows()) {
			output.setComponentOutputRowsPreservingPhysicalCost(resultRows);
		} else if (output.hasContextualOutputRows()) {
			output.setContextualOutputRowsPreservingPhysicalCost(resultRows);
		} else {
			output.setOutputRowsPreservingPhysicalCost(resultRows);
		}
	}

	private void setFrontierProvenance(PackedCostEstimate output, EvidenceStateRef state) {
		EvidenceCalibrationSummary calibration = arena.nearestCalibration(state);
		if (calibration == null) {
			output.setEstimateProvenance(FRONTIER_SOURCE, "frontier_authoritative");
			return;
		}
		if (FRONTIER_EXACT_FACT_CALIBRATION_SOURCE.equals(calibration.source())) {
			output.setEstimateProvenance(FRONTIER_LEO_SOURCE, "frontier_exact_fact");
			return;
		}
		CalibrationStages stages = calibrationStages(state);
		if (stages.unambiguous() && stages.learnedFilterPresent() && stages.leoPresent()) {
			output.setEstimateProvenance(
					FRONTIER_LEARNED_FILTER_LEO_SOURCE, "frontier_learned_filter_then_leo_residual");
			return;
		}
		boolean learnedFilter = calibration.source().startsWith("learned-filter");
		output.setEstimateProvenance(
				learnedFilter ? FRONTIER_LEARNED_FILTER_SOURCE : FRONTIER_LEO_SOURCE,
				learnedFilter ? "frontier_learned_filter_calibration" : "frontier_learned_calibration");
	}

	private EvidenceStateRef restrictFilter(EvidenceStateRef input, FrontierStateKey outputKey, int relationId,
			Filter filter) {
		FrontierLayout layout = arena.key(input).frontier();
		long scratchBytes = Math.addExact(FILTER_BINDING_SCRATCH_BASE_BYTES,
				Math.multiplyExact(FILTER_BINDING_SCRATCH_SLOT_BYTES, layout.size()));
		try (FrontierMemoryReservation ignored = arena.reserveTemporary(
				scratchBytes, FrontierMemoryPurpose.TARGET_COALESCING)) {
			String[] names = new String[layout.size()];
			for (int slot = 0; slot < names.length; slot++) {
				names[slot] = layout.variable(slot);
			}
			ArrayBindingSet bindings = new ArrayBindingSet(names);
			return FrontierLinearTransforms.restrict(arena, input, outputKey, relationId,
					(payload, exact, stratum, index) -> evaluateFilterTuple(
							filter, payload, exact, stratum, index, names, bindings));
		}
	}

	private boolean evaluateFilterTuple(Filter filter, FrontierPayloadLease payload, boolean exact, int stratum,
			int index, String[] names, ArrayBindingSet bindings) {
		try {
			for (int slot = 0; slot < names.length; slot++) {
				Value value = null;
				if (payload.masks().isBound(stratum, slot)) {
					long termId = payloadTermId(payload, exact, stratum, index, slot);
					value = frontierValue(termId);
					if (value == null) {
						throw new FilterEvaluationFailure("retained Frontier term is absent from the value store");
					}
				}
				bindings.setBinding(names[slot], value);
			}
			return evaluationStrategy.isTrue(filter.getCondition(), bindings);
		} catch (ValueExprEvaluationException ignored) {
			return false;
		} catch (IOException | QueryEvaluationException failure) {
			throw new FilterEvaluationFailure("Frontier filter evaluation failed", failure);
		}
	}

	private static boolean filterCanInspectRetainedState(Filter filter, FrontierLayout layout) {
		boolean[] deterministic = { true };
		filter.getCondition().visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (!deterministic[0]) {
					return;
				}
				if (node instanceof Exists exists) {
					/*
					 * A locally evaluable EXISTS remains a deterministic predicate of the retained outer tuple even
					 * when it is nested under AND, OR, or another scalar expression. The ordinary restriction kernel
					 * evaluates the complete expression against that tuple, preserving tuple covariance and the input
					 * design weights.
					 */
					deterministic[0] = exactExistsCanEvaluate(exists);
					return;
				}
				if (node instanceof FunctionCall || node instanceof BNodeGenerator) {
					deterministic[0] = false;
					return;
				}
				node.visitChildren(this);
			}
		});
		if (!deterministic[0]) {
			return false;
		}
		for (String variable : directConditionVariables(filter)) {
			if (layout.indexOf(variable) < 0) {
				return false;
			}
		}
		return true;
	}

	private static boolean exactExistsCanEvaluate(Exists exists) {
		return exactLocalEvaluation(exists.getSubQuery());
	}

	private static boolean exactLocalEvaluation(QueryModelNode expression) {
		boolean[] exactLocalEvaluation = { true };
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (!exactLocalEvaluation[0]) {
					return;
				}
				if (node instanceof Service || node instanceof TupleFunctionCall) {
					exactLocalEvaluation[0] = false;
					return;
				}
				if (node instanceof ValueExpr valueExpression) {
					exactLocalEvaluation[0] = ScalarEvaluationEffects.reorderingIsSafe(valueExpression);
					return;
				}
				node.visitChildren(this);
			}
		});
		return exactLocalEvaluation[0];
	}

	private static boolean requiresUnboundedOptionalCompatibilityScan(
			TupleExpr rightArgument, FrontierMaskStrata outerMasks) {
		HashSet<String> possiblyBoundOuterVariables = new HashSet<>();
		FrontierLayout outerLayout = outerMasks.layout();
		for (int slot = 0; slot < outerLayout.size(); slot++) {
			for (int stratum = 0; stratum < outerMasks.stratumCount(); stratum++) {
				if (outerMasks.isBound(stratum, slot)) {
					possiblyBoundOuterVariables.add(outerLayout.variable(slot));
					break;
				}
			}
		}
		if (possiblyBoundOuterVariables.isEmpty()) {
			return false;
		}

		boolean[] requiresScan = { false };
		rightArgument.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (requiresScan[0]) {
					return;
				}
				if (node instanceof LeftJoin nestedOptional) {
					HashSet<String> optionalVariables = new HashSet<>(
							nestedOptional.getRightArg().getBindingNames());
					if (nestedOptional.getCondition() != null) {
						nestedOptional.getCondition().visit(new AbstractQueryModelVisitor<RuntimeException>() {
							@Override
							public void meet(Var variable) {
								if (!variable.hasValue()) {
									optionalVariables.add(variable.getName());
								}
							}
						});
					}
					optionalVariables.removeAll(nestedOptional.getLeftArg().getBindingNames());
					for (String variable : optionalVariables) {
						if (possiblyBoundOuterVariables.contains(variable)) {
							requiresScan[0] = true;
							return;
						}
					}
				}
				node.visitChildren(this);
			}
		});
		return requiresScan[0];
	}

	private static Iterable<String> directConditionVariables(Filter filter) {
		var variables = new HashSet<String>();
		filter.getCondition().visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof Exists) {
					return;
				}
				node.visitChildren(this);
			}

			@Override
			public void meet(Var variable) {
				if (!variable.hasValue()) {
					variables.add(variable.getName());
				}
			}
		});
		return variables;
	}

	private void degradeOperator(PackedCostEstimate output, EvidenceStateRef input, String reason) {
		degradeOperator(0, output, input, reason);
	}

	private void publishDegradedState(PackedCostEstimate output, EvidenceStateRef state) {
		output.setEvidenceStateId(state.stateId());
		annotateState(output, state, "degraded");
		annotateFactorCount(output, state);
		output.putPlannedStringMetric("plannedFrontierFallbackReason", state.summary().degradationReason());
	}

	private void publishNonComposableAppend(int relationId, PackedCostEstimate output, EvidenceStateRef input,
			EvidenceStateRef factor, FrontierLayout outputLayout, String reason) {
		EvidenceGuarantee estimateGuarantee = output.evidenceGuarantee();
		double pointRows = finiteNonNegative(output.outputRows())
				? output.outputRows()
				: saturatedMultiply(input.summary().pointRows(), factor.summary().pointRows());
		EvidenceStateRef boundary = arena.deriveOpaqueBoundary(
				input,
				factor,
				outputLayout,
				EvidenceStateSummary.unresolved(pointRows, Double.POSITIVE_INFINITY,
						Double.POSITIVE_INFINITY, reason),
				relationId);
		rememberState(boundary);
		output.setEvidenceStateId(boundary.stateId());
		annotateState(output, boundary, "degraded");
		annotateFactorCount(output, boundary);
		if (estimateGuarantee != null) {
			/*
			 * An exact scalar access surface and a composable Frontier payload are independent properties. In
			 * particular, a bounded finite lookup may count its rows exactly even when an earlier opaque boundary
			 * prevents tuple-level Frontier composition. Retain that event-local cardinality guarantee while the
			 * boundary state honestly remains unresolved and non-composable.
			 */
			output.setEvidenceGuarantee(estimateGuarantee);
		}
		output.putPlannedStringMetric("plannedFrontierFallbackReason", reason);
	}

	private void degradeBinaryOperator(int relationId, PackedCostEstimate output, EvidenceStateRef left,
			EvidenceStateRef right, String reason) {
		if (left == null || right == null) {
			degradeOperator(relationId, output, left != null ? left : right, reason);
			return;
		}
		double pointRows = finiteNonNegative(output.outputRows())
				? output.outputRows()
				: Math.max(left.summary().pointRows(), right.summary().pointRows());
		EvidenceStateRef boundary = arena.deriveOpaqueBoundary(
				left,
				right,
				outputLayout(relationId),
				EvidenceStateSummary.unresolved(pointRows, Double.POSITIVE_INFINITY,
						Double.POSITIVE_INFINITY, reason),
				relationId);
		rememberState(boundary);
		output.setEvidenceStateId(boundary.stateId());
		annotateState(output, boundary, "degraded");
		annotateFactorCount(output, boundary);
		output.putPlannedStringMetric("plannedFrontierFallbackReason", reason);
	}

	private void publishUnionBoundary(int relationId, PackedCostEstimate output, EvidenceStateRef left,
			EvidenceStateRef right, String reason) {
		if (left == null || right == null) {
			degradeOperator(relationId, output, left != null ? left : right, reason);
			return;
		}
		double pointRows = saturatedAdd(left.summary().pointRows(), right.summary().pointRows());
		double certifiedUpperBound = saturatedAdd(
				left.summary().certifiedUpperBound(), right.summary().certifiedUpperBound());
		EvidenceStateRef boundary = arena.deriveBoundBoundary(
				left,
				right,
				outputLayout(relationId),
				EvidenceStateSummary.unresolved(
						pointRows, certifiedUpperBound, certifiedUpperBound, reason),
				relationId);
		rememberState(boundary);
		output.setEvidenceStateId(boundary.stateId());
		annotateState(output, boundary, "degraded");
		annotateFactorCount(output, boundary);
		output.putPlannedStringMetric("plannedFrontierFallbackReason", reason);
	}

	private void degradeOperator(int relationId, PackedCostEstimate output, EvidenceStateRef input, String reason) {
		if (input != null) {
			double pointRows = finiteNonNegative(output.outputRows())
					? output.outputRows()
					: input.summary().pointRows();
			EvidenceStateRef boundary = arena.deriveOpaqueBoundary(input,
					EvidenceStateSummary.unresolved(pointRows, Double.POSITIVE_INFINITY,
							Double.POSITIVE_INFINITY, reason),
					relationId);
			rememberState(boundary);
			output.setEvidenceStateId(boundary.stateId());
			annotateState(output, boundary, "degraded");
			annotateFactorCount(output, boundary);
		} else if (arena != null) {
			double pointRows = finiteNonNegative(output.outputRows()) ? output.outputRows() : 1.0d;
			EvidenceStateRef unresolved = arena.append(
					outputLayout(relationId),
					EvidenceStateSummary.unresolved(pointRows, Double.POSITIVE_INFINITY,
							Double.POSITIVE_INFINITY, reason));
			rememberState(unresolved);
			output.setEvidenceStateId(unresolved.stateId());
			annotateState(output, unresolved, "degraded");
			annotateFactorCount(output, unresolved);
		} else {
			output.setEvidenceStateId(0);
			output.putPlannedStringMetric("plannedFrontierStatus", "degraded");
			output.putPlannedStringMetric("plannedFrontierMode", mode.getConfigValue());
		}
		output.putPlannedStringMetric("plannedFrontierFallbackReason", reason);
	}

	private FrontierLayout outputLayout(int relationId) {
		if (relationId <= 0) {
			return FrontierLayout.empty();
		}
		String[] variables = query.materializeRelation(relationId).getBindingNames().toArray(String[]::new);
		Arrays.sort(variables);
		return FrontierLayout.of(variables);
	}

	private EvidenceStateRef extendInner(EvidenceStateRef input, LeafState factor, FrontierStateKey outputKey,
			int operationRecipeId) {
		ExactExpansionScanBudget scanBudget = new ExactExpansionScanBudget(settings.refinementWorkUnits());
		try (FrontierPayloadLease payload = arena.openPayload(input)) {
			boolean learnedInput = arena.nearestCalibration(input) != null;
			int inputEntries = payloadEntryCount(payload);
			/*
			 * Refinement work units count candidate probes, independently of the access kernel used to answer them. The
			 * mapped query index changes the physical cost of a probe, but it does not create additional statistical
			 * work budget. Keeping the configured limit literal also bounds planning time when an exact source is
			 * large.
			 */
			long probeBudget = settings.refinementWorkUnits();
			int[] drawCounts = null;
			double resampledEntryMass = 0.0d;
			FrontierMemoryReservation drawCountReservation = null;
			try {
				if (inputEntries > probeBudget) {
					/*
					 * A bag beyond the probe budget is resampled to it with conditionally unbiased fixed-capacity
					 * multinomial draws instead of surrendering to the scalar estimator; a zero budget still means no
					 * probes are permitted. Resampling turns even a database-exact input into sampled evidence.
					 */
					int target = (int) Math.min(probeBudget, Integer.MAX_VALUE);
					if (target <= 0) {
						return arena.intern(outputKey, EvidenceStateSummary.unresolved(input.summary().pointRows(),
								Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY,
								"frontier exact probe budget exhausted"));
					}
					drawCountReservation = arena.reserveTemporary(
							retainedArrayBytes(inputEntries, Integer.BYTES), FrontierMemoryPurpose.ARRAY_GROWTH);
					try (FrontierMemoryReservation weightScratch = arena.reserveTemporary(
							Math.multiplyExact(2L, retainedArrayBytes(inputEntries, Double.BYTES)),
							FrontierMemoryPurpose.ARRAY_GROWTH)) {
						double[] weights = entryWeights(payload, inputEntries);
						double totalMass = 0.0d;
						for (double weight : weights) {
							totalMass += weight;
						}
						long resampleSeed = FrontierSeedSchedule.derive(
								arena.deterministicSeed(input), FrontierRandomDomain.RESAMPLE,
								Integer.toUnsignedLong(operationRecipeId), 0L);
						drawCounts = FrontierMultinomialResampler.drawCounts(weights, target, resampleSeed);
						resampledEntryMass = totalMass / target;
					}
				}
				int outputParticleBudget = (int) Math.min(probeBudget, Integer.MAX_VALUE);
				FrontierMaskStrata outputMasks = outputKey.maskStrata();
				FrontierPayloadWriter writer = null;
				try (EmissionBuffer emissions = new EmissionBuffer(
						arena, outputMasks.layout().size(), outputParticleBudget)) {
					BridgeEmissionSurvey survey = new BridgeEmissionSurvey(emissions);
					visitMatchingRows(
							payload, factor, outputMasks, drawCounts, resampledEntryMass, scanBudget, survey);
					boolean mutated = survey.emissionCount() > outputParticleBudget;
					double mutationVariance = 0.0d;
					if (mutated) {
						if (outputParticleBudget == 0) {
							return arena.deriveSummary(
									outputKey,
									EvidenceStateSummary.unresolved(
											input.summary().pointRows(),
											Double.POSITIVE_INFINITY,
											Double.POSITIVE_INFINITY,
											"frontier-bridge-particle-budget-exhausted"),
									FrontierStateOperation.UNRESOLVED,
									input,
									null,
									operationRecipeId);
						}
						if (!Double.isFinite(survey.totalWeight())) {
							return arena.deriveSummary(
									outputKey,
									EvidenceStateSummary.unresolved(
											input.summary().pointRows(),
											Double.POSITIVE_INFINITY,
											Double.POSITIVE_INFINITY,
											"frontier-bridge-mass-overflow"),
									FrontierStateOperation.UNRESOLVED,
									input,
									null,
									operationRecipeId);
						}
						emissions.clear();
						long mutationSeed = FrontierSeedSchedule.derive(
								arena.deterministicSeed(input),
								FrontierRandomDomain.BRIDGE_NEIGHBOR,
								Integer.toUnsignedLong(operationRecipeId),
								0L);
						try (BridgeImportanceSelector selector = new BridgeImportanceSelector(
								arena,
								emissions,
								survey.emissionCount(),
								survey.totalWeight(),
								outputParticleBudget,
								mutationSeed)) {
							visitMatchingRows(
									payload, factor, outputMasks, drawCounts, resampledEntryMass, scanBudget, selector);
							selector.finish();
							mutationVariance = selector.estimatedVariance();
						}
					}
					int emissionCount = emissions.size();
					boolean exactOutput = !mutated && drawCounts == null
							&& input.summary().guarantee() == EvidenceGuarantee.DATABASE_EXACT;
					writer = materializeEmissions(outputKey, emissions, exactOutput);
					double pointRows = writer.pointRows();
					if (learnedInput && pointRows == 0.0d) {
						writer.close();
						writer = null;
						return arena.deriveSummary(
								outputKey,
								EvidenceStateSummary.unresolved(
										0.0d,
										Double.POSITIVE_INFINITY,
										Double.POSITIVE_INFINITY,
										"learned-calibrated-transform-zero-support"),
								FrontierStateOperation.UNRESOLVED,
								input,
								null,
								operationRecipeId);
					}
					EvidenceStateSummary summary = exactOutput
							? EvidenceStateSummary.exact(pointRows)
							: learnedInput
									? learnedSummary(pointRows, writer.effectiveSampleSize(),
											writer.maximumWeightFraction(), mutationVariance)
									: sampledSummary(pointRows, writer.effectiveSampleSize(),
											writer.maximumWeightFraction(), mutationVariance);
					FrontierStateOperation operation = mutated
							? FrontierStateOperation.BRIDGE_MUTATION
							: FrontierStateOperation.BRIDGE_TRANSFER;
					EvidenceStateRef output = learnedInput
							? arena.derivePayload(
									outputKey, summary, operation, input, null, operationRecipeId, writer)
							: arena.internPayload(
									outputKey, summary, operation, input, null, operationRecipeId, writer);
					writer = null;
					return output;
				} finally {
					if (writer != null) {
						writer.close();
					}
				}
			} finally {
				if (drawCountReservation != null) {
					drawCountReservation.close();
				}
			}
		} catch (ExactExpansionScanBudgetExceeded exhausted) {
			return arena.deriveSummary(
					outputKey,
					EvidenceStateSummary.unresolved(
							input.summary().pointRows(),
							Double.POSITIVE_INFINITY,
							Double.POSITIVE_INFINITY,
							"frontier exact expansion scan budget exhausted"),
					FrontierStateOperation.UNRESOLVED,
					input,
					null,
					operationRecipeId);
		} catch (IOException | QueryEvaluationException failure) {
			throw new IllegalStateException("snapshot-exact Frontier append probe failed", failure);
		}
	}

	private FrontierPayloadWriter materializeEmissions(FrontierStateKey outputKey, EmissionBuffer emissions,
			boolean exactOutput) {
		FrontierMaskStrata outputMasks = outputKey.maskStrata();
		int[] counts = new int[outputMasks.stratumCount()];
		for (int emission = 0; emission < emissions.size(); emission++) {
			int stratum = emissions.stratum(emission);
			counts[stratum] = Math.incrementExact(counts[stratum]);
		}
		if (!exactOutput) {
			FrontierPayloadWriter writer = arena.newPayloadWriter(
					outputKey, new int[counts.length], counts);
			try {
				int[] indexes = new int[counts.length];
				for (int emission = 0; emission < emissions.size(); emission++) {
					int stratum = emissions.stratum(emission);
					writer.putResidual(
							stratum,
							indexes[stratum]++,
							emissions.weight(emission),
							emissions.tuples(),
							emissions.tupleOffset(emission));
				}
				return writer;
			} catch (RuntimeException | Error failure) {
				writer.close();
				throw failure;
			}
		}

		ExactLeafAccumulator[] accumulators = new ExactLeafAccumulator[counts.length];
		FrontierPayloadWriter writer = null;
		try {
			for (int stratum = 0; stratum < counts.length; stratum++) {
				accumulators[stratum] = new ExactLeafAccumulator(
						arena, counts[stratum], outputMasks.layout().size());
			}
			for (int emission = 0; emission < emissions.size(); emission++) {
				accumulators[emissions.stratum(emission)].add(
						emissions.tuples(), emissions.tupleOffset(emission), emissions.weight(emission));
			}
			int[] exactCounts = new int[counts.length];
			for (int stratum = 0; stratum < exactCounts.length; stratum++) {
				exactCounts[stratum] = accumulators[stratum].size();
			}
			writer = arena.newPayloadWriter(outputKey, exactCounts, new int[exactCounts.length]);
			for (int stratum = 0; stratum < exactCounts.length; stratum++) {
				accumulators[stratum].writeTo(writer, stratum);
			}
			FrontierPayloadWriter completed = writer;
			writer = null;
			return completed;
		} finally {
			if (writer != null) {
				writer.close();
			}
			for (ExactLeafAccumulator accumulator : accumulators) {
				if (accumulator != null) {
					accumulator.close();
				}
			}
		}
	}

	private EvidenceStateRef extendFinite(EvidenceStateRef input, FiniteLeafState factor, FrontierStateKey outputKey,
			int operationRecipeId) {
		try (FrontierPayloadLease inputPayload = arena.openPayload(input);
				FrontierPayloadLease factorPayload = arena.openPayload(factor.state)) {
			int inputEntries = payloadEntryCount(inputPayload);
			int factorEntries = payloadEntryCount(factorPayload);
			long candidatePairs = Math.multiplyExact((long) inputEntries, factorEntries);
			int workBudget = settings.refinementWorkUnits();
			if (candidatePairs > 0L && workBudget <= 0) {
				return arena.deriveSummary(
						outputKey,
						EvidenceStateSummary.unresolved(
								input.summary().pointRows(),
								Double.POSITIVE_INFINITY,
								Double.POSITIVE_INFINITY,
								"frontier finite product budget exhausted"),
						FrontierStateOperation.UNRESOLVED,
						input,
						factor.state,
						operationRecipeId);
			}
			int[] sampleTargets = finiteJoinSampleTargets(inputEntries, factorEntries, workBudget);
			try (PayloadResample inputSample = resamplePayload(
					inputPayload, inputEntries, sampleTargets[0], input, operationRecipeId, 0L);
					PayloadResample factorSample = resamplePayload(
							factorPayload, factorEntries, sampleTargets[1], factor.state, operationRecipeId, 1L)) {
				boolean learnedInput = arena.nearestCalibration(input) != null;
				boolean exactOutput = !inputSample.sampled()
						&& !factorSample.sampled()
						&& input.summary().guarantee() == EvidenceGuarantee.DATABASE_EXACT;
				FrontierMaskStrata outputMasks = outputKey.maskStrata();
				try (EmissionBuffer emissions = new EmissionBuffer(arena, outputMasks.layout().size())) {
					emitFiniteJoin(
							inputPayload, inputSample, factorPayload, factorSample, outputMasks, emissions);
					int emissionCount = emissions.size();
					FrontierPayloadWriter writer = null;
					ExactLeafAccumulator[] accumulators = null;
					try {
						if (exactOutput) {
							accumulators = new ExactLeafAccumulator[outputMasks.stratumCount()];
							int[] maximumCounts = new int[outputMasks.stratumCount()];
							for (int emission = 0; emission < emissionCount; emission++) {
								int stratum = emissions.stratum(emission);
								maximumCounts[stratum] = Math.incrementExact(maximumCounts[stratum]);
							}
							for (int stratum = 0; stratum < accumulators.length; stratum++) {
								accumulators[stratum] = new ExactLeafAccumulator(
										arena, maximumCounts[stratum], outputMasks.layout().size());
							}
							for (int emission = 0; emission < emissionCount; emission++) {
								accumulators[emissions.stratum(emission)].add(
										emissions.tuples(), emissions.tupleOffset(emission),
										emissions.weight(emission));
							}
							int[] exactCounts = new int[accumulators.length];
							for (int stratum = 0; stratum < accumulators.length; stratum++) {
								exactCounts[stratum] = accumulators[stratum].size();
							}
							writer = arena.newPayloadWriter(outputKey, exactCounts, new int[exactCounts.length]);
							for (int stratum = 0; stratum < accumulators.length; stratum++) {
								accumulators[stratum].writeTo(writer, stratum);
							}
						} else {
							int[] residualCounts = new int[outputMasks.stratumCount()];
							for (int emission = 0; emission < emissionCount; emission++) {
								int stratum = emissions.stratum(emission);
								residualCounts[stratum] = Math.incrementExact(residualCounts[stratum]);
							}
							writer = arena.newPayloadWriter(outputKey, new int[residualCounts.length], residualCounts);
							int[] localIndexes = new int[residualCounts.length];
							for (int emission = 0; emission < emissionCount; emission++) {
								int stratum = emissions.stratum(emission);
								writer.putResidual(stratum, localIndexes[stratum]++, emissions.weight(emission),
										emissions.tuples(), emissions.tupleOffset(emission));
							}
						}
						double pointRows = writer.pointRows();
						if (learnedInput && pointRows == 0.0d) {
							writer.close();
							writer = null;
							return arena.deriveSummary(
									outputKey,
									EvidenceStateSummary.unresolved(
											0.0d,
											Double.POSITIVE_INFINITY,
											Double.POSITIVE_INFINITY,
											"learned-calibrated-transform-zero-support"),
									FrontierStateOperation.UNRESOLVED,
									input,
									factor.state,
									operationRecipeId);
						}
						EvidenceStateSummary summary = exactOutput
								? EvidenceStateSummary.exact(pointRows)
								: learnedInput
										? learnedSummary(pointRows, writer.effectiveSampleSize(),
												writer.maximumWeightFraction())
										: sampledSummary(pointRows, writer.effectiveSampleSize(),
												writer.maximumWeightFraction());
						EvidenceStateRef output = learnedInput
								? arena.derivePayload(outputKey, summary, FrontierStateOperation.JOIN,
										input, factor.state, operationRecipeId, writer)
								: arena.internPayload(outputKey, summary, FrontierStateOperation.JOIN,
										input, factor.state, operationRecipeId, writer);
						writer = null;
						return output;
					} finally {
						if (writer != null) {
							writer.close();
						}
						if (accumulators != null) {
							for (ExactLeafAccumulator accumulator : accumulators) {
								if (accumulator != null) {
									accumulator.close();
								}
							}
						}
					}
				}
			}
		}
	}

	private PayloadResample resamplePayload(FrontierPayloadLease payload, int entryCount, int target,
			EvidenceStateRef state, int operationRecipeId, long streamOrdinal) {
		if (entryCount == 0 || target >= entryCount) {
			return PayloadResample.exact();
		}
		if (target <= 0) {
			throw new IllegalArgumentException("a nonempty Frontier payload requires a positive sample target");
		}
		FrontierMemoryReservation retainedCounts = arena.reserveTemporary(
				retainedArrayBytes(entryCount, Integer.BYTES), FrontierMemoryPurpose.ARRAY_GROWTH);
		try {
			long scratchBytes = Math.addExact(
					retainedArrayBytes(entryCount, Double.BYTES),
					retainedArrayBytes(target, Double.BYTES));
			try (FrontierMemoryReservation scratch = arena.reserveTemporary(
					scratchBytes, FrontierMemoryPurpose.ARRAY_GROWTH)) {
				double[] weights = entryWeights(payload, entryCount);
				double totalMass = 0.0d;
				for (double weight : weights) {
					totalMass += weight;
				}
				long seed = FrontierSeedSchedule.derive(
						arena.deterministicSeed(state),
						FrontierRandomDomain.RESAMPLE,
						Integer.toUnsignedLong(operationRecipeId),
						streamOrdinal);
				int[] drawCounts = FrontierMultinomialResampler.drawCounts(weights, target, seed);
				return new PayloadResample(drawCounts, totalMass / target, retainedCounts);
			}
		} catch (RuntimeException | Error failure) {
			retainedCounts.close();
			throw failure;
		}
	}

	private static int[] finiteJoinSampleTargets(int leftEntries, int rightEntries, int workBudget) {
		if (leftEntries == 0 || rightEntries == 0) {
			return new int[] { leftEntries, rightEntries };
		}
		long candidatePairs = (long) leftEntries * rightEntries;
		if (candidatePairs <= workBudget) {
			return new int[] { leftEntries, rightEntries };
		}
		if (workBudget <= 0) {
			return new int[] { 0, 0 };
		}
		/*
		 * The right side is a database-exact finite relation. Retain its complete tuple domain whenever one full
		 * expansion fits, and spend the remaining work on conditionally unbiased draws from the incoming bag. If the
		 * finite relation itself is larger than the budget, retain the complete incoming bag when possible. Only when
		 * neither side fits do both measures need resampling; equalizing their retained fractions minimizes the larger
		 * inverse sampling factor subject to the product-work constraint.
		 */
		if (rightEntries <= workBudget) {
			return new int[] { Math.max(1, workBudget / rightEntries), rightEntries };
		}
		if (leftEntries <= workBudget) {
			return new int[] { leftEntries, Math.max(1, workBudget / leftEntries) };
		}
		double balancedLeft = Math.sqrt((double) workBudget * leftEntries / rightEntries);
		int leftTarget = Math.max(1, Math.min(workBudget, (int) Math.round(balancedLeft)));
		int rightTarget = Math.max(1, Math.min(rightEntries, workBudget / leftTarget));
		leftTarget = Math.max(1, Math.min(leftEntries, workBudget / rightTarget));
		return new int[] { leftTarget, rightTarget };
	}

	private static void emitFiniteJoin(FrontierPayloadLease left, PayloadResample leftSample,
			FrontierPayloadLease right, PayloadResample rightSample, FrontierMaskStrata outputMasks,
			EmissionBuffer emissions) {
		int leftOrdinal = 0;
		for (int leftStratum = 0; leftStratum < left.stratumCount(); leftStratum++) {
			for (int leftIndex = 0; leftIndex < left.exactCount(leftStratum); leftIndex++) {
				double leftWeight = sampledEntryWeight(
						left, leftSample, true, leftStratum, leftIndex, leftOrdinal++);
				if (leftWeight > 0.0d) {
					emitFiniteJoinRight(left, true, leftStratum, leftIndex, leftWeight,
							right, rightSample, outputMasks, emissions);
				}
			}
			for (int leftIndex = 0; leftIndex < left.residualCount(leftStratum); leftIndex++) {
				double leftWeight = sampledEntryWeight(
						left, leftSample, false, leftStratum, leftIndex, leftOrdinal++);
				if (leftWeight > 0.0d) {
					emitFiniteJoinRight(left, false, leftStratum, leftIndex, leftWeight,
							right, rightSample, outputMasks, emissions);
				}
			}
		}
	}

	private static void emitFiniteJoinRight(FrontierPayloadLease left, boolean leftExact, int leftStratum,
			int leftIndex, double leftWeight, FrontierPayloadLease right, PayloadResample rightSample,
			FrontierMaskStrata outputMasks, EmissionBuffer emissions) {
		int rightOrdinal = 0;
		for (int rightStratum = 0; rightStratum < right.stratumCount(); rightStratum++) {
			for (int rightIndex = 0; rightIndex < right.exactCount(rightStratum); rightIndex++) {
				double rightWeight = sampledEntryWeight(
						right, rightSample, true, rightStratum, rightIndex, rightOrdinal++);
				if (rightWeight > 0.0d) {
					emitFinitePair(left, leftExact, leftStratum, leftIndex, leftWeight,
							right, true, rightStratum, rightIndex, rightWeight, outputMasks, emissions);
				}
			}
			for (int rightIndex = 0; rightIndex < right.residualCount(rightStratum); rightIndex++) {
				double rightWeight = sampledEntryWeight(
						right, rightSample, false, rightStratum, rightIndex, rightOrdinal++);
				if (rightWeight > 0.0d) {
					emitFinitePair(left, leftExact, leftStratum, leftIndex, leftWeight,
							right, false, rightStratum, rightIndex, rightWeight, outputMasks, emissions);
				}
			}
		}
	}

	private static void emitFinitePair(FrontierPayloadLease left, boolean leftExact, int leftStratum, int leftIndex,
			double leftWeight, FrontierPayloadLease right, boolean rightExact, int rightStratum, int rightIndex,
			double rightWeight, FrontierMaskStrata outputMasks, EmissionBuffer emissions) {
		FrontierLayout leftLayout = left.masks().layout();
		FrontierLayout rightLayout = right.masks().layout();
		for (int leftSlot = 0; leftSlot < leftLayout.size(); leftSlot++) {
			if (!left.masks().isBound(leftStratum, leftSlot)) {
				continue;
			}
			int rightSlot = rightLayout.indexOf(leftLayout.variable(leftSlot));
			if (rightSlot >= 0
					&& right.masks().isBound(rightStratum, rightSlot)
					&& payloadTermId(left, leftExact, leftStratum, leftIndex, leftSlot) != payloadTermId(right,
							rightExact, rightStratum, rightIndex, rightSlot)) {
				return;
			}
		}
		long[] tuple = new long[outputMasks.layout().size()];
		for (int outputSlot = 0; outputSlot < tuple.length; outputSlot++) {
			String variable = outputMasks.layout().variable(outputSlot);
			int leftSlot = leftLayout.indexOf(variable);
			if (leftSlot >= 0 && left.masks().isBound(leftStratum, leftSlot)) {
				tuple[outputSlot] = payloadTermId(left, leftExact, leftStratum, leftIndex, leftSlot);
				continue;
			}
			int rightSlot = rightLayout.indexOf(variable);
			if (rightSlot >= 0 && right.masks().isBound(rightStratum, rightSlot)) {
				tuple[outputSlot] = payloadTermId(right, rightExact, rightStratum, rightIndex, rightSlot);
			}
		}
		double weight = leftWeight * rightWeight;
		if (!Double.isFinite(weight) || weight <= 0.0d) {
			throw new IllegalStateException("Frontier finite join produced an invalid weight");
		}
		emissions.add(tupleMaskStratum(outputMasks, tuple), tuple, 0, weight);
	}

	private static double sampledEntryWeight(FrontierPayloadLease payload, PayloadResample sample,
			boolean exact, int stratum, int index, int ordinal) {
		if (!sample.sampled()) {
			return inputWeight(payload, exact, stratum, index);
		}
		return sample.drawCounts()[ordinal] * sample.drawMass();
	}

	private static int tupleMaskStratum(FrontierMaskStrata masks, long[] tuple) {
		for (int stratum = 0; stratum < masks.stratumCount(); stratum++) {
			boolean matches = true;
			for (int slot = 0; slot < tuple.length; slot++) {
				if (masks.isBound(stratum, slot) != (tuple[slot] != 0L)) {
					matches = false;
					break;
				}
			}
			if (matches) {
				return stratum;
			}
		}
		throw new IllegalStateException("Frontier finite join produced an undeclared bound-mask stratum");
	}

	private static double[] entryWeights(FrontierPayloadLease payload, int inputEntries) {
		double[] weights = new double[inputEntries];
		int ordinal = 0;
		for (int stratum = 0; stratum < payload.stratumCount(); stratum++) {
			for (int index = 0; index < payload.exactCount(stratum); index++) {
				weights[ordinal++] = payload.exactWeight(stratum, index);
			}
			for (int index = 0; index < payload.residualCount(stratum); index++) {
				weights[ordinal++] = payload.residualWeight(stratum, index);
			}
		}
		return weights;
	}

	private void visitMatchingRows(FrontierPayloadLease payload, LeafState factor, FrontierMaskStrata outputMasks,
			int[] drawCounts, double resampledEntryMass, ExactExpansionScanBudget scanBudget,
			FrontierEmissionSink emissions)
			throws IOException, QueryEvaluationException {
		FrontierLayout outputLayout = outputMasks.layout();
		FrontierLayout inputLayout = payload.masks().layout();
		int[] componentInputSlots = new int[4];
		for (int component = 0; component < 4; component++) {
			String name = factor.componentNames[component];
			componentInputSlots[component] = factor.constantValues[component] == null && name != null
					? inputLayout.indexOf(name)
					: -1;
		}
		int[] outputInputSlots = new int[outputLayout.size()];
		int[] outputFactorComponents = new int[outputLayout.size()];
		for (int outputSlot = 0; outputSlot < outputInputSlots.length; outputSlot++) {
			String variable = outputLayout.variable(outputSlot);
			outputInputSlots[outputSlot] = inputLayout.indexOf(variable);
			outputFactorComponents[outputSlot] = factor.component(variable);
		}
		int equalityMask = factor.selectorEqualityMask();
		boolean namedContexts = factor.scope == StatementPattern.Scope.NAMED_CONTEXTS;
		long[] tuple = new long[outputLayout.size()];
		int ordinal = 0;
		for (int stratum = 0; stratum < payload.stratumCount(); stratum++) {
			for (int index = 0; index < payload.exactCount(stratum); index++) {
				double emissionWeight = drawCounts == null
						? inputWeight(payload, true, stratum, index)
						: drawCounts[ordinal] * resampledEntryMass;
				ordinal++;
				if (emissionWeight > 0.0d) {
					visitMatchingRow(payload, factor, outputMasks, true, stratum, index, componentInputSlots,
							outputInputSlots, outputFactorComponents, equalityMask, namedContexts, tuple,
							emissionWeight, scanBudget, emissions);
				}
			}
			for (int index = 0; index < payload.residualCount(stratum); index++) {
				double emissionWeight = drawCounts == null
						? inputWeight(payload, false, stratum, index)
						: drawCounts[ordinal] * resampledEntryMass;
				ordinal++;
				if (emissionWeight > 0.0d) {
					visitMatchingRow(payload, factor, outputMasks, false, stratum, index, componentInputSlots,
							outputInputSlots, outputFactorComponents, equalityMask, namedContexts, tuple,
							emissionWeight, scanBudget, emissions);
				}
			}
		}
	}

	private void visitMatchingRow(FrontierPayloadLease payload, LeafState factor, FrontierMaskStrata outputMasks,
			boolean inputExact, int stratum, int index, int[] componentInputSlots, int[] outputInputSlots,
			int[] outputFactorComponents, int equalityMask, boolean namedContexts, long[] tuple,
			double emissionWeight, ExactExpansionScanBudget scanBudget, FrontierEmissionSink emissions)
			throws IOException, QueryEvaluationException {
		FrontierLayout outputLayout = outputMasks.layout();
		long[] constants = new long[4];
		for (int component = 0; component < 4; component++) {
			long constant = factor.constantIds[component];
			int slot = componentInputSlots[component];
			if (constant == FrontierLeafSelector.UNBOUND && slot >= 0 && payload.masks().isBound(stratum, slot)) {
				constant = payloadTermId(payload, inputExact, stratum, index, slot);
			}
			constants[component] = constant;
		}
		/*
		 * The mapped index answers a probe exactly when it provably retains every matching quad: always for a
		 * database-exact generation, trivially when an unknown constant proves emptiness, and on a sampled generation
		 * whenever the probed subject center is complete (a survivor of the center-coordinated design or an exact-heavy
		 * center). Every other retained tuple keeps the exact snapshot cursor probe.
		 */
		boolean impossibleConstant = constants[0] == FrontierLeafSelector.UNKNOWN
				|| constants[1] == FrontierLeafSelector.UNKNOWN
				|| constants[2] == FrontierLeafSelector.UNKNOWN
				|| constants[3] == FrontierLeafSelector.UNKNOWN;
		boolean mapped = false;
		boolean reverseMapped = false;
		if (queryIndexLease != null) {
			if (generationDatabaseExact || impossibleConstant) {
				mapped = true;
			} else if (constants[0] > 0L && queryIndexCenterComplete(constants[0], false)) {
				mapped = true;
			} else if (constants[2] > 0L && queryIndexCenterComplete(constants[2], true)) {
				mapped = true;
				reverseMapped = true;
			}
		}
		if (!mapped) {
			visitMatchingStatements(payload, inputExact, stratum, index, factor, scanBudget,
					(ignoredExact, ignoredStratum, ignoredIndex, subjectId, predicateId, objectId, contextId) -> {
						long[] output = outputTuple(
								payload, inputExact, stratum, index, subjectId, predicateId, objectId, contextId,
								factor, outputLayout);
						emissions.add(
								tupleMaskStratum(outputMasks, output), output, 0, emissionWeight);
					});
			return;
		}
		FrontierLeafSelector selector = new FrontierLeafSelector(constants[0], constants[1], constants[2],
				constants[3], namedContexts, equalityMask);
		double weight = emissionWeight;
		FrontierQueryIndexRowSink sink = (subjectId, predicateId, objectId, contextId, rowWeight) -> {
			for (int outputSlot = 0; outputSlot < tuple.length; outputSlot++) {
				int inputSlot = outputInputSlots[outputSlot];
				if (inputSlot >= 0 && payload.masks().isBound(stratum, inputSlot)) {
					tuple[outputSlot] = payloadTermId(payload, inputExact, stratum, index, inputSlot);
				} else {
					int component = outputFactorComponents[outputSlot];
					if (component < 0) {
						tuple[outputSlot] = 0L;
						continue;
					}
					tuple[outputSlot] = switch (component) {
					case 0 -> subjectId;
					case 1 -> predicateId;
					case 2 -> objectId;
					case 3 -> contextId;
					default -> throw new AssertionError("Unexpected Frontier tuple component");
					};
				}
			}
			emissions.add(tupleMaskStratum(outputMasks, tuple), tuple, 0, weight);
		};
		if (reverseMapped) {
			queryIndexReverseMappedProbes = Math.incrementExact(queryIndexReverseMappedProbes);
			queryIndexLease.visitReverseMatches(selector, sink);
		} else {
			queryIndexForwardMappedProbes = Math.incrementExact(queryIndexForwardMappedProbes);
			queryIndexLease.visitMatches(selector, sink);
		}
	}

	private boolean queryIndexCenterComplete(long centerId, boolean reverse) {
		LmdbFrontierLongObjectMemo<Boolean> memo = reverse ? objectCenterCompleteness : subjectCenterCompleteness;
		if (memo == null && arena != null) {
			memo = LmdbFrontierLongObjectMemo.createIfCapacity(arena);
			if (reverse) {
				objectCenterCompleteness = memo;
			} else {
				subjectCenterCompleteness = memo;
			}
		}
		if (memo != null) {
			Boolean cached = memo.get(centerId);
			if (cached != null) {
				return cached;
			}
		}
		boolean complete = reverse
				? queryIndexLease.objectCenterComplete(centerId)
				: queryIndexLease.centerComplete(centerId);
		if (memo != null) {
			memo.put(centerId, complete);
		}
		return complete;
	}

	private long visitMatchingStatements(FrontierPayloadLease payload, boolean inputExact, int stratum, int index,
			LeafState factor, ExactExpansionScanBudget scanBudget, StatementMatchConsumer consumer)
			throws IOException, QueryEvaluationException {
		Value[] bound = new Value[4];
		long[] boundIds = new long[4];
		FrontierLayout inputLayout = payload.masks().layout();
		for (int component = 0; component < bound.length; component++) {
			Value constant = factor.constantValues[component];
			if (constant != null) {
				bound[component] = constant;
				boundIds[component] = factor.constantIds[component];
				continue;
			}
			String name = factor.componentNames[component];
			int slot = name == null ? -1 : inputLayout.indexOf(name);
			if (slot >= 0 && payload.masks().isBound(stratum, slot)) {
				long id = payloadTermId(payload, inputExact, stratum, index, slot);
				bound[component] = frontierValue(id);
				boundIds[component] = id;
			}
		}
		if (bound[0] != null && !(bound[0] instanceof Resource)
				|| bound[1] != null && !(bound[1] instanceof IRI)
				|| bound[3] != null && !(bound[3] instanceof Resource)) {
			return 0L;
		}
		Resource[] contexts = bound[3] == null
				? new Resource[0]
				: new Resource[] { (Resource) bound[3] };
		int probeFlags = factor.scope.ordinal() << 6 | factor.selectorEqualityMask();
		if (statementProbeMemo == null && arena != null) {
			statementProbeMemo = LmdbFrontierStatementProbeMemo.createIfCapacity(arena);
		}
		LmdbFrontierStatementProbeMemo.Result cached = statementProbeMemo == null
				? null
				: statementProbeMemo.get(boundIds[0], boundIds[1], boundIds[2], boundIds[3], probeFlags);
		if (cached != null) {
			scanBudget.consumeRows(cached.sourceRowsScanned());
			for (int row = 0; row < cached.rowCount(); row++) {
				if (consumer != null) {
					consumer.accept(inputExact, stratum, index, cached.quad(row, 0), cached.quad(row, 1),
							cached.quad(row, 2), cached.quad(row, 3));
				}
			}
			return cached.rowCount();
		}
		LmdbFrontierStatementProbeMemo.Capture capture = statementProbeMemo == null
				? null
				: statementProbeMemo.beginCapture();
		long matches = 0L;
		long sourceRowsScanned = 0L;
		boolean scanComplete = false;
		try {
			try (CloseableIteration<? extends Statement> statements = statementSource.getStatements(
					(Resource) bound[0], (IRI) bound[1], bound[2], contexts)) {
				while (statements.hasNext()) {
					scanBudget.consumeRow();
					Statement statement = statements.next();
					sourceRowsScanned = Math.incrementExact(sourceRowsScanned);
					if (!factor.matches(statement, bound)) {
						continue;
					}
					long subjectId = statementTermId(statement, 0, boundIds[0]);
					long predicateId = statementTermId(statement, 1, boundIds[1]);
					long objectId = statementTermId(statement, 2, boundIds[2]);
					long contextId = statementTermId(statement, 3, boundIds[3]);
					if (capture != null && !capture.add(subjectId, predicateId, objectId, contextId)) {
						capture = null;
					}
					if (consumer != null) {
						consumer.accept(inputExact, stratum, index, subjectId, predicateId, objectId, contextId);
					}
					matches = Math.incrementExact(matches);
				}
			}
			scanComplete = true;
		} finally {
			if (capture != null) {
				if (scanComplete) {
					statementProbeMemo.complete(boundIds[0], boundIds[1], boundIds[2], boundIds[3], probeFlags,
							sourceRowsScanned, capture);
				} else {
					capture.close();
				}
			}
		}
		return matches;
	}

	private long[] outputTuple(FrontierPayloadLease payload, boolean inputExact, int stratum, int index,
			long subjectId, long predicateId, long objectId, long contextId, LeafState factor,
			FrontierLayout outputLayout) {
		FrontierLayout inputLayout = payload.masks().layout();
		long[] tuple = new long[outputLayout.size()];
		for (int outputSlot = 0; outputSlot < outputLayout.size(); outputSlot++) {
			String variable = outputLayout.variable(outputSlot);
			int inputSlot = inputLayout.indexOf(variable);
			if (inputSlot >= 0 && payload.masks().isBound(stratum, inputSlot)) {
				tuple[outputSlot] = payloadTermId(payload, inputExact, stratum, index, inputSlot);
				continue;
			}
			int component = factor.component(variable);
			if (component < 0) {
				tuple[outputSlot] = 0L;
				continue;
			}
			tuple[outputSlot] = switch (component) {
			case 0 -> subjectId;
			case 1 -> predicateId;
			case 2 -> objectId;
			case 3 -> contextId;
			default -> throw new AssertionError("Unexpected Frontier tuple component");
			};
		}
		return tuple;
	}

	private long statementTermId(Statement statement, int component, long boundId) throws IOException {
		if (boundId > 0L) {
			return boundId;
		}
		Value value = statementValue(statement, component);
		if (value == null && component == 3) {
			return 0L;
		}
		long termId = runtime.valueStore().getId(value);
		if (termId <= 0L) {
			throw new IllegalStateException("snapshot-exact Frontier probe returned an unstored term");
		}
		return termId;
	}

	private EvidenceStateRef stateReference(int stateId) {
		return stateReferences == null || stateId <= 0 || stateId >= stateReferences.length
				? null
				: stateReferences[stateId];
	}

	private void rememberState(EvidenceStateRef state) {
		int stateId = state.stateId();
		if (stateReferences == null) {
			stateReferences = new EvidenceStateRef[Math.max(8, stateId + 1)];
		} else if (stateId >= stateReferences.length) {
			int replacementLength = Math.max(stateId + 1, Math.multiplyExact(stateReferences.length, 2));
			stateReferences = Arrays.copyOf(stateReferences, replacementLength);
		}
		stateReferences[stateId] = state;
	}

	private int factorCount(EvidenceStateRef state) {
		int factorWordCount = (query.relationCount() + 63) >>> 6;
		if (factorCountWords == null || factorCountWords.length < factorWordCount) {
			factorCountWords = new long[factorWordCount];
		} else {
			Arrays.fill(factorCountWords, 0, factorWordCount, 0L);
		}
		int requiredVisitCapacity = stateReferences == null ? state.stateId() + 1 : stateReferences.length;
		if (factorCountVisitEpochs == null || factorCountVisitEpochs.length < requiredVisitCapacity) {
			factorCountVisitEpochs = new int[requiredVisitCapacity];
			factorCountVisitEpoch = 0;
		}
		int visitEpoch = nextFactorCountVisitEpoch();
		collectLineageFactors(state, factorCountWords, factorCountVisitEpochs, visitEpoch);
		int count = 0;
		for (int word = 0; word < factorWordCount; word++) {
			count = Math.addExact(count, Long.bitCount(factorCountWords[word]));
		}
		return count;
	}

	private int nextFactorCountVisitEpoch() {
		int visitEpoch = factorCountVisitEpoch + 1;
		if (visitEpoch <= 0) {
			Arrays.fill(factorCountVisitEpochs, 0);
			visitEpoch = 1;
		}
		factorCountVisitEpoch = visitEpoch;
		return visitEpoch;
	}

	private void collectLineageFactors(EvidenceStateRef state, long[] factors, int[] visitEpochs, int visitEpoch) {
		int stateId = state.stateId();
		if (stateId >= visitEpochs.length || visitEpochs[stateId] == visitEpoch) {
			return;
		}
		visitEpochs[stateId] = visitEpoch;
		if (arena.hasCanonicalKey(state)) {
			FrontierStateKey key = arena.key(state);
			boolean keyContainsFactors = false;
			for (int word = 0; word < key.logicalFactorWordCount(); word++) {
				long factorWord = key.logicalFactorWord(word);
				factors[word] |= factorWord;
				keyContainsFactors |= factorWord != 0L;
			}
			if (keyContainsFactors || arena.parentCount(state) == 0) {
				return;
			}
		}
		int parentCount = arena.parentCount(state);
		for (int parent = 0; parent < parentCount; parent++) {
			collectLineageFactors(arena.parent(state, parent), factors, visitEpochs, visitEpoch);
		}
		if (parentCount == 0) {
			addRelationFactors(arena.operationRecipeId(state), factors,
					new boolean[query.relationCount() + 1]);
		}
	}

	private void annotateFactorCount(PackedCostEstimate output, EvidenceStateRef state) {
		int factorCount = factorCount(state);
		if (factorCount > 0) {
			output.putPlannedDoubleMetric("plannedFrontierFactorCount", factorCount);
		}
	}

	private static int payloadEntryCount(FrontierPayloadLease payload) {
		int count = 0;
		for (int stratum = 0; stratum < payload.stratumCount(); stratum++) {
			count = Math.addExact(count,
					Math.addExact(payload.exactCount(stratum), payload.residualCount(stratum)));
		}
		return count;
	}

	private static long payloadTermId(FrontierPayloadLease payload, boolean exact, int stratum, int index, int slot) {
		return exact
				? payload.exactTermId(stratum, index, slot)
				: payload.residualTermId(stratum, index, slot);
	}

	private static double inputWeight(FrontierPayloadLease payload, boolean exact, int stratum, int index) {
		return exact ? payload.exactWeight(stratum, index) : payload.residualWeight(stratum, index);
	}

	private static boolean finiteNonNegative(double value) {
		return Double.isFinite(value) && value >= 0.0d;
	}

	private static double saturatedMultiply(double left, double right) {
		double product = left * right;
		return Double.isFinite(product) ? product : Double.MAX_VALUE;
	}

	private static double saturatedAdd(double left, double right) {
		double sum = left + right;
		return Double.isFinite(sum) ? sum : Double.MAX_VALUE;
	}

	private static double saturatedMaximum(double left, double right) {
		double maximum = Math.max(left, right);
		return Double.isFinite(maximum) ? maximum : Double.MAX_VALUE;
	}

	private static long saturatedLongAdd(long left, long right) {
		return left > Long.MAX_VALUE - right ? Long.MAX_VALUE : left + right;
	}

	private static Value statementValue(Statement statement, int component) {
		return switch (component) {
		case 0 -> statement.getSubject();
		case 1 -> statement.getPredicate();
		case 2 -> statement.getObject();
		case 3 -> statement.getContext();
		default -> throw new IndexOutOfBoundsException("statement component must be between zero and three");
		};
	}

	@FunctionalInterface
	private interface StatementMatchConsumer {

		void accept(boolean inputExact, int stratum, int index, long subjectId, long predicateId, long objectId,
				long contextId) throws IOException;
	}

	private static int supportedLeafCount(LeafState[] candidates) {
		int count = 0;
		for (LeafState candidate : candidates) {
			count += candidate == null ? 0 : 1;
		}
		return count;
	}

	private static int supportedFiniteLeafCount(FiniteLeafState[] candidates) {
		int count = 0;
		for (FiniteLeafState candidate : candidates) {
			count += candidate == null ? 0 : 1;
		}
		return count;
	}

	private static LeafState leafState(LeafState[] candidates, int relationId) {
		return relationId <= 0 || relationId >= candidates.length ? null : candidates[relationId];
	}

	private static int[] leafScanOrder(LeafState[] candidates, long[] candidateRangeRows) {
		int[] order = new int[supportedLeafCount(candidates)];
		int size = 0;
		for (int relationId = 1; relationId < candidates.length; relationId++) {
			if (candidates[relationId] != null) {
				order[size++] = relationId;
			}
		}
		for (int index = 1; index < size; index++) {
			int relationId = order[index];
			int cursor = index;
			while (cursor > 0) {
				int previous = order[cursor - 1];
				int comparison = Long.compare(candidateRangeRows[relationId], candidateRangeRows[previous]);
				if (comparison > 0 || comparison == 0 && relationId >= previous) {
					break;
				}
				order[cursor] = previous;
				cursor--;
			}
			order[cursor] = relationId;
		}
		return order;
	}

	private static EvidenceStateRef materializeLeafBuffer(
			FrontierStateArena targetArena,
			LeafState candidate,
			FrontierStateKey key,
			EmissionBuffer rows,
			boolean generationExact,
			int relationId) {
		FrontierPayloadWriter writer = null;
		ExactLeafAccumulator exactAccumulator = null;
		try {
			if (generationExact) {
				exactAccumulator = new ExactLeafAccumulator(
						targetArena, rows.size(), candidate.masks.layout().size());
			} else {
				writer = targetArena.newPayloadWriter(key, new int[] { 0 }, new int[] { rows.size() });
			}
			int[] writtenCounts = new int[relationId + 1];
			long[] tupleScratch = new long[candidate.masks.layout().size()];
			for (int entry = 0; entry < rows.size(); entry++) {
				int offset = rows.tupleOffset(entry);
				writeMatchingLeaf(
						candidate,
						writer,
						exactAccumulator,
						writtenCounts,
						relationId,
						tupleScratch,
						generationExact,
						rows.tuples()[offset],
						rows.tuples()[offset + 1],
						rows.tuples()[offset + 2],
						rows.tuples()[offset + 3],
						rows.weight(entry));
			}
			if (writtenCounts[relationId] != rows.size()) {
				throw new IllegalStateException("Frontier leaf buffer replay lost rows");
			}
			if (generationExact) {
				writer = targetArena.newPayloadWriter(
						key, new int[] { exactAccumulator.size() }, new int[] { 0 });
				exactAccumulator.writeTo(writer);
			}
			double pointRows = writer.pointRows();
			EvidenceStateSummary summary = generationExact
					? EvidenceStateSummary.exact(pointRows)
					: sampledSummary(pointRows, writer.effectiveSampleSize(), writer.maximumWeightFraction());
			EvidenceStateRef state = targetArena.internPayload(
					key,
					summary,
					generationExact ? FrontierStateOperation.EXACT_LEAF : FrontierStateOperation.COORDINATED_STAR,
					null,
					null,
					relationId,
					writer);
			writer = null;
			return state;
		} finally {
			if (writer != null) {
				writer.close();
			}
			if (exactAccumulator != null) {
				exactAccumulator.close();
			}
		}
	}

	private static void writeMatchingLeaf(LeafState candidate, FrontierPayloadWriter writer,
			ExactLeafAccumulator exactAccumulator, int[] writtenCounts, int relationId, long[] tupleScratch,
			boolean generationExact, long subjectId, long predicateId, long objectId, long contextId, double weight) {
		Arrays.fill(tupleScratch, 0L);
		for (int component = 0; component < candidate.componentToSlot.length; component++) {
			int slot = candidate.componentToSlot[component];
			if (slot >= 0) {
				tupleScratch[slot] = switch (component) {
				case 0 -> subjectId;
				case 1 -> predicateId;
				case 2 -> objectId;
				case 3 -> contextId;
				default -> throw new AssertionError("Unexpected Frontier tuple component");
				};
			}
		}
		int index = writtenCounts[relationId]++;
		if (generationExact) {
			exactAccumulator.add(tupleScratch, weight);
		} else {
			writer.putResidual(0, index, weight, tupleScratch, 0);
		}
	}

	private static FrontierStateKey leafStateKey(LeafState candidate, FrontierSynopsisReadResult generation,
			int relationCountWithZero) {
		return leafStateKey(candidate, generation, relationCountWithZero, DESIGN_LANE_INDEX);
	}

	private static FrontierStateKey leafStateKey(LeafState candidate, FrontierSynopsisReadResult generation,
			int relationCountWithZero, int laneIndex) {
		return logicalLeafStateKey(
				candidate.relationId, candidate.masks, generation, relationCountWithZero, laneIndex);
	}

	private static FrontierStateKey finiteStateKey(FiniteLeafState candidate, FrontierSynopsisReadResult generation,
			int relationCountWithZero) {
		return logicalLeafStateKey(
				candidate.relationId, candidate.masks, generation, relationCountWithZero, DESIGN_LANE_INDEX);
	}

	private static FrontierStateKey logicalLeafStateKey(int relationId, FrontierMaskStrata masks,
			FrontierSynopsisReadResult generation, int relationCountWithZero, int laneIndex) {
		int relationCount = relationCountWithZero - 1;
		long[] factors = new long[(relationCount + 63) >>> 6];
		int factorIndex = relationId - 1;
		factors[factorIndex >>> 6] |= 1L << (factorIndex & 63);
		return FrontierStateKey.of(factors, masks, 0L, 0L, 0L,
				generation.storeIdHigh(), generation.storeIdLow(), generation.snapshotEpoch(),
				FrontierLaneFamily.DESIGN, laneIndex, SEED_SCHEDULE_VERSION);
	}

	private static FrontierStateKey projectionStateKey(FrontierStateKey inputKey, int relationId,
			Projection projection) {
		int[] sourceSlots = projectionSourceSlots(inputKey.frontier(), projection);
		if (sourceSlots == null) {
			return null;
		}
		String[] targetNames = new String[sourceSlots.length];
		for (int index = 0; index < targetNames.length; index++) {
			ProjectionElem element = projection.getProjectionElemList().getElements().get(index);
			targetNames[index] = element.getProjectionAlias().orElse(element.getName());
		}
		try {
			FrontierLayout layout = FrontierLayout.of(targetNames);
			FrontierMaskStrata masks = projectedMaskStrata(inputKey.maskStrata(), layout, sourceSlots);
			return operatorStateKey(inputKey, relationId, masks);
		} catch (IllegalArgumentException failure) {
			return null;
		}
	}

	private static FrontierMaskStrata optionalMaskStrata(FrontierMaskStrata inputMasks, TupleExpr right) {
		FrontierLayout inputLayout = inputMasks.layout();
		String[] variables = new String[Math.addExact(inputLayout.size(), right.getBindingNames().size())];
		int variableCount = 0;
		for (int slot = 0; slot < inputLayout.size(); slot++) {
			variables[variableCount++] = inputLayout.variable(slot);
		}
		for (String variable : right.getBindingNames()) {
			if (indexOf(variables, variableCount, variable) < 0) {
				variables[variableCount++] = variable;
			}
		}
		Arrays.sort(variables, 0, variableCount);
		FrontierLayout outputLayout = FrontierLayout.of(Arrays.copyOf(variables, variableCount));
		if (outputLayout.size() == 0) {
			return FrontierMaskStrata.of(outputLayout, 1, new long[0]);
		}

		int wordCount = (outputLayout.size() + 63) >>> 6;
		int[] rightSlots = new int[right.getBindingNames().size()];
		int rightSlotCount = 0;
		for (String variable : right.getBindingNames()) {
			rightSlots[rightSlotCount++] = outputLayout.indexOf(variable);
		}
		ArrayList<long[]> masks = new ArrayList<>();
		for (int inputStratum = 0; inputStratum < inputMasks.stratumCount(); inputStratum++) {
			long[] base = new long[wordCount];
			for (int inputSlot = 0; inputSlot < inputLayout.size(); inputSlot++) {
				if (!inputMasks.isBound(inputStratum, inputSlot)) {
					continue;
				}
				int outputSlot = outputLayout.indexOf(inputLayout.variable(inputSlot));
				base[outputSlot >>> 6] |= 1L << (outputSlot & 63);
			}
			int[] unboundRightSlots = new int[rightSlotCount];
			int unboundRightCount = 0;
			int combinationCount = 1;
			for (int index = 0; index < rightSlotCount; index++) {
				int slot = rightSlots[index];
				if ((base[slot >>> 6] & 1L << (slot & 63)) != 0L) {
					continue;
				}
				if (combinationCount > MAX_OPTIONAL_MASK_STRATA / 2) {
					return null;
				}
				combinationCount *= 2;
				unboundRightSlots[unboundRightCount++] = slot;
			}
			if (masks.size() > MAX_OPTIONAL_MASK_STRATA - combinationCount) {
				return null;
			}
			for (int combination = 0; combination < combinationCount; combination++) {
				long[] mask = base.clone();
				for (int bit = 0; bit < unboundRightCount; bit++) {
					if ((combination & 1 << bit) != 0) {
						int slot = unboundRightSlots[bit];
						mask[slot >>> 6] |= 1L << (slot & 63);
					}
				}
				masks.add(mask);
			}
		}

		long[] flattened = new long[Math.multiplyExact(masks.size(), wordCount)];
		for (int stratum = 0; stratum < masks.size(); stratum++) {
			System.arraycopy(masks.get(stratum), 0, flattened, stratum * wordCount, wordCount);
		}
		sortMaskStrata(flattened, masks.size(), wordCount);
		int unique = 0;
		for (int stratum = 0; stratum < masks.size(); stratum++) {
			if (unique == 0 || compareMaskStrata(flattened, unique - 1, stratum, wordCount) != 0) {
				if (unique != stratum) {
					System.arraycopy(flattened, stratum * wordCount, flattened, unique * wordCount, wordCount);
				}
				unique++;
			}
		}
		return FrontierMaskStrata.of(outputLayout, unique,
				Arrays.copyOf(flattened, Math.multiplyExact(unique, wordCount)));
	}

	private static FrontierMaskStrata extensionMaskStrata(FrontierMaskStrata inputMasks, Extension extension) {
		FrontierLayout inputLayout = inputMasks.layout();
		String[] variables = new String[Math.addExact(inputLayout.size(), extension.getElements().size())];
		int variableCount = 0;
		for (int slot = 0; slot < inputLayout.size(); slot++) {
			variables[variableCount++] = inputLayout.variable(slot);
		}
		for (ExtensionElem element : extension.getElements()) {
			if (indexOf(variables, variableCount, element.getName()) < 0) {
				variables[variableCount++] = element.getName();
			}
		}
		Arrays.sort(variables, 0, variableCount);
		FrontierLayout outputLayout = FrontierLayout.of(Arrays.copyOf(variables, variableCount));
		if (outputLayout.size() == 0) {
			return FrontierMaskStrata.of(outputLayout, 1, new long[0]);
		}

		int[] assignedSlots = new int[extension.getElements().size()];
		int assignedSlotCount = 0;
		for (ExtensionElem element : extension.getElements()) {
			int slot = outputLayout.indexOf(element.getName());
			if (indexOf(assignedSlots, assignedSlotCount, slot) < 0) {
				assignedSlots[assignedSlotCount++] = slot;
			}
		}
		int combinations = 1;
		for (int index = 0; index < assignedSlotCount; index++) {
			if (combinations > MAX_OPTIONAL_MASK_STRATA / 2) {
				return null;
			}
			combinations *= 2;
		}
		if (inputMasks.stratumCount() > MAX_OPTIONAL_MASK_STRATA / combinations) {
			return null;
		}

		int wordCount = (outputLayout.size() + 63) >>> 6;
		int maximumStrata = Math.multiplyExact(inputMasks.stratumCount(), combinations);
		long[] flattened = new long[Math.multiplyExact(maximumStrata, wordCount)];
		int nextStratum = 0;
		for (int inputStratum = 0; inputStratum < inputMasks.stratumCount(); inputStratum++) {
			long[] base = new long[wordCount];
			copyBoundVariables(inputMasks, inputStratum, outputLayout, base, 0);
			for (int index = 0; index < assignedSlotCount; index++) {
				int slot = assignedSlots[index];
				base[slot >>> 6] &= ~(1L << (slot & 63));
			}
			for (int combination = 0; combination < combinations; combination++) {
				int offset = nextStratum++ * wordCount;
				System.arraycopy(base, 0, flattened, offset, wordCount);
				for (int index = 0; index < assignedSlotCount; index++) {
					if ((combination & 1 << index) != 0) {
						int slot = assignedSlots[index];
						flattened[offset + (slot >>> 6)] |= 1L << (slot & 63);
					}
				}
			}
		}
		sortMaskStrata(flattened, nextStratum, wordCount);
		int unique = 0;
		for (int stratum = 0; stratum < nextStratum; stratum++) {
			if (unique == 0 || compareMaskStrata(flattened, unique - 1, stratum, wordCount) != 0) {
				if (unique != stratum) {
					System.arraycopy(flattened, stratum * wordCount, flattened, unique * wordCount, wordCount);
				}
				unique++;
			}
		}
		return FrontierMaskStrata.of(outputLayout, unique,
				Arrays.copyOf(flattened, Math.multiplyExact(unique, wordCount)));
	}

	private static int[] projectionSourceSlots(FrontierLayout inputLayout, Projection projection) {
		var elements = projection.getProjectionElemList().getElements();
		int[] sourceSlots = new int[elements.size()];
		for (int index = 0; index < sourceSlots.length; index++) {
			int sourceSlot = inputLayout.indexOf(elements.get(index).getName());
			if (sourceSlot < 0) {
				return null;
			}
			sourceSlots[index] = sourceSlot;
		}
		return sourceSlots;
	}

	private static MultiProjectionPlan multiProjectionPlan(FrontierMaskStrata inputMasks,
			MultiProjection multiProjection) {
		FrontierLayout inputLayout = inputMasks.layout();
		var projections = multiProjection.getProjections();
		int maximumOutputNames = 0;
		for (ProjectionElemList projection : projections) {
			maximumOutputNames = Math.addExact(maximumOutputNames, projection.getElements().size());
		}
		String[] outputNames = new String[maximumOutputNames];
		int outputNameCount = 0;
		for (ProjectionElemList projection : projections) {
			for (ProjectionElem element : projection.getElements()) {
				String target = element.getProjectionAlias().orElse(element.getName());
				if (indexOf(outputNames, outputNameCount, target) < 0) {
					outputNames[outputNameCount++] = target;
				}
			}
		}
		Arrays.sort(outputNames, 0, outputNameCount);
		FrontierLayout outputLayout;
		try {
			outputLayout = FrontierLayout.of(Arrays.copyOf(outputNames, outputNameCount));
		} catch (IllegalArgumentException failure) {
			return null;
		}

		int[][] sourceSlots = new int[projections.size()][];
		int[][] targetSlots = new int[projections.size()][];
		for (int projection = 0; projection < projections.size(); projection++) {
			var elements = projections.get(projection).getElements();
			sourceSlots[projection] = new int[elements.size()];
			targetSlots[projection] = new int[elements.size()];
			for (int element = 0; element < elements.size(); element++) {
				ProjectionElem projectionElement = elements.get(element);
				sourceSlots[projection][element] = inputLayout.indexOf(projectionElement.getName());
				targetSlots[projection][element] = outputLayout.indexOf(
						projectionElement.getProjectionAlias().orElse(projectionElement.getName()));
			}
		}

		int projectedStratumCount = Math.max(1,
				Math.multiplyExact(Math.max(1, projections.size()), inputMasks.stratumCount()));
		int wordCount = (outputLayout.size() + 63) >>> 6;
		long[] projectedMasks = new long[Math.multiplyExact(projectedStratumCount, wordCount)];
		int nextMask = 0;
		if (projections.isEmpty()) {
			nextMask = 1;
		} else {
			for (int projection = 0; projection < projections.size(); projection++) {
				for (int inputStratum = 0; inputStratum < inputMasks.stratumCount(); inputStratum++) {
					int outputOffset = nextMask++ * wordCount;
					for (int element = 0; element < sourceSlots[projection].length; element++) {
						int sourceSlot = sourceSlots[projection][element];
						if (sourceSlot >= 0 && inputMasks.isBound(inputStratum, sourceSlot)) {
							int targetSlot = targetSlots[projection][element];
							projectedMasks[outputOffset + (targetSlot >>> 6)] |= 1L << (targetSlot & 63);
						}
					}
				}
			}
		}
		sortMaskStrata(projectedMasks, nextMask, wordCount);
		int unique = 0;
		for (int stratum = 0; stratum < nextMask; stratum++) {
			if (unique == 0 || compareMaskStrata(projectedMasks, unique - 1, stratum, wordCount) != 0) {
				if (unique != stratum) {
					System.arraycopy(
							projectedMasks, stratum * wordCount, projectedMasks, unique * wordCount, wordCount);
				}
				unique++;
			}
		}
		FrontierMaskStrata outputMasks = FrontierMaskStrata.of(
				outputLayout, unique, Arrays.copyOf(projectedMasks, Math.multiplyExact(unique, wordCount)));
		int[][] targetStrata = new int[projections.size()][inputMasks.stratumCount()];
		for (int projection = 0; projection < projections.size(); projection++) {
			for (int inputStratum = 0; inputStratum < inputMasks.stratumCount(); inputStratum++) {
				int targetStratum = -1;
				for (int candidate = 0; candidate < outputMasks.stratumCount(); candidate++) {
					boolean matches = true;
					for (int outputSlot = 0; outputSlot < outputLayout.size(); outputSlot++) {
						boolean projectedBound = false;
						for (int element = 0; element < sourceSlots[projection].length; element++) {
							if (targetSlots[projection][element] == outputSlot) {
								int sourceSlot = sourceSlots[projection][element];
								projectedBound = sourceSlot >= 0 && inputMasks.isBound(inputStratum, sourceSlot);
							}
						}
						if (outputMasks.isBound(candidate, outputSlot) != projectedBound) {
							matches = false;
							break;
						}
					}
					if (matches) {
						targetStratum = candidate;
						break;
					}
				}
				if (targetStratum < 0) {
					return null;
				}
				targetStrata[projection][inputStratum] = targetStratum;
			}
		}
		return new MultiProjectionPlan(outputMasks, sourceSlots, targetSlots, targetStrata);
	}

	private static FrontierMaskStrata projectedMaskStrata(FrontierMaskStrata inputMasks, FrontierLayout outputLayout,
			int[] sourceSlots) {
		if (outputLayout.size() == 0) {
			return FrontierMaskStrata.of(outputLayout, 1, new long[0]);
		}
		int outputWordCount = (outputLayout.size() + 63) >>> 6;
		long[] projected = new long[Math.multiplyExact(inputMasks.stratumCount(), outputWordCount)];
		for (int inputStratum = 0; inputStratum < inputMasks.stratumCount(); inputStratum++) {
			int outputOffset = Math.multiplyExact(inputStratum, outputWordCount);
			for (int outputSlot = 0; outputSlot < sourceSlots.length; outputSlot++) {
				if (inputMasks.isBound(inputStratum, sourceSlots[outputSlot])) {
					projected[outputOffset + (outputSlot >>> 6)] |= 1L << (outputSlot & 63);
				}
			}
		}
		sortMaskStrata(projected, inputMasks.stratumCount(), outputWordCount);
		int unique = 0;
		for (int stratum = 0; stratum < inputMasks.stratumCount(); stratum++) {
			if (unique == 0 || compareMaskStrata(projected, unique - 1, stratum, outputWordCount) != 0) {
				if (unique != stratum) {
					System.arraycopy(projected, stratum * outputWordCount, projected, unique * outputWordCount,
							outputWordCount);
				}
				unique++;
			}
		}
		return FrontierMaskStrata.of(outputLayout, unique,
				Arrays.copyOf(projected, Math.multiplyExact(unique, outputWordCount)));
	}

	private static void sortMaskStrata(long[] words, int stratumCount, int wordCount) {
		for (int stratum = 1; stratum < stratumCount; stratum++) {
			int cursor = stratum;
			while (cursor > 0 && compareMaskStrata(words, cursor - 1, cursor, wordCount) > 0) {
				for (int word = 0; word < wordCount; word++) {
					int left = (cursor - 1) * wordCount + word;
					int right = cursor * wordCount + word;
					long swap = words[left];
					words[left] = words[right];
					words[right] = swap;
				}
				cursor--;
			}
		}
	}

	private static int compareMaskStrata(long[] words, int leftStratum, int rightStratum, int wordCount) {
		for (int word = 0; word < wordCount; word++) {
			int comparison = Long.compareUnsigned(
					words[leftStratum * wordCount + word],
					words[rightStratum * wordCount + word]);
			if (comparison != 0) {
				return comparison;
			}
		}
		return 0;
	}

	private static FrontierStateKey operatorStateKey(FrontierStateKey inputKey, int relationId,
			FrontierMaskStrata outputMasks) {
		return operatorStateKey(inputKey, logicalFactorWords(inputKey), relationId, outputMasks);
	}

	private FrontierStateKey operatorStateKeyWithRelationFactors(FrontierStateKey inputKey, int relationId,
			FrontierMaskStrata outputMasks) {
		long[] factors = logicalFactorWords(inputKey);
		addRelationFactors(relationId, factors, new boolean[query.relationCount() + 1]);
		return operatorStateKey(inputKey, factors, relationId, outputMasks);
	}

	private EvidenceStateRef alignUnionBranch(EvidenceStateRef input, FrontierMaskStrata outputMasks,
			int relationId) {
		FrontierStateKey inputKey = arena.key(input);
		if (inputKey.maskStrata().equals(outputMasks)) {
			return input;
		}
		int[] sourceSlots = new int[outputMasks.layout().size()];
		for (int outputSlot = 0; outputSlot < sourceSlots.length; outputSlot++) {
			sourceSlots[outputSlot] = inputKey.frontier().indexOf(outputMasks.layout().variable(outputSlot));
		}
		FrontierStateKey alignedKey = operatorStateKey(inputKey, relationId, outputMasks);
		arena.declareCanonicalState(alignedKey);
		EvidenceStateRef aligned = arena.find(alignedKey);
		if (aligned == null) {
			aligned = FrontierLinearTransforms.align(arena, input, alignedKey, relationId, sourceSlots);
			rememberState(aligned);
		}
		return aligned;
	}

	private static FrontierStateKey combinedOperatorStateKey(FrontierStateKey leftKey, FrontierStateKey rightKey,
			int relationId, FrontierMaskStrata outputMasks) {
		if (!leftKey.maskStrata().equals(outputMasks) || !rightKey.maskStrata().equals(outputMasks)
				|| !sameSamplingIdentity(leftKey, rightKey)
				|| !sameEstimatorSemantics(leftKey, rightKey)) {
			return null;
		}
		return operatorStateKey(leftKey, unionFactorWords(leftKey, rightKey), relationId, outputMasks);
	}

	private static FrontierStateKey operatorStateKey(FrontierStateKey inputKey, long[] factors, int relationId,
			FrontierMaskStrata outputMasks) {
		return FrontierStateKey.of(factors, outputMasks,
				Long.MIN_VALUE | Integer.toUnsignedLong(relationId),
				inputKey.correlationScope(), inputKey.continuationObjective(),
				inputKey.snapshotStoreIdHigh(), inputKey.snapshotStoreIdLow(), inputKey.snapshotEpoch(),
				inputKey.laneFamily(), inputKey.laneIndex(), inputKey.seedVersion());
	}

	private static FrontierStateKey withSamplingIdentity(FrontierStateKey stateKey, FrontierStateKey samplingKey) {
		if (stateKey.snapshotStoreIdHigh() != samplingKey.snapshotStoreIdHigh()
				|| stateKey.snapshotStoreIdLow() != samplingKey.snapshotStoreIdLow()
				|| stateKey.snapshotEpoch() != samplingKey.snapshotEpoch()
				|| stateKey.seedVersion() != samplingKey.seedVersion()) {
			throw new IllegalArgumentException("alternate replay must remain on the same database snapshot");
		}
		return FrontierStateKey.of(
				logicalFactorWords(stateKey),
				stateKey.maskStrata(),
				stateKey.semanticScope(),
				stateKey.correlationScope(),
				stateKey.continuationObjective(),
				stateKey.snapshotStoreIdHigh(),
				stateKey.snapshotStoreIdLow(),
				stateKey.snapshotEpoch(),
				samplingKey.laneFamily(),
				samplingKey.laneIndex(),
				samplingKey.seedVersion());
	}

	private static FrontierStateKey joinedStateKey(FrontierStateKey inputKey, FrontierStateKey factorKey) {
		if (!sameSamplingIdentity(inputKey, factorKey)) {
			throw new IllegalArgumentException("Frontier join inputs have different sampling identities");
		}
		FrontierMaskStrata masks = joinedMaskStrata(inputKey.maskStrata(), factorKey.maskStrata());
		return FrontierStateKey.of(unionFactorWords(inputKey, factorKey), masks,
				joinedSemanticScope(inputKey.semanticScope(), factorKey.semanticScope()),
				inputKey.correlationScope(), inputKey.continuationObjective(),
				inputKey.snapshotStoreIdHigh(), inputKey.snapshotStoreIdLow(), inputKey.snapshotEpoch(),
				inputKey.laneFamily(), inputKey.laneIndex(), inputKey.seedVersion());
	}

	private static long joinedSemanticScope(long left, long right) {
		if (left == 0L || left == right) {
			return right;
		}
		if (right == 0L) {
			return left;
		}
		long mixed = left ^ Long.rotateLeft(right, 29) ^ 0x9e3779b97f4a7c15L;
		mixed ^= mixed >>> 30;
		mixed *= 0xbf58476d1ce4e5b9L;
		mixed ^= mixed >>> 27;
		mixed *= 0x94d049bb133111ebL;
		return mixed ^ mixed >>> 31;
	}

	private static FrontierMaskStrata joinedMaskStrata(FrontierMaskStrata left, FrontierMaskStrata right) {
		FrontierLayout layout = unionLayout(left.layout(), right.layout());
		if (layout.size() == 0) {
			return FrontierMaskStrata.of(layout, 1, new long[0]);
		}
		int wordCount = (layout.size() + 63) >>> 6;
		int pairCount = Math.multiplyExact(left.stratumCount(), right.stratumCount());
		long[] words = new long[Math.multiplyExact(pairCount, wordCount)];
		int pair = 0;
		for (int leftStratum = 0; leftStratum < left.stratumCount(); leftStratum++) {
			for (int rightStratum = 0; rightStratum < right.stratumCount(); rightStratum++) {
				int offset = pair++ * wordCount;
				copyBoundVariables(left, leftStratum, layout, words, offset);
				copyBoundVariables(right, rightStratum, layout, words, offset);
			}
		}
		sortMaskStrata(words, pairCount, wordCount);
		int unique = 0;
		for (int stratum = 0; stratum < pairCount; stratum++) {
			if (unique == 0 || compareMaskStrata(words, unique - 1, stratum, wordCount) != 0) {
				if (unique != stratum) {
					System.arraycopy(words, stratum * wordCount, words, unique * wordCount, wordCount);
				}
				unique++;
			}
		}
		return FrontierMaskStrata.of(layout, unique,
				Arrays.copyOf(words, Math.multiplyExact(unique, wordCount)));
	}

	private static FrontierMaskStrata unionMaskStrata(FrontierMaskStrata left, FrontierMaskStrata right) {
		FrontierLayout layout = unionLayout(left.layout(), right.layout());
		if (layout.size() == 0) {
			return FrontierMaskStrata.of(layout, 1, new long[0]);
		}
		int wordCount = (layout.size() + 63) >>> 6;
		int maximumStrata = Math.addExact(left.stratumCount(), right.stratumCount());
		long[] words = new long[Math.multiplyExact(maximumStrata, wordCount)];
		int nextStratum = 0;
		for (int leftStratum = 0; leftStratum < left.stratumCount(); leftStratum++) {
			copyBoundVariables(left, leftStratum, layout, words, nextStratum++ * wordCount);
		}
		for (int rightStratum = 0; rightStratum < right.stratumCount(); rightStratum++) {
			copyBoundVariables(right, rightStratum, layout, words, nextStratum++ * wordCount);
		}
		sortMaskStrata(words, nextStratum, wordCount);
		int unique = 0;
		for (int stratum = 0; stratum < nextStratum; stratum++) {
			if (unique == 0 || compareMaskStrata(words, unique - 1, stratum, wordCount) != 0) {
				if (unique != stratum) {
					System.arraycopy(words, stratum * wordCount, words, unique * wordCount, wordCount);
				}
				unique++;
			}
		}
		return FrontierMaskStrata.of(layout, unique,
				Arrays.copyOf(words, Math.multiplyExact(unique, wordCount)));
	}

	private static void copyBoundVariables(FrontierMaskStrata source, int sourceStratum, FrontierLayout target,
			long[] targetWords, int targetOffset) {
		for (int sourceSlot = 0; sourceSlot < source.layout().size(); sourceSlot++) {
			if (!source.isBound(sourceStratum, sourceSlot)) {
				continue;
			}
			int targetSlot = target.indexOf(source.layout().variable(sourceSlot));
			targetWords[targetOffset + (targetSlot >>> 6)] |= 1L << (targetSlot & 63);
		}
	}

	private void addRelationFactors(int relationId, long[] factors, boolean[] visited) {
		if (relationId <= 0 || relationId >= visited.length || visited[relationId]) {
			return;
		}
		visited[relationId] = true;
		LeafState leaf = leafState(relationId);
		if (leaf != null) {
			int factorIndex = relationId - 1;
			factors[factorIndex >>> 6] |= 1L << (factorIndex & 63);
			return;
		}
		FiniteLeafState finiteLeaf = finiteLeafState(relationId);
		if (finiteLeaf != null) {
			int factorIndex = relationId - 1;
			factors[factorIndex >>> 6] |= 1L << (factorIndex & 63);
			return;
		}
		for (int ordinal = 0; ordinal < query.childCount(relationId); ordinal++) {
			addRelationFactors(query.childRelationId(relationId, ordinal), factors, visited);
		}
	}

	private static long[] logicalFactorWords(FrontierStateKey key) {
		long[] factors = new long[key.logicalFactorWordCount()];
		for (int word = 0; word < factors.length; word++) {
			factors[word] = key.logicalFactorWord(word);
		}
		return factors;
	}

	private static long[] unionFactorWords(FrontierStateKey leftKey, FrontierStateKey rightKey) {
		int wordCount = Math.max(leftKey.logicalFactorWordCount(), rightKey.logicalFactorWordCount());
		long[] factors = new long[wordCount];
		for (int word = 0; word < wordCount; word++) {
			long left = word < leftKey.logicalFactorWordCount() ? leftKey.logicalFactorWord(word) : 0L;
			long right = word < rightKey.logicalFactorWordCount() ? rightKey.logicalFactorWord(word) : 0L;
			factors[word] = left | right;
		}
		return factors;
	}

	private static FrontierLayout unionLayout(FrontierLayout left, FrontierLayout right) {
		String[] variables = new String[Math.addExact(left.size(), right.size())];
		int count = 0;
		for (int slot = 0; slot < left.size(); slot++) {
			variables[count++] = left.variable(slot);
		}
		for (int slot = 0; slot < right.size(); slot++) {
			String variable = right.variable(slot);
			if (indexOf(variables, count, variable) < 0) {
				variables[count++] = variable;
			}
		}
		Arrays.sort(variables, 0, count);
		return FrontierLayout.of(Arrays.copyOf(variables, count));
	}

	private static FrontierMaskStrata allBoundMasks(FrontierLayout layout) {
		long[] mask = new long[(layout.size() + 63) >>> 6];
		Arrays.fill(mask, -1L);
		if (layout.size() != 0 && (layout.size() & 63) != 0) {
			mask[mask.length - 1] = (1L << (layout.size() & 63)) - 1L;
		}
		return FrontierMaskStrata.of(layout, 1, mask);
	}

	private static boolean sameSamplingIdentity(FrontierStateKey left, FrontierStateKey right) {
		return left.snapshotStoreIdHigh() == right.snapshotStoreIdHigh()
				&& left.snapshotStoreIdLow() == right.snapshotStoreIdLow()
				&& left.snapshotEpoch() == right.snapshotEpoch()
				&& left.laneFamily() == right.laneFamily()
				&& left.laneIndex() == right.laneIndex()
				&& left.seedVersion() == right.seedVersion();
	}

	private static boolean sameEstimatorSemantics(FrontierStateKey left, FrontierStateKey right) {
		return left.semanticScope() == right.semanticScope()
				&& left.correlationScope() == right.correlationScope()
				&& left.continuationObjective() == right.continuationObjective();
	}

	private static int indexOf(String[] values, int size, String target) {
		for (int index = 0; index < size; index++) {
			if (values[index].equals(target)) {
				return index;
			}
		}
		return -1;
	}

	private static int indexOf(int[] values, int size, int target) {
		for (int index = 0; index < size; index++) {
			if (values[index] == target) {
				return index;
			}
		}
		return -1;
	}

	private static long retainedArrayBytes(int length, int elementBytes) {
		long bytes = 16L + (long) length * elementBytes;
		return bytes + 7L & ~7L;
	}

	private static EvidenceStateSummary sampledSummary(double pointRows, double effectiveSampleSize,
			double maximumWeightFraction) {
		return sampledSummary(pointRows, effectiveSampleSize, maximumWeightFraction, 0.0d);
	}

	private static EvidenceStateSummary sampledSummary(double pointRows, double effectiveSampleSize,
			double maximumWeightFraction, double mutationVariance) {
		return new EvidenceStateSummary(pointRows, 0.0d, Double.POSITIVE_INFINITY, 0.0d,
				EvidenceIntervalKind.NONE, Double.POSITIVE_INFINITY, mutationVariance, 0.0d, effectiveSampleSize,
				maximumWeightFraction, Double.POSITIVE_INFINITY, EvidenceGuarantee.MEASURE_UNBIASED,
				pointRows == 0.0d ? EvidenceZeroStatus.ESTIMATED_ZERO : EvidenceZeroStatus.POSITIVE, "");
	}

	private static EvidenceStateSummary learnedSummary(double pointRows, double effectiveSampleSize,
			double maximumWeightFraction) {
		return learnedSummary(pointRows, effectiveSampleSize, maximumWeightFraction, 0.0d);
	}

	private static EvidenceStateSummary learnedSummary(double pointRows, double effectiveSampleSize,
			double maximumWeightFraction, double mutationVariance) {
		return new EvidenceStateSummary(pointRows, 0.0d, Double.POSITIVE_INFINITY, 0.0d,
				EvidenceIntervalKind.HEURISTIC, Double.POSITIVE_INFINITY, mutationVariance, 0.0d, effectiveSampleSize,
				maximumWeightFraction, Double.POSITIVE_INFINITY, EvidenceGuarantee.LEARNED_CALIBRATED,
				EvidenceZeroStatus.POSITIVE, "");
	}

	private static double unitInterval(long randomWord) {
		return (randomWord >>> 11) * 0x1.0p-53;
	}

	private LeafState leafState(int relationId) {
		return leafStates == null || relationId <= 0 || relationId >= leafStates.length
				? null
				: leafStates[relationId];
	}

	private FiniteLeafState finiteLeafState(int relationId) {
		return finiteLeafStates == null || relationId <= 0 || relationId >= finiteLeafStates.length
				? null
				: finiteLeafStates[relationId];
	}

	private EvidenceStateRef leafEvidenceState(int relationId) {
		LeafState statementLeaf = leafState(relationId);
		if (statementLeaf != null) {
			return statementLeaf.state;
		}
		FiniteLeafState finiteLeaf = finiteLeafState(relationId);
		return finiteLeaf == null ? null : finiteLeaf.state;
	}

	private EvidenceStateRef materializeReplayableLeafState(int relationId, double scalarRows) {
		LeafState leaf = leafState(relationId);
		if (leaf == null || leaf.key == null || arena == null) {
			return null;
		}
		if (leaf.state != null) {
			return leaf.state;
		}
		double pointRows = finiteNonNegative(scalarRows) ? scalarRows : 1.0d;
		String reason = leaf.replayFallbackReason != null && !leaf.replayFallbackReason.isBlank()
				? leaf.replayFallbackReason
				: fallbackReason == null || fallbackReason.isBlank()
						? "replayable_statement_source_without_synopsis_payload"
						: fallbackReason;
		leaf.state = arena.intern(leaf.key,
				EvidenceStateSummary.unresolved(pointRows, Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY, reason));
		rememberState(leaf.state);
		return leaf.state;
	}

	private void annotateReady(PackedCostEstimate output, EvidenceStateRef state) {
		annotateState(output, state, isComposableState(state) ? "ready" : "degraded");
	}

	private boolean isComposableState(EvidenceStateRef state) {
		return state != null
				&& arena.disposition(state) == FrontierStateDisposition.COMPOSABLE_PAYLOAD
				&& state.summary().guarantee().isComposablePointEstimate();
	}

	private void annotateState(PackedCostEstimate output, EvidenceStateRef state, String status) {
		EvidenceStateSummary summary = state.summary();
		output.setEvidenceDisposition(arena.disposition(state));
		output.setEvidenceGuarantee(summary.guarantee());
		output.putPlannedStringMetric("plannedFrontierStatus", status);
		output.putPlannedStringMetric("plannedFrontierMode", mode.getConfigValue());
		output.putPlannedStringMetric("plannedFrontierGuarantee", statusName(summary.guarantee()));
		output.putPlannedStringMetric("plannedFrontierDisposition", statusName(arena.disposition(state)));
		output.putPlannedStringMetric("plannedFrontierZeroStatus", statusName(summary.zeroStatus()));
		output.putPlannedStringMetric("plannedFrontierIntervalKind", statusName(summary.intervalKind()));
		output.putPlannedDoubleMetric("plannedFrontierRows", summary.pointRows());
		output.putPlannedDoubleMetric("plannedFrontierLowerRows", summary.lowerRows());
		output.putPlannedDoubleMetric("plannedFrontierUpperRows", summary.upperRows());
		output.putPlannedDoubleMetric("plannedFrontierConfidence", summary.confidence());
		output.putPlannedDoubleMetric("plannedFrontierInheritedVariance", summary.inheritedVariance());
		output.putPlannedDoubleMetric("plannedFrontierMutationVariance", summary.mutationVariance());
		output.putPlannedDoubleMetric("plannedFrontierResamplingVariance", summary.resamplingVariance());
		output.putPlannedDoubleMetric("plannedFrontierEffectiveSampleSize", summary.effectiveSampleSize());
		output.putPlannedDoubleMetric("plannedFrontierMaximumWeightFraction", summary.maximumWeightFraction());
		output.putPlannedDoubleMetric("plannedFrontierCertifiedUpperBound", summary.certifiedUpperBound());
		output.putPlannedDoubleMetric("plannedFrontierStateId", state.stateId());
		if (arena != null) {
			output.putPlannedStringMetric("plannedFrontierBindingLayout", arena.layout(state).variables().toString());
		}
		output.putPlannedDoubleMetric("plannedFrontierFinalRows", summary.pointRows());
		if (arena != null) {
			FrontierStateOperation operation = arena.operation(state);
			if (operation == FrontierStateOperation.CARTESIAN) {
				output.putPlannedDoubleMetric("plannedFrontierIndependentCartesian", 1.0d);
			}
			if (operation == FrontierStateOperation.BRIDGE_MUTATION) {
				output.putPlannedStringMetric(
						"plannedFrontierBridgeMutation", "importance_with_replacement");
				output.putPlannedDoubleMetric(
						"plannedFrontierBridgeProposalEpsilon", BRIDGE_FULL_SUPPORT_EPSILON);
			}
			output.putPlannedDoubleMetric("plannedFrontierExactAtoms", arena.exactAtomCount(state));
			output.putPlannedDoubleMetric(
					"plannedFrontierResidualParticles", arena.residualParticleCount(state));
			EvidenceCalibrationSummary calibration = arena.nearestCalibration(state);
			if (calibration != null) {
				double cumulativeFactor = arena.cumulativeCalibrationFactor(state);
				double rawRows = Double.isFinite(cumulativeFactor) && cumulativeFactor > 0.0d
						? summary.pointRows() / cumulativeFactor
						: calibration.rawRows();
				output.putPlannedDoubleMetric("plannedFrontierRawRows", rawRows);
				annotateCalibrationStages(output, state, rawRows);
				output.putPlannedDoubleMetric("plannedFrontierCalibrationFinalRows", summary.pointRows());
				output.putPlannedDoubleMetric("plannedFrontierCalibrationFactor", cumulativeFactor);
				output.putPlannedDoubleMetric("plannedFrontierCalibrationEvidence", calibration.evidenceCount());
				output.putPlannedDoubleMetric("plannedFrontierCalibrationConfidence",
						calibration.correctionConfidence());
				output.putPlannedDoubleMetric("plannedFrontierCalibrationRevision", calibration.evidenceRevision());
				output.putPlannedStringMetric("plannedFrontierCalibrationSource", calibration.source());
				output.putPlannedStringMetric("plannedFrontierCalibrationKey", calibration.evidenceKey());
				if (arena.calibration(state) != null && arena.parentCount(state) > 0) {
					output.putPlannedDoubleMetric("plannedFrontierCalibrationParentStateId",
							arena.parent(state, 0).stateId());
				}
			} else {
				output.putPlannedDoubleMetric("plannedFrontierRawRows", summary.pointRows());
			}
		}
		if (arena != null) {
			output.putPlannedDoubleMetric("plannedFrontierQueryMemoryBytes", arena.allocatedBytes());
			output.putPlannedDoubleMetric("plannedFrontierQueryMemoryPeakBytes", arena.peakReservedBytes());
			output.putPlannedDoubleMetric("plannedFrontierQueryMemoryBudgetBytes", arena.memoryBudgetBytes());
		}
		if (executionSnapshotEpoch.isPresent()) {
			output.putPlannedDoubleMetric("plannedFrontierSnapshotEpoch", executionSnapshotEpoch.getAsLong());
		}
		annotateQueryIndex(output);
	}

	private void annotateCalibrationStages(PackedCostEstimate output, EvidenceStateRef state, double rawRows) {
		CalibrationStages stages = calibrationStages(state);
		if (!stages.unambiguous()
				|| !Double.isFinite(rawRows)
				|| !Double.isFinite(stages.learnedFilterFactor())
				|| !Double.isFinite(stages.leoFactor())) {
			return;
		}
		double learnedFilterRows = rawRows * stages.learnedFilterFactor();
		if (!Double.isFinite(learnedFilterRows)) {
			return;
		}
		if (stages.learnedFilterPresent()) {
			output.putPlannedDoubleMetric("plannedFrontierLearnedFilterRows", learnedFilterRows);
		}
		double leoRows = learnedFilterRows * stages.leoFactor();
		if (stages.leoPresent() && Double.isFinite(leoRows)) {
			output.putPlannedDoubleMetric("plannedFrontierLeoRows", leoRows);
		}
	}

	private CalibrationStages calibrationStages(EvidenceStateRef state) {
		CalibrationStages cached = calibrationStagesByStateId.get(state.stateId());
		if (cached != null) {
			return cached;
		}
		CalibrationStages inherited;
		int parentCount = arena.parentCount(state);
		if (parentCount == 0) {
			inherited = CalibrationStages.RAW;
		} else if (parentCount == 1) {
			inherited = calibrationStages(arena.parent(state, 0));
		} else {
			inherited = CalibrationStages.merge(
					calibrationStages(arena.parent(state, 0)),
					calibrationStages(arena.parent(state, 1)));
		}
		CalibrationStages result = inherited.with(arena.calibration(state));
		calibrationStagesByStateId.put(state.stateId(), result);
		return result;
	}

	private static boolean approximatelyEqual(double left, double right) {
		if (Double.doubleToLongBits(left) == Double.doubleToLongBits(right)) {
			return true;
		}
		if (!Double.isFinite(left) || !Double.isFinite(right)) {
			return false;
		}
		double scale = Math.max(1.0d, Math.max(Math.abs(left), Math.abs(right)));
		return Math.abs(left - right) <= 8.0d * Math.ulp(scale);
	}

	private void annotateFallback(PackedCostEstimate output) {
		if (!exposeFallback || availabilityStatus == null) {
			return;
		}
		output.putPlannedStringMetric("plannedFrontierStatus", availabilityStatus);
		output.putPlannedStringMetric("plannedFrontierMode", mode.getConfigValue());
		if (fallbackReason != null && !fallbackReason.isBlank()) {
			output.putPlannedStringMetric("plannedFrontierFallbackReason", fallbackReason);
		}
		annotateQueryIndex(output);
	}

	private void annotateMissingLeafState(int relationId, PackedCostEstimate output) {
		if (!exposeFallback) {
			return;
		}
		if (!"ready".equals(availabilityStatus)) {
			annotateFallback(output);
			return;
		}
		TupleExpr expression = query.materializeRelation(relationId);
		String reason = fallbackReason != null && !fallbackReason.isBlank()
				? fallbackReason
				: FrontierOperatorCapabilities
						.handling(expression) == FrontierOperatorCapabilities.Handling.STATEFUL
								? "stateful_leaf_state_unavailable"
								: FrontierOperatorCapabilities.boundaryReason(expression);
		degradeOperator(relationId, output, null, reason);
		annotateQueryIndex(output);
	}

	private void unavailable(String reason) {
		LmdbFrontierSynopsisService synopsis = runtime.frontierSynopsis();
		availabilityStatus = synopsis == null ? "unavailable" : statusName(synopsis.status());
		fallbackReason = reason;
	}

	private void unavailableQueryIndex(String reason) {
		availabilityStatus = statusName(runtime.frontierSynopsis().status());
		fallbackReason = reason;
		queryIndexStatus = reason;
		if (queryIndexLease != null) {
			queryIndexLease.close();
			queryIndexLease = null;
		}
	}

	private void annotateQueryIndex(PackedCostEstimate output) {
		if (queryIndexStatus != null) {
			output.putPlannedStringMetric("plannedFrontierQueryIndexStatus", queryIndexStatus);
		}
		output.putPlannedDoubleMetric("plannedFrontierQueryIndexCandidateRows", queryIndexCandidateRows);
		output.putPlannedDoubleMetric("plannedFrontierQueryIndexVisitedRows", queryIndexVisitedRows);
		output.putPlannedDoubleMetric("plannedFrontierQueryIndexMatchedRows", queryIndexMatchedRows);
		output.putPlannedDoubleMetric("plannedFrontierQueryIndexScanPasses", queryIndexScanPasses);
		output.putPlannedDoubleMetric(
				"plannedFrontierIndependentMaterializedLeaves",
				queryIndexIndependentMaterializedLeaves);
		output.putPlannedDoubleMetric(
				"plannedFrontierIndependentMaterializedRows",
				queryIndexIndependentMaterializedRows);
		output.putPlannedDoubleMetric("plannedFrontierQueryIndexForwardMappedProbes", queryIndexForwardMappedProbes);
		output.putPlannedDoubleMetric("plannedFrontierQueryIndexReverseMappedProbes", queryIndexReverseMappedProbes);
		if (queryIndexLaneDiagnosticLeaves > 0) {
			output.putPlannedStringMetric("plannedFrontierLaneDiagnostics", "audit_only");
		}
		output.putPlannedDoubleMetric(
				"plannedFrontierLaneDiagnosticScannedRows",
				queryIndexLaneDiagnosticScannedRows);
		output.putPlannedDoubleMetric("plannedFrontierPrimaryDesignRows", queryIndexPrimaryDesignRows);
		output.putPlannedDoubleMetric("plannedFrontierSecondDesignRows", queryIndexSecondDesignRows);
		output.putPlannedDoubleMetric("plannedFrontierAuditRows", queryIndexAuditRows);
		double designScale = Math.max(1.0d, 0.5d * (queryIndexPrimaryDesignRows + queryIndexSecondDesignRows));
		double auditScale = Math.max(1.0d, 0.5d * (queryIndexPrimaryDesignRows + queryIndexAuditRows));
		output.putPlannedDoubleMetric(
				"plannedFrontierDesignLaneRelativeDisagreement",
				queryIndexDesignLaneAbsoluteDifference / designScale);
		output.putPlannedDoubleMetric(
				"plannedFrontierAuditRelativeDrift",
				queryIndexAuditAbsoluteDifference / auditScale);
		output.putPlannedDoubleMetric("plannedFrontierQueryIndexExcludedLeaves", queryIndexExcludedLeaves);
		output.putPlannedDoubleMetric("plannedFrontierQueryIndexBytes", queryIndexBytes);
		output.putPlannedDoubleMetric("plannedFrontierPreparationNanos", preparationNanos);
		output.putPlannedDoubleMetric("plannedFrontierPathExpansionPlanningNanos", pathExpansionPlanningNanos);
		output.putPlannedDoubleMetric("plannedFrontierPathExpansionMappingProbes", pathExpansionMappingProbes);
		output.putPlannedDoubleMetric("plannedFrontierPathExpansionStates", pathExpansionStates);
	}

	private void recordLaneDiagnostics(FrontierQueryIndexLaneDiagnostics diagnostics) {
		queryIndexLaneDiagnosticScannedRows = Math.addExact(
				queryIndexLaneDiagnosticScannedRows,
				diagnostics.scannedRows());
		queryIndexLaneDiagnosticLeaves = Math.incrementExact(queryIndexLaneDiagnosticLeaves);
		double primaryRows = diagnostics.designWeightedRows(0);
		queryIndexPrimaryDesignRows += primaryRows;
		if (diagnostics.designLaneCount() > 1) {
			double secondRows = diagnostics.designWeightedRows(1);
			queryIndexSecondDesignRows += secondRows;
			queryIndexDesignLaneAbsoluteDifference += Math.abs(primaryRows - secondRows);
		}
		if (diagnostics.auditLaneCount() > 0) {
			double auditRows = 0.0d;
			for (int lane = 0; lane < diagnostics.auditLaneCount(); lane++) {
				auditRows += diagnostics.auditWeightedRows(lane);
			}
			auditRows /= diagnostics.auditLaneCount();
			queryIndexAuditRows += auditRows;
			queryIndexAuditAbsoluteDifference += Math.abs(primaryRows - auditRows);
		}
	}

	private static String statusName(Enum<?> value) {
		return value.name().toLowerCase(Locale.ROOT);
	}

	private record CalibrationStages(
			double learnedFilterFactor,
			double leoFactor,
			boolean learnedFilterPresent,
			boolean leoPresent,
			boolean unambiguous) {

		private static final CalibrationStages RAW = new CalibrationStages(1.0d, 1.0d, false, false, true);

		private CalibrationStages with(EvidenceCalibrationSummary calibration) {
			if (calibration == null) {
				return this;
			}
			if (FRONTIER_EXACT_FACT_CALIBRATION_SOURCE.equals(calibration.source())) {
				/* A current-stamp fact supersedes statistical row calibration; it is not a LEO sample. */
				return new CalibrationStages(1.0d, 1.0d, false, false, unambiguous);
			}
			boolean learnedFilter = calibration.source().startsWith("learned-filter");
			return new CalibrationStages(
					learnedFilter ? learnedFilterFactor * calibration.factor() : learnedFilterFactor,
					learnedFilter ? leoFactor : leoFactor * calibration.factor(),
					learnedFilterPresent || learnedFilter,
					leoPresent || !learnedFilter,
					unambiguous);
		}

		private static CalibrationStages merge(CalibrationStages first, CalibrationStages second) {
			boolean same = first.unambiguous
					&& second.unambiguous
					&& first.learnedFilterPresent == second.learnedFilterPresent
					&& first.leoPresent == second.leoPresent
					&& approximatelyEqual(first.learnedFilterFactor, second.learnedFilterFactor)
					&& approximatelyEqual(first.leoFactor, second.leoFactor);
			return new CalibrationStages(
					first.learnedFilterFactor,
					first.leoFactor,
					first.learnedFilterPresent,
					first.leoPresent,
					same);
		}
	}

	@FunctionalInterface
	private interface FrontierEmissionSink {

		void add(int stratum, long[] source, int offset, double weight);
	}

	/**
	 * Query-index probes are already bounded when the synopsis is built. Snapshot probes are not: one weakly bound
	 * probe can traverse the complete store. Charge every cursor row to one budget shared by the survey and replay
	 * passes so refinement work remains bounded by the configured planning budget.
	 */
	private static final class ExactExpansionScanBudget {

		private long remainingRows;

		private ExactExpansionScanBudget(long maximumRows) {
			if (maximumRows < 0L) {
				throw new IllegalArgumentException("exact expansion scan budget must be nonnegative");
			}
			remainingRows = maximumRows;
		}

		private void consumeRow() {
			if (remainingRows == 0L) {
				throw ExactExpansionScanBudgetExceeded.INSTANCE;
			}
			remainingRows--;
		}

		private void consumeRows(long rows) {
			if (rows < 0L) {
				throw new IllegalArgumentException("exact expansion scan rows must be nonnegative");
			}
			if (rows > remainingRows) {
				throw ExactExpansionScanBudgetExceeded.INSTANCE;
			}
			remainingRows -= rows;
		}
	}

	/** Stackless control signal converted by {@link #extendInner} into a typed, lineage-preserving state. */
	private static final class ExactExpansionScanBudgetExceeded extends RuntimeException {

		private static final long serialVersionUID = 1L;
		private static final ExactExpansionScanBudgetExceeded INSTANCE = new ExactExpansionScanBudgetExceeded();

		private ExactExpansionScanBudgetExceeded() {
			super(null, null, false, false);
		}
	}

	/** First pass over an exact bridge expansion: retain only the affordable prefix and summarize the full measure. */
	private static final class BridgeEmissionSurvey implements FrontierEmissionSink {

		private final EmissionBuffer retained;
		private long emissionCount;
		private double totalWeight;

		private BridgeEmissionSurvey(EmissionBuffer retained) {
			this.retained = retained;
		}

		@Override
		public void add(int stratum, long[] source, int offset, double weight) {
			if (!Double.isFinite(weight) || weight <= 0.0d) {
				throw new IllegalStateException("Frontier bridge produced an invalid target weight");
			}
			emissionCount = Math.incrementExact(emissionCount);
			totalWeight += weight;
			retained.tryAdd(stratum, source, offset, weight);
		}

		private long emissionCount() {
			return emissionCount;
		}

		private double totalWeight() {
			return totalWeight;
		}
	}

	/**
	 * Second bridge pass selecting fixed-size with-replacement draws from a mass-informed proposal mixed with a uniform
	 * full-support lane.
	 */
	private static final class BridgeImportanceSelector implements FrontierEmissionSink, AutoCloseable {

		private final EmissionBuffer output;
		private final long expectedEmissions;
		private final double totalWeight;
		private final int drawCount;
		private FrontierMemoryReservation reservation;
		private double[] thresholds;
		private long observedEmissions;
		private int nextDraw;
		private double cumulativeProposal;
		private double contributionSum;
		private double contributionSquareSum;

		private BridgeImportanceSelector(FrontierStateArena arena, EmissionBuffer output,
				long expectedEmissions, double totalWeight, int drawCount, long seed) {
			if (expectedEmissions <= 0L || !Double.isFinite(totalWeight) || totalWeight <= 0.0d
					|| drawCount <= 0) {
				throw new IllegalArgumentException("invalid Frontier bridge proposal dimensions");
			}
			this.output = output;
			this.expectedEmissions = expectedEmissions;
			this.totalWeight = totalWeight;
			this.drawCount = drawCount;
			reservation = arena.reserveTemporary(
					retainedArrayBytes(drawCount, Double.BYTES), FrontierMemoryPurpose.RESAMPLING);
			try {
				thresholds = new double[drawCount];
				for (int draw = 0; draw < drawCount; draw++) {
					thresholds[draw] = unitInterval(FrontierSeedSchedule.derive(
							seed, FrontierRandomDomain.BRIDGE_NEIGHBOR, 0L, draw));
				}
				Arrays.sort(thresholds);
			} catch (RuntimeException | Error failure) {
				reservation.close();
				reservation = null;
				throw failure;
			}
		}

		@Override
		public void add(int stratum, long[] source, int offset, double weight) {
			if (!Double.isFinite(weight) || weight <= 0.0d) {
				throw new IllegalStateException("Frontier bridge proposal observed an invalid target weight");
			}
			observedEmissions = Math.incrementExact(observedEmissions);
			double informed = weight / totalWeight;
			double uniform = 1.0d / expectedEmissions;
			double proposal = (1.0d - BRIDGE_FULL_SUPPORT_EPSILON) * informed
					+ BRIDGE_FULL_SUPPORT_EPSILON * uniform;
			if (!Double.isFinite(proposal) || proposal <= 0.0d) {
				throw new IllegalStateException("Frontier bridge proposal lost full support");
			}
			boolean last = observedEmissions == expectedEmissions;
			double upper = last ? 1.0d : Math.min(1.0d, cumulativeProposal + proposal);
			double contribution = weight / proposal;
			while (nextDraw < drawCount && (thresholds[nextDraw] < upper || last)) {
				output.add(stratum, source, offset, contribution / drawCount);
				contributionSum += contribution;
				contributionSquareSum += contribution * contribution;
				nextDraw++;
			}
			cumulativeProposal = upper;
		}

		private void finish() {
			if (observedEmissions != expectedEmissions || nextDraw != drawCount) {
				throw new IllegalStateException("Frontier bridge proposal replay did not reproduce its survey");
			}
		}

		private double estimatedVariance() {
			if (drawCount <= 1) {
				return Double.POSITIVE_INFINITY;
			}
			double centered = contributionSquareSum - contributionSum * contributionSum / drawCount;
			if (!Double.isFinite(centered)) {
				return Double.POSITIVE_INFINITY;
			}
			return Math.max(0.0d, centered) / (drawCount - 1.0d) / drawCount;
		}

		@Override
		public void close() {
			if (reservation != null) {
				reservation.close();
				reservation = null;
				thresholds = null;
			}
		}
	}

	/** Growable emission staging buffer whose retained bytes stay charged to the query arena while it is open. */
	private static final class EmissionBuffer implements FrontierEmissionSink, AutoCloseable {

		private final FrontierStateArena arena;
		private final int width;
		private final int maximumSize;
		private FrontierMemoryReservation reservation;
		private long[] tuples;
		private double[] weights;
		private int[] strata;
		private int size;

		EmissionBuffer(FrontierStateArena arena, int width) {
			this(arena, width, Integer.MAX_VALUE);
		}

		EmissionBuffer(FrontierStateArena arena, int width, int maximumSize) {
			if (maximumSize < 0) {
				throw new IllegalArgumentException("maximum emission count must be nonnegative");
			}
			this.arena = arena;
			this.width = width;
			this.maximumSize = maximumSize;
			int capacity = Math.min(64, maximumSize);
			reservation = arena.reserveTemporary(retainedBytes(capacity, width),
					FrontierMemoryPurpose.TARGET_COALESCING);
			try {
				tuples = new long[Math.multiplyExact(capacity, width)];
				weights = new double[capacity];
				strata = new int[capacity];
			} catch (RuntimeException | Error failure) {
				reservation.close();
				reservation = null;
				throw failure;
			}
		}

		void add(long[] source, int offset, double weight) {
			add(0, source, offset, weight);
		}

		void addRow(long first, long second, long third, long fourth, double weight) {
			if (width != 4) {
				throw new IllegalStateException("primitive row append requires a four-column buffer");
			}
			if (size == maximumSize) {
				throw new IllegalStateException("Frontier emission buffer capacity exhausted");
			}
			if (size == weights.length) {
				grow();
			}
			int offset = size * width;
			tuples[offset] = first;
			tuples[offset + 1] = second;
			tuples[offset + 2] = third;
			tuples[offset + 3] = fourth;
			weights[size] = weight;
			strata[size] = 0;
			size++;
		}

		@Override
		public void add(int stratum, long[] source, int offset, double weight) {
			if (size == maximumSize) {
				throw new IllegalStateException("Frontier emission buffer capacity exhausted");
			}
			if (size == weights.length) {
				grow();
			}
			System.arraycopy(source, offset, tuples, size * width, width);
			weights[size] = weight;
			strata[size] = stratum;
			size++;
		}

		boolean tryAdd(int stratum, long[] source, int offset, double weight) {
			if (size == maximumSize) {
				return false;
			}
			add(stratum, source, offset, weight);
			return true;
		}

		void clear() {
			size = 0;
		}

		int size() {
			return size;
		}

		long[] tuples() {
			return tuples;
		}

		int tupleOffset(int emission) {
			return emission * width;
		}

		double weight(int emission) {
			return weights[emission];
		}

		int stratum(int emission) {
			return strata[emission];
		}

		private void grow() {
			int capacity = weights.length >= maximumSize / 2
					? maximumSize
					: Math.multiplyExact(weights.length, 2);
			if (capacity <= weights.length) {
				throw new IllegalStateException("Frontier emission buffer cannot grow beyond its bound");
			}
			FrontierMemoryReservation grown = arena.reserveTemporary(retainedBytes(capacity, width),
					FrontierMemoryPurpose.TARGET_COALESCING);
			try {
				tuples = Arrays.copyOf(tuples, Math.multiplyExact(capacity, width));
				weights = Arrays.copyOf(weights, capacity);
				strata = Arrays.copyOf(strata, capacity);
			} catch (RuntimeException | Error failure) {
				grown.close();
				throw failure;
			}
			reservation.close();
			reservation = grown;
		}

		@Override
		public void close() {
			if (reservation != null) {
				reservation.close();
				reservation = null;
				tuples = null;
				weights = null;
				strata = null;
			}
		}

		private static long retainedBytes(int capacity, int width) {
			return Math.addExact(retainedArrayBytes(capacity, Integer.BYTES), Math.addExact(
					retainedArrayBytes(Math.multiplyExact(capacity, Math.max(width, 1)), Long.BYTES),
					retainedArrayBytes(capacity, Double.BYTES)));
		}
	}

	/**
	 * Primitive exact-bag coalescer. The table is sized from the validated count pass and every retained byte is
	 * reserved before allocation.
	 */
	private static final class ExactLeafAccumulator implements AutoCloseable {

		private static final long OBJECT_BYTES = 96L;

		private FrontierMemoryReservation reservation;
		private long[] tuples;
		private double[] weights;
		private int[] table;
		private final int width;
		private int size;

		ExactLeafAccumulator(FrontierStateArena arena, int maximumEntries, int width) {
			if (maximumEntries < 0 || width < 0) {
				throw new IllegalArgumentException("invalid exact Frontier coalescer dimensions");
			}
			this.width = width;
			int tableCapacity = tableCapacity(maximumEntries);
			int tupleValues = Math.multiplyExact(maximumEntries, width);
			long bytes = Math.addExact(OBJECT_BYTES,
					Math.addExact(arrayBytes(tupleValues, Long.BYTES),
							Math.addExact(arrayBytes(maximumEntries, Double.BYTES),
									arrayBytes(tableCapacity, Integer.BYTES))));
			reservation = arena.reserveTemporary(bytes, FrontierMemoryPurpose.TARGET_COALESCING);
			try {
				tuples = new long[tupleValues];
				weights = new double[maximumEntries];
				table = new int[tableCapacity];
			} catch (RuntimeException | Error failure) {
				reservation.close();
				reservation = null;
				throw failure;
			}
		}

		void add(long[] tuple, double weight) {
			add(tuple, 0, weight);
		}

		void add(long[] source, int sourceOffset, double weight) {
			if (reservation == null) {
				throw new IllegalStateException("exact Frontier coalescer is closed");
			}
			if (!Double.isFinite(weight) || weight <= 0.0d) {
				throw new IllegalArgumentException("exact Frontier multiplicity must be finite and positive");
			}
			long hash = tupleHash(source, sourceOffset, width);
			int slot = (int) hash & table.length - 1;
			while (true) {
				int encoded = table[slot];
				if (encoded == 0) {
					if (size >= weights.length) {
						throw new IllegalStateException("exact Frontier count pass underreported matching rows");
					}
					int offset = Math.multiplyExact(size, width);
					System.arraycopy(source, sourceOffset, tuples, offset, width);
					weights[size] = weight;
					table[slot] = ++size;
					return;
				}
				int entry = encoded - 1;
				if (sameTuple(tuples, Math.multiplyExact(entry, width), source, sourceOffset, width)) {
					double sum = weights[entry] + weight;
					if (!Double.isFinite(sum)) {
						throw new IllegalStateException("exact Frontier multiplicity overflow");
					}
					weights[entry] = sum;
					return;
				}
				slot = slot + 1 & table.length - 1;
			}
		}

		int size() {
			return size;
		}

		void writeTo(FrontierPayloadWriter writer) {
			writeTo(writer, 0);
		}

		void writeTo(FrontierPayloadWriter writer, int stratum) {
			if (reservation == null) {
				throw new IllegalStateException("exact Frontier coalescer is closed");
			}
			for (int index = 0; index < size; index++) {
				writer.putExact(stratum, index, weights[index], tuples, Math.multiplyExact(index, width));
			}
		}

		@Override
		public void close() {
			if (reservation != null) {
				reservation.close();
				reservation = null;
				tuples = null;
				weights = null;
				table = null;
			}
		}

		private static int tableCapacity(int maximumEntries) {
			if (maximumEntries > 1 << 28) {
				throw new IllegalStateException("exact Frontier coalescer exceeds the supported query-local range");
			}
			int required = Math.max(2, maximumEntries + (maximumEntries >>> 1) + 1);
			int capacity = 2;
			while (capacity < required) {
				capacity <<= 1;
			}
			return capacity;
		}

		private static long tupleHash(long[] tuple, int offset, int width) {
			long hash = 0x9e3779b97f4a7c15L ^ width;
			for (int index = 0; index < width; index++) {
				hash ^= tuple[offset + index] + 0x9e3779b97f4a7c15L + (hash << 6) + (hash >>> 2);
			}
			hash = (hash ^ hash >>> 30) * 0xbf58476d1ce4e5b9L;
			hash = (hash ^ hash >>> 27) * 0x94d049bb133111ebL;
			return hash ^ hash >>> 31;
		}

		private static boolean sameTuple(long[] stored, int storedOffset, long[] candidate, int candidateOffset,
				int width) {
			for (int index = 0; index < width; index++) {
				if (stored[storedOffset + index] != candidate[candidateOffset + index]) {
					return false;
				}
			}
			return true;
		}

		private static long arrayBytes(int length, int elementBytes) {
			long bytes = 16L + (long) length * elementBytes;
			return bytes + 7L & ~7L;
		}
	}

